#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <ifaddrs.h>
#include <sys/socket.h>
#include <netdb.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>

typedef struct nicp_config {
    char mac[18]; // MAC address with '\0' terminator
    sockaddr_in ip; // IP configuration
    int status; // Link state flag
} nicp_config;

struct nicp_list {
    size_t len;
    nicp_config *arr;
    pthread_mutex_t mutex;
};

nicp_list* init_nicp_list() {
    nicp_list *list = malloc(sizeof(nicp_list));
    list->len = 0;
    list->arr = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_nicp_list(nicp_list *list) {
    for (size_t i = 0; i < list->len; ++i) {
        free(list->arr[i].mac);
    }
    free(list->arr);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

nicp_config* add_nicp_config(nicp_list *list) {
    nicp_config *new = malloc(sizeof(nicp_config));
    if (!getifaddrs(new, NULL)) { // Get first available interface's MAC and IP
        new->mac[17] = '\0';
        strncpy(new->mac, new->ifa_name, 17);
        bzero(&new->ip, sizeof(sockaddr_in));
        memcpy(&new->ip.sin_addr, &new->ifa_addr->sa_data[2], sizeof(struct in_addr));
        freeifaddrs(new); // Free the ifaddrs buffer
    } else {
        fprintf(stderr, "getifaddrs: %s\n", gai_strerror(h_errnoval));
        exit(EXIT_FAILURE);
    }
    new->status = 0;

    pthread_mutex_lock(&list->mutex);
    list->arr = realloc(list->arr, sizeof(nicp_config) * (list->len + 1));
    list->arr[list->len] = *new;
    list->len++;
    pthread_mutex_unlock(&list->mutex);

    return &list->arr[list->len - 1];
}

void update_nicp_config(nicp_list *list, size_t idx, int status) {
    if (idx >= list->len) {
        fprintf(stderr, "Index out of bounds.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&list->mutex);
    list->arr[idx].status = status;
    pthread_mutex_unlock(&list->mutex);
}

void check_connectivity(nicp_list *list, int timeout_ms) {
    time_t start;
    int connected = 0;

    for (size_t i = 0; i < list->len && !connected; ++i) {
        if (list->arr[i].status == 1) { // Skip interfaces with no link
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += timeout_ms / 1000;
        ts.tv_nsec = (timeout_ms % 1000) * 1000000;

        while (!connected && (ts.tv_sec - start < 2 || (ts.tv_sec == start + 2 && ts.tv_nsec <= timeout_ms))) {
            int sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_IP);
            if (sockfd == -1) {
                perror("socket");
                exit(EXIT_FAILURE);
            }

            if (connect(sockfd, (struct sockaddr *)&list->arr[i].ip, sizeof(list->arr[i].ip)) != -1) { // Check for connection success
                close(sockfd);
                connected = 1;
                list->arr[i].status = 1;
            } else if (errno == EINPROGRESS) { // Handle non-blocking connection check
                fd_set fs;
                FD_ZERO(&fs);
                FD_SET(sockfd, &fs);

                struct timeval tv = {timeout_ms / 1000, (timeout_ms % 1000) * 1000000};
                select(sockfd + 1, NULL, &fs, NULL, &tv); // Wait for connection to become ready

                if (!FD_ISSET(sockfd, &fs)) { // Connection not ready within timeout
                    close(sockfd);
                    continue;
                }
            } else { // Handle other errors during connection check
                perror("connect");
                list->arr[i].status = -1; // Set error status for failed connectivity check
                close(sockfd);
                continue;
            }
        }
    }
}
