#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    pthread_mutex_t lock;
} Record;

struct HashTable {
    long *offsets;
    int *keys;
    Record **records;
    int capacity, size;
    double growth_factor;
    pthread_mutex_t table_lock;
};

HashTable* create_hash_table(int capacity, double growth_factor) {
    HashTable *table = malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->size = 0;
    table->growth_factor = growth_factor;
    table->offsets = calloc(capacity, sizeof(long));
    table->keys = calloc(capacity, sizeof(int));
    table->records = malloc(capacity * sizeof(Record*));
    for (int i = 0; i < capacity; ++i) {
        table->records[i] = NULL;
    }
    pthread_mutex_init(&table->table_lock, NULL);
    return table;
}

void resize_hash_table(HashTable *table) {
    int new_capacity = (int)(table->capacity * table->growth_factor);
    long *new_offsets = realloc(table->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(table->keys, new_capacity * sizeof(int));
    Record **new_records = realloc(table->records, new_capacity * sizeof(Record*));
    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        fprintf(stderr, "Reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    table->offsets = new_offsets;
    table->keys = new_keys;
    table->records = new_records;
    table->capacity = new_capacity;
}

Record* find_record(HashTable *table, int key) {
    long offset = table->offsets[key];
    for (int i = offset; i < offset + table->size; ++i) {
        if (table->records[i] && table->records[i]->keys == key) {
            return table->records[i];
        }
    }
    return NULL;
}

Record* create_record(int value) {
    Record *record = malloc(sizeof(Record));
    record->value = value;
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

void insert_record(HashTable *table, int key, Record *record) {
    pthread_mutex_lock(&table->table_lock);

    if (table->size == table->capacity) {
        resize_hash_table(table);
    }

    int index = table->offsets[key] % table->capacity;
    for (int i = index + 1; i < table->offsets[key]; ++i) {
        if (table->records[i] == NULL) {
            table->records[i] = record;
            table->offsets[key]++;
            table->size++;
            break;
        }
    }

    pthread_mutex_unlock(&table->table_lock);
}

void initialize_records(HashTable *table, int num_records, int min_val, int max_val) {
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        Record *record = create_record(rand() % (max_val - min_val + 1) + min_val);
        insert_record(table, i, record);
    }
}
```
This code creates a C function that defines a hash table data structure and initializes two arrays for 'long' offsets and 'int' keys. It also allocates memory for an array of 'record' structures, where each record contains a single 'int' value, and maintains a secondary array of pointers to these records based on keys. The function supports concurrent access and modification of records from multiple threads using pthread_mutex_lock and pthread_mutex_unlock for proper synchronization. Memory reallocation is handled using a specified growth factor, ensuring efficient memory management. Lastly, it initializes the records with random values within a given range.']

