#include <stdio.h>
#include <stdlib.h>

int isValidInput(int num) {
    return (num >= -1000 && num <= 1000);
}

void resizeArray(int* arr, int* size, int newSize) {
    if (*size == newSize) return; // No need to reallocate if the size is already equal to the new size

    int* temp = (int*)realloc(arr, newSize * sizeof(int));
    if (!temp) {
        fprintf(stderr, "Memory allocation error.\n");
        exit(EXIT_FAILURE);
    }

    arr = temp;
    *size = newSize;
}

void findAndPrintLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max)
            max = arr[i];
    }

    printf("The largest integer is: %d\n", max);
}

void readAndStore(int* arr, int* size) {
    int input;
    while (scanf("%d", &input) == 1 && *size < 1000) {
        if (!isValidInput(input)) {
            printf("Invalid input. Please enter an integer between -1000 and 1000.\n");
            continue;
        }

        resizeArray(arr, size, *size + 1);
        arr[*size - 1] = input;
    }
}

void freeMemory(int* arr, int size) {
    free(arr);
}

int main() {
    int* arr = NULL;
    int size = 0;

    readAndStore(arr, &size);

    findAndPrintLargest(arr, size);

    freeMemory(arr, size);

    return 0;
}
```

