typedef struct {
    EVP_CIPHER_CTX *ctx;
    const char *mode;
} crypt_ops;

bool validate_token(const char *json) {
    json_object *o = json_tokener_parse(json, 0);
    if (!o) return false;

    json_object *access_token = json_object_object_get(o, "access_token");
    json_object *expires_in = json_object_object_get(o, "expires_in");
    json_object *token_type = json_object_object_get(o, "token_type");

    if (!access_token || !json_is_type(access_token, JSON_TYPE_STRING) ||
        !expires_in || !json_is_type(expires_in, JSON_TYPE_INT) ||
        !token_type || !json_is_type(token_token, JSON_TYPE_STRING)) {
        json_object_put(o);
        return false;
    }

    if (strcmp(json_string_value(token_type), "Bearer") != 0 || expires_in->v.i < 0) {
        json_object_put(o);
        return false;
    }

    json_object_put(o);
    return true;
}

crypt_ops *create_crypt_ops(const char *json) {
    if (!validate_token(json)) return NULL;

    EVP_CIPHER *cipher = NULL;
    crypt_ops *crypto_ops = malloc(sizeof(crypt_ops));

    switch (strcasecmp(json_string_value(json_object_object_get(json_tokener_parse(json, 0), "mode")), "ecb")) {
        case 0:
            cipher = EVP_des_ecb();
            break;
        case 0:
            cipher = EVP_des_ede3_cbc();
            crypto_ops->mode = "EDE3";
            break;
        case 0:
            cipher = EVP_des_ede2_cbc();
            crypto_ops->mode = "EDE";
            break;
        case 0:
            cipher = EVP_cfb128();
            crypto_ops->mode = "CFB";
            break;
        default:
            if (strcmp(json_string_value(json_object_object_get(json_tokener_parse(json, 0), "mode")), "null") == 0) {
                cipher = NULL;
                crypto_ops->mode = "NULL";
            } else {
                return NULL;
            }
    }

    crypto_ops->ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_init(cipher, NULL, crypto_ops->ctx);
    return crypto_ops;
}
