            .callTimeout(10, TimeUnit.SECONDS)
            .build();

    public static PokemonReport getDetailedReport(Pokemon pokemon) {
        List<String> weaknesses = new ArrayList<>();
        List<String> strengths = new ArrayList<>();
        List<String> typeSpecificAbilities = new ArrayList<>();

        Type type = pokemon.getType();
        String name = pokemon.getName();

        switch (type) {
            case NORMAL:
                // Add weaknesses, strengths, and type-specific abilities for Normal type here
                break;
            // Add cases for other types here
        }

        Runnable fetchTypeSpecificAbilitiesTask = () -> {
            try {
                String url = "https://api.example.com/pokemon/" + name + "/typespecialabilities";
                Request request = new Request.Builder()
                        .url(url)
                        .build();
                Response response = httpClient.newCall(request).execute();
                if (!response.isSuccessful()) {
                    retryTypeSpecificAbilitiesFetch(name);
                } else {
                    JsonArray jsonArray = Json.createArrayBuilder(response.body().string()).build();
                    typeSpecificAbilities.addAll(jsonArray.getValuesAs(String.class));
                }
            } catch (Exception e) {
                // Log the error and retry fetching the type-specific abilities
                retryTypeSpecificAbilitiesFetch(name);
            }
        };

        executor.submit(fetchTypeSpecificAbilitiesTask);

        return new PokemonReport(name, weaknesses, strengths, typeSpecificAbilities);
    }

    private static void retryTypeSpecificAbilitiesFetch(String name) {
        if (executor.getActiveCount() <= 10) {
            executor.execute(() -> {
                try {
                    TimeUnit.MILLISECONDS.sleep(Math.min((long) Math.pow(2, executor.getActiveCount()), 10000)); // Exponential backoff
                    getDetailedReport(new Pokemon(name, Type.NORMAL)); // Simulate fetching the data from an external API
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }
    }
}
