bool validate_json(const char *json) {
    json_object *o = json_tokener_parse(json);
    struct json_token_response response;
    response.obj = o;
    response.valid = true;

    if (json_object_get_type(o) != json_type_object) {
        response.valid = false;
        return response.valid;
    }

    json_object *token_type, *expires_in, *access_token;
    if (!(access_token = json_object_object_get(o, "access_token"))) {
        response.valid = false;
        return response.valid;
    }
    if (!(token_type = json_object_object_get(o, "token_type")) ||
        strcmp(json_object_get_string(token_type), "Bearer") != 0) {
        response.valid = false;
        return response.valid;
    }
    if (!(expires_in = json_object_object_get(o, "expires_in")) ||
        json_object_get_int(expires_in) <= 0) {
        response.valid = false;
        return response.valid;
    }

