    EVP_CIPHER *des_ede = EVP_des_ede3_cbc();
    EVP_CIPHER *des_ede3 = EVP_des_ede3();
    EVP_CIPHER *des_cfb = EVP_des_cfb1();

    const char *modes[] = {
        "ECB", "EDE-CBC", "EDE3", "CFB"
    };
    int cipher_idx = -1;
    for (int i = 0; i < 4 && cipher_idx == -1; ++i) {
        if (strcmp(option, modes[i]) == 0) {
            cipher_idx = i;
        }
    }

    switch (cipher_idx) {
        case 0:
            ctx->cipher_mode = des_ecb;
            ctx->key = "your-des-key";
            break;
        case 1:
            ctx->cipher_mode = des_ede;
            ctx->key = "your-des-key";
