#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    sem_t sem_init; // Semaphore for initializing resource
    sem_t sem_lock; // Semaphore to indicate lock is held
    pthread_mutex_t mutex; // Mutex for more fine-grained locking
    bool initialized; // Flag indicating whether the resource is initialized
} Resource;

Resource* create_resource(int init_count) {
    Resource *res = malloc(sizeof(Resource));
    res->sem_init = sem_init(init_count, MUTEX, 0);
    res->sem_lock = sem_init(0, MUTEX, 1);
    pthread_mutex_init(&res->mutex, NULL);
    res->initialized = false;
    return res;
}

void init_resource(Resource *res) {
    if (res->initialized) {
        return;
    }

    sem_wait(&res->sem_init); // Wait for initialization to complete
    res->initialized = true;
    sem_post(&res->sem_lock); // Signal that lock is available
}

void destroy_resource(Resource *res) {
    if (!res || !res->initialized) {
        return;
    }

    sem_destroy(&res->sem_init);
    sem_destroy(&res->sem_lock);
    pthread_mutex_destroy(&res->mutex);
    free(res);
}

void lock(Resource *res) {
    if (!res || !res->initialized) {
        return;
    }

    // Wait for lock to become available
    sem_wait(&res->sem_lock);
    pthread_mutex_lock(&res->mutex);
}

void unlock(Resource *res) {
    if (!res || !res->initialized) {
        return;
    }

    // Signal that lock is no longer held
    pthread_mutex_unlock(&res->mutex);
    sem_post(&res->sem_lock);
}
