#include <iostream>
#include <fstream>
#include <mutex>
#include <chrono>
#include <string>
#include <sstream>
#include <thread>
#include <vector>

enum class LogLevel { DEBUG, INFO, WARN, ERROR, FATAL };

class Logger {
private:
    static std::mutex mtx;
    LogLevel level;
    std::ostream* destination;
    std::string filePath;

public:
    Logger(LogLevel lvl, std::ostream* out = &std::cout, const char* file = "") : level(lvl), destination(out) {
        if (file && level >= LogLevel::INFO) {
            this->filePath = file;
            openFile();
        }
    }

    ~Logger() {
        if (filePath.length())
            closeFile();
    }

    static void setGlobalLogLevel(LogLevel lvl) {
        std::call_once(init, [lvl]() { globalLevel = lvl; });
    }

    static LogLevel getGlobalLogLevel() {
        return globalLevel;
    }

    static void log(const char* message, const LogLevel level) {
        if (level >= globalLevel) {
            std::lock_guard<std::mutex> lock(mtx);
            auto now = std::chrono::system_clock::now().time_since_epoch().count();
            auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(now).count();
            std::stringstream ss;
            ss << ms % 1000 << " : ";
            ss << level << " : ";
            ss << message;
            (*Logger::getGlobalInstance()->destination) << ss.str() << '\n';
        }
    }

private:
    static void openFile() {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("Unable to open log file.");
        }
        destination = &std::cout.rdbuf(new std::ofbufferr_iterator<char>(file));
    }

    static void closeFile() {
        (*destination) << '\n';
        destination->rdbuf()->pubsetbuf("", 0);
        destination->flush();
        destination->close();
        destination = &std::cout;
    }

    static std::unique_ptr<Logger> globalInstance;
    static std::once_flag init;
};

std::mutex Logger::mtx;
std::unique_ptr<Logger> Logger::globalInstance;
std::once_flag Logger::init;

int main() {
    // Initialize logger with INFO level and file logging
    Logger("INFO", nullptr, "log.txt");

    // Configure global log level to WARN
    Logger::setGlobalLogLevel(Logger::WARN);

    Logger::log("This is an INFO log message.", Logger::INFO);
    Logger::log("This is a WARN log message.", Logger::WARN);
    Logger::log("This is an ERROR log message.", Logger::ERROR);

    // Create and log from another thread
    auto logThread = [this]() {
        Logger log("DEBUG");
        log.log("This is a DEBUG log message from another thread.", Logger::DEBUG);
    };
    std::thread t(logThread);
    t.join();
}
```

This code defines a `Logger` class that supports multiple log levels and has the ability to output logs to both console and file. The logger is thread-safe, using a static mutex for synchronization in multi-threaded scenarios. Error handling is included to manage file I/O operations, and potential deadlocks are avoided when logging from multiple threads by using `std::call_once` and `std::unique_ptr`. The global logging settings are managed using a static member variable and appropriate constructors and destructor methods.']

