const express = require('express');
const async = require('async');
const DataStore = require('./DataStore'); // Assume you have a data store implementation here

const router = express.Router();

router.get('/resources', (req, res) => {
  DataStore.getAllResources((err, resources) => {
    if (err) return res.status(500).send(err);
    res.json(resources);
  });
});

router.post('/resources', (req, res) => {
  const resource = req.body;
  DataStore.createResource(resource, (err, createdResource) => {
    if (err) return res.status(500).send(err);
    res.json(createdResource);
  });
});

router.put('/resources/:id', (req, res) => {
  const id = req.params.id;
  const updatedResource = req.body;
  DataStore.updateResource(id, updatedResource, (err, updatedResource) => {
    if (err) return res.status(500).send(err);
    res.json(updatedResource);
  });
});

router.delete('/resources/:id', (req, res) => {
  const id = req.params.id;
  DataStore.deleteResource(id, (err, deletedResource) => {
    if (err) return res.status(500).send(err);
    res.json(deletedResource);
  });
});

router.post('/resources/bulk', (req, res) => {
  const operations = req.body;

  async.series(operations.map((operation) => {
    if (operation.action === 'create') {
      return (cb) => DataStore.createResource(operation.resource, cb);
    } else if (operation.action === 'update') {
      return (cb) => DataStore.updateResource(operation.id, operation.resource, cb);
    } else if (operation.action === 'delete') {
      return (cb) => DataStore.deleteResource(operation.id, cb);
    }
  }), (err) => {
    if (err) return res.status(500).send(err);
    res.json({ success: true });
  });
});
