import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.io.PrintWriter;
import java.io.FileWriter;
import java.io.IOException;

public class MD5Hasher {
    private static final ConcurrentHashMap<String, BigInteger> cache = new ConcurrentHashMap<>(10_000);
    private static final String LOG_FILE = "hash_cache_errors.log";

    public static BigInteger md5(String input) throws Exception {
        input = input.trim();
        if (cache.containsKey(input)) return cache.get(input);

        MessageDigest digest;
        try {
            digest = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new Exception("No such algorithm: MD5", e);
        }

        digest.update(input.getBytes());
        BigInteger hash = new BigInteger(1, digest.digest());
        cache.putIfAbsent(input, hash);

        return hash;
    }

    public static void main(String[] args) throws Exception {
        PrintWriter logWriter = new PrintWriter(new FileWriter(LOG_FILE, true));
        try {
            for (String input : new String[]{"test", "  ", "", "\uD83D\uDC42", "abcdefghijklmnopqrstuvwxyz" + new String(new char[10000]).replace("\0", "\n"), null}) {
                System.out.printf("Hash of '%s': %s\n", input, md5(input));
            }
        } catch (Exception e) {
            logWriter.println(e.getMessage());
            throw e;
        } finally {
            logWriter.close();
        }
    }
}
```

