class DynamicLoader {
  constructor(config) {
    this.config = config;
    this.performanceMonitor = new PerformanceMonitor();
  }

  loadAndExecute(filePath, condition) {
    if (condition) {
      try {
        const fileContent = fs.readFileSync(path.resolve(__dirname, filePath), 'utf8');
        this.performanceMonitor.startTimer(filePath);
        // Use eval to execute the loaded code but wrap it in a function to avoid global pollution
        (() => { eval(`(${fileContent})`) })();
        this.performanceMonitor.stopTimer(filePath);
      } catch (error) {
        logger.error(`Error while loading and executing ${filePath}:`, error);
      }
    }
  }
}

module.exports = DynamicLoader;
