import java.lang.System;

public class GeoTriangles {
    static long startTime;
    public static int countTriangularRegions(List<Coordinate> points) {
        if (points.size() < 3) return 0;
        Collections.sort(points, Comparator.comparingDouble(p -> p.latitude));
        Set<Long> hashValues = new HashSet<>();
        Map<Long, Integer> pointCounts = new HashMap<>();
        for (Coordinate point : points) {
            hashValues.add(TriangleHashCode.getHashCode(point.latitude, point.longitude));
            pointCounts.merge(hashValues.size(), point.count, Integer::sum);
        }
        int count = 0;
        for (Map.Entry<Long, Integer> entry : pointCounts.entrySet()) {
            long hashCode = entry.getKey();
            int countAtHashCode = entry.getValue();
            if (countAtHashCode >= 3) {
                int regionsAtHashCode = (int) Math.floorDiv(countAtHashCode, 3);
                count += regionsAtHashCode * (regionsAtHashCode - 1) / 2;
            }
        }
        return count;
    }

    static class Coordinate {
        double latitude;
        double longitude;
        int count = 1;

        public Coordinate(double latitude, double longitude) {
            this.latitude = latitude;
            this.longitude = longitude;
        }
    }

    static class TriangleHashCode {
        private static final String DELIM = ",";
        private static final int PRIME = 1000003;

        public static long getHashCode(double lat, double lon) {
            return hashPoints(lat + DELIM, lon);
        }

        private static long hashPoints(String... points) {
            long result = 1;
            for (String point : points) {
                result = (result * PRIME + point.hashCode()) % PRIME;
            }
            return result;
        }
    }

    public static void main(String[] args) throws Exception {
        List<Coordinate> points = new ArrayList<>();
        // Add your test points here
        for (int i = 0; i < 10_000; i++) {
            double lat = ThreadLocalRandom.current().nextDouble(-90, 90);
            double lon = ThreadLocalRandom.current().nextDouble(-180, 180);
            points.add(new Coordinate(lat, lon));
        }
        startTime = System.nanoTime();
        int triangularRegions = countTriangularRegions(points);
        long timeTakenInMillis = TimeUnit.MILLISECONDS.convert((System.nanoTime() - startTime), TimeUnit.NANOSECONDS);
        System.out.printf("Number of non-overlapping triangular regions: %d%nExecution time (ms): %d%n", triangularRegions, timeTakenInMillis);
    }
}
