import java.nio.channels.*;
import java.util.*;
import java.net.InetSocketAddress;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import java.nio.channels.SelectableChannel;
import java.io.IOException;

public class ConnectionPool {
    private final ExecutorService poolExecutor;
    private final ScheduledExecutorService scheduler;
    private final BlockingQueue<SelectionKey> queue = new LinkedBlockingQueue<>();
    private final Map<Integer, SelectionKey> activeConnections = new ConcurrentHashMap<>();
    private final ReentrantLock lock = new ReentrantLock();
    private final int maxPoolSize;
    private final int connectionTimeoutMillis;
    private final TimeUnit timeUnit;

    public ConnectionPool(int maxPoolSize, int connectionTimeoutMillis, TimeUnit timeUnit) {
        this.maxPoolSize = maxPoolSize;
        this.connectionTimeoutMillis = connectionTimeoutMillis;
        this.timeUnit = timeUnit;
        poolExecutor = Executors.newFixedThreadPool(maxPoolSize);
        scheduler = Executors.newScheduledThreadPool(1);
    }

    public SelectionKey acquireConnection() throws InterruptedException, IOException {
        lock.lock();
        try {
            SelectionKey key = queue.poll(connectionTimeoutMillis, timeUnit);
            if (key != null) {
                activeConnections.put(key.hashCode(), key);
                return key;
            }
            if (queue.size() < maxPoolSize && !poolExecutor.isShutdown()) {
                SelectionKey key = createConnection();
                queue.offer(key, connectionTimeoutMillis, timeUnit);
                activeConnections.put(key.hashCode(), key);
                return key;
            }
        } finally {
            lock.unlock();
        }
        throw new NoSuchElementException("No available connections");
    }

    public void releaseConnection(SelectionKey key) throws IOException {
        if (activeConnections.remove(key.hashCode()) != null) {
            queue.put(key);
        } else {
            throw new IllegalArgumentException("Connection not in use or already released");
        }
    }

    private SelectionKey createConnection() throws IOException {
        Selector selector = Selector.open();
        SocketChannel socketChannel = SocketChannel.open(new InetSocketAddress("remote-address", 80));
        socketChannel.configureBlocking(false);
        socketChannel.register(selector, SelectionKey.OP_CONNECT);
        socketChannel.register(selector, SelectionKey.OP_READ);
        return selector.register(poolExecutor, selector.keyFor(socketChannel), null);
    }

    private void manageIdleConnections() {
        scheduler.scheduleAtFixedRate(() -> {
            lock.lock();
            try {
                Selector selector = null;
                SelectionKey keyToRemove = null;
                Iterator<Map.Entry<Integer, SelectionKey>> iter = activeConnections.entrySet().iterator();
                while (iter.hasNext()) {
                    Map.Entry<Integer, SelectionKey> entry = iter.next();
                    SelectionKey key = entry.getValue();
                    selector = key.attachment();
                    if (!selector.selectNow()) continue;
                    SelectableChannel channel = key.channel();
                    if (channel.isConnected() && !channel.validOps(SelectionKey.OP_READ)) {
                        iter.remove();
                        keyToRemove = key;
                    }
                }
                if (keyToRemove != null) releaseConnection(keyToRemove);
            } finally {
                lock.unlock();
            }
        }, connectionTimeoutMillis, connectionTimeoutMillis, TimeUnit.MILLISECONDS);
    }
}
