    public string Name { get; set; }
    public string City { get; set; }
    public string Address { get; set; }
    public int SupervisorId { get; set; }
}

public class EmployeesContext : DbContext
{
    public DbSet<Employee> Employees { get; set; }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        => optionsBuilder.UseSqlServer(ConfigurationManager.ConnectionStrings["DefaultConnection"]);
}

public static async Task<IEnumerable<Employee>> GetEmployeesBySupervisorIdAsync(int supervisorId, int pageSize, int pageIndex)
{
    using var context = new EmployeesContext();
    int skip = pageSize * pageIndex;
    var query = context.Employees
        .Where(e => e.SupervisorId == supervisorId)
        .AsQueryable();

    return await query.Skip(skip).Take(pageSize).ToListAsync();
}
