<?php

class Weather {
    private $apiKey;
    private $cacheFile;
    private $cacheExpiry = 60 * 5; // Cache expires in 5 minutes (in seconds)

    public function __construct($apiKey, $cacheFile) {
        $this->apiKey = $apiKey;
        $this->cacheFile = $cacheFile;
    }

    private function getCache() {
        if (file_exists($this->cacheFile)) {
            return json_decode(file_get_contents($this->cacheFile), true);
        }
        return [];
    }

    public function fetchWeatherData($location) {
        $data = $this->getCache();

        if (isset($data['location']) && isset($data['timestamp']) && (time() - $data['timestamp']) < $this->cacheExpiry) {
            return $data;
        }

        try {
            $response = file_get_contents("https://api.openweathermap.org/data/2.5/weather?q=$location&appid=$this->apiKey");
            if ($response === false) {
                throw new Exception('API request failed');
            }

            $decodedResponse = json_decode($response, true);
            if (!isset($decodedResponse['cod']) || $decodedResponse['cod'] != 200) {
                throw new Exception("Invalid response from API: " . $decodedResponse['message']);
            }

            file_put_contents($this->cacheFile, json_encode([
                'location' => $location,
                'timestamp' => time(),
                'data' => $decodedResponse
            ]));

            return $decodedResponse;
        } catch (Exception $e) {
            return [
                'error' => true,
                'message' => $e->getMessage()
            ];
        }
    }

    public function invalidateCache($location = null) {
        if ($location === null || !file_exists($this->cacheFile)) {
            unlink($this->cacheFile);
        } else {
            file_put_contents($this->cacheFile, '');
        }
    }
}
