#include <vector>
#include <memory>
#include <mutex>
#include <cassert>
#include <new>
#include <type_traits>

struct OctreeNode {
    std::array<OctreeNode*, 8> children; // Lazy initialization
    int dataCapacity;                     // Capacity to store additional metadata or attributes
    std::vector<void*> data;             // Data associated with the node
    double center;                       // Center of the bounding box
    bool isLeaf;                          // Flag indicating whether the node stores data directly
};

class Octree {
private:
    static const int MAX_DEPTH = 25;        // Maximum depth of the octree
    std::unique_ptr<OctreeNode> root_;      // Root node of the octree
    mutex mtx_;                             // Mutex for thread safety

public:
    Octree(int initialCapacity, int dataCapacity);
    void insert(const Eigen::Vector3d& point, const void* data);
    std::vector<void*> query(const Eigen::Vector3d& point, double radius) const;
    // ... Other necessary functions for spatial database integration and error handling ...
};

Octree::Octree(int initialCapacity, int dataCapacity) : root_(std::make_unique<OctreeNode>()) {
    root_->dataCapacity = dataCapacity;
    root_.get()->isLeaf = false;
    // Initialize the center and recursively allocate child nodes if necessary
}

void Octree::insert(const Eigen::Vector3d& point, const void* data) {
    std::lock_guard<std::mutex> lock(mtx_);

    auto node = root_.get();
    for (int depth = 0; depth < MAX_DEPTH; ++depth) {
        int childIndex = findChildIndex(node->center, point);
        if (!node->children[childIndex]) { // Lazy initialization
            if (depth == MAX_DEPTH - 1) { // Leaf node reached
                node->children[childIndex] = std::make_unique<OctreeNode>();
                node->children[childIndex]->dataCapacity = dataCapacity;
                node->children[childIndex]->isLeaf = true;
            } else {
                node = node->children[childIndex].get();
            }
        }
    }

    auto leafNode = reinterpret_cast<OctreeNode*>(std::addressof(node->children[childIndex]));
    assert(leafNode->isLeaf);

    if (leafNode->data.size() < leafNode->dataCapacity) { // Batch processing
        leafNode->data.emplace_back(data);
    } else {
        // Handle memory overflow and reallocation of the octree here
    }
}

std::vector<void*> Octree::query(const Eigen::Vector3d& point, double radius) const {
    std::lock_guard<std::mutex> lock(mtx_);

    auto node = root_.get();
    std::vector<void*> results;

    for (int depth = 0; depth < MAX_DEPTH; ++depth) {
        int childIndex = findChildIndex(node->center, point);
        if (node->children[childIndex]) {
            node = node->children[childIndex].get();
        } else {
            break; // Query has left the octree region
        }
    }

    if (!node || depth == MAX_DEPTH) return results; // No matching nodes found

    const auto& leafData = node->data;

    for (const auto& data : leafData) {
        double distanceSquared = (point - Eigen::Vector3d(leafNode->center)).squaredNorm();
        if (distanceSquared <= radius * radius) results.emplace_back(data);
    }

    return results;
}
```

This implementation uses lazy initialization for the octree nodes, thread safety through a mutex, and dynamic memory allocation to handle varying load conditions efficiently. It also incorporates data capacity constraints and batch processing during bulk insertion to optimize performance.

For error handling, the code snippet includes assert statements for invalid node states and potential overflow scenarios, but more robust mechanisms should be added to ensure proper exception handling and logging.

The implementation above is a starting point and requires further testing, optimization, and integration with external systems according to your specific requirements.']

