void process_transaction(GlobalData *data, int user_id, double amount, double weight) {
    time_t current_time = time(NULL);

    if (current_time - data->users[user_id].last_transaction_time > 10)
        return;

    double weighted_amount = amount * data->users[user_id].weight_factor;

    if (weighted_amount <= 0 || data->users[user_id].num_transactions_5s >= 3)
        return;

    data->users[user_id].moving_avg_sum += weighted_amount;
    data->users[user_id].num_transactions_5s++;
    data->users[user_id].last_transaction_time = current_time;

    pthread_mutex_lock(&data->mutex);
    if (weighted_amount > data->users[user_id].max_10s)
        data->users[user_id].max_10s = weighted_amount;
    data->total_volume += amount;
    pthread_mutex_unlock(&data->mutex);
}

void update_moving_avg(UserData *ud, double new_value) {
    if (ud->num_transactions_10 < 10) {
        ud->moving_avg_sum = new_value;
        ud->num_transactions_10++;
    } else {
        double avg = ud->moving_avg_sum - ud->transaction_10[ud->num_transactions_10 - 1] + new_value;
        for (int i = 9; i > 0; i--)
            ud->transaction_10[i] = ud->transaction_10[i - 1];
        ud->transaction_10[0] = new_value;
        ud->moving_avg_sum = avg;
    }
}

UserData find_highest_user(GlobalData *data) {
    UserData highest_user = data->users[0];
    for (size_t i = 1; i < data->users_count; i++) {
        if (data->users[i].max_10s > highest_user.max_10s)
            highest_user = data->users[i];
    }
    return highest_user;
}

void init(GlobalData *data, int users_count) {
    data->users = malloc(sizeof(UserData) * users_count);
    for (int i = 0; i < users_count; i++) {
        data->users[i].user_id = i;
        data->users[i].weight_factor = 1.0; // Replace with user-specific weight factor
        data->users[i].threshold = 10.0; // Replace with predefined threshold
        data->users[i].moving_avg_sum = 0.0;
        data->users[i].num_transactions_5s = 0;
        data->users[i].last_transaction_time = 0;
        data->users[i].max_10s = -INT_MAX; // Initialize to a minimum value
    }
    data->users_count = users_count;
    pthread_mutex_init(&data->mutex, NULL);
}

void cleanup(GlobalData *data) {
    free(data->users);
    pthread_mutex_destroy(&data->mutex);
