#include <chrono>
#include <random>
#include <functional>
#include <thread>

struct AttackResource {
    int resources = 50;
    int cooldown = 9;

    bool canAttack() const {
        if (cooldown > 0) return false;
        if (resources == 0) return false;
        return true;
    }

    void consumeResource() {
        if (resources > 0) --resources;
    }

    void resetCooldown() {
        cooldown = 9;
    }
};

void selectAttack(AttackResource& resource, std::function<bool()> restoreResourcesCallback) {
    std::mt19937 rng(std::random_device{}());
    std::uniform_int_distribution<> distribution(0, 1);
    bool canAttack = false;

    while (!canAttack) {
        if (resource.canAttack()) {
            canAttack = true;
        } else {
            if (restoreResourcesCallback()) {
                resource.resources = std::min(resource.resources + 5, 50);
                if (resource.resources == 50) resource.cooldown = 9 * 0.8; // Reduce cooldown by 20% when fully restored
            } else {
                int remainingTime = std::chrono::duration_cast<std::chrono::seconds>(30s - std::chrono::system_clock::now().time_since_epoch()).count();
                if (remainingTime > 0) {
                    std::this_thread::sleep_for(std::chrono::seconds(remainingTime));
                }
            }
        }
    }

    resource.consumeResource();
    std::cout << "Attack selected: " << distribution(rng) + 1 << '\n';
    resource.resetCooldown();
}
