using System;

namespace RandomValueGenerator
{
    public class RandomValueGenerator
    {
        private (int min, int max) currentRange;

        public (int MinValue, int MaxValue) CurrentRange
        {
            get => currentRange;
            set
            {
                if (value.min >= value.max || value.min < int.MinValue || value.max > int.MaxValue)
                    throw new ArgumentOutOfRangeException(nameof(value), "The provided range is invalid.");

                currentRange = value;
            }
        }

        public float GetRandomFloat()
        {
            if (currentRange.min == currentRange.max) return currentRange.min;

            var random = new Random();
            return currentRange.min + (float)random.NextDouble() * (currentRange.max - currentRange.min);
        }

        public int GetRandomInt()
        {
            if (currentRange.min == currentRange.max) return currentRange.min;

            var random = new Random();
            return currentRange.min + random.Next(currentRange.max - currentRange.min);
        }

        public RandomValueGenerator(int minValue, int maxValue) => CurrentRange = (minValue, maxValue);

        public void UpdateRange(int newMin, int newMax)
        {
            if (newMin >= newMax || newMin < int.MinValue || newMax > int.MaxValue)
                throw new ArgumentOutOfRangeException(nameof((int, int) newRange), "The provided range is invalid.");

            currentRange = (newMin, newMax);
        }

        public override string ToString() => $"[{CurrentRange.MinValue}, {CurrentRange.MaxValue})";
    }
}
