const asyncReduce = (numbers, initialValue, callback, retries = 3, delay = 1000) => {
  let currentValue = initialValue;
  const updateValue = (partialSum, number) =>
    axios.get(`https://api.example.com/reduce/${number}`) // Adjust this URL to match your data source
      .then(res => callback(currentValue, res.data))
      .catch(err => {
        if (retries > 0) {
          setTimeout(() => updateValue(partialSum, number), delay * Math.pow(2, retries));
          console.error(`Error processing number ${number}: ${err.message}`);
          retries--;
        } else {
          throw new Error(`Failed to process number ${number}: ${err.message}`);
        }
      });

  numbers.forEach(updateValue, [initialValue]); // Initialize with initial value and start the reduction process
};

