#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char* append_special_char(const char *str, size_t limit, bool append) {
    if (!str || !limit || limit <= 0) {
        return NULL;
    }

    size_t len = strlen(str);

    if (len > limit) {
        return NULL;
    }

    char *result = malloc(len + (append && len < limit ? 2 : 0));
    if (!result) {
        return NULL;
    }

    memcpy(result, str, len);
    if (append && len < limit) {
        result[len] = '/';
        result[len + 1] = '\0';
    }

    return result;
}
