char* update_filename(const char *original) {
    size_t len = strlen(original);
    if (len > 255) return NULL; // Max filename length is 255 characters

    size_t base_name_len = original + strlen(original) - strrchr(original, '.') - 1;
    char base_name[6]; // Pad the base name with zeros to have 5 digits
    memset(base_name, '0', 6);
    memcpy(base_name + (5 - base_name_len), original + base_name_len, base_name_len);

    char new_ext[19]; // Timestamp extension with format YYYYMMDDHHMMSS
    snprintf(new_ext, sizeof(new_ext), "%04d%02d%02d%02d%02d%02d",
             localtime(&time(NULL))->tm_year + 1900,
             localtime(&time(NULL))->tm_mon + 1,
             localtime(&time(NULL))->tm_mday,
             localtime(&time(NULL))->tm_hour,
             localtime(&time(NULL))->tm_min,
             localtime(&time(NULL))->tm_sec);

    size_t new_len = len + strlen(new_ext) - 1; // Subtract one for the original dot
    if (new_len > 255) return NULL; // Ensure the filename doesn't exceed 255 characters

    char *result = malloc(new_len + 1); // Allocate memory for the new filename plus a null terminator
    if (!result) return NULL;

    snprintf(result, new_len + 1, "%s.%s", base_name, new_ext);
    return result;
}
