int create_directory_structure(char *input, char *target_dir, char *output_file) {
    char path[PATH_MAX];
    int len = strlen(target_dir);
    snprintf(path, sizeof(path), "%s", target_dir);

    char curr_path[PATH_MAX];
    memset(curr_path, 0, sizeof(curr_path));
    strncpy(curr_path, path, len);

    int i = 0;
    char *token = strtok(input, "/");
    while (token != NULL) {
        if (strlen(token) == 1 && *(token) == '*') { // file creation
            snprintf(path + strlen(curr_path), sizeof(path) - strlen(curr_path), "/%s", token);
            mkdir(curr_path) == -1 ? return 1 : 0;
            FILE *file = fopen(path, "w");
            if (file != NULL) {
                fclose(file);
                snprintf(path, sizeof(path), "%s", curr_path);
            } else {
                return 1;
            }
        } else { // directory creation
            snprintf(path + strlen(curr_path), sizeof(path) - strlen(curr_path), "/%s", token);
            mkdir(path, S_IRWXU | S_IRGRP | S_IROTH | S_IXGRP | S_IXOTH) == -1 ? return 1 : 0;
            snprintf(path, sizeof(path), "%s", curr_path + strlen(curr_path) + strlen(token) + 1);
        }

        token = strtok(NULL, "/");
        i++;
    }

    // create the final output file
    snprintf(path + strlen(curr_path), sizeof(path) - strlen(curr_path), "/%s", output_file);
    FILE *file = fopen(path, "w");
    if (file != NULL) {
        fclose(file);
        return 0;
    } else {
        return 1;
