using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;
using IWebHostBuilder = Microsoft.AspNetCore.Hosting.IWebHostBuilder;

namespace WebsiteDeployer
{
    public class DeploymentManager
    {
        private readonly ILogger<DeploymentManager> _logger;
        private readonly object _lockObject = new object();
        private readonly int _maxConcurrentDeploys;

        public DeploymentManager(ILogger<DeploymentManager> logger, int maxConcurrentDeploys)
        {
            _logger = logger;
            _maxConcurrentDeploys = maxConcurrentDeploys;
        }

        public async Task<WebHostBuilderContext?> StartWebsiteAsync(string directoryPath)
        {
            if (!Directory.Exists(directoryPath))
            {
                _logger.LogError($"The specified directory '{directoryPath}' does not exist.");
                return null;
            }

            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                _logger.LogInformation($"The specified directory '{directoryPath}' does not contain a 'web.config' file.");
                return null;
            }

            lock (_lockObject)
            {
                var activeDeploys = Interlocked.Add(1, _maxConcurrentDeploys < 0 ? _maxConcurrentDeploys : _maxConcurrentDeploys - 1);
                if (activeDeploys >= _maxConcurrentDeploys)
                {
                    var waitingDeploys = Interlocked.Increment(ref _waitingDeploys);
                    await Task.Delay(TimeSpan.FromMilliseconds(500)); // Wait for a slot to become available
                    if (activeDeploys < _maxConcurrentDeploys)
                    {
                        Interlocked.Decrement(ref _waitingDeploys);
                    }
                }
            }

            if (activeDeploys >= _maxConcurrentDeploys) return null;

            var webHostBuilder = new WebHostBuilder()
                .UseContentRoot(directoryPath)
                .UseStartup<Startup>();

            try
            {
                using var host = webHostBuilder.Build();
                host.Run();

                return host.GetServices<IWebHostBuilder>().OfType<IWebHostEnvironment>().FirstOrDefault()?.CreateWebHostBuilderContext();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"An error occurred while starting the website in directory '{directoryPath}': {ex.Message}");
            }
            finally
            {
                lock (_lockObject)
                {
                    Interlocked.Decrement(ref activeDeploys);
                }
            }

            return null;
        }

        private int _waitingDeploys = 0;
    }
}
```

