import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Properties;

public class Main {
    public static void main(String[] args) throws IOException, InterruptedException {
        Properties properties = new Properties();
        properties.load(Main.class.getClassLoader().getResourceAsStream("config.properties"));

        ConcurrentCommandExecutor executor = new ConcurrentCommandExecutor(properties);
        String command = "your-command-here";
        File fileToDelete = Paths.get("/path/to/the/file").toFile();
        executor.executeCommand(command, fileToDelete);
    }
}
