#include <pthread.h>

static pthread_mutex_t json_mutex = PTHREAD_MUTEX_INITIALIZER;

bool is_valid_oauth2_token(const char *json_str) {
    json_t *root, *access_token, *expires_in, *token_type, *refresh_token;
    int expires_in_int = 0;
    const char *token_type_str = NULL;
    char *refresh_token_base64 = NULL;
    bool is_valid = true;

    pthread_mutex_lock(&json_mutex);
    root = json_loads(json_str, 0, NULL);
    pthread_mutex_unlock(&json_mutex);

    if (!root) {
        fprintf(stderr, "JSON is malformed.\n");
        return false;
    }

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");
    refresh_token = json_object_get(root, "refresh_token");

    if (!access_token || !json_is_string(access_token)) {
        fprintf(stderr, "Missing or invalid access_token field.\n");
        is_valid = false;
    }

    if (!expires_in || !json_is_integer(expires_in) || expires_in_int < 0) {
        fprintf(stderr, "Invalid or missing expires_in field.\n");
        is_valid = false;
    } else {
        expires_in_int = json_integer_value(expires_in);
    }

    if (token_type && !json_is_string(token_type)) {
        fprintf(stderr, "Invalid token_type field.\n");
        is_valid = false;
    } else {
        token_type_str = json_string_value(token_type);
        if (strcmp(token_type_str, "Bearer") != 0) {
            fprintf(stderr, "Deprecated or non-standard token_type: %s\n", token_type_str);
        }
    }

    if (refresh_token) {
        if (!json_is_string(refresh_token)) {
            fprintf(stderr, "Invalid refresh_token field.\n");
            is_valid = false;
        } else {
            refresh_token_base64 = json_string_value(refresh_token);
            if (!Base64_decode_init(NULL, 0) || !Base64_valid(refresh_token_base64, strlen(refresh_token_base64))) {
                fprintf(stderr, "Invalid refresh_token base64 encoding.\n");
                is_valid = false;
            } else {
                Base64_decode_end();
            }
        }
    }

    json_decref(root);

    return is_valid;
}
```

