using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Net;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

public async Task<Dictionary<string, string>> UploadCompressedData(byte[] data)
{
    var compressedData = CompressByteArray(data);

    using (var httpClient = new HttpClient())
    {
        var uploadRequest = new HttpRequestMessage(HttpMethod.Post, "https://yourcloudstorageurl.com/upload");
        uploadRequest.Content = new StreamContent(new MemoryStream(compressedData));

        try
        {
            var response = await httpClient.SendAsync(uploadRequest);
            response.EnsureSuccessStatusCode();

            var responseMetadataJson = await response.Content.ReadAsStringAsync();
            return JObject.Parse(responseMetadataJson).ToObject<Dictionary<string, string>>();
