using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Amazon.S3;
using Amazon.S3.Model;
using Newtonsoft.Json;

namespace LogProcessor
{
    public class Configuration
    {
        public string EncryptionKey { get; set; }
        public string Iv { get; set; }
        public string SortKey { get; set; }
        public string ConfigFilePath { get; set; }
    }

    public class LogEntry
    {
        public int SequenceNumber { get; set; }
        public string Line { get; set; }
    }

    public class Program
    {
        static void Main(string[] args)
        {
            try
            {
                var config = LoadConfiguration();
                var sequenceNumber = DecryptAndProcessLogFile(config);
                Console.WriteLine($"Last sequence number: {sequenceNumber}");
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error: {ex.Message}");
            }
        }

        private static Configuration LoadConfiguration()
        {
            var configJson = File.ReadAllText("config.json");
            return JsonConvert.DeserializeObject<Configuration>(configJson);
        }

        private static string DecryptAndProcessLogFile(Configuration config)
        {
            using (var s3Client = new AmazonS3Client())
            {
                var request = new GetObjectRequest
                {
                    BucketName = "my-bucket",
                    Key = "log.enc"
                };

                using (var memoryStream = new MemoryStream())
                {
                    s3Client.GetObject(request, memoryStream);
                    var decryptedData = Decrypt(memoryStream.ToArray(), config.EncryptionKey, config.Iv);
                    return ProcessSortedData(decryptedData, config.SortKey);
                }
            }
        }

        private static byte[] Decrypt(byte[] encryptedData, string key, string iv)
        {
            using (var des = TripleDES.Create())
            {
                des.Key = Encoding.ASCII.GetBytes(key);
                des.IV = Encoding.ASCII.GetBytes(iv);

                var encryptedTripleDes = new TripleDESCryptoServiceProvider();
                encryptedTripleDes.Mode = CipherMode.CBC;
                encryptedTripleDes.Padding = PaddingMode.PKCS7;

                using (var msEncrypt = new MemoryStream(encryptedData))
                {
                    using (var msDecrypt = new MemoryStream())
                    {
                        using (var cs = new CryptoStream(msEncrypt, encryptedTripleDes.CreateDecryptor(), CryptoStreamMode.Read))
                        {
                            cs.CopyTo(msDecrypt);
                            return msDecrypt.ToArray();
                        }
                    }
                }
            }
        }

        private static string ProcessSortedData(byte[] data, string sortKey)
        {
            var logEntries = new List<LogEntry>();
            using (var reader = new StreamReader(new MemoryStream(data)))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    var parts = line.Split(':');
                    logEntries.Add(new LogEntry { SequenceNumber = int.Parse(parts[0]), Line = parts[1] });
                }
            }

            logEntries.Sort((x, y) => x.SequenceNumber.CompareTo(y.SequenceNumber));

            return logEntries.Last().SequenceNumber.ToString();
        }
    }
}
