using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;

namespace LogProcessingService
{
    public class LogProcessor
    {
        private readonly IDistributedCache _cache;
        private readonly ILogger<LogProcessor> _logger;
        private readonly MD5 _md5Hasher = MD5.Create();

        public LogProcessor(IDistributedCache cache, ILogger<LogProcessor> logger)
        {
            _cache = cache;
            _logger = logger;
        }

        public void ProcessLogs(IEnumerable<LogEntry> logEntries)
        {
            var tasks = new List<Task>();

            foreach (var entry in logEntries)
            {
                tasks.Add(ProcessLogAsync(entry));
            }

            Task.WhenAll(tasks).ContinueWith(_ =>
            {
                // Log the total processed count at the end for auditing purposes.
                _logger.LogInformation($"Total log entries processed: {logEntries.Count()}");
            });
        }

        private async Task ProcessLogAsync(LogEntry entry)
        {
            try
            {
                var messageBodyHash = ComputeMD5Hash(entry.Message);
                var serializedData = JsonConvert.SerializeObject(new { Id = entry.Id, Hash = messageBodyHash },
                    new DefaultContractResolver
                    {
                        NamingStrategy = new SnakeCaseNamingStrategy()
                    });

                await _cache.SetAsync(CreateCacheKey(entry), serializedData);
            }
            catch (Exception ex)
            {
                // Log the error for further investigation and retry if applicable.
                _logger.LogError(ex, $"Failed to process log entry: {entry}");
            }
        }

        private static string CreateCacheKey(LogEntry entry) => $"log:{entry.Id}:hash";

        private byte[] ComputeMD5Hash(string data)
        {
            var hashedData = _md5Hasher.ComputeHash(Encoding.UTF8.GetBytes(data));
            return new byte[hashedData.Length];
        }
    }

    public class LogEntry
    {
        public Guid Id { get; set; }
        public string Message { get; set; }
    }
}
```
