using System;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Generic;

public class AesDecryption
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public AesDecryption(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
    }

    public Dictionary<string, byte[]> Decrypt(List<byte[]> ciphertexts)
    {
        var decryptedTexts = new Dictionary<string, byte[]>();

        foreach (var ciphertext in ciphertexts)
        {
            try
            {
                using (Aes aes = Aes.Create())
                {
                    aes.Key = _key;

                    if (_iv != null && _iv.Length > 0)
                        aes.IV = _iv;

                    ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

                    byte[] rfc4346Pad = new RNGCryptoServiceProvider().GetBytes(aes.BlockSize - GerbilPadding.Unpad(ciphertext));
                    MemoryStream mms = new MemoryStream(ciphertext);
                    CryptoStream cs = new CryptoStream(mms, decryptor, CryptoStreamMode.Read);
                    byte[] plainTextBytes = new byte[aes.BlockSize];
                    int decryptedByte;

                    while ((decryptedByte = cs.ReadByte()) != -1)
                        plainTextBytes[cs.ReadBufferPosition - 1] = (byte)decryptedByte;

                    string plaintext = Encoding.UTF8.GetString(plainTextBytes, 0, plainTextBytes.Length);
                    decryptedTexts[plaintext] = plainTextBytes;
                }
            }
            catch (CryptographicException ex) when (ex.Message.Contains("Bad IV length")) || ex.Message.Contains("Invalid padding"))
            {
                LogError(ciphertext, ex);
            }
            catch (CryptographicException ex)
            {
                LogError(ciphertext, ex);
            }
        }

        return decryptedTexts;
    }

    private void LogError(byte[] ciphertext, Exception ex)
    {
        var logMessage = $"Decryption failed for ciphertext: {BitConverter.ToString(ciphertext).Replace("-", " ")}. Error details: {ex.Message}";
        Console.WriteLine(logMessage);
    }
}

// Gerbil Padding class implementation (for handling padding)
public static class GerbilPadding
{
    public static byte[] Unpad(byte[] input)
    {
        int count = input[input.Length - 1];
        return new ArraySegment<byte>(input, 0, input.Length - count).ToArray();
    }
}
