using System;
using System.IO;
using System.IO.Compression;
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;

public T LoadFromCompressedFile<T>(string filePath) where T : new()
{
    if (string.IsNullOrWhiteSpace(filePath)) throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));

    using var stream = File.OpenRead(filePath);

    string extension = Path.GetExtension(filePath).ToLowerInvariant();

    switch (extension)
    {
        case ".gz":
            using var gzStream = new GzipStream(stream, CompressionMode.Decompress);
                return JsonSerializer.Deserialize<T>(new StreamReader(gzStream));
        case ".zip":
            using var zipArchive = new ZipArchive(stream, ZipArchiveMode.Read);
            var jsonEntry = zipArchive.GetEntry("data.json");

            if (jsonEntry == null) throw new FileNotFoundException("Data file not found.", filePath);

            using var jsonStream = jsonEntry.Open() ;
                return JsonSerializer.Deserialize<T>(new StreamReader(jsonStream));
        default:
            throw new NotSupportedException($"Unsupported compression format for '{extension}'.");
    }
}
