use std::env;
use std::fs::{self, create_dir_all, remove_dir_all};
use std::io::{BufWriter, Write};
use tempfile::NamedTempFile;
use uuid::Uuid;
use time::SystemTime;
use serde_json as json;
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Debug)]
struct Config {
    timestamp: i64,
    uuid: String,
}

fn project_config_dir() -> Result<String, Box<dyn std::error::Error> {
    let config_dir = env::var("PROJECT_CONFIG_DIR")?;
    if !fs::metadata(config_dir).is_ok() || !fs::read_link(&config_dir).is_err() {
        fs::create_dir_all(&config_dir)?;
    }
    Ok(config_dir)
}

fn new_project_config_dir() -> Result<String, Box<dyn std::error::Error> {
    let mut config_dir = project_config_dir()?;
    if fs::metadata(&config_dir).is_err() {
        let tempfile = NamedTempFile::new("configs")?.into_temp_path();
        config_dir = tempfile.parent().unwrap().to_string_lossy();
        create_dir_all(config_dir)?;
    }
    let mut unique_counter = 0;
    let mut current_dir = config_dir.clone() + "/";
    loop {
        let timestamp = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH)?.as_secs();
        let uuid = Uuid::new_v4().to_string();
        let candidate_path = format!("{}/{}{}_{}", current_dir, timestamp, uuid);
        if !fs::metadata(&candidate_path).is_err() {
            unique_counter += 1;
            continue;
        }
        current_dir += "/";
        if unique_counter > 64 {
            return Err(format!("Failed to create a unique project configuration directory due to system constraints.").into());
        }
    }
    let new_dir = format!("{}/{}", config_dir, Config { timestamp, uuid }.to_string()).serialize_json_obj()?.write_pretty::<BufWriter<std::io::File>>(&fs::file(new_dir).unwrap())?;
    env::set_var("PROJECT_CONFIG_DIR", &config_dir);
    Ok(config_dir)
}

fn main() {
    match new_project_config_dir() {
        Ok(_) => println!("Created or verified project configuration directory: {}", env::var("PROJECT_CONFIG_DIR").unwrap()),
        Err(e) => eprintln!("Failed to create or verify project configuration directory: {}", e),
    }
}
```

