typedef struct {
    char *method;
    void (*handler)(struct request_data*);
} handler_t;

typedef struct ip_rate_limit {
    unsigned long ip[3600]; // an array to store requests per minute for each IP
    unsigned int max_requests;
} ip_rate_limit_t;

struct request_data {
    char *method;
    Json_object *headers;
    Json_object *body;
    handler_t* handlers[5]; // array to store handlers for each supported method
    ip_rate_limit_t* rate_limiter;
};

void get_handler(struct request_data* req_data) {
    // Implementation for GET method
}

void post_handler(struct request_data* req_data) {
    if (req_data->headers->count["Content-Type"] != json_obj_key_exists(req_data->headers, "Content-Type") ||
        strcmp(req_data->headers->val[json_obj_get_item(req_data->headers, "Content-Type")], "application/json") != 0) {
        return;
    }

    Json_object* json = json_tokener_parse_ex(req_data->body->str, req_data->body->len, JSON_TOKENER_PARSE_RETURN_INPUT);
    if (!json || !json_object_is_valid(json)) {
        return;
    }

    // Validate JSON schema here

    // Continue with the request processing
}

void put_handler(struct request_data* req_data) {
    // Implementation for PUT method
}

void delete_handler(struct request_data* req_data) {
    // Implementation for DELETE method
}

void head_handler(struct request_data* req_data) {
    // Implementation for HEAD method
}

void register_handler(struct request_data *req_data, const char *method, void (*handler)(struct request_data*)) {
    int index = -1;
    switch (method[0]) {
        case 'G': index = 0; break;
        case 'P': index = 1; break;
        case 'U': index = 2; break;
        case 'D': index = 3; break;
        case 'H': index = 4; break;
    }
    if (index != -1) {
        req_data->handlers[index] = malloc(sizeof(handler_t));
        req_data->handlers[index]->method = strdup(method);
        req_data->handlers[index]->handler = handler;
    }
}

void unregister_handler(struct request_data *req_data, const char *method) {
    int index = -1;
    switch (method[0]) {
        case 'G': index = 0; break;
        case 'P': index = 1; break;
        case 'U': index = 2; break;
        case 'D': index = 3; break;
        case 'H': index = 4; break;
    }
    if (index != -1) {
        free(req_data->handlers[index]->method);
        free(req_data->handlers[index]);
        req_data->handlers[index] = NULL;
    }
}

struct request_data* handle_request(const char *headers, const char *body) {
    struct request_data* req_data = malloc(sizeof(struct request_data));
    memset(req_data, 0, sizeof(struct request_data));

    Json_object* headers_obj = json_tokener_parse(headers);
    if (!headers_obj || !json_object_is_valid(headers_obj)) {
        free(req_data);
        return NULL;
    }

    req_data->headers = headers_obj;
    req_data->body = json_tokener_parse_ex(body, body ? strlen(body) : 0, JSON_TOKENER_PARSE_RETURN_INPUT);

    // Initialize rate limiter if needed
    if (req_data->rate_limiter == NULL) {
        req_data->rate_limiter = malloc(sizeof(ip_rate_limit_t));
        memset(req_data->rate_limiter, 0, sizeof(ip_rate_limit_t));
    }

    // Check rate limit
    unsigned long current_time = time(NULL);
    req_data->rate_limiter->ip[current_time % 3600]++;
    if (req_data->rate_limiter->ip[current_time % 3600] > req_data->rate_limiter->max_requests) {
        free(req_data);
        return NULL;
    }

    // Find the appropriate handler based on the request method
    int found = 0;
