#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct {
    int key;
    long offset;
} Record;

struct node {
    Record data;
    struct node *next;
};

struct hash_table {
    unsigned long capacity; // Current table size
    unsigned long num_records; // Number of records currently in use
    struct node **table; // Array of pointers to nodes
    pthread_mutex_t lock; // Mutex for concurrent access
};

// Thread-safe random number generator (using Xorshift128+)
struct rng {
    unsigned long x, y, z, w;
};

void rng_init(struct rng *r) {
    r->x = 123456789;
    r->y = 362436069;
    r->z = 521288629;
    r->w = 88675123;
}

unsigned long rng(struct rng *r) {
    unsigned long t;

    t = (r->x += r->y);
    r->y += (t <= (r->z = r->z + r->w));
    r->z ^= r->w;

    return (t << 18 | t >> 48) ^ (r->x << 27 | r->x >> 5);
}

// Custom hash function for keys (using a simple modulo operation)
unsigned long hash(int key, unsigned long capacity) {
    return key % capacity;
}

// Resizes the table to the given capacity
void resize_table(struct hash_table *ht, unsigned long new_capacity) {
    struct node **new_table = malloc(sizeof(struct node *) * new_capacity);
    unsigned long i;

    for (i = 0; i < ht->capacity; ++i) {
        struct node *current = ht->table[i];
        while (current != NULL) {
            struct node *next = current->next;
            unsigned long h = hash(current->data.key, new_capacity);
            if (!new_table[h]) {
                new_table[h] = current;
            } else {
                struct node *list = new_table[h];
                current->next = list;
                new_table[h] = current;
            }
            current = next;
        }
    }

    ht->capacity = new_capacity;
    free(ht->table);
    ht->table = new_table;
}

// Initializes the hash table with the given capacity and growth factor
void init_hash_table(struct hash_table *ht, unsigned long capacity, double growth_factor) {
    ht->capacity = capacity;
    ht->num_records = 0;
    ht->table = malloc(sizeof(struct node *) * capacity);
    pthread_mutex_init(&ht->lock, NULL);

    if (capacity * growth_factor <= 1000) {
        resize_table(ht, capacity * 2);
    }
}

// Inserts a record into the hash table if it doesn't already exist
void insert_record(struct hash_table *ht, Record *rec) {
    pthread_mutex_lock(&ht->lock);
    unsigned long h = hash(rec->key, ht->capacity);
    struct node **list = &ht->table[h];
    struct node *current = *list;

    if (!current) {
        *list = rec;
        ++ht->num_records;
        pthread_mutex_unlock(&ht->lock);
    } else {
        while (current->next && current->next->data.key == rec->key) {
            current = current->next;
        }

        if (!current->next) {
            current->next = rec;
            ++ht->num_records;
        }

        pthread_mutex_unlock(&ht->lock);
    }
}

// Deletes a record with the given key from the hash table, if it exists
void delete_record(struct hash_table *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    unsigned long h = hash(key, ht->capacity);
    struct node **list = &ht->table[h];
    struct node *current = *list;

    if (!current) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }

    while (current != NULL && current->data.key != key) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }

    if (current == *list) {
        *list = current->next;
    } else {
        struct node *prev = *list;
        while (prev->next && prev->next != current) {
            prev = prev->next;
        }
        prev->next = current->next;
    }

    --ht->num_records;
    free(current);
    pthread_mutex_unlock(&ht->lock);
}

// Retrieves the record with the given key from the hash table, if it exists
Record *get_record(struct hash_table *ht, int key) {
    unsigned long h = hash(key, ht->capacity);
    struct node **list = &ht->table[h];
    struct node *current = *list;

    while (current != NULL && current->data.key != key) {
        current = current->next;
    }

    return current;
}

// Periodically compacts the hash table, reducing fragmentation without reallocating all memory at once
void compact_hash_table(struct hash_table *ht, unsigned long threshold) {
    if (ht->num_records <= threshold) {
        return;
    }

    struct node **new_table = malloc(sizeof(struct node *) * ht->capacity);
    unsigned long i;

    for (i = 0; i < ht->capacity; ++i) {
        struct node *current = ht->table[i];
        while (current != NULL) {
            struct node *next = current->next;
            if (!new_table[hash(current->data.key, ht->capacity)]) {
                new_table[hash(current->data.key, ht->capacity)] = current;
            } else {
                struct node *list = new_table[hash(current->data.key, ht->capacity)];
                current->next = list;
                new_table[hash(current->data.key, ht->capacity)] = current;
            }
            current = next;
        }
    }

    free(ht->table);
    ht->table = new_table;
}

// Sets the value of a record's key to a random value within the given range, using a thread-safe random number generator
void set_random_key(struct hash_table *ht, Record *rec, unsigned long min, unsigned long max) {
    pthread_mutex_lock(&ht->lock);
    rec->key = (rng(ht->rng) % (max - min + 1)) + min;
    pthread_mutex_unlock(&ht->lock);
}

// Performance monitoring: logs the number of successful operations, failed operations due to concurrency issues, and memory allocation/deallocation events
void log_performance(const char *message) {
    // Implement logging functionality here (e.g., writing to a file or using printf for debugging purposes)
}
