#include <stdio.h>
#include <time.h>
#include <unordered_map>
#include <vector>
#include <mutex>

struct Transaction {
    int user_id;
    double amount;
    double weight;
};

class FinancialProcessor {
private:
    std::unordered_map<int, std::vector<Transaction>> transactions;
    std::unordered_map<int, double> movingAverages;
    std::unordered_map<int, int> transactionCounts;
    std::unordered_map<int, double> maxWeightedSumPerUser;
    std::mutex mtx;

    time_t lastUpdateTime = 0;
    time_t currentTime() { return std::time(nullptr); }

public:
    void processTransaction(const Transaction& transaction) {
        auto now = currentTime();

        if (transaction.amount <= 0 || now - lastUpdateTime > 10) {
            return;
        }

        transactions[transaction.user_id].push_back(transaction);
        updateMetrics(now, transaction);
    }

    void updateMetrics(time_t now, const Transaction& transaction) {
        std::lock_guard<std::mutex> lock(mtx);

        if (now - lastUpdateTime > 5) {
            resetUserMetrics();
        }

        int user_id = transaction.user_id;

        movingAverages[user_id].push_back(transaction.amount);
        movingAverages[user_id].pop_front();
        if (movingAverages[user_id].size() > 10) {
            movingAverages[user_id] = std::accumulate(movingAverages[user_id].begin(), movingAverages[user_id].end(), 0.0, [](double a, double b) { return a + b; }) / 10.0;
        }

        transactionCounts[user_id]++;
        if (transactionCounts[user_id] > 3) {
            transactionCounts[user_id] = 0;
        }

        double weightedSum = std::accumulate(transactions[user_id].begin(), transactions[user_id].end(), 0.0, [](double a, const Transaction& b) { return a + (b.amount * b.weight); });
        if (weightedSum > maxWeightedSumPerUser[user_id] || maxWeightedSumPerUser.find(user_id) == maxWeightedSumPerUser.end()) {
            maxWeightedSumPerUser[user_id] = weightedSum;
        }

        lastUpdateTime = now;
    }

    const std::unordered_map<int, double>& getMaxWeightedSum() const { return maxWeightedSumPerUser; }

    void resetUserMetrics() {
        for (auto& user : transactions) {
            movingAverages[user.first] = {};
            transactionCounts[user.first] = 0;
        }
    }
};
```

