```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <sys/stat.h>
#include <time.h>

typedef struct CacheNode {
    char* key;
    char* value;
    struct CacheNode *next;
    time_t last_accessed;
} CacheNode;

#define CACHE_SIZE 10000
CacheNode* head = NULL;
CacheNode* tail = NULL;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *file_cache_errors;

void lru_cache_insert(char* key, char* value) {
    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    node->key = strdup(key);
    node->value = strdup(value);
    node->next = NULL;
    if (!head) {
        head = node;
        tail = node;
    } else {
        node->last_accessed = time(NULL);
        tail->next = node;
        tail = node;
    }
}

CacheNode* lru_cache_get(char* key) {
    CacheNode* current = head;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            current->last_accessed = time(NULL);
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void lru_cache_remove(char* key) {
    CacheNode* node = lru_cache_get(key);
    if (node == NULL) return;

    pthread_mutex_lock(&cache_mutex);
    if (head == node) head = node->next;
    if (node->next == NULL) tail = head;

    struct timeval now;
    gettimeofday(&now, NULL);
    file_cache_errors && fprintf(file_cache_errors, "Removed %s from cache at %ld\n", node->key, now.tv_sec * 1000 + now.tv_usec / 1000);

    free(node->key);
    free(node->value);
    free(node);
    pthread_mutex_unlock(&cache_mutex);
}

void lru_cache_cleanup() {
    CacheNode* current = head;
    CacheNode* next;
    while (current != NULL && CACHE_SIZE > 0) {
        next = current->next;
        if (time(NULL) - current->last_accessed > 60) {
            lru_cache_remove(current->key);
        } else {
            current = next;
        }
    }
}

void* modifyFileExtension(char* filename) {
    char new_filename[4096];
    int len = strlen(filename);
    int dot_index = -1;
    for (int i = len - 1; i >= 0; --i) {
        if (filename[i] == '.') {
            dot_index = i;
            break;
        }
    }

    int ext_len = dot_index != -1 ? len - dot_index : 0;
    int num_digits = strlen(filename) - ext_len;
    snprintf(new_filename, sizeof(new_filename), "%s%0*d.%s", filename, num_digits, num_digits, dot_index != -1 ? filename + dot_index : "");

    CacheNode* cached = lru_cache_get(filename);
    if (cached) strcpy(new_filename, cached->value);

    if (!cached) {
        lru_cache_insert(filename, new_filename);
        if (file_cache_errors) fprintf(file_cache_errors, "Stored %s in cache\n", filename);
    }

    return strdup(new_filename);
}

void test_modifyFileExtension() {
    lru_cache_cleanup();

    // Initialize file_cache_errors.log if it doesn't exist
    if (!file_cache_errors) file_cache_errors = fopen("file_cache_errors.log", "w");

    char filenames[5][10] = {"test.txt", "longer.file.name.with.extension", "no-extension", ".test", "..test.."};
    for (int i = 0; i < 5; ++i) {
        char* result = modifyFileExtension(filenames[i]);
        printf("modifyFileExtension(%s): %s\n", filenames[i], result);
        free(result);
    }
}
```

