int num_handlers = 0;

void register_handler(char *method, request_handler func) {
    pthread_mutex_lock(&handler_list_lock);
    if (num_handlers >= MAX_HANDLERS) {
        printf("Error: Maximum number of handlers reached.\n");
        return;
    }
    strcpy(handlers[num_handlers].method, method);
    handlers[num_handlers].func = func;
    handlers[num_handlers].lock = PTHREAD_MUTEX_INITIALIZER;
    num_handlers++;
    pthread_mutex_unlock(&handler_list_lock);
}

