    State *buffer = malloc(max_states * sizeof(State));
    if (!buffer)
        return NULL;

    State *head = buffer;
    int processed = 0;
    int current_state = -1;

    // Use a stack to store states during traversal
    int stack[max_states];
    int top = -1;

    for (int i = 0; i < num_initials; ++i) {
        current_state = initial_states[i];
        stack[++top] = current_state;
    }

    while (top >= 0 || processed < max_states) {
        if (top >= 0) {
            current_state = stack[top--];
        }

        int *next_states = fsa->transitions[current_state];
        bool found_new_state = false;

        // Traverse using the specified algorithm (depth-first or breadth-first)
        if (traversal_mode & 1) { // DFS
            for (int i = 0; next_states[i] != -1 && processed < max_states; ++i) {
                int next_state = next_states[i];
                if (!buffer[next_state].next) { // Already processed or null pointer means this state is not yet in the list
                    buffer[next_state].id = processed++;
                    buffer[next_state].next = head;
                    head = &buffer[next_state];

                    stack[++top] = next_state;
                    found_new_state = true;
                    break;
                }
            }
        } else { // BFS (implicitly uses a queue instead of a stack)
            for (int i = 0; i < max(next_states, 1); ++i) {
                int next_state = next_states[i];
                if (!buffer[next_state].next) { // Already processed or null pointer means this state is not yet in the list
                    buffer[next_state].id = processed++;
                    buffer[next_state].next = head;
                    State *temp = head;
                    head = &buffer[next_state];
                    head->next = temp;

                    if (!top) { // If the stack is empty, use the new state as the current state for the next iteration
                        current_state = next_state;
                        top = -1;
                    }
                }
            }
        }

        if (!found_new_state) {
            break; // No more unprocessed states can be found, either reach the max number of states or memory constraints
        }
    }

    if (head == buffer) { // If the head pointer points to the start of the buffer, no valid states were constructed
        free(buffer);
        return NULL;
    }

    // Update the 'next' pointer of the last state in the list
    head->next = NULL;
    return buffer;
}
```

