using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Numerics;

public class FileBasedValueGenerator
{
    private readonly (int MinValue, int MaxValue) _currentRange;
    private readonly string _filePath;
    private List<long> _sequenceNumbers = new List<long>();

    public FileBasedValueGenerator(string filePath, int minValue = int.MinValue, int maxValue = int.MaxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentOutOfRangeException(nameof(minValue));

        _filePath = filePath;
        (_currentRange.MinValue, _currentRange.MaxValue) = (Math.Max(minValue, 1), Math.Min(maxValue, int.MaxValue));

        try
        {
            var lines = File.ReadAllLines(_filePath).ToList();
            lines.Sort((a, b) => b.CompareTo(a));
            _sequenceNumbers = lines.Last()
                .Split('_')
                .Where(s => long.TryParse(s, out var number))
                .Select(long.Parse)
                .ToList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading file: {ex.Message}");
        }
    }

    public int MinValue => _currentRange.MinValue;
    public int MaxValue => _currentRange.MaxValue;

    public void UpdateRange(int newMin, int newMax)
    {
        if (newMin >= newMax || newMin < 1 || newMax > int.MaxValue)
            throw new ArgumentOutOfRangeException(nameof(newMin));

        _currentRange = (_currentRange.MinValue, _currentRange.MaxValue);
        (_currentRange.MinValue, _currentRange.MaxValue) = (Math.Max(newMin, 1), Math.Min(newMax, int.MaxValue));
    }

    public float GetRandomFloat() => new Random((int)Math.Floor(_sequenceNumbers[^1] * 1_000_000)).NextDouble() * (_currentRange.MaxValue - _currentRange.MinValue) + _currentRange.MinValue;

    public int GetRandomInt() => (int)(GetRandomFloat() * ((BigDecimal)_currentRange.MaxValue - _currentRange.MinValue + 1) + _currentRange.MinValue);

    public override string ToString()
    {
        return $"[{_currentRange.MinValue}, {_currentRange.MaxValue}) SequenceNumber: {_sequenceNumbers.LastOrDefault()}";
    }
}
