#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/stat.h>
#include <time.h>

#define CACHE_SIZE 10000
#define FEATURE_SIZE 32
#define LEAF_NODES 8
#define DATA_CAPACITY (FEATURE_SIZE * LEAF_NODES)

typedef struct _Node {
    int index;
    float feature[FEATURE_SIZE];
} Node;

typedef struct _Octree {
    Node* prefixLeafs;
    Node** leafs;
    int capacity;
    int numLeafs;
} Octree;

Octree initializeOctree(int featureSize, int leafNodes, int dataCapacity) {
    Octree octree = {0};

    octree.prefixLeafs = (Node*)malloc(leafNodes * sizeof(Node));
    octree.leafs = (Node**)calloc(leafNodes, sizeof(Node*));
    octree.capacity = dataCapacity;

    for (int i = 0; i < leafNodes; ++i) {
        octree.leafs[i] = (Node*)malloc(dataCapacity * sizeof(Node));
    }

    return octree;
}

char* modifyFileExtension(const char* filename, FILE** cache) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int cacheSize = 0;
    static char* cacheEntries[CACHE_SIZE];

    struct stat fileStat;
    stat(filename, &fileStat);

    int len = fileStat.st_size - (strlen(filename) - strlen(&filename[strrchr(filename, '.') + 1]));
    int digits = len > 5 ? 5 : len;
    char newExtension[6] = ".dat";

    snprintf(newExtension + 3, 3, "%03d", digits);

    char* newFilename = (char*)malloc(strlen(filename) + strlen(newExtension) + 1);
    strcpy(newFilename, filename);
    strcat(newFilename, newExtension);

    pthread_mutex_lock(&mutex);

    int index = hashFunction(newFilename);
    if (cacheSize > CACHE_SIZE || cacheSize == 0) {
        for (int i = cacheSize - 1; i >= 0 && cache[i] != NULL; --i) {
            free(cacheEntries[i]);
        }
        cacheSize -= (cacheSize - 1);
    }

    if (!cache[index]) {
        cache[index] = fopen("file_cache_errors.log", "a");
    }

    for (int i = cacheSize; i >= index; --i) {
        cacheEntries[i] = cacheEntries[i - 1];
    }
    cacheEntries[index] = strdup(newFilename);
    cacheSize++;

    pthread_mutex_unlock(&mutex);

    return newFilename;
}

int hashFunction(const char* key) {
    uint32_t hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % CACHE_SIZE;
}
