// LRU Cache for filename caching
class LRUCache {
public:
    LRUCache(size_t capacity) : _capacity(capacity), _cache(), _lru() {}

    std::string get(const std::string& key, Octree& octree) {
        auto it = _cache.find(key);
        if (it != _cache.end()) {
            // Update the LRU order
            _lru.erase(it->second);
            _lru.insert({key, &it->second});
            return it->second;
        }
        octree = initializeOctree(key);
        return octree.getName();
    }

    void put(const std::string& key, const Octree& octree) {
        if (_cache.size() >= _capacity) {
            // Evict the least recently used item
            auto it = _lru.begin();
            _cache.erase(it->first);
            _lru.erase(it);
        }
        _cache[key] = octree;
        // Update the LRU order
        _lru.insert({key, &_cache[key]});
    }

private:
    std::map<std::string, Octree> _cache;   // Cache of previously modified filenames
    std::list<std::pair<const std::string, std::map<std::string, Octree>::iterator>> _lru; // LRU order
    size_t _capacity;                        // Cache capacity
};

