        size_t next;     // Index of next leaf in the octree
    };

    Leaf* _prefixLeafs;   // Prefix leaves for the octree
    size_t _dataCapacity; // Capacity of the data array
    float* _data;         // Data array for the octree
    std::string _name;    // Original filename
    size_t _featureSize;   // Feature size of each node in the octree
    size_t _numLeafNodes;  // Number of leaf nodes in the octree
};

// Function to modify file extension
Octree modifyFileExtension(const std::string& filename) {
    LRUCache cache(10000);   // Initialize the LRU cache with a capacity of 10,000 unique filenames

    // Extract base name and extension from the filename
    size_t lastDot = filename.find_last_of('.');
    std::string baseName;
    std::string ext;
    if (lastDot != std::string::npos) {
        baseName = filename.substr(0, lastDot);
        ext = filename.substr(lastDot);
    } else {
        baseName = filename;
    }

    // Construct new filename with a number of digits representing the length of the base name and extension
    int digits = static_cast<int>(baseName.length() + ext.length());
    std::stringstream ss;
    ss << baseName << "_" << std::setw(digits) << std::setfill('0') << digits << ext;
    std::string newFilename = ss.str();

    Octree octree;  // Initialize the octree with the newly constructed filename
    octree.initialize(newFilename);

    // Cache the result for future use and optimization
    cache.put(filename, octree);

    return octree;
}
