typedef struct Record {
    int value;
} Record;

const size_t MAX_RECORDS = 1000000; // Max records to store
const size_t RECORD_SIZE = sizeof(Record);
const size_t KEY_SIZE = sizeof(int);
const size_t LONG_SIZE = sizeof(long);
const size_t LIMIT = 2 * MAX_RECORDS + 2 * MAX_RECORDS * KEY_SIZE + MAX_RECORDS * LONG_SIZE; // Total memory limit in bytes

size_t total_allocated = 0;

Record* records;
long* offsets;
int* keys;

void check_memory() {
    if (total_allocated > LIMIT) {
        fprintf(stderr, "Memory limit exceeded. Exiting...\n");
        exit(1);
    }
}

Record* allocate_records(size_t size) {
    check_memory();
    Record* new_records = malloc(size * RECORD_SIZE);
    if (!new_records) {
        fprintf(stderr, "Memory allocation failed. Exiting...\n");
        exit(1);
    }
    total_allocated += size * RECORD_SIZE;
    return new_records;
}

long* allocate_longs(size_t size) {
    check_memory();
    long* new_longs = malloc(size * LONG_SIZE);
    if (!new_longs) {
        fprintf(stderr, "Memory allocation failed. Exiting...\n");
        exit(1);
    }
    total_allocated += size * LONG_SIZE;
    return new_longs;
}

int* allocate_ints(size_t size) {
    check_memory();
    int* new_ints = malloc(size * KEY_SIZE);
    if (!new_ints) {
        fprintf(stderr, "Memory allocation failed. Exiting...\n");
        exit(1);
    }
    total_allocated += size * KEY_SIZE;
    return new_ints;
}

void deallocate() {
    free(records);
    free(offsets);
    free(keys);
}

void update_memory(size_t records_added, size_t keys_added, size_t offsets_added) {
    total_allocated -= RECORD_SIZE * records;
    total_allocated -= LONG_SIZE * offsets;
    total_allocated -= KEY_SIZE * keys;

    records = allocate_records(records + records_added);
    offsets = allocate_longs(offsets + offsets_added);
    keys = allocate_ints(keys + keys_added);
