#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

typedef struct Record {
    int value;
} Record;

struct DynamicMemoryManager {
    long *offsets;
    int *keys;
    Record *records;
    size_t memoryUsage;
    size_t maxMemoryUsage;
    int MinValue, MaxValue;
    bool validRange;
};

void InitializeRange(struct DynamicMemoryManager *dmm, int minValue, int maxValue) {
    dmm->MinValue = minValue < maxValue ? minValue : maxValue;
    dmm->MaxValue = minValue > maxValue ? minValue : maxValue;
    dmm->validRange = dmm->MinValue < dmm->MaxValue;
}

struct DynamicMemoryManager *DynamicMemoryManager_Create(size_t recordCount, size_t memoryUsageLimit) {
    struct DynamicMemoryManager *dmm = malloc(sizeof(struct DynamicMemoryManager));
    if (!dmm) {
        fprintf(stderr, "Failed to allocate memory for DynamicMemoryManager.\n");
        return NULL;
    }

    InitializeRange(dmm, 0, INT_MAX);
    dmm->memoryUsage = 0;
    dmm->maxMemoryUsage = memoryUsageLimit;

    dmm->offsets = calloc(recordCount + 1, sizeof(long));
    if (!dmm->offsets) {
        fprintf(stderr, "Failed to allocate memory for offset array.\n");
        free(dmm);
        return NULL;
    }

    dmm->keys = malloc((recordCount + 1) * sizeof(int));
    if (!dmm->keys) {
        fprintf(stderr, "Failed to allocate memory for key array.\n");
        free(dmm->offsets);
        free(dmm);
        return NULL;
    }

    dmm->records = malloc(recordCount * sizeof(Record));
    if (!dmm->records) {
        fprintf(stderr, "Failed to allocate memory for record array.\n");
        free(dmm->offsets);
        free(dmm->keys);
        free(dmm);
        return NULL;
    }

    return dmm;
}

void UpdateRange(struct DynamicMemoryManager *dmm, int newMinValue, int newMaxValue) {
    if (newMinValue >= newMaxValue || !dmm->validRange)
        return;

    dmm->MinValue = newMinValue < newMaxValue ? newMinValue : newMaxValue;
    dmm->MaxValue = newMinValue > newMaxValue ? newMaxValue : newMinValue;
    dmm->validRange = dmm->MinValue < dmm->MaxValue;
}

int GetRandomInt(struct DynamicMemoryManager *dmm) {
    if (!dmm || !dmm->validRange)
        return 0;

    int rangeSize = dmm->MaxValue - dmm->MinValue + 1;
    double randomDouble = (double)rand() / RAND_MAX * rangeSize;
    return dmm->MinValue + (int)randomDouble;
}

float GetRandomFloat(struct DynamicMemoryManager *dmm) {
    if (!dmm || !dmm->validRange)
        return 0.0f;

    float rangeSize = (float)(dmm->MaxValue - dmm->MinValue + 1);
    float randomFloat = (float)((double)rand() / RAND_MAX * rangeSize);
    return dmm->MinValue + randomFloat;
}

Record *GetNextEmptyRecord(struct DynamicMemoryManager *dmm) {
    for (size_t i = 0; i < dmm->offsets[dmm->records]; ++i) {
        if (!dmm->keys[i]) {
            dmm->keys[i] = -1;
            return &dmm->records[i];
        }
    }

    size_t newOffset = dmm->offsets[dmm->records];
    long *newOffsets = realloc(dmm->offsets, (newOffset + 1) * sizeof(long));
    if (!newOffsets) {
        fprintf(stderr, "Failed to allocate memory for expanded offset array.\n");
        return NULL;
    }
    dmm->offsets = newOffsets;
    dmm->offsets[dmm->records] = newOffset + 1;

    int *newKeys = realloc(dmm->keys, (newOffset + 1) * sizeof(int));
    if (!newKeys) {
        fprintf(stderr, "Failed to allocate memory for expanded key array.\n");
        free(newOffsets);
        return NULL;
    }
    dmm->keys = newKeys;
    dmm->keys[newOffset] = -1;

    Record *newRecord = realloc(dmm->records, (dmm->offsets[dmm->records] + 1) * sizeof(Record));
    if (!newRecord) {
        fprintf(stderr, "Failed to allocate memory for expanded record array.\n");
        free(newOffsets);
        free(newKeys);
        return NULL;
    }
    dmm->records = newRecord;

    return &dmm->records[newOffset];
}
```

