using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;

public class NetworkedDataProcessor
{
    private readonly ConcurrentDictionary<string, object> dataCache = new ConcurrentDictionary<string, object>();
    private readonly HttpClient[] dataSources = new HttpClient[3];

    public NetworkedDataProcessor(Func<int, Uri> dataSourceFactory)
    {
        if (dataSourceFactory == null || dataSourceFactory.Invoke(0) == null || dataSourceFactory.Invoke(1) == null || dataSourceFactory.Invoke(2) == null)
            throw new ArgumentException("Each data source must be provided as a non-null Uri factory function.");

        for (int i = 0; i < dataSources.Length; i++)
        {
            dataSources[i] = new HttpClient();
        }
    }

    public Uri DataSource1 { get => dataSources[0].BaseAddress; }
    public Uri DataSource2 { get => dataSources[1].BaseAddress; }
    public Uri DataSource3 { get => dataSources[2].BaseAddress; }

    private async Task FetchDataFromSource(int sourceIndex)
    {
        try
        {
            if (sourceIndex < 0 || sourceIndex > dataSources.Length - 1)
                throw new ArgumentOutOfRangeException("Source index must be within range [0, DataSources.Length).");

            HttpResponseMessage response = await dataSources[sourceIndex].GetAsync("/api/data", HttpCompletionOption.ResponseHeadersRead);
            if (!response.IsSuccessStatusCode)
                return;

            string content = await response.Content.ReadAsStringAsync();
            foreach (var kvp in JsonNetSerializer.Deserialize<IDictionary<string, object>>(content))
            {
                dataCache[kvp.Key] = kvp.Value;
            }
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Failed to fetch data from source {sourceIndex}: {ex}");
        }
    }

    public async Task RefreshCache()
    {
        if (!CheckNetworkAvailability())
            return;

        for (int i = 0; i < dataSources.Length; i++)
        {
            await FetchDataFromSource(i);
        }
    }

    private bool CheckNetworkAvailability()
    {
        try
        {
            using (var client = new WebClient())
            {
                client.DownloadString("http://www.google.com");
                return true;
            }
        }
        catch (WebException ex)
        {
            if ((ex.Status == WebExceptionStatus.NameResolutionFailure || ex.Status == WebExceptionStatus.ConnectFailure))
                return false;
        }
        catch (TaskCanceledException ex)
        {
            // Assume network unavailable if any operation times out.
            return false;
        }

        return true;
    }

    public T GetData<T>(string key)
    {
        if (string.IsNullOrEmpty(key))
            throw new ArgumentNullException("Key is required.");

        object data;
        if (!dataCache.TryGetValue(key, out data))
            throw new KeyNotFoundException($"Key '{key}' not found in cache.");

        return (T)data;
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        sb.AppendLine("NetworkedDataProcessor State:");
        sb.AppendFormat("- Items cached: {0}\n", dataCache.Count);
        sb.AppendFormat("- Last refreshed: {0}\n", DateTime.Now.ToLocalTime().ToString("HH:mm:ss"));
        foreach (var kvp in dataSources)
            sb.AppendFormat("- Source {0}: {1}\n", kvp.Key, kvp.Value);
        return sb.ToString();
    }
}

public static class JsonNetSerializer
{
    private static readonly Newtonsoft.Json.JsonSerializer serializer = new Newtonsoft.Json.JsonSerializer();
    public static T Deserialize<T>(string json) => (T)serializer.Deserialize(new StringReader(json), typeof(T));
}
```

