void add_config(LinkedListNode** head, NICPConfig config) {
    LinkedListNode* new_node = new_node(config);
    if (*head == NULL) {
        *head = new_node;
    } else {
        LinkedListNode* current = *head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    }
}

void update_config(LinkedListNode** head, int index, NICPConfig config) {
    if (index < 1 || *head == NULL) return;

    LinkedListNode* current = *head;
    for (int i = 0; i < index && current != NULL; ++i) current = current->next;

    if (current == NULL) return;

    memcpy(&current->config, &config, sizeof(NICPConfig));
}

