2. C function to generate a new file path with appended checksum:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>

void generate_checksum(const char *file_path, char **new_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        printf("Failed to open file: %s\n", file_path);
        return;
    }

    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;

    SHA256_Init(&ctx);
    while (1) {
        size_t bytes_read = fread(digest, 1, sizeof(digest), file);
        if (!bytes_read) break;
        SHA256_Update(&ctx, digest, bytes_read);
    }
    SHA256_Final(digest, &ctx);

    char checksum[32 + 1];
    sprintf(checksum, "%064x", *((unsigned long *)digest));
    *new_path = malloc(strlen(file_path) + strlen(checksum) + 2);
    sprintf(*new_path, "%s.%s", file_path, checksum);
}
