    context->rrc_state = malloc(sizeof(enum RRC_STATE));
    *context->rrc_state = RRC_IDLE;
    context->last_activity = time(NULL);
    return context;
}

void add_context(struct ue_context_manager *uecm, LTE_UE_CONTEXT *context) {
    pthread_mutex_lock(&uecm->mutex);
    NODE *node = malloc(sizeof(NODE));
    node->context = context;
    node->next = uecm->head[context->ue_id % uecm->size];
    uecm->head[context->ue_id % uecm->size] = node;
    pthread_mutex_unlock(&uecm->mutex);
