    int metric_id;
    int value;
};

pthread_mutex_t nodes_lock = PTHREAD_MUTEX_INITIALIZER; // Lock for managing the array of nodes
struct Node** nodes;
int num_nodes = 0;

void init_node(struct Node* node, int id) {
    node->id = id;
    node->health_score = 0;
    node->maintenance_status = false;
    node->metrics = NULL;
    pthread_mutex_init(&node->node_lock, NULL);
}

void init_list(struct List* list) {
    list->size = 0;
    list->data = NULL;
    pthread_mutex_init(&list->list_lock, NULL);
}

struct NodeMetric* create_node_metric(int metric_id, int value) {
    struct NodeMetric *new_node_metric = malloc(sizeof(struct NodeMetric));
    new_node_metric->metric_id = metric_id;
    new_node_metric->value = value;
    return new_node_metric;
}

void append_to_list(struct List* list, struct NodeMetric *new_node_metric) {
    pthread_mutex_lock(&list->list_lock);
    if (list->data == NULL) {
        list->size = 1;
        list->data = malloc(sizeof(struct NodeMetric*));
        list->data[0] = new_node_metric;
    } else {
        int i;
        for (i = list->size; i > 0; --i) {
            list->data[i] = list->data[i - 1];
        }
        list->data[0] = new_node_metric;
        list->size++;
    }
    pthread_mutex_unlock(&list->list_lock);
}

void add_new_node(int id) {
    if (num_nodes == 0) {
        nodes = malloc(sizeof(struct Node));
        init_node(nodes[0], id);
        num_nodes++;
