    double weight;
    long long total_volume;
    double moving_average;
    int transactions_5s;
    int transactions_10s;
} User;

// Global variables and locks for each user
pthread_mutex_t users_lock[1000]; // Assuming a maximum of 1000 users
User users[1000];

// Function to filter transactions by time and positive amounts
bool is_valid(struct timespec now, double amount) {
    struct timespec diff;
    if (amount <= 0.0) return false;
    timersub(&now, &transaction_time, &diff);
    if (diff.tv_sec > 10 || (diff.tv_sec == 10 && diff.tv_nsec > 100000000)) return false;
    int user_id = transaction_user % 1000;
    timersub(&now, &users[user_id].transactions[users[user_id].transactions_count - 1].time, &diff);
    if (diff.tv_sec < 5 || (diff.tv_sec == 5 && diff.tv_nsec > 500000000)) return false;
    return true;
}

// Function to process a transaction
void process_transaction(struct timespec now, int user_id, double amount, double weight) {
    pthread_mutex_lock(&users_lock[user_id]);
    users[user_id].transactions[users[user_id].transactions_count++] = (Transaction){now, amount};
    if (is_valid(now, amount)) {
        users[user_id].transactions_10s++;
        users[user_id].transactions_5s++;
        users[user_id].total_volume += amount * weight;
        users[user_id].moving_average = (users[user_id].transactions[users[user_id].transactions_count - 1].amount + users[user_id].moving_average * (double)(10 - users[user_id].transactions_count)) / 10.0;
        if (now.tv_sec >= users.max_weighted_sum_time && users[user_id].total_volume > users.max_weighted_sum) {
            users.max_weighted_sum = users[user_id].total_volume;
            users.max_weighted_sum_user_id = user_id;
        }
    }
    pthread_mutex_unlock(&users_lock[user_id]);
}
