#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    uint64_t id;
    enum RRC_STATE {RRC_IDLE, RRC_CONNECTED} state;
    time_t last_activity;
} LTE_UE_CONTEXT;

typedef struct LTE_CONTEXT_MANAGER {
    LTE_UE_CONTEXT *contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LTE_CONTEXT_MANAGER;

void lte_context_manager_init(LTE_CONTEXT_MANAGER *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->contexts = malloc(sizeof(LTE_UE_CONTEXT) * initial_capacity);
    if (!manager->contexts) {
        perror("malloc failed");
        return;
    }
    pthread_mutex_init(&manager->lock, NULL);
}

size_t lte_context_manager_find(const LTE_CONTEXT_MANAGER *manager, uint64_t id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].id == id) {
            return i;
        }
    }
    return SIZE_MAX;
}

void lte_context_manager_resize(LTE_CONTEXT_MANAGER *manager, size_t new_capacity) {
    if (new_capacity > manager->count) {
        LTE_UE_CONTEXT *new_contexts = realloc(manager->contexts, sizeof(LTE_UE_CONTEXT) * new_capacity);
        if (!new_contexts) {
            perror("realloc failed");
            return;
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }
}

void lte_context_manager_add(LTE_CONTEXT_MANAGER *manager, const LTE_UE_CONTEXT *context) {
    pthread_mutex_lock(&manager->lock);
    size_t id_index = lte_context_manager_find(manager, context->id);
    if (id_index != SIZE_MAX && id_index < manager->count) {
        printf("Error: UE ID already exists\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    if (manager->count == manager->capacity) {
        lte_context_manager_resize(manager, manager->capacity * 2);
    }
    manager->contexts[manager->count++] = *context;
    pthread_mutex_unlock(&manager->lock);
}

void lte_context_manager_update(LTE_CONTEXT_MANAGER *manager, uint64_t id, const LTE_UE_CONTEXT *new_context) {
    pthread_mutex_lock(&manager->lock);
    size_t index = lte_context_manager_find(manager, id);
    if (index == SIZE_MAX || index >= manager->count) {
        printf("Error: UE ID not found\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->contexts[index] = *new_context;
    pthread_mutex_unlock(&manager->lock);
}

LTE_UE_CONTEXT* lte_context_manager_get(const LTE_CONTEXT_MANAGER *manager, uint64_t id) {
    pthread_mutex_lock(&manager->lock);
    size_t index = lte_context_manager_find(manager, id);
    if (index == SIZE_MAX || index >= manager->count) {
        LTE_UE_CONTEXT null_context = {0};
        pthread_mutex_unlock(&manager->lock);
        return &null_context;
    }
    LTE_UE_CONTEXT *context = &manager->contexts[index];
    pthread_mutex_unlock(&manager->lock);
    return context;
}
```

