public class MostStateLoader {
    public Optional<MostState> loadFromFile(String filename) {
        FileInputStream fis = null;
        ObjectInputStream ois = null;
        try {
            fis = new FileInputStream(filename);
            ois = new ObjectInputStream(fis);
            MostState mostState = (MostState) ois.readObject();
            return Optional.of(mostState);
