            // Handle exceptions gracefully...
            if (ois != null) try { ois.close(); } catch (IOException ex) {}
            if (fis != null) try { fis.close(); } catch (IOException ex) {}
        } finally {
            if (ois != null) try { ois.close(); } catch (IOException ex) {}
            if (fis != null) try { fis.close(); } catch (IOException ex) {}
        }
        return Optional.empty();
