['```cpp
#include <atomic>
#include <cstdint>
#include <functional>
#include <initializer_list>
#include <memory>
#include <new>
#include <random>
#include <unordered_map>
#include <vector>

class Record {
public:
    int value;

    Record(int value) : value(value) {}
};

class DynamicMemoryManager {
private:
    struct MemoryRange {
        std::atomic_int minValue;
        std::atomic_int maxValue;
    };

    using Ranges = std::unordered_map<std::thread::id, MemoryRange>;
    using AllocatorType = std::function<void*(size_t)>;
    using DeallocatorType = std::function<void(void*)>;

    AllocatorType allocator;
    DeallocatorType deallocator;
    size_t memoryLimit;
    Ranges ranges;
    MemoryRange globalRange;
    std::vector<Record> records;
    mutable std::unordered_map<std::pair<int, int>, void*> cachedRecords;
    mutable std::random_device rd;
    mutable std::mt19937 gen;
    std::unique_ptr<IConfigurationService> configService;

public:
    DynamicMemoryManager(AllocatorType alloc, DeallocatorType dealloc, size_t limit, IConfigurationService* service)
        : allocator(std::move(alloc)), deallocator(std::move(dealloc)), memoryLimit(limit), configService(service), rd(), gen(rd()) {
        globalRange.minValue = INT32_MIN;
        globalRange.maxValue = INT32_MAX;
    }

    void UpdateRange(const std::thread::id& threadId, int newMin, int newMax) {
        auto it = ranges.find(threadId);
        if (it == ranges.end()) {
            ranges[threadId] = MemoryRange{std::atomic_var<int>(newMin), std::atomic_var<int>(newMax)};
        } else {
            it->second.minValue.store(newMin, std::memory_order_relaxed);
            it->second.maxValue.store(newMax, std::memory_order_relaxed);
        }
    }

    int GetMinValue() const { return globalRange.minValue; }

    int GetMaxValue() const { return globalRange.maxValue; }

    void* Allocate(size_t size) {
        try {
            void* ptr = allocator(size);
            if (memoryLimit <= (size_t)((double)std::distance(records.cbegin(), records.cend()) + std::distance(cachedRecords.cbegin(), cachedRecords.cend()) + (ptr - static_cast<void*>(records.data())))) {
                throw std::runtime_error("Memory limit exceeded.");
            }
            return ptr;
        } catch (...) {
            // Log error message and handle gracefully
        }
        return nullptr;
    }

    void Deallocate(void* ptr) {
        if (!ptr) return;
        deallocator(ptr);
    }

    int GetRandomInt() const {
        auto range = CalculateCurrentRange();
        if (range.first == INT32_MIN && range.second == INT32_MAX) {
            globalRange; // Use the global range if no current range is set
        }
        std::uniform_int_distribution<> dist(range.first, range.second);
        return dist(gen);
    }

    float GetRandomFloat() const {
        auto range = CalculateCurrentRange();
        std::uniform_real_distribution<> dist(static_cast<double>(range.first), static_cast<double>(range.second));
        return dist(gen);
    }

private:
    std::pair<int, int> CalculateCurrentRange() const {
        auto currentMin = globalRange.minValue;
        auto currentMax = globalRange.maxValue;
        for (const auto& [_, range] : ranges) {
            if (currentMin > range.minValue.load()) currentMin = range.minValue.load();
            if (currentMax < range.maxValue.load()) currentMax = range.maxValue.load();
        }
        return std::make_pair(currentMin, currentMax);
    }
};
```
