    GCMParams gcm_ctx;
} AES256GCM_CTX;

void PKCS5_PBKDF2_HMAC_SHA256(const char *passphrase, const unsigned char salt[], size_t passphrase_len, size_t salt_len, size_t dk_len, unsigned char *derived_key) {
    EVP_pbkdf2((EVP_CIPHER *)EVP_aes_256_gcm(), passphrase, passphrase_len, salt, salt_len, dk_len, 100000, derived_key);
}

AES256GCM_CTX* AES256GCM_init(const char *passphrase) {
    unsigned char key[32], iv[16];
    PKCS5_PBKDF2_HMAC_SHA256(passphrase, (const unsigned char *)"AES-GCM", strlen("AES-GCM"), sizeof("AES-GCM"), 32, key);
    PKCS5_PBKDF2_HMAC_SHA256(passphrase, (const unsigned char *)"nonce", strlen("nonce"), sizeof("nonce"), 16, iv);

    AES256GCM_CTX *ctx = malloc(sizeof(AES256GCM_CTX));
    if (!ctx) return NULL;

    AES_set_encrypt_key((const unsigned char *)key, 256, &ctx->aes_ctx);
    GCMParams_init(&ctx->gcm_ctx);
    GCM_SET_IV(&ctx->gcm_ctx, iv);
    GCM_set_key(&ctx->gcm_ctx, &ctx->aes_ctx);

    return ctx;
}

void AES256GCM_free(AES256GCM_CTX *ctx) {
    if (!ctx) return;

    free(ctx);
}
