const int GROWTH_FACTOR = 1.5;
const int CACHE_LINE_SIZE = 64;
const int LOG_DETAIL_LEVEL = 2; // Configurable log detail level

struct Node {
    atomic<int> key;
    atomic<long> offset;
    pthread_mutex_t mutex;
};

class HashTable {
public:
    HashTable(size_t capacity) : _capacity(capacity), _nodes((Node*)aligned_alloc(CACHE_LINE_SIZE, sizeof(Node) * _capacity)), _num_elements(0) {}

    int get(int key) const {
        size_t hash = hashFunction(key);
        pthread_mutex_lock(&_nodes[hash].mutex);
        int value = _nodes[hash].key.load();
        if (value == key) {
            pthread_mutex_unlock(&_nodes[hash].mutex);
            return _nodes[hash].offset.load();
        }
        pthread_mutex_unlock(&_nodes[hash].mutex);
        return -1; // Not found
    }

    void set(int key, long offset) {
        size_t hash = hashFunction(key);
        Node* node = &_nodes[hash];
        int inserted = false;

        while (true) {
            if (node->key.compare_exchange_weak(INT_MIN, key)) { // Acquire lock using CAS
                inserted = true;
                break;
            }

            node = getNextBucket(hash, node);

            if (!_nodes[node->hash].key.load()) { // Found an empty slot
                _num_elements++;
                if (_num_elements >= _capacity * GROWTH_FACTOR) {
                    resize();
                }
                node->key.store(key);
                node->offset.store(offset);
                break;
            }
        }

        if (inserted) { // Release the lock after successful insertion
            node->mutex.unlock();
        }
    }

    void remove(int key) {
        size_t hash = hashFunction(key);
        pthread_mutex_lock(&_nodes[hash].mutex);
        if (_nodes[hash].key.compare_exchange_strong(key, INT_MIN)) { // Remove the node from the bucket
            _num_elements--;
            if (_num_elements < _capacity / GROWTH_FACTOR) {
                compact();
            }
        }
        pthread_mutex_unlock(&_nodes[hash].mutex);
    }

private:
    size_t hashFunction(int key) const {
        return key % _capacity;
    }

    Node* getNextBucket(size_t currentHash, Node* currentNode) const {
        return &_nodes[(currentHash + 1 + currentNode->hash) % _capacity];
    }

    void resize() {
        // Resize the hash table to a new capacity
    }

    void compact() {
        // Compact the hash table to reduce fragmentation
    }

    size_t _capacity;
    Node* _nodes;
    int _num_elements;
};

// Thread-safe random number generator
void setRandomValue(int& value, int min, int max) {
