#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int level;
    int (*handler)(const char*, const char*);
    double frequency;
    double total_duration;
} LogHandler;

LogHandler* register_handler(int level, int (*func)(const char*, const char*)) {
    LogHandler* handler = malloc(sizeof(LogHandler));
    handler->level = level;
    handler->handler = func;
    handler->frequency = 0.0;
    handler->total_duration = 0.0;
    return handler;
}

void unregister_handler(LogHandler* handler) {
    free(handler);
}

struct LogMessageSchema {
    size_t max_debug_len;
    char context[32];
};

int validate_log_message(const char* message, const struct LogMessageSchema* schema) {
    // Implement validation logic here
    // Return 1 if the log message is valid, 0 otherwise
}

struct TimeStamp {
    time_t t;
    char timestamp[32];
};

void format_timestamp(struct TimeStamp* timestamp) {
    ctime_r(&timestamp->t, timestamp->timestamp);
    timestamp->timestamp[strlen(timestamp->timestamp) - 1] = '\0'; // Remove newline character
}

int log(const char* message, const struct LogMessageSchema* schema, LogHandler* handlers[]) {
    int len = strlen(message);

    if (schema->max_debug_len > 0 && len > schema->max_debug_len) return 0;

    struct TimeStamp timestamp;
    format_timestamp(&timestamp);

    char formatted_message[256];
    snprintf(formatted_message, sizeof(formatted_message), "%s [%4.4s] %s", timestamp.timestamp, schema->context, message);

    for (LogHandler* handler : handlers) {
        if (!handler || handler->level > schema->context[0]) continue;
        double start = clock();
        int res = handler->handler(formatted_message, timestamp.timestamp);
        double duration = (clock() - start) / CLOCKS_PER_SEC;
        handler->frequency++;
        handler->total_duration += duration;
        if (!res) return 0;
    }

    return 1;
}
