#include <memory>

class NetworkDevice {
public:
    explicit NetworkDevice(unsigned long id) : id_(id), last_activity_(std::chrono::system_clock::now()), healthy_(true) {}

    unsigned long getId() const { return id_; }
    const std::vector<bool>& getConnectionStates() const { return connection_states_; }
    const auto& getLastActivity() const { return last_activity_; }
    bool isHealthy() const { return healthy_; }

private:
    unsigned long id_;
    std::vector<bool> connection_states_;
    std::chrono::system_clock::time_point last_activity_;
    bool healthy_;
};

class NetworkDeviceCollection {
public:
    void addDevice(const std::unique_ptr<NetworkDevice>& device) {
        std::scoped_lock lock(mutex_);
        devices_.emplace(device->getId(), std::move(device));
    }

    const std::shared_ptr<NetworkDevice> getDeviceById(unsigned long id) const {
        std::scoped_lock lock(mutex_);
        auto it = devices_.find(id);
        if (it != devices_.end())
            return it->second;
        return nullptr;
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<unsigned long, std::shared_ptr<NetworkDevice>> devices_;
};

// Lazy resizing strategy for efficient memory usage
constexpr size_t MAX_DEVICE_COUNT = 50000;
NetworkDeviceCollection collection;
size_t device_count = 0;
const size_t BATCH_SIZE = std::min(MAX_DEVICE_COUNT / 10, 1024);

void resize() {
    if (device_count >= MAX_DEVICE_COUNT)
        return;

    std::unique_ptr<NetworkDevice> devices(new NetworkDevice[BATCH_SIZE]);
    for (size_t i = device_count; i < device_count + BATCH_SIZE && i < MAX_DEVICE_COUNT; ++i) {
        devices[i - device_count].swap(collection.getDeviceById(i));
    }
    collection.addDevice(std::move(devices));
    device_count += BATCH_SIZE;
}

// Thread-safe resizing and operations using a lock-based approach
void performOperations() {
    std::vector<std::thread> threads;
    for (size_t i = 0; i < BATCH_SIZE; ++i) {
        threads.emplace_back([&]() {
            resize();
            unsigned long id = static_cast<unsigned long>(std::rand()) % MAX_DEVICE_COUNT;
            auto device = collection.getDeviceById(id);
            if (device)
                device->setHealthy(!device->isHealthy()); // Simulate health update operation
        });
    }

    for (auto& thread : threads)
        thread.join();
}
```

