function traverseDOMTree(node, selector, testFunc) {
    if (node.matches && node.matches(selector)) {
        return [node];
    }

    let matches = [];

    Array.from(node.children).forEach((childNode) => {
        const childrenMatches = traverseDOMTree(childNode, selector, testFunc);
        matches = matches.concat(childrenMatches);
    });

    for (let i = 0; i < matches.length; ++i) {
        const match = matches[i];
        if (testFunc(match)) {
            matches.splice(i, 1, [match]); // Replace matched elements with a single-element array
            return matches;
        }
    }

    return matches;
}
