typedef void* (*AlgorithmImplementation)(const void*, size_t, void*);
typedef struct {
    char id[32];
    AlgorithmImplementation implementation;
    const char* properties;
    bool is_supported;
} Algorithm;

typedef struct ListNode {
    Algorithm algorithm;
    struct ListNode* next;
} ListNode;

ListNode* create_node(Algorithm algorithm) {
    ListNode* node = malloc(sizeof(ListNode));
    if (!node) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    node->algorithm = algorithm;
    node->next = NULL;
    return node;
}

void free_list(ListNode* head) {
    while (head) {
        ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

ListNode* generateCryptographicReport(const char* inputFile, const char* outputFile, const char* rules) {
    FILE* input = fopen(inputFile, "rb");
    if (!input) {
        fprintf(stderr, "Unable to open input file: %s\n", inputFile);
        return NULL;
    }

    ListNode* head = NULL;
    Algorithm algorithm;

    while (fread(&algorithm.id, sizeof(algorithm.id), 1, input)) {
        void* handle = dlopen("", RTLD_LAZY);
        if (!handle) {
            fprintf(stderr, "Error loading library: %s\n", dlerror());
            continue;
        }

        char algorithm_path[256];
        sprintf(algorithm_path, "%s/%s.so", "./algorithms", algorithm.id);
        void* algorithm_symbol = dlsym(handle, algorithm.id);
        if ((dlerror()) || !(AlgorithmImplementation)algorithm_symbol) {
            fprintf(stderr, "Error loading algorithm %s: %s\n", algorithm.id, dlerror());
            dlclose(handle);
            continue;
        }

        Algorithm* current = &algorithm;
        if (current->is_supported = is_algorithm_supported()) {
            Algorithm new_algorithm = *current;
            ListNode* node = create_node(new_algorithm);
            node->algorithm.implementation = algorithm_symbol;
            char property_string[256];
            snprintf(property_string, sizeof(property_string), "%s %lu %lu", current->properties, current->implementation->blockSize, current->implementation->outputLength);
            node->algorithm.properties = strdup(property_string);
            node->next = head;
            head = node;
        }

        dlclose(handle);
    }

    fclose(input);

    // Apply transformation rules to the parsed contents before writing them to the output file

    FILE* output = fopen(outputFile, "w");
    if (!output) {
        fprintf(stderr, "Unable to open output file: %s\n", outputFile);
        return NULL;
    }

    ListNode* current = head;
    while (current) {
        fprintf(output, "%s\t%s\t%s\n", current->algorithm.id, current->algorithm.properties, current->algorithm.is_supported ? "Supported" : "Not supported");
        current = current->next;
    }

    fclose(output);

    return head;
}
