void* generate_rng(void* arg) {
    srand((unsigned int)arg);
    return &rand();
}

int create_pdu_arr(NFAPI_CRC_INDICATION_PDU_T** arr, size_t num_elements) {
    *arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*arr) return -1; // error: memory allocation failed

    pthread_t rng_threads[num_elements];
    void** rng_results = malloc(sizeof(void*) * num_elements);

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_create(&rng_threads[i], NULL, generate_rng, (void*)i);
    }

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_join(rng_threads[i], rng_results + i);
    }

    size_t idx = 0;
    for (size_t i = 0; i < num_elements; ++i) {
        (*arr)[idx].tag.id = RX_UE_INFORMATION_TAG_ID;
        (*arr)[idx].rnti = (RNTI){.rnti_value = idx};
        (*arr)[idx].crcInd.crcFlag = *(uint32_t*)rng_results[i]; // Cast to uint32_t since rand() returns an int
        idx++;
    }

    free(rng_results);
    return 0; // success
}
