#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} PDU_T;

typedef struct _allocator {
    size_t allocated_count;
    size_t failed_count;
    PDU_T *data;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Allocator;

Allocator allocator = {0, 0, NULL};

void destroy_pdu(PDU_T *pdu) {
    free(pdu);
}

int allocate_pdu(PDU_T **pdu) {
    pthread_mutex_lock(&allocator.mutex);

    if (allocator.data == NULL) {
        size_t capacity = 10000;
        allocator.data = malloc(capacity * sizeof(*allocator.data));
        if (!allocator.data) {
            allocator.failed_count++;
            pthread_mutex_unlock(&allocator.mutex);
            return -1;
        }
    }

    PDU_T *new_pdu = &allocator.data[allocator.allocated_count];
    new_pdu->tag.present = true;
    new_pdu->rnti = rand();
    new_pdu->crc_indication.present = true;
    new_pdu->crc_indication.crcflag = (rand() % 2) == 0 ? 1 : 0;

    allocator.allocated_count++;
    pthread_mutex_unlock(&allocator.mutex);

    return 0;
}

void free_all_pdus() {
    pthread_mutex_lock(&allocator.mutex);

    size_t i;
    for (i = 0; i < allocator.allocated_count; ++i) {
        destroy_pdu(&allocator.data[i]);
    }

    free(allocator.data);
    allocator.data = NULL;
    allocator.allocated_count = 0;
    allocator.failed_count = 0;

    pthread_mutex_unlock(&allocator.mutex);
}

// Usage example:
void* worker(void *arg) {
    PDU_T *pdu;

    while (1) {
        if (allocate_pdu(&pdu) == 0) {
            // Process the allocated pdu here...
            destroy_pdu(pdu);
        } else {
            printf("Failed to allocate PDU\n");
        }
    }
}
```

