import requests
import time
import logging

def monitor_remote_services(services, retry_count=3, timeout=5):
    for service in services:
        attempts = 0
        while attempts < retry_count:
            try:
                response = requests.get(service, timeout=timeout)
                if response.status_code == 200:
                    logging.info(f"{service} is healthy.")
                    break
                else:
                    logging.warning(f"{service} returned status code {response.status_code}. Retrying...")
            except requests.exceptions.RequestException as e:
                logging.error(f"Failed to reach {service}: {e}")
                attempts += 1
                time.sleep(timeout * 2)
        else:
            logging.info(f"{service} is unhealthy and no longer responding.")
