#include <pthread.h>

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    sem_t semaphore;
} resource_t;

resource_t shared_resource;
EVP_CIPHER *cipher = NULL;

void init_resources() {
    pthread_mutex_init(&shared_resource.mutex, NULL);
    pthread_cond_init(&shared_resource.cond, NULL);
    sem_init(&shared_resource.semaphore, 1, 1);
}

void cleanup_resources() {
    pthread_mutex_destroy(&shared_resource.mutex);
    pthread_cond_destroy(&shared_resource.cond);
    sem_destroy(&shared_resource.seaphore);
}

int is_valid_oauth2_token(const char *json_string) {
    json_t *root, *access_token, *expires_in, *token_type;
    int result = 1;

    root = json_loads(json_string, 0, NULL);
    if (!root || !json_is_object(root)) {
        result = 0;
        goto clean_up;
    }

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");

    if (!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) {
        result = 0;
        goto clean_up;
    }

    if (strcmp(json_string(token_type), "Bearer") != 0 || json_value_get_integer(expires_in) < 0) {
        result = 0;
    }

clean_up:
    json_decref(root);
    return result;
}

void lock() {
    pthread_mutex_lock(&shared_resource.mutex);
    sem_wait(&shared_resource.semaphore);
}

void unlock() {
    pthread_mutex_unlock(&shared_resource.mutex);
    sem_post(&shared_resource.semaphore);
}

int thread_safe_crypto_operation(const char *input, const char *options) {
    init_resources();

    lock();

    if (strstr(options, "null")) {
        cipher = NULL;
    } else if (strstr(options, "ecb")) {
        cipher = EVP_cipher_ctor("AES-128-ECB");
    } else if (strstr(options, "ede")) {
        cipher = EVP_cipher_ctor("AES-128-CBC");
    } else if (strstr(options, "ede3")) {
        cipher = EVP_cipher_ctor("AES-128-CFB1");
    } else if (strstr(options, "cfb")) {
        cipher = EVP_cipher_ctor("AES-128-CFB8");
    }

    if (!cipher) {
        goto clean_up;
    }

    if (!is_valid_oauth2_token(options)) {
        goto clean_up;
    }

    // Perform cryptographic operations here

clean_up:
    unlock();
    cleanup_resources();

    return 0;
}
```

