#include <vector>
#include <algorithm>
#include <mutex>
#include <utility>

std::mutex mtx; // Thread safety mutex

void modifyVector(std::vector<int>& vec, int target, int replacement, bool strictMode) {
    if (vec.empty()) return; // Handle empty vector

    auto it = std::find(vec.begin(), vec.end(), target);
    if (it != vec.end()) { // Target found
        std::lock_guard<std::mutex> lock(mtx); // Ensure thread safety when modifying the vector
        *it = replacement;
    } else if (!strictMode) { // Target not found, append to the end of the vector (thread-safe)
        std::lock_guard<std::mutex> lock(mtx);
        vec.push_back(replacement);
    }

    // Optimization for sorted or nearly sorted vectors
    if (!strictMode && std::is_sorted(vec.begin(), it)) {
        auto newEnd = std::upper_bound(it, vec.end(), target);
        vec.insert(newEnd, replacement);
    }
}
