public:
    SandeshClient(boost::asio::io_context& io_context) : strand_(io_context), timer_(io_context) {}

    void start(const std::string& serverUrl, size_t numPdusToSend) {
        generateUuid_ = boost::uuids::random_generator();
        for (size_t i = 0; i < numPdusToSend; ++i)
            sendRequest(serverUrl + "?uuid=" + boost::uuids::to_string(*generateUuid_++));
    }

private:
    void sendRequest(const std::string& requestUrl) {
        auto self = shared_from_this();
        auto req = std::make_shared<boost::asio::ip::tcp::iostream>(requestUrl);
        if (!req->is_open()) {
            ++failedRequests_;
            logFailedRequest(requestUrl);
            return;
        }
        self->startRequest(*req, [self](const boost::system::error_code& ec) {
            if (ec) {
                ++failedRequests_;
                logFailedRequest(requestUrl);
            } else {
                ++successfulRequests_;
                logSuccessfulRequest(requestUrl);
            }
        });
    }

    void startRequest(boost::asio::streambuf& buffer, std::function<void(const boost::system::error_code&)> callback) {
