    }

    void logFailedRequest(const std::string& requestUrl) {
        ++totalRequests_;
        std::cout << "Failed Request: " << requestUrl << "\n";
    }

    boost::uuids::random_device generateUuid_;
    boost::asio::io_context::strand strand_;
    boost::asio::deadline_timer timer_;

    size_t successfulRequests_ = 0;
    size_t failedRequests_ = 0;
