        testCase();
        blueslip.log(`Test passed: ${name}`);
        results.passed.push(name);
      } catch (error) {
        if (retries > 0) {
          blueslip.log(`Test failed: ${name}\nRetry attempt #${retries--}: ${error.message}`);
          continue; // Retry the test if it fails due to a transient network issue
        } else {
          blueslip.log(`Test failed: ${name}\nRetry attempts exhausted`);
          results.failed.push(name);
        }
      }
    }
  } catch (error) {
    blueslip.log(`Failed to load module: ${moduleName}\nError: ${error.message}`);
    results.skipped.push(moduleName);
  } finally {
    const performance = blueslip.getPerformanceMetrics();
    logs.push({ name, test, status: results.passed.includes(name) ? 'passed' : 'failed', timestamp: blueslip.now(), performance });

    blueslip.log(`Test suite completed: ${label}`);
    blueslip.reset(); // Reset the logging utility at the end of each test suite

    return { passed, failed, skipped, logs };
  }
};
```
In this example, I've created a `executeTests` function as per your specifications. The function takes three parameters: moduleName (string), testCases (array of test functions), and label (string representing the test suite name). It returns an object containing the names of tests that passed, failed, and were skipped, along with detailed logs of each test's outcome and any performance metrics collected during execution.

The example usage provided demonstrates how to use this function correctly, while the expected output is based on your specified requirements. The `blueslip` object is assumed to be a global utility for logging purposes, and its implementation is not included in this code snippet."]

["```javascript
const privacyWords = /(personal|confidential|sensitive)( data|information)|\bsensitive\b(\spersonal\sdata|\binformation|area)/gi;
const securityWords = /(security|integrity|confidentiality)(\sof|to|for|on|about)(\ssystem|data|network|infrastructure|services|applications|procedures)/gi;
const commonExclusions = /(disclaimer|terms|agreement|licence|warranty|indemnity|limitation|arbitration|governing law|\bassigned\b)/gi;

function extractClauses(doc) {
  const privacyCount = {};
  const securityCount = {};

  if (!doc || !doc.length) return { privacy: privacyCount, security: securityCount };

  let currentWord = '';
  let currentCount = 0;
  let commonExcluded = false;

  for (let i = 0; i < doc.length; ++i) {
    const charCode = doc.charCodeAt(i);

    if (charCode >= 32 && charCode <= 126) { // Ignore punctuation and special characters
      currentWord += String.fromCharCode(charCode);
    } else if (currentWord.length > 0) {
      if (!commonExcluded) {
        if (privacyWords.test(currentWord)) {
          privacyCount[currentWord] = (privacyCount[currentWord] || 0) + 1;
        }
        if (securityWords.test(currentWord)) {
          securityCount[currentWord] = (securityCount[currentWord] || 0) + 1;
        }
      }

      currentWord = '';
      currentCount = 0;
    }

    if (charCode === 32) { // Space character
      commonExcluded = commonExclusions.test(currentWord);
      currentCount++;

      if (!commonExcluded && currentCount > 3) { // Ignore phrases shorter than 4 words
        privacyCount[currentWord] = (privacyCount[currentWord] || 0) + 1;
        securityCount[currentWord] = (securityCount[currentWord] || 0) + 1;
      }
      currentWord = '';
      currentCount = 0;
    }
  }

  if (currentWord.length > 0) { // Process any remaining words at the end of the document
    if (!commonExcluded) {
      if (privacyWords.test(currentWord)) {
        privacyCount[currentWord] = (privacyCount[currentWord] || 0) + 1;
      }
      if (securityWords.test(currentWord)) {
        securityCount[currentWord] = (securityCount[currentWord] || 0) + 1;
      }
    }
  }

  return { privacy: privacyCount, security: securityCount };
}
```"]

[' Here's a JavaScript function that meets your requirements. It uses an efficient data structure (Map) to store menu items and handles sub-menu items recursively. The filtering mechanism is case-insensitive and updates the displayed menu items in real-time using setTimeouts for smooth UIs.

```javascript
const buildMenu = (data, filter = '', parentId = null) => {
  const menuItems = new Map();

  data.forEach(item => {
    if (!item.title || !item.icon) return; // Skip invalid items

    let id = item.id || `${Date.now()}-${Math.floor(Math.random() * 1000)}`;

    if (item.subItems && item.subItems.length > 0) {
      buildMenu(item.subItems, filter, id); // Recursive call for sub-menu items
    }

    const filtered = (item.title.toLowerCase().includes(filter.toLowerCase()) || item.icon.toLowerCase().includes(filter.toLowerCase()));

    if (filtered) {
      menuItems.set(id, { ...item, parentId }); // Add the filtered item to the menu
    }
  });

  const menuHtml = menuItems.entries()
    .reduce((acc, [id, { title, icon, subItems, parentId }]) => {
      const hasSubmenu = subItems && subItems.length > 0;
      let html = `<li class="nav-item" id="${id}">`;
      if (hasSubmenu) html += `<a class="nav-link dropdown-toggle" data-bs-toggle="dropdown" href="#" role="button" aria-expanded="false">`;
      else html += `<a class="nav-link" href="${parentId ? parentId : '#'}" ${hasSubmenu ? 'aria-controls="navbarNavDropdown"' : ''}>`;
      html += `${icon ? `<span class="me-2 nav-icon"><i class="${icon}"></i></span>` : ''}${title}</a>`;
      if (hasSubmenu) {
        const subMenuHtml = Array.from(subItems).reduce((acc, subItem) => acc + buildMenu(subItem, filter, id), '');
        html += `<ul class="dropdown-menu" aria-labelledby="${id}">${subMenuHtml}</ul>`;
      }
      return html + '</li>';
    }, '');

  setTimeout(() => document.getElementById('navbarNav').innerHTML = menuHtml, filter ? 10 : 0); // Update the navigation in real-time

  return menuHtml;
};
```

