func createGRPCClient(address, tlsCert, tlsKey, caCert string, authType string, maxConcurrentRequests int, maxConnectionIdle time.Duration, backoffFactor float64, monitoringEnabled bool, monitoringServiceURL string) (*grpc.ClientConn, error) {
	var creds credentials.TransportCredentials
	if authType == "client_cert" {
		cert, err := tls.LoadX509KeyPair(tlsCert, tlsKey)
		if err != nil {
			return nil, err
		}
		creds = credentials.NewClientTLSFromCertificate(nil, caCert)
	} else if authType == "basic" {
		username, password, err := getAuthCredentials()
		if err != nil {
			return nil, err
		}
		creds = credentials.NewBasicAuth(username, password)
	}

	dialOptions := []grpc.DialOption{
		grpc.WithTransportCredentials(creds),
		grpc.WithKeepaliveParams(keepalive.ClientParameters{Time: 5 * time.Second, TobIdle: maxConnectionIdle}),
	}

	if monitoringEnabled {
		dialOptions = append(dialOptions, grpc.WithUnaryInterceptor(monitoring.NewGRPCMonitoringInterceptor(monitoringServiceURL)))
	}

	conn, err := grpc.DialContext(context.Background(), address, dialOptions...)
	if err != nil {
		return nil, err
	}

	connOpts := &options{maxConcurrentRequests: maxConcurrentRequests, backoffFactor: backoffFactor}
	client := grpc.NewClientStream(conn, connOpts)

	go func() {
		<-signal.Interrupt
		_ = conn.Close()
	}()

	return conn, nil
}

func getAuthCredentials() (string, string, error) {
	// Implement your custom method for getting the username and password from environment variables or other sources
	username := os.Getenv("GRPC_USERNAME")
	password := os.Getenv("GRPC_PASSWORD")
	if username == "" || password == "" {
		return "", "", errors.New("missing GRPC_USERNAME or GRPC_PASSWORD environment variables")
	}
	return username, password, nil
}
