using System;
using System.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using Dapper;
using System.Collections.Generic;
using System.Linq;

public class EmployeeQuery
{
    private readonly IConfiguration _config;
    public EmployeeQuery(IConfiguration config)
    {
        _config = config;
    }

    public IEnumerable<Employee> GetEmployeesBySupervisorId(int supervisorId, int pageSize, int pageNumber)
    {
        string connectionString = _config.GetConnectionString("DefaultConnection");
        using (var conn = new SqlConnection(connectionString))
        {
            var parameters = new DynamicParameters();
            parameters.Add("supervisor_id", supervisorId, dbType: DbType.Int32);
            parameters.Add("@pageSize", pageSize, dbType: DbType.Int32);
            parameters.Add("@pageNumber", pageNumber, dbType: DbType.Int32);

            var sql = @"
                WITH EmployeeAndSupervisor AS (
                    SELECT e.*, s.name as supervisor_name
                    FROM Employees e
                    INNER JOIN Supervisors s ON e.supervisor_id = s.id
                    WHERE e.id = @supervisor_id
                ), EmployeeWithoutSupervisor AS (
                    SELECT e.*
                    FROM Employees e
                    LEFT JOIN EmployeeAndSupervisor eas ON e.id = eas.id
                    WHERE eas.id IS NULL
                )
                SELECT
                    ROW_NUMBER() OVER (ORDER BY e.name) AS rowNumber,
                    e.name, e.city, e.address,
                    CASE WHEN rowNumber > (EmployeeWithoutSupervisor.rowNumber + @pageSize * (@pageNumber - 1)) THEN 'No Employees' ELSE e.name END AS message
                FROM EmployeeWithoutSupervisor e
                ORDER BY e.name";

            var queryResult = conn.Query<Employee, string, Employee>(sql, (employee, message) => { employee.Message = message; return employee }, parameters, pageSize: pageSize, pageNumber: pageNumber);

            return queryResult;
        }
    }
}

public class Employee
{
    public int Id { get; set; }
    public string Name { get; set; }
    public string City { get; set; }
    public string Address { get; set; }
    public string Message { get; set; }
}
```

