<?php

namespace App\Helpers;

use Closure;
use Illuminate\Support\Facades\Config;
use Illuminate\Support\Str;
use Ramsey\Uuid\Uuid;
use Psr\Cache\CacheItemPoolInterface;
use Symfony\Component\PasswordHasher\Argon2iPasswordHasher;
use GuzzleHttp\Client as HttpClient;

class UtilityHelper
{
    protected static $config;
    protected static $passwordHasher;
    protected static $cache;

    public function __construct(array $config = [], CacheItemPoolInterface $cache)
    {
        self::$config = array_merge([
            'randomStringCharSet' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',
            'randomStringLength' => 10,
            'passwordHasherClass' => Argon2iPasswordHasher::class,
            'apiKey' => null,
        ], $config);

        static::$passwordHasher = new self::$config['passwordHasherClass'](static::$config['memoryCost'], static::$config['timeCost']);
        static::$cache = $cache;
    }

    public static function setConfig(array $config): void
    {
        self::$config = array_merge(self::$config, $config);
    }

    // Random String Generation
    public static function generateRandomString($length = null)
    {
        if (is_null($length)) {
            $length = self::$config['randomStringLength'];
        }

        return Str::random($length, self::$config['randomStringCharSet']);
    }

    // Password Hashing
    public static function hashPassword(string $password)
    {
        return static::$passwordHasher->hashPassword($password);
    }

    public static function verifyPassword(string $plainPassword, string $hashedPassword)
    {
        return static::$passwordHasher->verifyHashedPassword($plainPassword, $hashedPassword);
    }

    // User Input Sanitization
    public static function sanitizeInput($input)
    {
        if (is_array($input)) {
            return array_map([__CLASS__, 'sanitizeInput'], $input);
        }

        return filter_var($input, FILTER_SANITIZE_STRING, FILTER_FLAG_STRIP_LOW | FILTER_FLAG_STRIP_HIGH);
    }

    // API Integration
    public static function callApi(string $url, array $params = [], Closure $callback = null)
    {
        if (!empty(self::$config['apiKey'])) {
            $headers = ['Authorization' => 'Bearer ' . self::$config['apiKey']];
        } else {
            $headers = [];
        }

        $httpClient = new HttpClient([
            'headers' => $headers,
        ]);

        try {
            if ($callback) {
                return $httpClient->request('GET', $url, ['query' => $params])->then($callback);
            } else {
                return $httpClient->request('GET', $url, ['query' => $params]);
            }
        } catch (\Exception $e) {
            // Handle exceptions as needed
        }
    }
}
