#include <map>

enum class EnemyType { ALIEN, ZOMBIE, SKELETON };

class AttackResource {
public:
    int maxResources = 60;
    int currentResources = maxResources;
    int energyLevel = 100;
    int cooldown = 9;
    std::map<int, int> attackCosts; // Key is the attack type, value is cost in resources and energy

    bool canAttack() {
        if (cooldown > 0) return false;
        if (currentResources < attackCosts[0]) return false;
        if (energyLevel < attackCosts[1]) return false;
        return true;
    }

    void consumeResource(int attackType) {
        currentResources -= attackCosts[attackType];
        energyLevel -= attackCostes[attackType + 2];
    }

    void resetCooldown() {
        cooldown = 9;
    }

    void restoreEnergy(int amount) {
        energyLevel += amount;
        if (energyLevel > 100) energyLevel = 100;
    }

    // This function should be provided by external power-up system.
    void provideResources(int resourceAmount, int energyAmount) {
        currentResources += std::min(currentResources + resourceAmount, maxResources);
        energyLevel += std::min(energyLevel + energyAmount, 100);
    }
};

void selectAttack(AttackResource& resources, EnemyType enemy) {
    auto start = std::chrono::high_resolution_clock::now();

    while (!resources.canAttack()) {
        if (resources.energyLevel < 100 && resources.currentResources < maxResources) {
            resources.provideResources(5, 3); // Example values for resource and energy amounts provided by power-up system.
        }
        std::this_thread::sleep_for(std::chrono::seconds(30)); // Attempt to retry every 30 seconds.
    }

    int attackType = (enemy == EnemyType::ALIEN) ? 0 : ((enemy == EnemyType::ZOMBIE) ? 1 : 2); // Prioritize attacks based on enemy type.

    resources.consumeResource(attackType);
    std::cout << "Attack " << attackType + 1 << " used at " << std::chrono::duration_cast<std::chrono::seconds>(std::chrono::high_resolution_clock::now() - start).count() << " seconds.\n";

    if (enemy == EnemyType::ALIEN && attackType == 0) resources.restoreEnergy(20); // Example of logging relevant statistics.
}
