char* processString(const char* str, size_t limit, bool append, char special) {
    if (!str || limit <= 0 || limit > SIZE_MAX || !ISFINITE(limit)) {
        return NULL;
    }

    size_t len = strlen(str);

    // Handle the special case where the string fits exactly without appending a character
    if (len < limit && !append) {
        return strdup(str);
    }

    // Check if the string fits with the append character
    if (len + (append ? 1 : 0) <= limit) {
        char* result = malloc(len + (append ? 1 : 0));
        if (!result) {
            return NULL;
        }
        memcpy(result, str, len);
        if (append) {
            result[len] = special;
        }
        return result;
    } else { // String is too long; truncate and append a truncation indicator
        size_t to_copy = limit - 3;
        char* result = malloc(to_copy + 1); // +1 for the null terminator
        if (!result) {
            return NULL;
        }
        memcpy(result, str, to_copy);
        result[to_copy] = UCHAR_MAX; // Replace truncated characters with UTF-8 continuation byte (0xFF)
        result[to_copy + 1] = '\0';
        result = realloc(result, strlen(result) + 3); // Allocate space for the truncation indicator ('...')
        if (!result) {
            free(result);
            return NULL;
        }
        strncat(result, "...", 3); // Append truncation indicator
        return result;
    }
}
```
