    const size_t env_var_len = strlen("ENV_VAR=");
    const size_t dir_len = strlen("DIR=");
    const size_t exec_len = strlen("EXEC=");

    if (strlen(line) <= env_var_len || strlen(line) <= dir_len || strlen(line) <= exec_len) {
        return false;
    }

    if (strncmp(line, "ENV_VAR=", env_var_len) == 0 ||
        strncmp(line, "DIR=", dir_len) == 0 ||
        strncmp(line, "EXEC=", exec_len) == 0) {
        return true;
    }

    return false;
}

