#define MAX_PROCESSES 10
static pid_t processes[MAX_PROCESSES];
static int num_processes = 0;
static char *config_file;
static struct timespec timeout = {5, 0}; // 5 seconds

void sig_handler(int signum) {
    for (int i = 0; i < num_processes; ++i) {
        if (tcsetpgrp(0, getpgid(processes[i])) == -1) {
            perror("tcsetpgrp");
        }

        if (kill(processes[i], signum) != 0) {
            perror("kill");
        }
    }
}

int exec_command(const char *command, const char *envp[], char **argv) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        // Child process
        signal(SIGINT, sig_handler);
        signal(SIGTERM, sig_handler);

        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);

        char logfile[64];
        snprintf(logfile, sizeof(logfile), "/path/to/logs/%ld.log", (long) getpid());

        int fd = open(logfile, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (fd != -1) {
            dup2(fd, STDOUT_FILENO);
            close(fd);
        }

        setpgid(0, 0);
        execvp(command, argv);
        perror("execvp");
        _exit(1);
    } else { // Parent process
        clock_gettime(CLOCK_MONOTONIC, &now);
        if ((now.tv_sec - start.tv_sec) > timeout.tv_sec || (now.tv_nsec - start.tv_nsec) >= timeout.tv_nsec) {
            kill(pid, SIGTERM);
            return 0;
        }

        int index = num_processes++;
        if (num_processes >= MAX_PROCESSES) {
            waitpid(-1, NULL, WNOHANG);
            for (int i = 0; i < num_processes; ++i) {
                if (tcsetpgrp(0, getpgid(processes[i])) == -1) {
                    perror("tcsetpgrp");
                }

                if (kill(processes[i], SIGTERM) != 0) {
                    perror("kill");
                }
            }
        }
        processes[index] = pid;
        return 1;
    }
}

