typedef enum { NO_ERROR = 0, JSON_ERROR = -1, FILE_ERROR = -2, BASE64_ERROR = -3 } ErrorCode;

ErrorCode validateOAuthToken(const char *token_json, json_t **oauth_token);
ErrorCode loadResourceBundle(const char *filepath, size_t *num_items, json_t **resource_bundle);

ErrorCode validateOAuthTokenAndLoadResourceBundle(const char *token_json, const char *filepath, size_t *num_items) {
    json_t *oauth_token = NULL;
    ErrorCode result;

    if ((result = validateOAuthToken(token_json, &oauth_token)) != NO_ERROR) return result;

    result = loadResourceBundle(filepath, num_items, &oauth_token);

    json_decref(oauth_token);
    return result;
}

ErrorCode validateOAuthToken(const char *token_json, json_t **oauth_token) {
    json_error_t error;
    json_t *root = json_loads(token_json, 0, &error);

    if (!root || json_is_error(&error)) {
        fprintf(stderr, "Error parsing token JSON: %s\n", error.text);
        return JSON_ERROR;
    }

    if (json_object_get(root, "access_token") == NULL) goto invalid_oauth;
    if (json_object_get(root, "expires_in") == NULL) goto invalid_oauth;
    if (json_object_get(root, "token_type") == NULL) goto invalid_oauth;
    if (strcmp(json_string_value(json_object_get(root, "token_type")), "Bearer")) goto invalid_oauth;

    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    if (expires_in <= 0) goto invalid_oauth;

    if (json_object_has_member(root, "refresh_token")) {
        const char *refresh_token = json_string_value(json_object_get(root, "refresh_token"));
        int b64len = base64_encoded_length((const unsigned char *)refresh_token, strlen(refresh_token));
        if (b64len != strlen(refresh_token)) goto invalid_oauth;

        unsigned char decoded[base64_encoded_length(refresh_token, strlen(refresh_token)) + 1];
        int decoded_len = base64_decode((const unsigned char *)refresh_token, strlen(refresh_token), decoded, b64len);
        if (decoded_len != b64len) goto invalid_oauth;
        // Perform additional checks for decoded string as needed
    }

    *oauth_token = root;
    return NO_ERROR;

invalid_oauth: {
    fprintf(stderr, "Invalid OAuth2 access token structure.\n");
    json_decref(*oauth_token);
    return JSON_ERROR;
}

ErrorCode loadResourceBundle(const char *filepath, size_t *num_items, json_t **resource_bundle) {
    FILE *fp = fopen(filepath, "r");
    if (!fp) {
        perror("Error opening file");
        return FILE_ERROR;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    json_t *root = json_loadf(fp, 0, &json_deprecated_cb, &json_warn_unknown_field_cb, &lock);
    if (root == NULL) {
        perror("Error parsing JSON from file");
        pthread_mutex_destroy(&lock);
        return FILE_ERROR;
    }

    *num_items = json_array_size(json_object_get(root, "resource_bundle"));
    *resource_bundle = root;

    pthread_mutex_destroy(&lock);
    fclose(fp);
    return NO_ERROR;
}
```

