namespace DownloadAndDecryptLogFile
{
    class Program
    {
        static void Main(string[] args)
        {
            string sequenceNumber = DecryptAndProcessLogFile();
            Console.WriteLine($"Sequence Number: {sequenceNumber}");
        }

        static string DecryptAndProcessLogFile()
        {
            const string cloudStorageUrl = "https://example-cloud-storage.com/logfile";
            const string aesKey = "Your AES Key Here";
            const string aesIv = "Your AES IV Here";
            const string tripleDesKey = "Your Triple DES Key Here";
            const string tripleDesIv = "Your Triple DES IV Here";
            const string configParam = "CustomKey";

            string logFilePath = DownloadFile(cloudStorageUrl);

            if (string.IsNullOrEmpty(logFilePath))
                return string.Empty;

            using var aes = AES.Create();
            aes.Key = Encoding.UTF8.GetBytes(aesKey);
            aes.IV = Encoding.UTF8.GetBytes(aesIv);

            using var tripleDes = TripleDES.Create();
            tripleDes.Key = Encoding.UTF8.GetBytes(tripleDesKey);
            tripleDes.IV = Encoding.UTF8.GetBytes(tripleDesIv);

            byte[] encryptedData = File.ReadAllBytes(logFilePath);

            using (MemoryStream ms = new MemoryStream())
            {
                using var tfde = new TripleDESCryptoServiceProvider().CreateCryptoTransform(Mode.CFB, tripleDes.CreateEncryptor());
                using var pdes = new AesCryptoServiceProvider().CreateCryptoTransform(aes.CreateDecryptor(), aesIv);

                tfde.TransformBlock(encryptedData, 0, encryptedData.Length, null, 0);
                pdes.TransformBlock(tfde.TransformFinalBlock(encryptedData, 0, encryptedData.Length), 0, encryptedData.Length, ms, 0);

                var decryptedContent = Encoding.UTF8.GetString(ms.ToArray());

                Dictionary<string, List<string>> sortedLines = new Dictionary<string, List<string>>();

                foreach (var line in decryptedContent.Split('\n'))
                {
                    var key = JObject.Parse(line)?.GetValue(configParam).ToString() ?? string.Empty;
                    if (!sortedLines.ContainsKey(key))
                        sortedLines[key] = new List<string>();
                    sortedLines[key].Add(line);
                }

                var sortedData = from key in sortedLines.Keys
                                 orderby sortedLines[key]
                                 select new { Key = key, Lines = sortedLines[key] };

                string sequenceNumber = sortedData.Last().Lines.Last(); // Last line of the sorted data

                File.Delete(logFilePath);
                return sequenceNumber;
            }
        }

        static string DownloadFile(string url)
        {
            try
            {
                using (var client = new WebClient())
                {
                    return client.DownloadFile(url, "tempfile.log");
                }
            }
            catch (WebException ex)
            {
                Console.WriteLine($"Failed to download log file: {ex.Message}");
                return string.Empty;
            }
        }
    }
}
