```csharp
using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

public class ThreadPoolExecutor
{
    private readonly ConcurrentQueue<Action> _taskQueue = new ConcurrentQueue<Action>();
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(Environment.ProcessorCount, Environment.ProcessorCount);
    private readonly CancellationTokenSource _cancellationTokenSource;
    private readonly Func<Task> _completionCallback;

    public ThreadPoolExecutor(Func<Action> taskGenerator, Func<Task> completionCallback = null)
    {
        _taskGenerator = () => new Action(taskGenerator);
        _completionCallback = completionCallback ?? (() => Task.CompletedTask);
    }

    public void Start(CancellationToken cancellationToken = default)
    {
        _cancellationTokenSource = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        Task.Run(async () => await ProcessTasks(_cancellationTokenSource.Token), _cancellationTokenSource.Token);
    }

    public void Stop()
    {
        _cancellationTokenSource.Cancel();
    }

    private async Task ProcessTasks(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            if (_taskQueue.TryDequeue(out var task))
            {
                await _semaphore.WaitAsync(cancellationToken);
                try
                {
                    task();
                }
                finally
                {
                    _semaphore.Release();
                }
            }
            else
            {
                await Task.Delay(100, cancellationToken);
            }
        }

        if (_completionCallback != null)
        {
            await _completionCallback();
        }
    }
}
