import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.nio.charset.StandardCharsets;

public class CustomClass {
    private static final String JAVASCRIPT_LOADER = "JavaScriptLoader";
    private static final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();

    public <T> T deserialize(byte[] data) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return (T) ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Unable to deserialize object. Class not found.", e);
        }
    }

    public void executeJavaScript(String filePath) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getByName(JAVASCRIPT_LOADER);

        try (Reader reader = new FileReader(filePath)) {
            engine.eval(reader, null, null);
        } catch (IOException | ScriptException e) {
            System.err.println("Error while loading or executing JavaScript file: " + e.getMessage());
        }
    }

    public void connectAndTransferData(String host, int port) {
        SocketChannel channel = null;

        try {
            Selector selector = Selector.open();
            ServerSocketChannel serverSocket = ServerSocketChannel.open();
            serverSocket.bind(new InetSocketAddress(host, port));
            serverSocket.configureBlocking(false);
            serverSocket.register(selector, SelectionKey.OP_ACCEPT);

            while (true) {
                selector.select();

                Iterator<SelectionKey> it = selector.selectedKeys().iterator();
                while (it.hasNext()) {
                    SelectionKey key = it.next();
                    it.remove();

                    if (key.isAcceptable()) {
                        SocketChannel clientSocket = serverSocket.accept();
                        clientSocket.configureBlocking(false);
                        clientSocket.register(selector, SelectionKey.OP_READ);
                        System.out.println("New connection established: " + clientSocket);
                    } else if (key.isReadable()) {
                        SocketChannel socketChannel = (SocketChannel) key.channel();
                        ByteBuffer buffer = ByteBuffer.allocateDirect(1024);
                        int readBytes = socketChannel.read(buffer);
                        if (readBytes > 0) {
                            buffer.flip();
                            while (buffer.hasRemaining()) {
                                // Process the received data
                            }
                            buffer.clear();
                        } else {
                            socketChannel.close();
                            System.out.println("Connection terminated: " + socketChannel);
                        }
                    }
                }
            }
        } catch (IOException e) {
            System.err.println("Error while connecting or transferring data: " + e.getMessage());
        } finally {
            if (channel != null) channel.close();
        }
    }
}
