  const process = child_process.spawn('sh', ['-c', command]);

  let output = '';
  process.stdout.on('data', (data) => {
    output += data;
  });

  process.stderr.on('data', (errData) => {
    console.error(`Command execution error: ${errData}`);
    throw new Error(errData);
  });

  process.on('close', (code) => {
    if (code !== 0) {
      console.error(`Command execution failed with code: ${code}`);
      throw new Error(`Command execution failed with code: ${code}`);
    }

    return redisClient.set(key, output, 'EX', 60 * 10); // Cache for 10 minutes
