import requests
import time
import logging
from concurrent.futures import ThreadPoolExecutor

def health_check(url, retries=5, timeout=10):
    attempts = retries
    success = False

    def check():
        nonlocal attempts, success
        try:
            response = requests.get(url, timeout=timeout)
            if response.status_code >= 200 and response.status_code < 300:
                success = True
                return True
        except Exception as e:
            logging.error(f"Health check failed for {url}: {e}")

        if attempts > 0:
            attempts -= 1
            time.sleep(timeout)
            return check()

    if not check():
        logging.warning(f"{url} is unhealthy after {retries} retries.")
    else:
        logging.info(f"{url} is healthy.")
```

