  2. C Function (using hashlib library for computing checksum):

```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdint.h>
#include <openssl/sha.h>

void append_checksum(const char *file_path, char *new_file_path) {
    FILE *fp = fopen(file_path, "rb");
    SHA256_CTX ctx;
    uint8_t hash[SHA256_DIGEST_LENGTH];

    if (!fp || !new_file_path) {
        return;
    }

    SHA256_Init(&ctx);
    while (1) {
        size_t n = fread(hash, 1, sizeof(hash), fp);
        if (n == 0) break;
        SHA256_Update(&ctx, hash, n);
    }
    SHA256_Final(hash, &ctx);

    snprintf(new_file_path, PATH_MAX, "%s.checksum", file_path);
    FILE *new_fp = fopen(new_file_path, "w");
    if (!new_fp) {
        return;
    }

    fprintf(new_fp, "%s", sha256_to_hex(hash));
    fclose(new_fp);
}
