// Service class for text preprocessing
class TextPreprocessor {
public:
    char* process(const char* input) {
        char* processed = (char*)calloc(strlen(input), sizeof(char));
        int len = 0;

        for (int i = 0; input[i]; ++i) {
            if (isalpha(input[i])) {
                processed[len++] = tolower(input[i]);
            } else if (input[i] == ' ') {
                processed[len++] = ' ';
            }
        }

        processed[len] = '\0';
        return processed;
    }
};

void processUserInput(const char* userId, const char* filePath, char** textData) {
    DIR* dir = opendir(".");
    struct stat pathStat;
    TextPreprocessor preprocessor;

    // Validate the file path within the application's directory structure
    if (stat(filePath, &pathStat) != 0 || S_ISDIR(pathStat.st_mode)) {
        printf("Invalid file path provided.\n");
        return;
    }

    int fd = open(filePath, O_RDONLY);
    struct stat contentStat;
    fstat(fd, &contentStat);
    char* buffer = (char*)malloc(contentStat.st_size + 1);

    // Read the file content into a dynamically allocated buffer
    read(fd, buffer, contentStat.st_size);
    close(fd);
    buffer[contentStat.st_size] = '\0';

    char* processedText = preprocessor.process(buffer);

    // Save the processed text back to the original file
    int writtenBytes = write(fd, processedText, strlen(processedText));
    close(fd);
}

unsigned long findLongestWordLength(char* text) {
    unsigned long maxLength = 0;
    unsigned long currentLength = 0;

    for (int i = 0; text[i]; ++i) {
        if (text[i] == ' ') {
            if (currentLength > maxLength)
                maxLength = currentLength;
            currentLength = 0;
        } else {
            ++currentLength;
        }
    }

    if (currentLength > maxLength)
        maxLength = currentLength;

    return maxLength;
}
