import os
import sys
from urllib.request import urlretrieve, Request
import zipfile
import logging

def find_longest_word_length(text):
    longest_length = 0
    current_length = 0

    for char in text:
        if char == ' ':
            if current_length > longest_length:
                longest_length = current_length
            current_length = 0
        else:
            current_length += 1

    if current_length > longest_length:
        longest_length = current_length

    return longest_length

def process_log(config):
    log_file_url = config['log_file_url']
    sort_key = config['sort_key']

    # Download the file from a cloud storage service
    local_file = 'download.zip'
    Request(log_file_url, headers={'User-Agent': 'Mozilla/5.0'}, method='GET').get_wrapper().doit(local_file)

    with zipfile.ZipFile(local_file, 'r') as zf:
        zf.extractall()

    # Sort the lines based on a custom key defined by the configuration parameter
    sort_key_func = {
        'word': lambda x: x.split()[0],
        'time': lambda x: x.split()[0]
    }[sort_key]

    lines = []
    with open(os.path.join(os.getcwd(), zf.namelist()[0]), 'r') as f:
        for line in f:
            lines.append((line, sort_key_func(line)))

    sorted_lines = sorted(lines, key=lambda x: x[1])

    # Extract a sequence number from the last line
    sequence_number = int(sorted_lines[-1][0].split(' ')[-1])

    os.remove(local_file)

    return sequence_number

if __name__ == "__main__":
    config = {
        'log_file_url': sys.argv[1],
        'sort_key': 'word'  # or 'time'
    }

    logging.basicConfig(level=logging.INFO)
    try:
        sequence_number = process_log(config)
        print(f"Sequence number extracted: {sequence_number}")
    except Exception as e:
        logging.exception(e)
        sys.exit(1)
