int process_directory(const char *path, const char *error_log_file) {
    error_log = fopen(error_log_file, "w");
    DIR *dir = opendir(path);
    if (!dir) log_error("Failed to open directory.");

    struct dirent *entry;
    FileData file_data;
    char new_filename[256];
    void *hash_data = NULL;
    int count = 0;
    pthread_t hash_thread;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        snprintf(file_data.path, sizeof(file_data.path), "%s/%s", path, entry->d_name);
        struct stat st;
        if (stat(file_data.path, &st) != 0 || S_ISDIR(st.st_mode)) continue;

        file_data.size = st.st_size;
        file_data.mtime = st.st_mtime;

        pthread_create(&hash_thread, NULL, hash_file, &file_data);
        if (pthread_join(hash_thread, &hash_data) != 0) log_error("Failed to join thread.");

        snprintf(new_filename, sizeof(new_filename), generate_new_filename(entry->d_name, hash_data));
        if (!is_valid_filename(new_filename)) {
            log_error("Invalid new filename.");
            continue;
        }

        if (rename_file(file_data.path, new_filename) == 0) {
            count++;
        } else {
            log_error("Failed to rename file.");
        }
    }

    closedir(dir);
    free(hash_data);
    free(error_log);
    return count;
}
