    size_t index = hash(key, hash_table->capacity);
    Record* current = hash_table->records[index];
    Record* previous = nullptr;

    pthread_mutex_lock(&hash_table->lock);
    while (current != nullptr && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == nullptr) {
        pthread_mutex_unlock(&hash_table->lock);
        return nullptr;
    }

    if (previous == nullptr) {
        hash_table->records[index] = current->next;
    } else {
        previous->next = current->next;
    }

    pthread_mutex_unlock(&hash_table->lock);

