typedef struct {
    SSL *tls_context;
    EC_KEY *identity_key; // ECDSA private key
} TLS_CONTEXT;

TLS_CONTEXT *tls1_3_init(const char *client_cert_pem, const char *client_key_pem) {
    SSL_library_init();
    const SSL_METHOD *method = TLSv1_3_server_method();
    SSL_CTX *ctx = SSL_CTX_new(method);

    // Set session ticket cache
    SSL_SESSION_CACHE_set_cb(SSL_SESSION_CACHE_get_default(), SSL_get_session_cache_callback(NULL, NULL));

    // Load client identity key and certificate
    EC_KEY *identity_key = EC_KEY_new_by_private_key(d2i_ECPrivateKey_fp(NULL, (const char *)client_key_pem, strlen(client_key_pem)), NULL);
    X509 *certificate = d2i_X509_fp((const char *)client_cert_pem, strlen(client_cert_pem));
    STACK_OF(X509) certs = SK_NEW(X509);
    sk_X509_push(certs, certificate);

    // Configure SSL context for ECDSA authentication and session resumption
    SSL_CTX_set_ecdh_auto(ctx, 1);
    SSL_CTX_set_session_cache_size(ctx, 1024);

    // Initialize TLS context
    TLS_CONTEXT *tls_context = malloc(sizeof(TLS_CONTEXT));
    tls_context->tls_context = SSL_new(ctx);
    SSL_set_ecdh_auto(tls_context->tls_context, 1);

    // Set identity key and certificate for ECDSA authentication
    EC_KEY *tmp_identity_key;
    EVP_PKEY *pkey;
    pkey = EC_KEY_get0_private_key(identity_key);
    tmp_identity_key = EC_KEY_dup(identity_key);
    SSL_use_certificate_chain_file(tls_context->tls_context, certs);
    SSL_set_ecdh_auto(tls_context->tls_context, 1);
    SSL_CTX_set_tmp_ecdh(ctx, EC_KEY_get0_public_key(tmp_identity_key));
    tls_context->identity_key = identity_key;

    // Return TLS context and clean up temporary variables
    ERR_clear_error();
    EVP_PKEY_free(pkey);
    EC_KEY_free(tmp_identity_key);
    sk_X509_pop_free(certs, X509_free);
    SK_FREE(certs);

    return tls_context;
}

void tls1_3_close(TLS_CONTEXT *tls_context) {
    SSL_free(tls_context->tls_context);
    EC_KEY_free(tls_context->identity_key);
    free(tls_context);
}
```

