#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <openssl/des.h>

#define MAX_LINE 4096

typedef struct {
    char *key;
    char *value;
} ConfigDirective;

void parse_config(const char *path, ConfigDirective **directives, size_t *size) {
    FILE *file = fopen(path, "r");
    char line[MAX_LINE];
    char *token;
    size_t count = 0;
    *directives = malloc(sizeof(ConfigDirective) * count);

    while (fgets(line, sizeof(line), file)) {
        token = strtok(line, "=");
        if (!token) continue;
        directives[count++]->key = strdup(token);
        token = strtok(NULL, "\n");
        directives[count-1]->value = strdup(token ? token : "");
    }
    *size = count;
    fclose(file);
}

int setup_environment(const char *config_path, const char *target_dir, const char *encrypted_message, char **env) {
    ConfigDirective *directives;
    size_t directive_count;
    parse_config(config_path, &directives, &directive_count);

    DES_cblock iv = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    DES_key_schedule key;
    DES_decryptInit(&key, (const unsigned char *)getenv("DES_KEY"), iv);
    unsigned char *message = malloc(strlen(encrypted_message) + 1);
    memcpy(message, encrypted_message, strlen(encrypted_message));
    DES_decrypt(message, message, &key);

    for (size_t i = 0; i < directive_count; ++i) {
        if (strcmp(directives[i].key, "ENV_VAR") == 0) {
            setenv(directives[i].value, NULL, 1);
        } else if (strcmp(directives[i].key, "DIR") == 0) {
            mkdir(directives[i].value, S_IRWXU | S_IRGRP | S_IXGRP | S_IROTH | S_IXOTH);
        } else if (strcmp(directives[i].key, "EXEC") == 0) {
            char *command = malloc(strlen(target_dir) + strlen(directives[i].value) + 2);
            snprintf(command, sizeof(command), "%s/%s", target_dir, directives[i].value);
            system(command);
            free(command);
        } else if (strcmp(directives[i].key, "ENCRYPTED_MESSAGE") == 0) {
            char *decrypted = malloc(strlen(message) + 1);
            memcpy(decrypted, message, strlen(message));
            for (char *p = decrypted; *p != '\0'; ++p) {
                if (*p >= 'A' && *p <= 'Z')
                    *p += strlen(decrypted);
            }
            env = realloc(env, sizeof(char*) * (strlen(decrypted) + 1));
            env[strlen(decrypted)] = strdup(decrypted);
        }
    }
    free(message);
    free(directives);

    return 0;
}
```

