      using System;
      using System.IO;
      using System.Linq;
      using System.Collections.Generic;

      public class FileBasedValueGenerator {
          private readonly List<double> _currentRange;
          private int _minValue, _maxValue;

          public FileBasedValueGenerator(string filePath) {
              if (!File.Exists(filePath)) throw new FileNotFoundException();
              _currentRange = File.ReadAllLines(filePath).Select(double.Parse).OrderBy(x => x).ToList();
              _minValue = _currentRange[0];
              _maxValue = _currentRange[^1];
          }

          public double GetRandomFloat() {
              if (_minValue >= _maxValue) throw new ArgumentOutOfRangeException("The range must be greater than zero.");
              return new Random().NextDouble() * (_maxValue - _minValue);
          }

          public int GetRandomInt() {
              if (_minValue >= _maxValue) throw new ArgumentOutOfRangeException("The range must be greater than zero.");
              return (int)(GetRandomFloat() + _minValue);
