```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <arpa/inet.h>

typedef struct NICPConfig {
    char mac[6];
    struct in_addr ip;
    int status;
    pthread_mutex_t lock;
} NICPConfig;

NICPConfig* nics = NULL;
size_t size = 0;
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;

void init_list() {
    pthread_mutex_lock(&listLock);
    if (nics) free(nics);
    nics = malloc(sizeof(NICPConfig));
    size = 1;
    pthread_mutex_init(&((nics)->lock), NULL);
    pthread_mutex_unlock(&listLock);
}

void add_nic(const char *mac, struct in_addr ip, int status) {
    NICPConfig* newNic = malloc(sizeof(NICPConfig));
    memcpy(newNic->mac, mac, 6);
    newNic->ip = ip;
    newNic->status = status;
    pthread_mutex_init(&(newNic->lock), NULL);

    pthread_mutex_lock(&listLock);
    if (size == 1) {
        nics[0] = *newNic;
    } else {
        NICPConfig* temp = realloc(nics, sizeof(NICPConfig) * (size + 1));
        memcpy(temp + size, newNic, sizeof(NICPConfig));
        nics = temp;
        size++;
    }
    pthread_mutex_unlock(&listLock);
}

void update_nic(int index, const char *mac, struct in_addr ip, int status) {
    if (index >= size || index < 0) return;

    pthread_mutex_lock(&listLock);
    pthread_mutex_lock(&(nics[index].lock));
    memcpy(nics[index].mac, mac, 6);
    nics[index].ip = ip;
    nics[index].status = status;
    pthread_mutex_unlock(&(nics[index].lock));
    pthread_mutex_unlock(&listLock);
}

