    void updateInterface(size_t index, const NetworkInterfaceConfig& config) {
        std::unique_lock<std::mutex> lock(interfaceMutex);
        if (index < interfaces.size()) {
            interfaces[index] = config;
        }
    }
    const NetworkInterfaceConfig* getInterface(size_t index) const {
        if (index < interfaces.size()) {
            std::unique_lock<std::mutex> lock(interfaceMutex);
            return &interfaces[index];
        }
        return nullptr;
    }
    void run() {
        while (true) {
            auto currentTime = std::chrono::steady_clock::now();
            if (currentTime - lastPingTime >= PING_PERIOD) {
                lastPingTime = currentTime;
                pingAllInterfaces();
            }
            checkConnectivityIssues();
            std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Adjust sleep duration as needed
        }
    }
    void pingAllInterfaces() { /* Implement ICMP ping logic here */ }
    void checkConnectivityIssues() { /* Check for connectivity issues based on ping responses */ }
};
