typedef struct {
    uint64_t weighted_sum;
    size_t valid_transactions;
    double moving_avg;
    time_t last_transaction;
} UserMetrics;

typedef struct {
    RX_UE_INFORMATION_TAG rxi;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRFC_INDICATION_PDU_T* transaction_stream(UserMetrics* users, uint64_t amount, RX_UE_INFORMATION_TAG rxi, RNTI rnti) {
    time_t now = time(NULL);
    if (amount <= 0 || now - users[rnti.value].last_transaction > 10) {
        return NULL;
    }

    if (now - users[rnti.value].last_transaction < 5 && ++users[rnti.value].valid_transactions > 3) {
        return NULL;
    }

    double weighted_amount = amount * users[rnti.value].weight_factor;
    if (weighted_amount >= users[rnti.value].threshold) {
        users[rnti.value].weighted_sum += weighted_amount;
        users[rnti.value].moving_avg = (users[rnti.value].moving_avg * (double)(users[rnti.value].total_transactions - 1) + weighted_amount) / users[rnti.value].total_transactions;
        users[rnti.value].total_transactions++;
        return (NFAPI_CRFC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRFC_INDICATION_PDU_T));
    }

    users[rnti.value].last_transaction = now;

    NFAPI_CRFC_INDICATION_PDU_T* pdu = (NFAPI_CRFC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRFC_INDICATION_PDU_T));
    pdu->rxi = rxi;
    pdu->rnti = rnti;
    pdu->crc.crcflag = rand() % 2;
    return pdu;
}
