['```c
#include <stdio.h>
#include <time.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int NODE_ID;
    time_t TIME_STAMP;
    int SENSOR_READING;
    bool VALIDITY_FLAG;
} SensorDataPDU_T;

struct node_metrics {
    time_t max_ts;
    int max_sum;
    int count;
    double ma_sum;
    double ma_count;
};

struct data_queue {
    SensorDataPDU_T* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
};

void initialize_metrics(struct node_metrics* metrics) {
    memset(metrics, 0, sizeof(struct node_metrics));
}

bool is_valid_reading(int reading, int min, int max, double factor, double threshold) {
    return reading >= min && reading <= max && reading * factor > threshold;
}

void enqueue(struct data_queue* q, SensorDataPDU_T value) {
    if ((q->head + 1) % q->capacity == q->tail) {
        // Queue is full, discard the oldest reading.
        free(q->buffer[(q->head + 1) % q->capacity]);
        q->head = (q->head + 1) % q->capacity;
    }
    q->buffer[q->tail] = value;
    q->tail = (q->tail + 1) % q->capacity;
}

SensorDataPDU_T dequeue(struct data_queue* q) {
    SensorDataPDU_T value = q->buffer[q->head];
    if ((q->head + 1) % q->capacity == q->tail) {
        // Queue is empty.
        return (SensorDataPDU_T){0, 0, 0, false};
    }
    q->head = (q->head + 1) % q->capacity;
    return value;
}

void process_reading(struct node_metrics* metrics, SensorDataPDU_T reading, struct data_queue* queue, double factor, double threshold) {
    if (!is_valid_reading(reading.SENSOR_READING, -1e9, 1e9, factor, threshold)) return;

    time_t now = time(NULL);
    if (difftime(now, reading.TIME_STAMP) > 15 * 60) {
        initialize_metrics(metrics);
    }

    if (difftime(now, reading.TIME_STAMP) < 5 * 60) {
        metrics->count++;
        metrics->ma_sum += reading.SENSOR_READING;
        metrics->ma_count++;
    } else {
        metrics->max_ts = now;
        metrics->max_sum = reading.SENSOR_READING;
        metrics->count = 1;
        metrics->ma_sum = reading.SENSOR_READING;
        metrics->ma_count = 1;
    }

    metrics->max_sum = fmax(metrics->max_sum, reading.SENSOR_READING);
}

void process_data(struct node_metrics* metrics, double factor, double threshold) {
    // Implement the non-blocking processing of data here.
}

void handle_sensor_reading(SensorDataPDU_T reading, struct data_queue* queue, void (*process_func)(struct node_metrics*, SensorDataPDU_T, struct data_queue*, double, double)) {
    enqueue(queue, reading);
    process_func(&metrics[reading.NODE_ID], reading, queue, factor, threshold);
}
```']

