#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG rxtag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcindication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

void createAndPopulateList(Node **head, size_t numElements) {
    if (*head == NULL) {
        *head = malloc(sizeof(Node));
        if (*head == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            return;
        }
        (*head)->next = NULL;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(Node));
        if (current->next == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            return;
        }
        current = current->next;
        current->next = NULL;
    }

    for (size_t i = 1; i < numElements; ++i) {
        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            return;
        }
        newNode->data.rxtag = i % 128;
        newNode->data.rnti = i * 5 + 123456;
        newNode->data.crcindication.crcflag = rand() % 2;
        newNode->next = *head;
        *head = newNode;
    }
}

void updateCRCIndicationStatus(Node **head, bool updateFlag) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    Node* current = *head;
    while (current != NULL) {
        pthread_mutex_lock(&mutex);
        current->data.crcindication.crcflag = updateFlag;
        pthread_mutex_unlock(&mutex);
        current = current->next;
    }
    pthread_mutex_destroy(&mutex);
}
```

