    CRCI_LIST* list = malloc(sizeof(CRCI_LIST));
    if (!list) return NULL;
    list->data = NULL;
    list->len = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void crci_list_resize(CRCI_LIST* list, size_t new_capacity) {
    if (new_capacity <= list->len) return;
    CRCI_PDU** new_data = realloc(list->data, new_capacity * sizeof(CRCI_PDU));
    if (!new_data) {
        fprintf(stderr, "Failed to resize array\n");
        return;
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

void crci_list_push_back(CRCI_LIST* list, const CRCI_PDU* pdu) {
    if (list->len == list->capacity) crci_list_resize(list, list->capacity * 2);
    list->data[list->len] = *pdu;
    list->len++;
}

void crci_list_destroy(CRCI_LIST* list) {
