#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Record {
    char buffer[256];
    int value;
} Record;

typedef Record* HashEntry;

unsigned long hashFunction(int key) {
    return key % 1024; // You can change this constant based on your requirements
}

void resizeHashTable(HashEntry** table, size_t currentSize, size_t newSize) {
    HashEntry* newTable = malloc(newSize * sizeof(HashEntry));
    if (!newTable) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < currentSize && i < newSize; ++i) {
        if (table[i]) {
            HashEntry curr = table[i];
            size_t hash = hashFunction(curr->value);
            while (newTable[hash]) hash = (hash + 1) % newSize;
            newTable[hash] = curr;
        }
    }

    free(table);
    table = newTable;
}

void initializeHashTable(HashEntry** table, size_t size) {
    *table = malloc(size * sizeof(HashEntry));
    if (!*table) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    memset(*table, 0, size * sizeof(HashEntry));
}

void serialize(const HashEntry table[], const size_t size, FILE* fp) {
    for (size_t i = 0; i < size; ++i) {
        if (table[i]) {
            fwrite(table[i]->buffer, sizeof(char), strlen(table[i]->buffer), fp);
            fwrite(&(table[i]->value), sizeof(int), 1, fp);
        }
    }
}

void deserialize(HashEntry** table, const size_t size, FILE* fp) {
    Record record;
    for (size_t i = 0; i < size; ++i) {
        size_t read = fread(&record.buffer, sizeof(char), 256, fp);
        if (read != 256) break; // Invalid data or end of file reached
        fread(&(record.value), sizeof(int), 1, fp);

        HashEntry entry = malloc(sizeof(Record));
        if (!entry) {
            perror("Memory allocation failure");
            exit(EXIT_FAILURE);
        }
        *entry = record;

        size_t hash = hashFunction(record.value);
        while (table[hash]) hash = (hash + 1) % size;
        table[hash] = entry;
    }
}

long* createLongArray(size_t size) {
    long* array = malloc(size * sizeof(long));
    if (!array) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    return array;
}

int* createIntArray(size_t size) {
    int* array = malloc(size * sizeof(int));
    if (!array) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    return array;
}

void freeHashTable(HashEntry** table, const size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (table[i]) free(table[i]);
    }
    free(table);
}

void freeAll(long* longArray, int* intArray, HashEntry** hashTable, const size_t size) {
    free(longArray);
    free(intArray);
    freeHashTable(hashTable, size);
}
