#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void init_data(Record** records, size_t size, size_t offsets_size, size_t keys_size, int range) {
    *records = (Record*)malloc(size * sizeof(Record));
    if (!*records) {
        perror("Memory allocation failed for records");
        return;
    }

    long* offsets = (long*)malloc(offsets_size * sizeof(long));
    if (!offsets) {
        perror("Memory allocation failed for offsets");
        free(*records);
        return;
    }

    int* keys = (int*)malloc(keys_size * sizeof(int));
    if (!keys) {
        perror("Memory allocation failed for keys");
        free(offsets);
        free(*records);
        return;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Initialize offset array
    for (size_t i = 0; i < offsets_size; ++i) {
        offsets[i] = i;
    }

    // Shuffle offsets array to ensure random distribution
    for (size_t i = offsets_size - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        long temp = offsets[j];
        offsets[j] = offsets[i];
        offsets[i] = temp;
    }

    // Initialize keys array
    for (size_t i = 0; i < keys_size; ++i) {
        keys[i] = offsets[i];
    }

    // Set record values with random numbers within the specified range
    for (size_t i = 0; i < size; ++i) {
        (*records + i)->value = keys[i % keys_size] * range / keys_size + rand() % range / keys_size;
    }
}

// Cleanup function to free allocated memory
void clean_data(Record* records, long* offsets, int* keys) {
    free(offsets);
    free(keys);
    free(records);
}
