#include <iostream>
#include <vector>
#include <map>
#include <memory>
#include <mutex>
#include <new>
#include <cstdlib>
#include <ctime>
#include <algorithm>

struct Profile {
    enum Type { USERNAME, PREFERENCES, IMAGE };
    std::string metadata; // Fixed-size metadata or serialized profile data
    union {
        std::string username;
        std::map<std::string, bool> preferences;
        unsigned char* image;
    } data;
    Type type;
};

class UserProfiles {
private:
    static const int PROFILE_HEADER_SIZE = sizeof(Profile) - sizeof(Profile::metadata);
    std::vector<std::unique_ptr<Profile>> profiles;
    std::mutex mtx;
    size_t capacity = 0, size = 0;
    size_t max_buffer_size = 0;

public:
    UserProfiles(size_t num_profiles, size_t seed, Type data_type, size_t max_buffer_size) : max_buffer_size(max_buffer_size) {
        srand(seed);
        reserve(num_profiles);
    }

    ~UserProfiles() {
        clear();
    }

    void allocate(size_t additional_capacity = 0) {
        std::lock_guard<std::mutex> lock(mtx);
        if (additional_capacity > 0) capacity += additional_capacity;
        if (capacity <= size) {
            size_t new_capacity = capacity + (capacity >> 1);
            resize(new_capacity);
        }
    }

    Profile* get_profile(size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        return profiles[index].get();
    }

    void set_metadata(size_t index, const std::string& metadata) {
        std::lock_guard<std::mutex> lock(mtx);
        profiles[index]->metadata = metadata;
    }

    void set_data(size_t index, Type type, const std::string& data) {
        std::lock_guard<std::mutex> lock(mtx);
        auto& p = profiles[index];
        if (type == Profile::USERNAME) {
            new (p.get()) Profile{ .metadata = "", .username = data };
        } else if (type == Profile::PREFERENCES) {
            new (p.get()) Profile{ .metadata = "", .preferences = std::map<std::string, bool>() };
            static_cast<Profile&>(*p)->preferences["default"] = true;
        } else if (type == Profile::IMAGE) {
            p->image = const_cast<unsigned char*>(data.data());
            p->metadata += std::to_string(p->image - reinterpret_cast<const unsigned char*>(profiles.data()));
        }
    }

    void clear() {
        for (auto& p : profiles) {
            p->~Profile();
        }
        capacity = 0;
        size = 0;
    }

private:
    void reserve(size_t num_profiles) {
        std::lock_guard<std::mutex> lock(mtx);
        if (capacity >= num_profiles) return;

        size_t new_capacity = capacity + (capacity >> 1);
        profiles.reserve(new_capacity);
        for (size_t i = capacity; i < new_capacity; ++i) {
            try {
                auto p = std::make_unique<Profile>();
                profiles.push_back(std::move(p));
            } catch (...) {
                if (--new_capacity <= capacity) {
                    throw std::runtime_error("Failed to allocate new profile");
                }
                break;
            }
        }
        capacity = new_capacity;
    }

    void resize(size_t num_profiles) {
        if (num_profiles <= capacity) reserve(num_profiles);
        std::lock_guard<std::mutex> lock(mtx);
        profiles.resize(num_profiles, nullptr);
        size = num_profiles;
    }
};
```

This code demonstrates the use of batch allocation, variable-sized buffers, and thread safety with a mutex. The class can handle different types of data stored, and the memory is automatically released when the `UserProfiles` object goes out of scope. Edge cases such as partial allocations or early exits are handled by the exception mechanism.

