struct Session {
    std::string sessionID;
    std::string authToken;
    std::deque<std::chrono::system_clock::time_point> activityTimestamps;
    std::chrono::system_clock::time_point expirationTime;
};

class SessionManager {
public:
    void createSession(const std::string& sessionID, const std::string& authToken) {
        // Verify token before creating the session
        if (!verifyToken(authToken)) {
            std::cerr << "Error: Invalid authentication token" << std::endl;
            return;
        }

        sessions_[sessionID] = Session{sessionID, authToken};
        activeUsers_++;
    }

    bool updateSession(const std::string& sessionID, const std::string& newAuthToken) {
        auto it = sessions_.find(sessionID);
        if (it == sessions_.end()) {
            std::cerr << "Error: Session not found" << std::endl;
            return false;
        }

        // Verify new token before updating the session
        if (!verifyToken(newAuthToken)) {
            std::cerr << "Error: Invalid authentication token" << std::endl;
            return false;
        }

        it->second.authToken = newAuthToken;
        return true;
    }

    bool validateSession(const std::string& sessionID) {
        auto it = sessions_.find(sessionID);
        if (it == sessions_.end()) {
            std::cerr << "Error: Session not found" << std::endl;
            return false;
        }

        if (std::chrono::system_clock::now() > it->second.expirationTime) {
            sessions_.erase(it);
            activeUsers_--;
            cleanUp();
            return false;
        }

        return true;
    }

private:
    void cleanUp() {
        std::chrono::system_clock::time_point now = std::chrono::system_clock::now();

        // Remove inactive sessions
        for (auto it = sessions_.begin(); it != sessions_.end(); ) {
            if (it->second.expirationTime <= now) {
                activeUsers_--;
                it = sessions_.erase(it);
            } else {
                ++it;
            }
        }
    }

    std::unordered_map<std::string, Session> sessions_;
    std::mutex sessionsMutex;
    int activeUsers_{0};

    // External authentication API integration - replace this with your actual implementation
    bool verifyToken(const std::string& token) { return true; }
};

