    }

    for (int i = 0; i < bits; ++i) {
        offsets[i] = i * sizeof(packet);
        timestamps[i] = time(NULL);
    }
}

void clean_up(RSA **private_key, RSA **public_key, packet **packets, long offsets[], double timestamps[]) {
    for (int i = 0; i < *private_key ? (*private_key)->e : 0; ++i) {
        free(packets[offsets[i]]);
    }
    free(packets);
    free(offsets);
    free(timestamps);
    RSA_free(*private_key);
    RSA_free(*public_key);
}

int sign_verify(RSA *private_key, RSA *public_key, packet *message) {
    int r = 0;

    if (RSA_sign(NID_sha256, (uint8_t *)message->data, message->length, NULL, &r, private_key, RSA_PKCS1_OAEP_SHA_256()) <= 0) {
        fprintf(stderr, "Signing failed\n");
    } else if (RSA_verify(NID_sha256, (uint8_t *)message->data, message->length, RSA_padding_get_sha256_type(RSA_PKCS1_OAEP_SHA_256()), (unsigned char*)RSA_publickey_get0(public_key), RSA_size(public_key)) <= 0) {
        fprintf(stderr, "Verification failed\n");
    } else {
        r = 1;
    }

    return r;
}
