class ConfigManager {
private:
    std::vector<std::unique_ptr<NICPConfig>> configs;

public:
    void addConfig(std::unique_ptr<NICPConfig> config) {
        configs.push_back(std::move(config));
    }

    void updateConfig(const std::string& macAddress, const NICPConfig& newConfig) {
        for (auto& config : configs) {
            if (config->macAddress == macAddress) {
                *config = newConfig;
                return;
            }
        }
