#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libxml/parser.h>
#include <libxml/xpath.h>
#include "nfapi_crc_indication_pdu.h"

static void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu != NULL) {
        free(pdu->rx_ue_information_tag);
        free(pdu->rnti);
        free(pdu->crc_indication_rel8_tag.crcflag);
        free(pdu);
    }
}

static void free_xmlNodes(xmlNode *node) {
    xmlNode *temp;

    while (node != NULL) {
        temp = node->next;
        xmlFreeNode(node);
        node = temp;
    }
}

xmlDocPtr doc = NULL;
xmlXPathContextPtr xpathCtx = NULL;
xmlNodeSetPtr nsNodeSet = NULL;

int populateNfaApiListWithXmlData(int N, const char *xmlFilePath, const char *tagName, struct NFAPI_CRC_INDICATION_PDU_T **pduList, int *crcFlagCount) {
    doc = xmlReadFile(xmlFilePath, NULL, XML_PARSE_NONET | XML_PARSE_DTDATTVAL | XML_PARSE_NOBLANKS);

    if (doc == NULL) {
        printf("Error: Unable to read XML file\n");
        *crcFlagCount = 0;
        return 1;
    }

    xpathCtx = xmlXPathNewContext(doc);
    nsNodeSet = xmlXPathRegisterNs(xpathCtx, BAD_CAST "urn:3gpp:ngap", BAD_CAST "n");

    *crcFlagCount = 0;
    *pduList = NULL;
    int count = 0;

    xmlNodeSetPtr nodes = xmlXPathEvalExpression(xpathCtx, (BAD_CHAR *)tagName, nsNodeSet);

    if (nodes == NULL || xmlNodeSetEmpty(nodes)) {
        free_xmlNodes(doc->root);
        *crcFlagCount = 0;
        return 1;
    }

    *pduList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * xmlNodeSetGetLength(nodes));

    if (*pduList == NULL) {
        free_xmlNodes(doc->root);
        *crcFlagCount = 0;
        return 1;
    }

    for (int i = 0; i < xmlNodeSetGetLength(nodes); ++i) {
        xmlNodePtr node = xmlNodeSetGetFirst(nodes)->xmlChildrenNode;

        while (node != NULL && !xmlStrcasecmp((const xmlChar *)tagName, (const xmlChar *)node->name)) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &(*pduList)[count];

            pdu->rx_ue_information_tag = strdup(xmlGetProp(node, BAD_CAST "RX-UE-INFORMATION-TAG"));
            pdu->rnti = strdup((const char *) xmlNodeGetContent(node));
            pdu->crc_indication_rel8_tag.crcflag = malloc(sizeof(int));
            *(pdu->crc_indication_rel8_tag.crcflag) = rand() % 2;

            ++count;
            node = node->xmlNextSibling;
        }
    }

    *crcFlagCount = count;

    free_xmlNodes(doc->root);
    xmlXPathFreeContext(xpathCtx);

    return 0;
}
