typedef void (*RuleFunc)(char *, char *);

void read_and_cache(const char *filename, Cache **cache) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    fseek(file, 0, SEEK_END);
    size_t filesize = ftell(file);
    rewind(file);

    *cache = malloc(sizeof(Cache));
    (*cache)->capacity = MAX_CACHE_SIZE;
    (*cache)->size = 0;
    (*cache)->entries = malloc((*cache)->capacity * sizeof(CacheEntry));

    char *map_start = mmap(NULL, filesize, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (map_start == MAP_FAILED) {
        fprintf(stderr, "Error mapping file: %s\n", strerror(errno));
        fclose(file);
        return;
    }

    char *ptr = map_start;
    size_t remaining = filesize;

    while (remaining > 0) {
        CacheEntry *entry = &((*cache)->entries[((*cache)->size % (*cache)->capacity)]);
        entry->data = ptr;
        entry->length = remaining < MAX_CACHE_SIZE ? remaining : MAX_CACHE_SIZE;
        entry->lock = PTHREAD_MUTEX_INITIALIZER;
        ptr += entry->length;
        remaining -= entry->length;
        (*cache)->size += 1;
    }

    munmap(map_start, filesize);
    fclose(file);
}

void process_and_write(const char *input, const char *output, Cache *cache, RuleFunc rule, int parallel) {
    FILE *out = fopen(output, "w");
    pthread_t threads[parallel];
    CacheEntry *current;

