    while (1) {
        if (!cache_full && offset < ftell(input)) { // Read from cache if possible
            memcpy(buffer, cache.data + offset - cache.pos, buffer_size);
            break;
        }

        pthread_mutex_lock(&file_lock);
        size_t read = fread(buffer, 1, buffer_size, input);
        pthread_mutex_unlock(&file_lock);

        if (read <= 0) break; // End of file or error

        offset += read;
        if (!cache_full && offset >= ftell(input)) { // Cache the read chunk if possible
            memcpy(cache.data + cache.pos, buffer, read);
            cache.len = read;
            cache.pos = offset - read;
            cache_full = (cache.len > CACHE_SIZE);
        }

        if (!cache_full) break; // Move on to the next chunk
    }

    return NULL;
}

