typedef struct {
    char* userId;
    char* filePath;
    char* textBuffer;
} UserData;

void processUserInput(char* userID, char* filePath, char* textBuffer) {
    // Validate file path and read file content
    DIR *dir = opendir(".");
    struct dirent *entry;
    FILE *file = NULL;
    size_t fileSize = 0;
    char* fileContent = NULL;

    if (dir == NULL) {
        printf("Invalid directory structure\n");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (!strcmp(entry->d_name, filePath)) {
            file = fopen(filePath, "r");
            if (file == NULL) {
                printf("Error opening file\n");
                return;
            }
            fseek(file, 0, SEEK_END);
            fileSize = ftell(file);
            rewind(file);
            fileContent = malloc(fileSize + 1);
            if (fread(fileContent, sizeof(char), fileSize, file) != fileSize) {
                printf("Error reading file\n");
                free(fileContent);
                fclose(file);
                return;
            }
            fclose(file);
        }
    }

    // Preprocess text data
    size_t processedTextLen = strlen(fileContent);
    char* processedText = malloc(processedTextLen + 1);
    for (size_t i = 0; i < processedTextLen; ++i) {
        if (isalpha(fileContent[i])) {
            processedText[i] = tolower(fileContent[i]);
        } else if (fileContent[i] == '_') {
            // Allow underscores for readability, but remove other non-alphanumeric characters
            continue;
        } else {
            processedText[i] = ' ';
        }
    }
    processedText[processedTextLen] = '\0';

    // Save processed text back to the original file
    file = fopen(filePath, "w");
    if (file == NULL) {
        printf("Error saving processed text\n");
        free(processedText);
        return;
    }
    if (fwrite(processedText, sizeof(char), processedTextLen + 1, file) != processedTextLen + 1) {
        printf("Error writing to file\n");
    }
    fclose(file);

    // Find and print the length of the longest word in the processed text
    size_t maxWordLength = 0;
    for (size_t i = 0; i < processedTextLen;) {
        while (i < processedTextLen && isspace(processedText[i])) ++i;
        size_t start = i;
        while (i < processedTextLen && !isspace(processedText[i])) ++i;
        size_t wordLength = i - start;
        if (wordLength > maxWordLength) {
            maxWordLength = wordLength;
        }
    }
    printf("Longest word length: %zu\n", maxWordLength);

    free(fileContent);
    free(processedText);
}

// Helper function to find and print the length of the longest word in the processed text
size_t findMaxWordLength(char* text) {
    // Same logic as in processUserInput, but optimized for repeated calls
    size_t maxWordLength = 0;
    for (size_t i = 0; i < strlen(text);) {
        while (i < strlen(text) && isspace(text[i])) ++i;
        size_t start = i;
        while (i < strlen(text) && !isspace(text[i])) ++i;
        size_t wordLength = i - start;
        if (wordLength > maxWordLength) {
            maxWordLength = wordLength;
        }
    }
    return maxWordLength;
}
