import os
import sys
import hashlib
import shutil
import tempfile
from datetime import datetime
import logging
from functools import lru_cache
import requests

def download_and_process_log(url, key):
    # Download the file
    try:
        response = requests.get(url)
        if response.status_code != 200:
            raise Exception("Error downloading file")

        temp_file = tempfile.NamedTemporaryFile(delete=False, prefix='log_', suffix='.txt')
        temp_file.write(response.content)
        temp_file.flush()
    except requests.exceptions.RequestException as e:
        print("Error downloading file:", e)
        return

    # Process the file
    try:
        with open(temp_file.name, 'r') as f:
            lines = [line for line in f]
            lines.sort(key=lambda x: eval(key))

            last_seq = -1
            seq = 0
            for line in lines:
                if last_seq == -1:
                    last_seq = int(line.split()[-1].strip())
                else:
                    seq += 1

            print("Sequence number:", last_seq + seq)

            # Clean up temporary file
            temp_file.close()
            os.remove(temp_file.name)
    except Exception as e:
        print("Error processing file:", e)

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: python log_processor.py <log_url> <key>")
        sys.exit(1)

    url = sys.argv[1]
    key = sys.argv[2]

    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')
    try:
        download_and_process_log(url, key)
    except Exception as e:
        logging.exception("Exception occurred during processing")
