#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <openssl/hmac.h>

typedef struct {
    AES_KEY cipher;
} AESContext;

void generateSalt(unsigned char* salt, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        salt[i] = rand() % 256;
    }
}

AESContext initCipherContext(const char* password) {
    const size_t iterations = 100000;
    const size_t saltLength = 32;
    unsigned char passwordBytes[EVP_MAX_PASSWORD_LENGTH];
    memcpy(passwordBytes, password, strlen(password));
    const EVP_CIPHER* cipher = EVP_aes_256_cbc();

    AESContext context;
    context.cipher.iv = malloc(AES_BLOCK_SIZE);

    unsigned char salt[saltLength];
    generateSalt(salt, saltLength);

    EVP_PBKDF2_HMAC(*EVP_sha256(), passwordBytes, strlen(password), salt, iterations,
                   NULL, EVP_MD_SIZE(EVP_sha256()), context.cipher.key);

    HMAC_CTX* hmacContext = HMAC_CTX_new();
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digestLen = sizeof(digest);

    HMAC_Init_ex(hmacContext, passwordBytes, strlen(password), EVP_sha256(), NULL);
    HMAC_Update(hmacContext, salt, saltLength);
    HMAC_Final(hmacContext, digest, &digestLen);
    HMAC_CTX_free(hmacContext);

    memcpy(context.cipher.iv, digest, AES_BLOCK_SIZE);

    return context;
}
```

