        if (sqlite3_open("myDB.db", &db) != SQLITE_OK) {
            perror("sqlite3 open failed");
            exit(1);
        }
    }

    void updateElementStatus(int clinicID, int status) {
        char sql[256];
        snprintf(sql, sizeof(sql), "UPDATE elements SET status = %d WHERE clinic_id = %d", status, clinicID);
        sqlite3_exec(db, sql, NULL, NULL, NULL);
    }

    void insertLastModifiedRecord(int clinicID, const char *ipAddress, time_t lastModifiedTime) {
        char sql[256];
        snprintf(sql, sizeof(sql), "INSERT INTO last_modified (clinic_id, ip_address, last_modified) VALUES (%d, '%s', from_time_t(%lld))", clinicID, ipAddress, lastModifiedTime);
        sqlite3_exec(db, sql, NULL, NULL, NULL);
    }

    ~Database() {
        sqlite3_close(db);
    }
};

// handleHttpPostRequest function
void handleHttpPostRequest(int sectionID, int elementID, const char *htmlContent, Service &service, Database &db) {
    ElementData *data = NULL;
    storeContent(&data, htmlContent);

    service.updateElement(sectionID, elementID, data[data->value - 1].htmlContent);
    db.updateElementStatus(elementID, 1); // Update status to 1 (e.g., "updated")
    db.insertLastModifiedRecord(elementID, getenv("REMOTE_ADDR"), time(NULL));

    free(data[data->value - 1].htmlContent);
    free(data);

    printf("Page should be refreshed\n");
}
```

