```java
import java.io.FileWriter;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.ConcurrentMap;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class HttpStatusCodeFetcher {
    private static final int MAX_CACHE_SIZE = 10000;
    private static final int RETRY_ATTEMPTS = 3;
    private static final long EXPONENTIAL_BACKOFF_MULTIPLIER = 2;
    private static final String LOG_FILE = "status_code_cache_errors.log";

    private final ConcurrentMap<String, Pair<Integer, Long>> cache;
    private final Lock cacheLock;

    public HttpStatusCodeFetcher() {
        this.cache = new LinkedHashMap<>(MAX_CACHE_SIZE, 0.75f) {
            private static final long serialVersionUID = 1L;

            @Override
            protected boolean removeEldestEntry(Map.Entry<String, Pair<Integer, Long>> eldest) {
                return size() > MAX_CACHE_SIZE;
            }
        };
        this.cacheLock = new ReentrantLock();
    }

    public int getHttpStatusCode(String url) {
        if (!isValidUrl(url)) {
            return -1;
        }

        Pair<Integer, Long> cachedStatusCode = cache.get(url);
        if (cachedStatusCode != null) {
            return cachedStatusCode.getKey();
        }

        int statusCode = -1;
        long backoff = 0;

        for (int attempt = 0; attempt < RETRY_ATTEMPTS && statusCode == -1; ++attempt) {
            try {
                URL urlObject = new URL(url);
                statusCode = urlObject.openConnection().getResponseCode();
            } catch (Exception e) {
                if (backoff < Long.MAX_VALUE) {
                    backoff *= EXPONENTIAL_BACKOFF_MULTIPLIER;
                    try {
                        Thread.sleep(backoff);
                    } catch (InterruptedException ignore) {}
                } else {
                    logError(e);
                }
            }
        }

        if (statusCode != -1) {
            cacheLock.lock();
            try {
                cache.put(url, new Pair<>(statusCode, System.currentTimeMillis()));
            } finally {
                cacheLock.unlock();
            }
        }

        return statusCode;
    }

    private boolean isValidUrl(String url) {
        // Implement URL validation and normalization logic here
        try {
            new URL(url);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private void logError(Throwable e) {
        try (FileWriter fileWriter = new FileWriter(LOG_FILE, true)) {
            fileWriter.write(String.format("%s\n", e.getMessage()));
        } catch (Exception ignored) {}
    }

    // Helper class for storing the status code and last access time
    private static class Pair<K, V> implements Map.Entry<K, V> {
        private final K key;
        private final V value;

        public Pair(K key, V value) {
            this.key = key;
            this.value = value;
        }

        @Override
        public K getKey() {
            return key;
        }

        @Override
        public V getValue() {
            return value;
        }

        @Override
        public V setValue(V value) {
            throw new UnsupportedOperationException();
        }
    }
}
```

