import org.junit.Test;
import static org.junit.Assert.*;
import java.io.File;
import java.net.URL;
import java.util.concurrent.TimeUnit;

public class HttpStatusCodeFetcherTest {
    @Test
    public void testValidUrls() throws Exception {
        HttpStatusCodeFetcher fetcher = new HttpStatusCodeFetcher();

        // Valid URLs
        URL validUrl1 = new URL("http://example.com");
        assertEquals(200, fetcher.getHttpStatusCode(validUrl1.toString()));

        URL validUrl2 = new URL("https://www.google.com");
        assertEquals(200, fetcher.getHttpStatusCode(validUrl2.toString()));
    }

    @Test
    public void testInvalidUrls() throws Exception {
        HttpStatusCodeFetcher fetcher = new HttpStatusCodeFetcher();

        // Invalid URLs
        assertEquals(-1, fetcher.getHttpStatusCode("http://example.com/"));
        assertEquals(-1, fetcher.getHttpStatusCode("http://example.com:8080"));
        assertEquals(-1, fetcher.getHttpStatusCode("http://example.com/?param=value"));
    }

    @Test(timeout = 6000)
    public void testCache() throws Exception {
        HttpStatusCodeFetcher fetcher = new HttpStatusCodeFetcher();

        // Test cache behavior with a large number of URLs (assuming the cache can handle 10,000 unique URLs efficiently)
        for (int i = 0; i < 10_000; ++i) {
            fetcher.getHttpStatusCode("http://example.com/" + i);
        }
    }

    @Test(timeout = 6000)
    public void testRetryMechanism() throws Exception {
        HttpStatusCodeFetcher fetcher = new HttpStatusCodeFetcher();

        URL urlWithTransientError = new URL("http://example.com/transient_error");
        for (int attempt = 0; attempt < HttpStatusCodeFetcher.RETRY_ATTEMPTS; ++attempt) {
            int statusCode = fetcher.getHttpStatusCode(urlWithTransientError.toString());
            if (statusCode != -1) {
                break;
            }
        }
        // Verify that the correct status code is eventually returned after retrying
        assertEquals(200, fetcher.getHttpStatusCode(urlWithTransientError.toString()));
    }
}
