#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netdb.h>
#include <time.h>

typedef struct nicp_config {
    char mac[18]; // MAC address (6 octets, each represented by 2 characters)
    struct in_addr ip; // IP configuration details
    unsigned short port; // Port number
    int status; // Link state flag: 0 - down, 1 - up
    pthread_mutex_t lock; // Thread safety mutex
} NICPConfig;

typedef struct nicp_list {
    size_t capacity;
    size_t count;
    NICPConfig** data;
    int active_count;
    pthread_mutex_t list_lock;
    pthread_cond_t not_full; // Condition variable for when space is available to add a new configuration
} NICPList;

void nicp_list_init(NICPList* list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->count = 0;
    list->data = malloc(initial_capacity * sizeof(NICPConfig*));
    memset(list->data, 0, initial_capacity * sizeof(NICPConfig*));

    list->active_count = 0;
    pthread_mutex_init(&list->list_lock, NULL);
    pthread_cond_init(&list->not_full, NULL);
}

void nicp_config_init(NICPConfig* config) {
    memset(config, 0, sizeof(NICPConfig));
    pthread_mutex_init(&config->lock, NULL);
}

NICPConfig* nicp_list_add(NICPList* list) {
    if (list->count >= list->capacity && list->capacity > 0) {
        size_t new_capacity = list->capacity * 2;
        NICPConfig** new_data = realloc(list->data, new_capacity * sizeof(NICPConfig*));
        if (!new_data) return NULL;
        list->data = new_data;
        list->capacity = new_capacity;
    }

    NICPConfig* config = &list->data[list->count];
    nicp_config_init(config);
    list->count++;

    pthread_mutex_lock(&list->list_lock);
    while (list->active_count >= list->capacity / 2) {
        pthread_cond_wait(&list->not_full, &list->list_lock);
    }
    list->active_count++;
    pthread_mutex_unlock(&list->list_lock);

    return config;
}

void nicp_list_update(NICPList* list, NICPConfig* config) {
    pthread_mutex_lock(&list->list_lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (!strcmp(config->mac, list->data[i]->mac)) {
            memcpy(list->data[i], config, sizeof(NICPConfig));
            break;
        }
    }
    pthread_mutex_unlock(&list->list_lock);
}

void nicp_list_remove(NICPList* list, NICPConfig* config) {
    pthread_mutex_lock(&list->list_lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (!strcmp(config->mac, list->data[i]->mac)) {
            memmove(&list->data[i], &list->data[i + 1], (list->count - i - 1) * sizeof(NICPConfig*));
            --list->count;
            break;
        }
    }
    pthread_mutex_unlock(&list->list_lock);

    if (pthread_mutex_destroy(&config->lock)) fprintf(stderr, "Error destroying mutex for config %s\n", config->mac);
}

int nicp_ping(const struct in_addr ip) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) return 0;

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(ICMP_ECHO_REQUEST); // ICMP echo request port
    serv_addr.sin_addr.s_addr = ip.s_addr;

    char buffer[64];
    if (sendto(sockfd, buffer, 1, 0, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        close(sockfd);
        return 0;
    }

    timeval timeout = {1, 0}; // Wait for 1 second
    fd_set read_fds;
    FD_ZERO(&read_fds);
    FD_SET(sockfd, &read_fds);
    select(sockfd + 1, &read_fds, NULL, NULL, &timeout);

    socklen_t len = sizeof(serv_addr);
    char buffer[64];
    ssize_t nbytes = recvfrom(sockfd, buffer, sizeof(buffer), 0, (struct sockaddr*)&serv_addr, &len);
    close(sockfd);

    return nbytes > 0; // Return true if a response was received within the timeout period
}

void nicp_list_check_connectivity(NICPList* list) {
    pthread_mutex_lock(&list->list_lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (!list->data[i]->status || !nicp_ping(list->data[i]->ip)) continue;

        list->data[i]->status = 1;
        pthread_cond_signal(&list->not_full);
    }
    pthread_mutex_unlock(&list->list_lock);
}

void nicp_config_log(const NICPConfig* config, const char* message) {
    time_t rawtime;
    struct tm * timeinfo;
    char time_buffer[80];

    time (&rawtime);
    timeinfo = localtime (&rawtime);
    strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s [%s] %s\n", time_buffer, config->mac, message);
}
```

This code defines a `NICPConfig` structure for the network interface configurations and a `NICPList` structure to manage the list of configurations. The `nicp_list_init()` function initializes the dynamic list with a given initial capacity, while the `nicp_config_init()` function initializes a single configuration.

The `nicp_list_add()` function adds a new configuration to the list when space is available, handling dynamically adjusting the list's capacity as necessary. The `nicp_list_update()` function updates an existing configuration with the given MAC address. The `nicp_list_remove()` function removes the configuration with the given MAC address from the list.

The `nicp_ping()` function checks the network connectivity of a given IP address using the ICMP protocol. It's used in the `nicp_list_check_connectivity()` function to check for connectivity issues in the list based on ping responses. The current implementation waits 1 second for a response, but you can modify this timeout as needed.

Lastly, the `nicp_config_log()` function logs critical events related to configuration updates and network status changes. You can modify this logging system to suit your specific needs.']

