#include <openssl/sha.h>

struct file_info {
    char path[256];
    off_t size;
    time_t mtime;
};

struct hash_ctx {
    unsigned char digest[SHA256_DIGEST_LENGTH];
};

void hash_file(const char *path, struct hash_ctx *ctx) {
    FILE *fp = fopen(path, "rb");
    if (!fp) return;

    size_t read;
    while ((read = fread(ctx->digest, 1, sizeof(ctx->digest), fp)) > 0) {
        SHA256_Update(SHA256_ctx_new(), ctx->digest, read);
    }

    fclose(fp);
}

void *process_file(void *data) {
    struct file_info *fi = data;
    struct hash_ctx hash_ctx;

    hash_file(fi->path, &hash_ctx);

    // Generate unique identifier using size, mtime, and hash
    char id[64];
    snprintf(id, sizeof(id), "%lld_%lu_%s", fi->size, (unsigned long)fi->mtime, hash_ctx.digest);

    char newname[256];
    strncpy(newname, fi->path, strlen(fi->path) + 1); // Ensure null terminator
    strncat(newname + strlen(fi->path), id, sizeof(newname) - strlen(fi->path) - 1);

    if (linkat(AT_FDCWD, fi->path, AT_FDCWD, newname, AT_SYMLINK_NOFOLLOW | AT_MOVED_SLOW) == -1) {
        // Handle retry logic here with exponential backoff and maximum attempts
    }

    return NULL;
}

int rename_files(const char *dirpath, const char *logfile) {
    DIR *dp = opendir(dirpath);
    if (!dp) {
        fprintf(stderr, "Failed to open directory: %s\n", dirpath);
        return 0;
    }

    pthread_t threads[256]; // Adjust thread count as needed for maximum concurrency
    struct file_info files[256]; // Adjust array size as needed for maximum number of files to process simultaneously

    int i = 0, nthreads = 0;
    struct dirent *de;
    while ((de = readdir(dp)) != NULL) {
        if (de->d_type == DT_REG && strcmp(de->d_name, ".") && strcmp(de->d_name, "..")) {
            strncpy(files[i].path, dirpath, strlen(dirpath) + 1);
            strncat(files[i].path, de->d_name, sizeof(files[i].path) - strlen(dirpath) - 1);
            struct stat st;
            fstatat(fdopen(dirpath, "r"), files[i].path, &st, AT_SYMLINK_NOFOLLOW);

            files[i].size = st.st_size;
            files[i].mtime = st.st_mtime;

            i++;
            if (nthreads < sizeof(threads)) nthreads++; // Adjust thread count as needed for maximum number of threads to use
            else break; // No need to create more threads, process remaining files sequentially
        }
    }
    closedir(dp);

    for (int j = 0; j < nthreads; j++) {
        if (pthread_create(&threads[j], NULL, process_file, &files[j])) {
            perror("Failed to create thread");
            return 0;
        }
    }

    for (int j = 0; j < nthreads; j++) {
        pthread_join(threads[j], NULL);
    }

    int count = 0;
    for (int i = 0; i < sizeof(files) / sizeof(struct file_info); i++) {
        if (access(files[i].path, F_OK) == -1) continue; // File was renamed, skip to next one
        count++;
    }

    return count;
}
```

