['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <ctype.h>
#include <inttypes.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdarg.h>
#include <json-c/json.h>
#include <strftime.h>

typedef struct {
    char description[256];
    time_t due_date;
    int priority;
} Task;

typedef struct Node {
    Task task;
    struct Node *next;
} Node;

Node* head = NULL;
Node** current = &head;

void add_task(const char* description, time_t due_date, int priority) {
    Node* new_node = malloc(sizeof(Node));
    strncpy(new_node->task.description, description, sizeof(new_node->task.description));
    new_node->task.due_date = due_date;
    new_node->task.priority = priority;
    new_node->next = NULL;

    if (*current == NULL) {
        *current = new_node;
    } else {
        Node* last = *current;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = new_node;
    }
}

void remove_task(const char* description) {
    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && strcmp(current->task.description, description)) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

void list_tasks() {
    Node* current = head;
    time_t now = time(NULL);

    printf("Task List:\n");
    printf("-------------------\n");
    while (current != NULL) {
        struct tm due_tm;
        localtime_r(&current->task.due_date, &due_tm);
        char due_str[32];
        strftime(due_str, sizeof(due_str), "%Y-%m-%d %H:%M", &due_tm);
        printf("%s (due: %s) - Priority: %d\n", current->task.description, due_str, current->task.priority);
        current = current->next;
    }
    printf("-------------------");
}

void sort_tasks() {
    Node* tasks[1000]; // Assuming maximum number of tasks is 1000
    int count = 0;

    Node* current = head;
    while (current != NULL) {
        tasks[count++] = current;
        current = current->next;
    }

    qsort(tasks, count, sizeof(Node*), compare_tasks);
}

int compare_tasks(const void *a, const void *b) {
    return ((((Task*)a)->due_date > ((Task*)b)->due_date) ? 1 : -1);
}

void export_to_csv(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "Description,Due Date,Priority\n");
    Node* current = head;
    while (current != NULL) {
        struct tm due_tm;
        localtime_r(&current->task.due_date, &due_tm);
        char due_str[32];
        strftime(due_str, sizeof(due_str), "%Y-%m-%d %H:%M", &due_tm);
        fprintf(file, "%s,%s,%d\n", current->task.description, due_str, current->task.priority);
        current = current->next;
    }

    fclose(file);
}

void import_from_json(const char* filename) {
    // Implement JSON parsing and task addition code here.
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printf("Usage: %s [add|remove|list|export|import] [options]\n", argv[0]);
        return 1;
    }

    const char* action = argv[1];

    switch(action[0]) {
        case 'a':
            add_task(argv[2], strtoll(argv[3], NULL, 10), atoi(argv[4]));
            break;
        case 'r':
            remove_task(argv[2]);
            break;
        case 'l':
            list_tasks();
            break;
        case 'e':
            export_to_csv(argv[2]);
            break;
        case 'i':
            import_from_json(argv[2]);
            break;
    }

    return 0;
}
```']

