#include <openssl/ssl.h>
#include <openssl/err.h>

SSL_CTX *tls_context_init() {
    SSL_CTX *ctx;
    const SSL_METHOD *method;

    // Initialize OpenSSL library and context
    SSL_load_error_strings();
    ERR_load_BIO_strings();
    ctx = SSL_CTX_new(TLSv1_3_server_method());

    // Set session ticket parameters
    SSL_CTX_set_session_cache_mode(ctx, SSL_SESS_CACHE_SERVER);
    SSL_SESSION_set_tmp_key(SSL_get_session_cache_expire(), 86400);

    // Configure ECC and ECDSA for key exchange and authentication
    const EC_GROUP *ecdhe;
    const EVP_MD *calculate_sha256 = EVP_sha256();
    ecdhe = EC_GROUP_new_by_curve_name(NID_X25519);
    SSL_CTX_set_ecdh_auto(ctx, 1);
    SSL_CTX_set_tmp_ecdh(ctx, ecdhe);
    SSL_CTX_set_ciphers(ctx, "ECDHE-CHACHA20-POLY1305");

    return ctx;
}
