AES_KEY *aes_context_init(const uint8_t *password, size_t password_len) {
    AES_KEY key;
    SHA1_CTX shaContext;
    unsigned char sha1Result[SHA_DIGEST_LENGTH];
    EVP_CIPHER_CTX *aesCipherCtx = EVP_AES_128_CBC_init();

    // Derive key from password using SHA-1 hash function
    SHA1_Init(&shaContext);
    SHA1_Update(&shaContext, password, password_len);
    SHA1_Final(sha1Result, &shaContext);

    // Set the encryption key and IV length to fixed values
    AES_set_encrypt_key(sha1Result, 256 / 8, &key.kt);
    AES_KEY *aesKey = malloc(sizeof(AES_KEY));
    memcpy(aesKey, &key, sizeof(AES_KEY));
    aesKey->length = 32; // Key length (128 bits)
    aesKey->iv_length = AES_BLOCK_SIZE; // IV length (16 bytes)

    // Configure AES-256-CBC cipher and return the context
    EVP_CIPHER_CTX_set_cipher(aesCipherCtx, EVP_aes_256_cbc());
    EVP_CIPHER_CTX_set_key_length(aesCipherCtx, 256);
    EVP_CIPHER_CTX_set_iv_length(aesCipherCtx, AES_BLOCK_SIZE);
    AES_KEY *cipherKey = aesCipherCtx->k;
    memcpy(cipherKey, aesKey, sizeof(AES_KEY));
    return aesKey;
}
```

