typedef struct VM_CONFIG {
    int id;
    int cpu_allocation;
    int memory_allocation;
    int gpu_allocation;
    bool state; // true for operational, false for non-operational
} VM_CONFIG;

typedef struct LIST_NODE {
    VM_CONFIG vm_config;
    struct LIST_NODE *next;
} LIST_NODE;

LIST_NODE* create_node(VM_CONFIG vm_config) {
    LIST_NODE* new_node = (LIST_NODE*) malloc(sizeof(LIST_NODE));
    new_node->vm_config = vm_config;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(LIST_NODE** head, VM_CONFIG vm_config) {
    LIST_NODE* new_node = create_node(vm_config);
    if (*head == NULL) {
        *head = new_node;
    } else {
        LIST_NODE* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void update_vm(LIST_NODE** head, int id, VM_CONFIG updated_config) {
    LIST_NODE* current = *head;
    while (current != NULL) {
        if (current->vm_config.id == id) {
            current->vm_config = updated_config;
            return;
        }
        current = current->next;
    }
}

void iterate_list(LIST_NODE* head, void(*function)(VM_CONFIG)) {
    LIST_NODE* current = head;
    while (current != NULL) {
        function(current->vm_config);
        current = current->next;
    }
}

