typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _HASH_TABLE {
    uint32_t size;
    NFAPI_CRC_INDICATION_PDU_T **data;
    pthread_mutex_t mutex;
} HASH_TABLE;

void initHashTable(HASH_TABLE *table, uint32_t size) {
    table->size = size;
    table->data = (NFAPI_CRC_INDICATION_PDU_T **)calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    table->mutex = PTHREAD_MUTEX_INITIALIZER;
}

uint32_t hashFunction(const uint32_t key) {
    return key % table->size;
}

void addEntry(HASH_TABLE *table, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&table->mutex);
    uint32_t index = hashFunction(entry->rnti);
    entry->next = table->data[index];
    table->data[index] = entry;
    pthread_mutex_unlock(&table->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* getEntryByRNTI(HASH_TABLE *table, uint32_t rnti) {
    pthread_mutex_lock(&table->mutex);
    uint32_t index = hashFunction(rnti);
    NFAPI_CRC_INDICATION_PDU_T *current = table->data[index];

    while (current != NULL) {
        if (current->rnti == rnti) {
            pthread_mutex_unlock(&table->mutex);
            return current;
        }
        current = current->next;
    }

    // Entry not found
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}
