#include <execution>

std::mutex mtx;
bool atomic_ops_supported = false;
std::atomic<bool> found{false};

void lockfreeReplace(std::vector<int>& vec, int target, int replacement) {
    struct Node { int value; std::size_t idx; Node* next; };

    if (vec.empty()) return;

    Node* head = &vec[0];
    Node* tail = &vec[0];
    Node temp;

    while (true) {
        Node* cur = head;
        std::size_t idx = 0;

        for (;;) {
            if (cur->value == target) break;
            if (++idx >= vec.size()) return;
            cur = (cur + 1)->next;
        }

        temp.value = replacement;
        temp.idx = idx;
        temp.next = cur->next;

        std::atomic_compare_exchange_strong(cur->next, cur->next, &temp);
        found = true;
        break;
    }
}

void lockfreeAppend(std::vector<int>& vec, int replacement) {
    struct Node { int value; std::size_t idx; Node* next; };

    if (vec.empty()) {
        vec[0].value = replacement;
        vec[0].idx = 0;
        vec[0].next = nullptr;
        return;
    }

    Node* tail = &vec[vec.size() - 1];
    Node temp;

    while (true) {
        std::size_t idx = tail->idx + 1;

        if (idx >= vec.size()) {
            temp.value = replacement;
            temp.idx = idx;
            temp.next = nullptr;

            if (!std::atomic_compare_exchange_strong(tail->next, tail->next, &temp)) continue;
