        std::unique_lock<std::mutex> lock(mutex);
        container.push_back(value);
    }

    int pop_front() {
        std::unique_lock<std::mutex> lock(mutex);
        return container.front();
    }
private:
    Container container;
    std::mutex mutex;
};

std::vector<int> modifyVector(const std::vector<int>& input, int target, int replacement, bool strictMode, std::chrono::duration<double> maxDuration) {
    LockFreeVector lockFreeContainer;
    ThreadSafeContainer<ThreadSafeContainer<std::vector<int>>> safeContainer;

    auto startTime = std::chrono::high_resolution_clock::now();
    size_t currentIndex = 0;
    bool foundTarget = false;
    std::shared_ptr<std::atomic<bool>> targetFound(new std::atomic<bool>(false));

    // Concurrently search for the target in both lock-free and thread-safe containers.
    auto lockFreeSearch = [&]() {
        for (; currentIndex < input.size(); ++currentIndex) {
            if (lockFreeContainer.at(currentIndex) == target && !targetFound->load()) {
                std::atomic_thread_fence(std::memory_order_acq_rel);
                targetFound->store(true, std::memory_order_release);
                break;
            }
        }
    };

    auto safeSearch = [&]() {
        for (; currentIndex < input.size(); ++currentIndex) {
            if (safeContainer.get()->at(currentIndex) == target && !targetFound->load()) {
                std::atomic_thread_fence(std::memory_order_acq_rel);
                targetFound->store(true, std::memory_order_release);
                break;
            }
        }
    };

    std::thread lockFreeThread(lockFreeSearch);
    std::thread safeThread(safeSearch);

    // Wait for the search to complete.
    lockFreeContainer.push_back(std::numeric_limits<int>::max()); // Signal completion of lock-free search.
    safeContainer.get()->push_back(std::numeric_limits<int>::max()); // Signal completion of thread-safe search.
    lockFreeThread.join();
    safeThread.join();

    foundTarget = targetFound->load();

    if (foundTime <= maxDuration && !strictMode) {
        std::unique_lock<std::mutex> lock(mutex);
        if (foundTarget) {
            // Atomically replace the target with replacement in both containers.
            lockFreeContainer[currentIndex] = replacement;
            auto& safeContainerRef = *safeContainer.get();
            auto& containerRef = safeContainerRef.back();
            auto originalValue = containerRef[currentIndex];
            while (containerRef[currentIndex] != originalValue) {
                std::this_thread::yield();
            }
            containerRef[currentIndex] = replacement;
        } else if (!strictMode) {
            safeContainer.get()->push_back(replacement);
        }
    } else if (strictMode) {
        // Throw an exception if the function took too long to execute and strictMode is true.
        auto endTime = std::chrono::high_resolution_clock::now();
        auto elapsedTime = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();
        if (elapsedTime > maxDuration.count()) {
            throw std::runtime_error("Operation exceeded the allowed duration.");
        }
    }

    return input;
}
