    def __init__(self, domain, ip_addresses, priority):
        self.domain = domain
        self.ip_addresses = list(ip_addresses)
        self.priority = priority
```

2. Here's the `DNSResolver` class that manages the collection of DNSConfig objects:

```python
import heapq

class DNSResolver:
    def __init__(self):
        self.configurations = []
        heapq.heapify(self.configurations)

    def add_configuration(self, domain, ip_addresses, priority):
        config = DNSConfig(domain, ip_addresses, priority)
        heapq.heappush(self.configurations, config)

    def update_configuration(self, domain, ip_addresses, priority):
        for i, config in enumerate(self.configurations):
            if config.domain == domain:
                self.configurations[i] = DNSConfig(domain, ip_addresses, priority)
                heapq.heapify(self.configurations)

    def resolve(self, domain):
        while self.configurations and self.configurations[0].domain != domain:
            heapq.heappop(self.configurations)
        if not self.configurations or len(self.configurations[0].ip_addresses) == 0:
            return None
        return self.configurations[0].ip_addresses[0]
```

