AESCipherContext* aes_gcm_init(const ConfigData* config, const char* passphrase) {
    // Initialize cipher context
    AESCipherContext* ctx = malloc(sizeof(AESCipperContext));
    EVP_CIPHER_CTX_init(&ctx->ctx);

    // Derive encryption key and nonce from passphrase using PBKDF2
    unsigned char key[32], iv[IV_LENGTH];
    int key_len = 0, iv_len = 0;
    PKCS5_PBKDF2_HMAC(*EVP_sha256(), config->iv_length + AES_BLOCK_SIZE, passphrase, strlen(passphrase), 10000, key, sizeof(key));
    key_len = sizeof(key);
