    iv_len = IV_LEN;

    // Configure AES-GCM cipher for authenticated encryption
    const EVP_CIPHER* cipher = EVP_aes_256_gcm();
    ctx->ctx->cipher = cipher;
    ctx->ctx->key = key;
    ctx->ctx->iv  = iv;
    ctx->ctx->key_len = key_len;
    ctx->ctx->iv_len = iv_len;
    ctx->ctx->flags |= EVP_CIPHER_FLAG_ENCRYPT | EVP_CIPHER_FLAG_GCM_MODE;
    ctx->ctx->aad_len = 0; // Assuming no additional authenticated data (AAD) for simplicity

    return ctx;
}

void aes_gcm_cleanup(AESCipherContext* ctx) {
    EVP_CIPHER_CTX_free(&ctx->ctx);
    free(ctx);
}
