['1. Here's the `DNSConfig` class for representing a single configuration:

```python
class DNSConfig:
    def __init__(self, domain, ip_addresses, priority):
        self.domain = domain
        self.ip_addresses = ip_addresses
        self.priority = priority
        self.ttl = 0  # Time-to-Live in seconds
        self.last_updated = None  # Timestamp of last update

    def is_expired(self):
        if not self.last_updated:
            return True
        current_time = time.time()
        return (current_time - self.last_updated) > self.ttl
```

2. Next, we create a `DNSResolver` class that manages the collection of configurations and provides methods for adding, updating, resolving, and logging:

```python
import threading
import time
from collections import OrderedDict
import pickle
import logging

class DNSResolver:
    def __init__(self, ttl=3600):
        self.configs = OrderedDict()
        self.ttl = ttl
        self.lock = threading.Lock()
        self.logger = logging.getLogger(__name__)
        self._load_state()

    def _load_state(self):
        try:
            with open('dns_resolver_state.pkl', 'rb') as f:
                state = pickle.load(f)
                if isinstance(state, DNSConfigState):
                    self.configs = state.configs
        except Exception as e:
            self.logger.exception("Failed to load state from file: " + str(e))

    def _save_state(self):
        try:
            with open('dns_resolver_state.pkl', 'wb') as f:
                pickle.dump(DNSConfigState(self.configs), f)
        except Exception as e:
            self.logger.exception("Failed to save state to file: " + str(e))

    def add_config(self, config):
        with self.lock:
            if config.domain not in self.configs:
                self.configs[config.domain] = config
                self._save_state()

    def update_config(self, domain, updates):
        with self.lock:
            if domain in self.configs:
                self.configs[domain].update(updates)
                self._save_state()

    def resolve(self, domain):
        with self.lock:
            for config in list(self.configs.values()):
                if not config.is_expired():
                    if config.domain == domain:
                        return config.ip_addresses
            return []

    def log_event(self, event):
        self.logger.info(str(event))
```

