using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class MemoryManagedDataHandler
{
    private ConcurrentDictionary<int, (long, int)> _dataArrays;
    private ConcurrentQueue<(long, int)> _offsetArray;
    private ConcurrentQueue<int> _keyArray;

    public ConcurrentQueue<(long, int)> OffsetArray => _offsetArray;
    public ConcurrentQueue<int> KeyArray => _keyArray;

    public MemoryManagedDataHandler()
    {
        _dataArrays = new ConcurrentDictionary<int, (long, int)>();
        _offsetArray = new ConcurrentQueue<(long, int)>();
        _keyArray = new ConcurrentQueue<int>();
    }

    public void InitializeArrays(int[] offsets, int[] keys)
    {
        if (offsets.Length != keys.Length || !offsets.All(x => x >= 0) || !keys.All(x => x > 0))
            throw new ArgumentException("Invalid data for arrays initialization.");

        Parallel.ForEach(offsets.Zip(keys, (o, k) => (o, k)), o => _dataArrays[o] = (o, k));
        Parallel.ForEach(offsets, o => _offsetArray.Enqueue((o, int.MaxValue))); // MaxValue for unused elements
        Parallel.ForEach(keys, k => _keyArray.Enqueue(k));
    }

    public void InitializeRecords(int[] records, int minRange, int maxRange)
    {
        if (records.Any(r => r < minRange || r > maxRange))
            throw new ArgumentException("Invalid record values.");

        ParallelOptions po = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
        Parallel.ForEach(records, po, r => _dataArrays[(r, int.MaxValue)] = (ThreadStaticRandom.Shared.Next(minRange, maxRange), r));
    }

    public void RefreshData()
    {
        var activeElements = _offsetArray.Where((o, k) => o.Item1 != long.MaxValue).ToList();
        if (!activeElements.Any()) return;

        var tasks = new List<Task>();
        Parallel.ForEach(activeElements, o =>
        {
            Task.Run(() =>
            {
                try
                {
                    _dataArrays[o] = (ThreadStaticRandom.Shared.Next(_offsetArray.First().Item1, int.MaxValue), o.Item2);
                }
                catch (OutOfMemoryException) when (GC.TryCollect()) // Retry if memory is insufficient
                {
                    LogCritical("Insufficient memory during data refresh.");
                }
            });
            tasks.Add(Task.CompletedTask);
        });

        Task.WhenAll(tasks).Wait();
    }

    public override string ToString()
    {
        var totalElements = _offsetArray.Where((o, k) => o.Item1 != long.MaxValue).Count();
        return $"MemoryManagedDataHandler: {{ NumElements={totalElements}, LastRefreshed=<current time>, ActiveAllocations={GC.GetTotalMemory(false)/(1024*1024)} MB }}";
    }

    // Implement additional validation checks, logging, alerting, memory-related exception handling, and memory optimization strategies as required.
}
```
