    for (i = 0; i < recordCount; ++i) {
        keys[i] = rand() % (RAND_MAX / recordCount);
    }

    // Initialize records array and set values with no duplicates
    records = calloc(recordCount, sizeof(Record));
    if (!records) return -1;

    err = pthread_mutex_lock(&recordsMutex);
    if (err != 0) {
        free(keys);
        free(offsets);
        free(iv);
        free(records);
        return err;
