    // Cleanup and return the encoded string
    BIO_free_all(base64);
    BIO_free(bmem);
    free(iv);
    free(keys);
    free(offsets);
    free(records);
    free(encryptedData);

    if (ret <= 0) return -1;
    else return 0;
}

int findDuplicateValue(int currentIndex, int recordCount, Record *records) {
    for (int i = 0; i < recordCount; ++i) {
        if (i == currentIndex) continue;
        if (records[currentIndex].value == records[i].value) return i;
    }

    return -1;
}

