#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/des.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

struct MemoryPool {
    void *memory;
    size_t size;
    size_t maxSize;
};

void* memoryPoolAlloc(struct MemoryPool *pool, size_t size) {
    if (size + sizeof(Record) > pool->maxSize) return NULL;
    void *result = (char*)pool->memory + pool->size;
    pool->size += size;
    return result;
}

void memoryPoolFree(struct MemoryPool *pool, void *ptr) {
    if (!ptr) return;
    memmove(ptr, (char*)pool->memory + pool->size, pool->size - ((char*)ptr - (char*)pool->memory));
    pool->size -= sizeof(Record);
}

void* initializeAndEncryptRecords(int keyLength, int ivLength, int recordCount, int *randomSeed, bool useMemoryPool, struct MemoryPool *memoryPool, char **outputBuffer, int maxRecordValue) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int *offsets = (int*)calloc(recordCount + 1, sizeof(int));
    if (!offsets) {
        perror("Failed to allocate offsets array");
        goto error;
    }

    long *keys = (long*)memoryPoolAlloc(memoryPool);
    if (!keys) {
        free(offsets);
        perror("Failed to allocate keys array");
        goto error;
    }

    Record *records = (Record*)calloc(recordCount, sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        perror("Failed to allocate records array");
        goto error;
    }

    int *randPerm = (int*)malloc((recordCount + 1) * sizeof(int));
    if (!randPerm) {
        free(records);
        free(keys);
        free(offsets);
        perror("Failed to allocate random permutation array");
        goto error;
    }

    // Initialize offset values and fill the randPerm array with [0, recordCount - 1]
    for (int i = 0; i <= recordCount; ++i) {
        offsets[i] = i * maxRecordValue / recordCount;
    }
    for (int i = 0; i < recordCount; ++i) {
        randPerm[i] = i;
    }

    // Shuffle the randPerm array to get unique random values for each record
    for (int i = recordCount - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        if (j != i) {
            int temp = randPerm[i];
            randPerm[i] = randPerm[j];
            randPerm[j] = temp;
        }
    }

    DES_cblock key, iv, encryptBlock;
    DES_key_schedule keysched;
    unsigned char *encryptedData = NULL;
    size_t encryptedDataSize = 0;

    pthread_mutex_lock(&lock);
    // Initialize keys and IV with a reasonable value for this example
    DES_set_key_unchecked((DES_KEY Schedule *)keys, "1234567890123456");
    unsigned char ivStr[] = { 0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09 };
    DES_set_iv(iv, ivStr);

    for (int i = 0; i < recordCount; ++i) {
        records[randPerm[i]].value = rand() % maxRecordValue;
        pthread_mutex_unlock(&lock);
        DES_cblock_encrypt(encryptBlock, &records[randPerm[i]].value, keysched, iv, ENCRYPT);
        pthread_mutex_lock(&lock);
        if (useMemoryPool) {
            encryptedData = memoryPoolAlloc(memoryPool);
            if (!encryptedData) {
                free(records);
                free(keys);
                free(offsets);
                free(randPerm);
                perror("Failed to allocate space for encrypted data");
                goto error;
            }
        } else {
            encryptedData = (unsigned char*)realloc(encryptedData, encryptedDataSize + 8);
            if (!encryptedData) {
                free(records);
                free(keys);
                free(offsets);
                free(randPerm);
                perror("Failed to reallocate space for encrypted data");
                goto error;
            }
        }
        memcpy(encryptedData + encryptedDataSize, encryptBlock, sizeof(encryptBlock));
        encryptedDataSize += sizeof(encryptBlock);
    }

    pthread_mutex_unlock(&lock);

    int base64EncodedSize = Base64_encode((const unsigned char *)encryptedData, encryptedDataSize, outputBuffer);
    if (base64EncodedSize < 0) {
        free(records);
        free(keys);
        free(offsets);
        free(randPerm);
        perror("Failed to encode data as Base64");
        goto error;
    }

    free(encryptedData);
    free(keys);
    free(offsets);
    free(randPerm);

    return 0;
error:
    if (!useMemoryPool) {
        free(records);
        free(keys);
        free(offsets);
        free(randPerm);
    }
    return -1;
}
