typedef struct {
    char *buffer;
    int value;
} Record;

struct hash_table {
    size_t capacity;
    size_t count;
    Record **records;
    pthread_mutex_t mutex;
};

void custom_hash(struct hash_table *ht, size_t index) {
    index = (index + 31) % ht->capacity;
}

Record* create_record() {
    Record *r = malloc(sizeof(Record));
    r->buffer = NULL;
    r->value = -1;
    return r;
}

void init_hash_table(struct hash_table *ht, size_t capacity) {
    ht->capacity = capacity;
    ht->count = 0;
    ht->records = calloc(capacity, sizeof(Record*));
}

void resize_hash_table(struct hash_table *ht, size_t newCapacity) {
    if (newCapacity <= ht->capacity) return;

    Record **newRecords = malloc(newCapacity * sizeof(Record*));
    memcpy(newRecords, ht->records, ht->capacity * sizeof(Record*));

    init_hash_table(ht, newCapacity);
    ht->records = newRecords;
}

void insert_record(struct hash_table *ht, Record *r) {
    size_t index = custom_hash(ht, r->value);
    pthread_mutex_lock(&ht->mutex);

    while (ht->records[index] != NULL) {
        if (!ht->records[index]->value) {
            ht->records[index] = r;
            break;
        }
        index = (index + 1) % ht->capacity;
    }

    if (ht->records[index] == NULL) {
        ht->records[index] = r;
        ++ht->count;
    }

    pthread_mutex_unlock(&ht->mutex);
}

Record* find_record(struct hash_table *ht, int value) {
    size_t index = custom_hash(ht, value);
    Record *r = ht->records[index];

    while (r != NULL && r->value != value) {
        r = r->next;
    }

    return r;
}

