#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/des.h>
#include <base64.h>
#include <pthread.h>
#define LOAD_FACTOR 0.75

typedef struct {
    char *buffer;
    int value;
} Record;

typedef struct HashNode {
    Record *record;
    struct HashNode *next;
} HashNode;

int hashFunction(int key, int arraySize) {
    return (key % arraySize < LOAD_FACTOR * arraySize) ? key % arraySize : (key % arraySize) + 1;
}

void resizeHashTable(HashNode **table, int *arraySize) {
    int newArraySize = *arraySize * 2;
    HashNode **newTable = malloc(sizeof(HashNode *) * newArraySize);

    for (int i = 0; i < newArraySize; ++i) {
        newTable[i] = NULL;
    }

    for (int i = 0; i < *arraySize; ++i) {
        HashNode *node = table[i];
        while (node != NULL) {
            Record *record = node->record;
            int key = hashFunction(record->value, newArraySize);
            node->next = newTable[key];
            newTable[key] = node;
            node = node->next;
        }
    }

    free(table);
    *arraySize = newArraySize;
}

Record *createRecordWithValue(int value) {
    Record *record = malloc(sizeof(Record));
    record->buffer = malloc(MAX_RECORD_SIZE);
    memset(record->buffer, 0, MAX_RECORD_SIZE);
    record->value = value;
    return record;
}

void initializeAndEncryptRecordsWithPersistence(int keyLength, int ivLength, int recordCount, int *randomSeed, bool useMemoryPool, char **outputBuffer, int maxRecordValue, bool persistToDisk) {
    // Initialize hash table and allocate memory for offsets, keys, and records
    HashNode **hashTable = malloc(sizeof(HashNode *) * recordCount);
    int *offsets = calloc(recordCount + 1, sizeof(int));
    int *keys = malloc(3 * keyLength * recordCount * sizeof(int));

    if (!useMemoryPool) {
        for (int i = 0; i < recordCount; ++i) {
            hashTable[i] = malloc(sizeof(HashNode));
            hashTable[i]->next = NULL;
        }
    }

    // Initialize DES encryption context
    DES_key_schedule ks;
    unsigned char encrypt_key[3 * keyLength];
    des_set_key(&ks, encrypt_key, keyLength);

    // Generate random values for the records, ensuring no duplicates
    srand(*randomSeed);
    int uniqueValues[recordCount];
    int usedValuesCount = 0;
    Record **records = useMemoryPool ? (Record**)malloc(sizeof(Record*) * recordCount) : calloc(recordCount, sizeof(Record*));

    for (int i = 0; i < recordCount; ++i) {
        int value = rand() % maxRecordValue;
        while (usedValuesCount > 0 && uniqueValues[usedValuesCount - 1] == value) {
            value = rand() % maxRecordValue;
        }
        uniqueValues[usedValuesCount++] = value;
        records[i] = createRecordWithValue(value);
    }

    // Hash records and insert them into the hash table
    for (int i = 0; i < recordCount; ++i) {
        int key = hashFunction(records[i]->value, recordCount);
        records[i]->offset = offsets[key];
        offsets[key] = i + 1;
        hashTable[key]->record = records[i];
    }

    // Encrypt the data and convert it to Base64 format
    unsigned char *encryptedData = malloc(3 * keyLength * recordCount);
    for (int i = 0, pos = 0; i < recordCount; ++i) {
        Record *record = hashTable[i % recordCount]->record;
        DES_cblock iv;
        memcpy(iv, &(record->buffer), ivLength);
        des_ede3_encrypt(&ks, DES_ecb(), &iv, encryptedData + pos, &iv, record->buffer, ivLength, NULL);
        pos += 3 * keyLength;
    }

    // Base64 encode the encrypted data and store it in outputBuffer
    char *encodedData = base64_encode((const unsigned char *)encryptedData, 3 * keyLength * recordCount, outputBuffer);

    // Free allocated memory and return
    free(keys);
    free(encryptedData);
    if (!useMemoryPool) {
        for (int i = 0; i < recordCount; ++i) {
            free(hashTable[i]);
        }
        free(hashTable);
    }
    free(records);

    // If persistToDisk is true, serialize the data structure to a binary file
    if (persistToDisk) {
        FILE *file = fopen("data.bin", "wb");
        fwrite(offsets, sizeof(int), recordCount + 1, file);
        for (int i = 0; i < recordCount; ++i) {
            Record *record = hashTable[i % recordCount]->record;
            fwrite(record->buffer, MAX_RECORD_SIZE, 1, file);
            fwrite(&record->value, sizeof(int), 1, file);
        }
        fclose(file);
    }
}
