import java.io.*;
import java.util.concurrent.atomic.AtomicInteger;

public class MD5Logger {
    private static final AtomicInteger retryCounter = new AtomicInteger(0);
    private static final int MAX_RETRIES = 3;

    public static void logError(Exception e) {
        if (retryCounter.getAndIncrement() < MAX_RETRIES) {
            tryLogError(e);
        } else {
            System.err.println("Failed to log error after " + MAX_RETRIES + " retries.");
        }
    }

    private static void tryLogError(Exception e) {
        RandomAccessFile logFile = null;
        try {
            logFile = new RandomAccessFile("hash_cache_errors.log", "rw");
            logFile.writeUTF(e.getClass().getSimpleName() + ": " + e.getMessage());
        } catch (IOException ex) {
            MD5Logger.logError(ex);
        } finally {
            if (logFile != null) {
                try {
                    logFile.close();
                } catch (IOException e) {
                    MD5Logger.logError(e);
                }
            }
        }
    }
}
