// Configuration structure
typedef struct {
    const char *filename;
    const char *key;
    int log_level;
    size_t max_messages_per_second;
} Config;

// Logging function using snprintf and va_start/va_end
void log(int level, const char *format, ...) {
    // Implement asynchronous logging to remote server here
}

// Custom compare function for qsort based on the custom key defined in configuration
bool compare_lines(const void *a, const void *b, void *param) {
    Config *config = param;
    const char *line_a = *(const char **) a;
    const char *line_b = *(const char **) b;

    size_t key_len = strlen(config->key);
    size_t pos_a = strcspn(line_a, "\n");
    size_t pos_b = strcspn(line_b, "\n");

    if (pos_a < key_len || pos_b < key_len) {
        return false; // One of the lines is not long enough to contain the custom key
    }

    const char *key_a = line_a + pos_a - key_len;
    const char *key_b = line_b + pos_b - key_len;

    return strcmp(key_a, config->key) < strcmp(key_b, config->key);
}

// Conditional sort and log function
void conditionalSortAndLog(Config config) {
    int fd = open(config.filename, O_RDONLY);

    if (fd == -1) {
        log(ERROR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    struct stat file_stats;
    fstat(fd, &file_stats);
    void *map = mmap(NULL, file_stats.st_size, PROT_READ, MAP_PRIVATE, fd, 0);

    if (map == MAP_FAILED) {
        close(fd);
        log(ERROR, "Failed to map log file: %s", strerror(errno));
        return;
    }

    char *lines = (char *) map;
    size_t lines_count = file_stats.st_size / sizeof(char) + 1;
    qsort((void *)lines, lines_count, sizeof(char), compare_lines, &config);

    munmap(map, file_stats.st_size);
    close(fd);

    size_t current_messages = 0;
    sem_t rate_limiter;
    sem_init(&rate_limiter, 0, config.max_messages_per_second);

    for (size_t i = 0; i < lines_count; ++i) {
        sem_wait(&rate_limiter);
        current_messages++;

        const char *line = &lines[i * sizeof(char)];
        log(config.log_level, line);
    }

    if (current_messages < lines_count) {
        // Handle the case where not all messages were logged due to rate limiting
    }
}
```

