function enhancedDOMTraversal(root, selector, callback) {
    let elements = [];
    const traverse = function (node) {
        if (!node || node.nodeType !== Node.ELEMENT_NODE) return;
        if (callback(node)) elements.push(node);
        Array.from(node.children).forEach(traverse);
    };
    traverse(root);
    return elements;
}
