#define MAX_LIST_SIZE 1000

typedef struct NetworkStat {
    time_t timestamp;
    unsigned int packet_count;
    float error_rate;
} NetworkStat;

struct DynamicList {
    NetworkStat* list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
};

void initDynamicList(struct DynamicList* list) {
    list->list = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

NetworkStat* createNetworkStat() {
    NetworkStat* stat = malloc(sizeof(NetworkStat));
    if (!stat) return NULL;
    stat->timestamp = time(NULL);
    stat->packet_count = 0;
    stat->error_rate = 0.0;
    return stat;
}

void validateData(NetworkStat* stat, float threshold) {
    // Implement your data validation logic here
    // Return 1 if the data is valid, 0 otherwise
    int isValid = (stat->packet_count > 0 && stat->error_rate <= threshold);
}

void logEvent(const char* message) {
    printf("%s\n", message);
}

int addNetworkStatToList(struct DynamicList* list, NetworkStat* stat) {
    if (!list || !stat) return -1;

    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        // Resize the list if it's full
        NetworkStat** newList = realloc(list->list, sizeof(NetworkStat)*(list->capacity + MAX_LIST_SIZE));
        if (!newList) {
            pthread_mutex_unlock(&list->mutex);
            free(stat);
            return -1;
        }
        list->list = newList;
        list->capacity += MAX_LIST_SIZE;
    }

    list->list[list->count] = *stat;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void manageNetworkStats(struct DynamicList* list) {
    NetworkStat* newStat = createNetworkStat();
    if (!newStat) {
        logEvent("Failed to allocate memory for network stat.");
        return;
    }

    // Collect data from network interfaces here

    int isValid = validateData(newStat, 0.1);
    if (isValid) {
        addNetworkStatToList(list, newStat);
        logEvent("Added network stat entry.");
    } else {
        free(newStat);
        logEvent("Discarded network stat due to invalid data.");
    }
}
```
