#include <atomic>
#include <chrono>
#include <condition_variable>
#include <fstream>
#include <iostream>
#include <lock_guard>
#include <map>
#include <mutex>
#include <queue>
#include <string>
#include <thread>

enum class LogLevel { DEBUG, INFO, WARN, ERROR, FATAL };

class Logger {
public:
    Logger(LogLevel level = LogLevel::INFO, const std::string& filename = "", bool console_log = true)
        : level_(level), file_(filename), console_(console_log) {}

    ~Logger() {
        stop_logging();
        if (file_) close_file();
    }

    void set_level(LogLevel level) { level_ = level; }

    void set_destination(const std::string& filename, bool console_log = true) {
        file_ = filename;
        console_ = console_log;
    }

    void log(LogLevel level, const std::string& message) {
        if (level < level_) return;
        log_queue_.emplace([this, message]() mutable { do_log(message); });
    }

private:
    void start_logging() {
        logging_ = true;
        if (!file_.empty()) open_file();
        thread_pool_.reserve(std::thread::hardware_concurrency());
        for (size_t i = 0; i < thread_pool_.capacity(); ++i)
            thread_pool_.emplace_back(&Logger::flush_queue, this);
    }

    void stop_logging() { logging_ = false; log_condition_.notify_all(); }

    void flush_queue(Logger* logger) {
        std::unique_lock<std::mutex> lock(logger->log_mutex_);
        log_condition_.wait(lock, [this]() { return !logger->log_queue_.empty() || !logger->logging_; });

        if (logger->logging_) {
            auto message = logger->log_queue_.front();
            logger->log_queue_.pop();
            lock.unlock();
            logger->do_log(std::move(message));
        }
    }

    void do_log(const std::string& message) {
        if (console_) std::cout << message;
        if (!file_.empty()) log_to_file(message);
    }

    void open_file() { file_.open(std::ios::out | std::ios::app | std::ios::trunc); }

    void close_file() { file_.close(); }

    void log_to_file(const std::string& message) {
        static constexpr size_t max_log_size = 10485760; // 10MB
        if (file_.tellp() > max_log_size) file_.clear();
        file_ << message << '\n';
    }

    LogLevel level_;
    std::string file_;
    bool console_;

    std::queue<std::function<void()>> log_queue_;
    mutex log_mutex_;
    condition_variable log_condition_;
    bool logging_{false};

    std::vector<std::thread> thread_pool_;
};
```

This code provides a basic Logger class that supports multiple log levels, configurable destinations, and dynamic adjustment of logging settings at runtime. The logger is thread-safe and can handle high-throughput logging scenarios with a batching strategy using a queue. The log file size is limited to prevent excessive disk usage.']

