#include <openssl/sha.h>
#include <openssl/aes.h>
#include <openssl/rand.h>

static unsigned char aes_key[AES_BLOCK_SIZE + AES_KEYSIZE_256];
static unsigned char aes_iv[AES_BLOCK_SIZE];

int init_aes(const char* pass, AES_KEY** key) {
    SHA1_CTX ctx;
    unsigned char hash[SHA_DIGEST_LENGTH];
    const EVP_CIPHER_CTX* cipher = EVP_aes_256_cbc();
    unsigned int len;

    /* Hash the password */
    SHA1Init(&ctx);
    SHA1Update(&ctx, pass, strlen(pass));
    SHA1Final(hash, &ctx);

    /* Derive key and IV from hashed password */
    memcpy(aes_key, hash, SHA_DIGEST_LENGTH);
    len = SHA_DIGEST_LENGTH;
    RAND_bytes(aes_iv, AES_BLOCK_SIZE);
    EVP_EncryptInit_ex(cipher, aes_key, aes_key, aes_iv, NULL);

    *key = AES_KEY_dup(EVP_CIPHER_CTX_get_cipher(cipher));

    return 1;
}
