LTE_UE_CONTEXT_MANAGER::~LTE_UE_CONTEXT_MANAGER() {
    // Save changes to the database before exiting
}

UE_CONTEXT* LTE_UE_CONTEXT_MANAGER::get_context(uint64_t ue_id) {
    pthread_rwlock_rdlock(&lock);
    auto it = cache.find(ue_id);
    if (it != cache.end()) {
        return it->second;
    }
    UE_CONTEXT context = db.get_context(ue_id);
    if (!context) {
        pthread_rwlock_unlock(&lock);
        return nullptr;
    }
    // Cache the context
    cache[ue_id] = new UE_CONTEXT(context);
    return cache[ue_id];
}

void LTE_UE_CONTEXT_MANAGER::add_context(const UE_CONTEXT& context) {
    pthread_rwlock_wrlock(&lock);
    db.add_context(context);
    cache.insert(context.ue_id, new UE_CONTEXT(context));
    pthread_rwlock_unlock(&lock);
}

void LTE_UE_CONTEXT_MANAGER::update_context(const UE_CONTEXT& context) {
    pthread_rwlock_wrlock(&lock);
    db.update_context(context);
    // Update the cache if needed (LRU Cache implementation will handle this)
    pthread_rwlock_unlock(&lock);
}
