void decrypt_base64(const unsigned char *input, size_t length, unsigned char **output, EVP_KEY **key, EVP_IV **iv) {
    BIO *bmem = NULL;
    BIO *buf = NULL;
    unsigned char *ptr = NULL;
    int buf_len = 0;

    if (!(bmem = BIO_new(BIO_s_mem()))) {
        perror("Error allocating BIO instance");
        goto end;
    }

    if (BIO_write(bmem, input, length) != length) {
        perror("Error writing to BIO");
        goto end;
    }

    buf = BIO_new(BIO_s_mem());
    if (!buf) {
        perror("Error allocating BIO instance");
        goto end;
    }

    if (!(ptr = malloc(512))) {
        perror("Error allocating memory for decrypted output");
        goto end;
    }
    buf_len = 512;

    while (BIO_read(bmem, ptr, buf_len) > 0) {
        int len = BIO_available(buf);
        if (len > 0 && len < buf_len) {
            buf_len = len;
        }

        if (!(ptr = realloc(ptr, buf_len))) {
            perror("Error reallocating memory for decrypted output");
            goto end;
        }

        if (BIO_write(buf, ptr, buf_len) != buf_len) {
            perror("Error writing to BIO");
            goto end;
        }
    }

    *output = ptr;
    *key = EVP_PKEY_new();
    *iv = EVP_CIPHER_iv(EVP_aes_128_cbc());

end:
    BIO_free_all(bmem);
    free(ptr);
}
