#include <sys/stat.h>
#include <syslog.h>

struct line_stats {
    size_t num_words;
    double avg_word_len;
    size_t longest_word_len;
};

struct line_stats process_line(char *line) {
    struct line_stats stats = {0, 0, 0};
    char *token = strtok(line, " \n");
    while (token != NULL) {
        stats.num_words++;
        size_t word_len = strlen(token);
        stats.avg_word_len += word_len;
        if (word_len > stats.longest_word_len) {
            stats.longest_word_len = word_len;
        }
        token = strtok(NULL, " \n");
    }
    if (stats.num_words > 0) {
        stats.avg_word_len /= stats.num_words;
    }
    return stats;
}

void usage() {
    printf("Usage: %s [options] <input_file>\n", __FILE__);
    printf("-h, --help              Display this help message.\n");
    printf("-c, --count             Output only the total number of lines.\n");
    printf("-w, --words             Output the average word length per line.\n");
    printf("-l, --longest           Output the length of the longest word in each line.\n");
    printf("-o <output_file>, --outfile <output_file>   Specify an output file to write results instead of printing to standard output.\n");
}

int main(int argc, char *argv[]) {
    const char *input_file = NULL;
    FILE *input = stdin;
    FILE *output = stdout;
    bool count = false;
    bool words = false;
    bool longest = false;
    const char *output_file = NULL;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"count", no_argument, 0, 'c'},
        {"words", no_argument, 0, 'w'},
        {"longest", no_argument, 0, 'l'},
        {"output-file", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    while (1) {
        int c = getopt_long(argc, argv, "hacwl:o:", long_options, &option_index);
        if (c == -1) {
            break;
        }
        switch (c) {
            case 'h':
                usage();
                return 0;
            case 'c':
                count = true;
                break;
            case 'w':
                words = true;
                break;
            case 'l':
                longest = true;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                usage();
                return -1;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Error: Missing input file.\n");
        return -1;
    }

    input_file = argv[optind];

    struct stat st;
    if (stat(input_file, &st) == -1) {
        perror("stat");
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "Error: %s is not a regular file.\n", input_file);
        return -1;
    }

    input = fopen(input_file, "r");
    if (input == NULL) {
        perror("fopen");
        return -1;
    }

    if (output_file != NULL) {
        output = fopen(output_file, "w");
        if (output == NULL) {
            perror("fopen");
            fclose(input);
            return -1;
        }
    }

    struct line_stats stats;
    size_t num_lines = 0;
    while (getline(&line, &len, input) != -1) {
        stats = process_line(line);
        if (!count && !words && !longest) {
            fprintf(output, "%zu %g %zu\n", stats.num_words, stats.avg_word_len, stats.longest_word_len);
        }
        num_lines++;
    }

    if (count) {
        openlog("myprogram", LOG_PID | LOG_PERROR, LOG_USER);
        syslog(LOG_INFO, "Total lines: %zu", num_lines);
        closelog();
    } else if (words || longest) {
        fprintf(output, "Average word length per line:\n");
        if (words) {
            for (size_t i = 0; i < num_lines; ++i) {
                fprintf(output, "%zu\n", stats.avg_word_len);
                stats = process_next_line(input);
            }
        }
        if (longest) {
            fprintf(output, "Longest word length in each line:\n");
            for (size_t i = 0; i < num_lines; ++i) {
                fprintf(output, "%zu\n", stats.longest_word_len);
                stats = process_next_line(input);
            }
        }
    }

    fclose(input);
    fclose(output);
    free(line);

    return 0;
}
