```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NICPConfig {
    char mac[18];
    char ip[20];
    int status;
    pthread_mutex_t lock;
} NICPConfig;

typedef struct ListNode {
    NICPConfig config;
    struct ListNode *next;
} ListNode;

ListNode* head = NULL;

void init_lock(NICPConfig* config) {
    pthread_mutex_init(&config->lock, NULL);
}

void add_config(const char* mac, const char* ip, int status) {
    ListNode* new_node = malloc(sizeof(ListNode));
    strncpy(new_node->config.mac, mac, sizeof(new_node->config.mac));
    strncpy(new_node->config.ip, ip, sizeof(new_node->config.ip));
    new_node->config.status = status;
    init_lock(&new_node->config);
    new_node->next = head;
    head = new_node;
}

void update_config(const char* mac, const char* ip, int status) {
    ListNode *current = head;
    while (current != NULL) {
        pthread_mutex_lock(&current->config.lock);
        if (strcmp(current->config.mac, mac) == 0) {
            strncpy(current->config.ip, ip, sizeof(current->config.ip));
            current->config.status = status;
            break;
        }
        current = current->next;
        pthread_mutex_unlock(&current->config.lock);
    }
}

void remove_config(const char* mac) {
    ListNode *prev = NULL, *current = head;
    while (current != NULL) {
        if (strcmp(current->config.mac, mac) == 0) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
}

void check_connectivity() {
    // Implement ping functionality to check connectivity and update status accordingly
}

void log_event(const char* event) {
