2. Java method `initializeDatabaseConnectionPool`:

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.LinkedList;
import java.util.concurrent.locks.ReentrantLock;

public class DatabaseConnectionPool {
    private final String url;
    private final int maxConnections;
    private final LinkedList<Connection> connectionQueue;
    private final ReentrantLock lock = new ReentrantLock();

    public DatabaseConnectionPool(String url, int maxConnections) {
        this.url = url;
        this.maxConnections = maxConnections;
        this.connectionQueue = new LinkedList<>();
    }

    public Connection getConnection() throws SQLException {
        lock.lock();
        try {
            if (connectionQueue.isEmpty()) {
                Connection connection = DriverManager.getConnection(url);
                connection.createStatement().execute("SELECT 1"); // Health check
                connectionQueue.addFirst(connection);
            }

            return connectionQueue.removeLast();
        } finally {
            lock.unlock();
        }
    }

    public void releaseConnection(Connection connection) throws SQLException {
        lock.lock();
        try {
            connection.createStatement().execute("SELECT 1"); // Health check
            connectionQueue.addLast(connection);
        } finally {
            lock.unlock();
        }
    }

    public void setMaxConnections(int maxConnections) {
        this.maxConnections = maxConnections;
    }
}
