void processAndStreamData(int chunkSize, int totalChunks, int *streamDelay, bool *useCompression, void (**callback)(void*), int maxDataValue, int *bufferCapacity, pthread_mutex_t *mutex) {
    int *timestamps = malloc(totalChunks * sizeof(int));
    int *sequenceNumbers = malloc(totalChunks * sizeof(int));
    Data *data = malloc(chunkSize * sizeof(Data));

    for (int i = 0; i < totalChunks; ++i) {
        sequenceNumbers[i] = i;
        int j = 0;
        while (j < chunkSize && data[j].value != -1) { // Ensure no duplicates
            data[j++].value = random() % maxDataValue;
        }
        if (j < chunkSize) {
            data[j].value = -1; // Mark the last empty slot in the current chunk
        }
    }

    gzFile outFile = gzopen(*outputStream, "wb");

    int processedChunks = 0;
    pthread_t threadId;
    for (int i = 0; i < totalChunks; ++i) {
        pthread_mutex_lock(mutex);

        void *compressedData = compressed ? gzalloc(*bufferCapacity) : malloc(*bufferCapacity); // Use compression if enabled and memory is not exhausted

        for (int j = processedChunks * chunkSize; j < (processedChunks + 1) * chunkSize && j < totalChunks; ++j) {
            if (compressed) {
                gzwrite(outFile, &data[sequenceNumbers[j]], sizeof(Data));
            } else {
                memcpy(compressedData, &data[sequenceNumbers[j]], sizeof(Data));
            }
        }

        pthread_mutex_unlock(mutex);

        struct timespec delay;
        delay.tv_sec = *streamDelay / 1000000000L;
        delay.tv_nsec = (*streamDelay % 1000000000L);
        nanosleep(&delay, NULL);

        if (compressed) {
            gzflush(outFile); // Flush the compressed data to the output stream
        }

        if (callback) {
            (*callback)(compressedData, chunkSize, processedChunks * chunkSize + i * chunkSize, compressed ? 1 : 0); // Call the user-provided callback function
        }

        free(compressedData);
        processedChunks++;
    }

    gzclose(outFile);
    free(timestamps);
    free(sequenceNumbers);
    free(data);
}
