void* create_and_populate_cache(size_t size) {
    void* cache = calloc(MAX_CACHE_SIZE, sizeof(sensor_reading*));
    if (!cache) {
        log_error("Error: Failed to allocate memory for the cache.");
        return NULL;
    }

    void* data = create_and_populate_sensor_data_array(size);
    if (!data) {
        free(cache);
        return NULL;
    }

    // Store recently accessed sensor readings in the cache
    for (int i = 0; i < size; ++i) {
        ((sensor_reading**)cache)[i] = (sensor_reading*)data + i;
    }

    return cache;
}

void manage_memory(void** data, size_t size) {
    if (data && size > 0) {
        free(*data);
        *data = NULL;
        size--;
    }
}

