    *timestamps = calloc(capacity, sizeof(long));
    if (*timestamps == NULL) {
        fprintf(stderr, "Error allocating memory for timestamps.\n");
        exit(EXIT_FAILURE);
    }

    *temperatures = malloc(capacity * sizeof(double));
    if (*temperatures == NULL) {
        fprintf(stderr, "Error allocating memory for temperatures.\n");
        free(*timestamps);
        exit(EXIT_FAILURE);
    }

    *sensors = malloc(capacity * sizeof(sensor_data));
    if (*sensors == NULL) {
        fprintf(stderr, "Error allocating memory for sensor data.\n");
        free(*timestamps);
        free(*temperatures);
        exit(EXIT_FAILURE);
    }

    *actual_size = 0;
}

void populate_data(double min_temp, double max_temp, size_t size, long *timestamps, double *temperatures, sensor_data **sensors) {
    for (size_t i = 0; i < size; ++i) {
        timestamps[i] = (long)time(NULL);
        temperatures[i] = min_temp + ((max_temp - min_temp) * rand() / RAND_MAX);
        sensors[i]->id = i + 1;
        sensors[i]->accuracy = (float)(0.5 + (2.0 * rand() / RAND_MAX));
    }
}

void free_arrays(long *timestamps, double *temperatures, sensor_data **sensors, size_t size) {
    if (timestamps != NULL) {
        free(timestamps);
        timestamps = NULL;
    }

    if (temperatures != NULL) {
        free(temperatures);
        temperatures = NULL;
    }

    if (sensors != NULL) {
        for (size_t i = 0; i < size; ++i) {
            free(sensors[i]);
            sensors[i] = NULL;
        }

        free(sensors);
        sensors = NULL;
    }
}
