    if (strlen(str) > limit) {
        return NULL;
    }

    strcat(str, "/");
    return str;
}

int* create_offsets(int size) {
    int* offsets = (int*)calloc((size - 1), sizeof(int));
    for (int i = 0; i < size - 1; ++i) {
        offsets[i] = i;
    }
    return offsets;
}

void free_offsets(int* offsets, int size) {
    free(offsets);
}

int* create_keys(int size) {
    int* keys = (int*)calloc(size, sizeof(int));
    for (int i = 0; i < size; ++i) {
        keys[i] = i;
    }
    return keys;
}

void free_keys(int* keys, int size) {
    free(keys);
}

record* fill_records(record* records, int size, int min, int max) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
    }
    return records;
}

record* generate_data(int limit, int range) {
    char str[limit];
    if (!str) {
        return NULL;
    }

    int size = rand() % (range - 1) + 2; // Ensure minimum size of 2 for the string and data structure

    record* records = create_records(size);
    if (!records) {
        free(str);
        return NULL;
    }

    char* str_ptr = str;
    int* offsets = create_offsets(size);
    int* keys = create_keys(size);

    records = fill_records(records, size, 0, range - 1);

    for (int i = 0; i < size - 1; ++i) {
        int j = keys[offsets[i]];
        swap(&records[i], &records[j]);
        offsets[j] = offsets[i];
    }

    free_keys(keys, size);
    free_offsets(offsets, size);

    strcpy(str_ptr, create_string("", limit));

    for (int i = 0; i < size; ++i) {
        sprintf(&str[i * sizeof(record)], "%d ", records[i].value);
    }

    free_records(records, size);

    return str;
}
