#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>

typedef struct {
    int val;
} record;

void randomize_string(size_t limit, size_t range, char* buffer, size_t* length) {
    if (*length > limit) {
        free(buffer);
        return 0;
    }

    // Initialize offset and key arrays
    uint64_t *offset = malloc((*length + 1) * sizeof(uint64_t));
    int *keys = malloc((*length + 1) * sizeof(int));
    uint64_t offset_sum = 0;
    memset(offset, 0, ((*length + 1) * sizeof(uint64_t)));
    memset(keys, -1, ((*length + 1) * sizeof(int)));

    // Allocate memory for records array
    record *records = malloc((*length) * sizeof(record));

    // Generate random values and assign unique keys to each record
    srand(time(NULL));
    size_t index = 0;
    while (index < *length) {
        int key = -1;
        do {
            key = rand() % range;
        } while (keys[key] != -1);

        keys[key] = index;
        records[index].val = key;
        offset_sum += offset[index] = ((uint64_t)1 << key);
        ++index;
    }

    // Append a slash to the end of the string and store the result in the buffer
    size_t i = 0;
    for (size_t j = 0; j < index; ++j) {
        buffer[i++] = (char)(records[keys[j]].val + '0');
    }
    buffer[i++] = '/';
    buffer[i] = '\0';

    // Update the length variable and free allocated memory
    *length = i;
    free(offset);
    free(keys);
}
