#include <stdbool.h>
#include <time.h>

typedef struct _record {
    int key;
    int value;
} record;

void generate_records(int size_limit, int range, char* output_buffer, size_t* output_length, const int* key_pool, size_t pool_size) {
    if (*output_length >= size_limit + 1) return;

    long* offsets = (long*)calloc(range, sizeof(long));
    int* keys = (int*)malloc(pool_size * sizeof(int));
    record* records = NULL;
    size_t record_count = 0;

    if (!offsets || !keys) {
        free(offsets);
        return;
    }

    for (int i = 0; i < range; ++i) offsets[i] = 0;
    for (size_t i = 0; i < pool_size; ++i) keys[i] = -1;

    size_t buffer_left = size_limit + 1 - *output_length;
    if (buffer_left < sizeof(long)*range + sizeof(record)*record_count) {
        free(offsets);
        free(keys);
        return;
    }

    records = (record*)((char*)output_buffer + *output_length);
    *output_length += sizeof(record)*record_count;

    srand(time(NULL));
    for (size_t i = 0; i < record_count && record_count < pool_size; ++i) {
        int value = rand() % range;
        while (offsets[value] >= buffer_left || keys[value] != -1) {
            value = (value + 1) % range;
        }
        records[i].key = value;
        records[i].value = value;
        offsets[value] += sizeof(record);
        keys[value] = i;
        record_count++;
    }

    char* pos = output_buffer + *output_length - 1;
    *pos++ = '/';
    *output_length += 1;

    free(offsets);
    free(keys);
}
