struct Record *records;
pthread_mutex_t lock;

void insert_record(int key, long offset) {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (!records[i].key) { // empty slot found
            records[i].key = key;
            records[i].offset = offset;
            break;
        } else if (records[i].key == key) { // update existing record
            records[i].offset = offset;
            break;
        }
    }
}

long get_record(int key) {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (records[i].key == key) return records[i].offset;
    }
    return -1; // not found
}

void set_random_keys(int min, int max) {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (records[i].key) continue; // skip filled slots
        records[i].key = rand() % (max - min + 1) + min;
    }
}

void* thread_function(void *arg) {
    for (int i = 0; i < 100000; ++i) { // Insert and retrieve records in a loop to simulate concurrent access.
        int key = rand() % MAX_RECORDS;
        long offset = i * 100 + pthread_self()->id;
        pthread_mutex_lock(&lock);
            insert_record(key, offset);
        pthread_mutex_unlock(&lock);
        pthread_mutex_lock(&lock);
            long retrieved_offset = get_record(key);
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    records = malloc(MAX_RECORDS * sizeof(Record));
    pthread_mutex_init(&lock, NULL);

    set_random_keys(0, MAX_RECORDS - 1);

    pthread_t threads[4]; // Adjust the number of threads based on your system resources.
    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }

    free(records);
    pthread_mutex_destroy(&lock);

    return 0;
}
