3. Insertion Function: Iterate through the hash table to find the correct bucket, insert or update the record accordingly.

```c
void insert_record(int key, long offset, double measurement) {
    // Find the correct bucket using the hash function
    int index = hash(key);

    // Iterate through the linked list in the bucket to find or create the record
    struct Node *node = buckets[index];
    struct Record *record;

    if (node == NULL) {
        node = malloc(sizeof(struct Node));
        record = &node->record;
    } else {
        node = node->next; // Move to the next node in the bucket
        record = &node->record;
    }

    // Update the key, offset and measurement values if it's a duplicate key
    if (record->key == key) {
        record->measurement = measurement;
    } else {
        memcpy(record, &new_record, sizeof(struct Record));
    }
}
```

4. Retrieval Function: Implement a function to find the record with the given key and return its contents.

```c
struct Record get_record(int key) {
    int index = hash(key);
    struct Node *node = buckets[index];

    // Iterate through the linked list in the bucket to find the matching record
    while (node != NULL) {
        if (node->record.key == key) return node->record;
        node = node->next;
    }

    return (struct Record){0, 0, 0}; // Return a default empty record
}
```

