    int log_level; // Debugging and logging level (0: none, 1: warnings, 2: errors)
    const char *db_url;
};

void* mempool_alloc(struct MemoryPool *pool, size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    pool->allocated += size;
    return ptr;
}

void mempool_free(struct MemoryPool *pool, void *ptr, size_t size) {
    munmap(ptr, size);
    pool->allocated -= size;
}

