typedef struct {
    char key;
    int value;
} Record;

// Function to parse hexadecimal offset array
long* parse_hex(char *str) {
    size_t len = strlen(str);
    long *arr = malloc((len+1)/2 * sizeof(long));
    long pos = 0, i = 0;

    while (i < len) {
        if (isxdigit(str[i])) {
            arr[pos++] *= 16;
            arr[pos] += strtol(&str[i], NULL, 16);
            i++;

            if (i < len && isxdigit(str[i])) continue;
        }

        // Handle odd-length hex strings by discarding last non-hex character
        if (pos > 0) i++;
    }

    return arr;
}

// Function to parse integer key array
int* parse_keys(char *str) {
    size_t len = strlen(str);
    int *arr = malloc((len+1)/3 * sizeof(int));
    int i = 0, j = 0;

    while ((i < len) && (j < arr_size)) {
        if (isdigit(str[i])) {
            sscanf(&str[i], "%d", &arr[j]);
            i += strlen(&str[i]) + 1;
            j++;
        } else if (str[i] == ',') {
            i++;
        }
    }

    return arr;
}

// Function to randomly generate integer within a specified range
int rand_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to dynamically resize record array
Record* resize_records(Record **arr, size_t new_size) {
    Record *new_arr = realloc(*arr, new_size * sizeof(**arr));

    if (new_arr == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        exit(1);
    }

    *arr = new_arr;
    return arr;
}

// Function to manage memory for multiple data structures
void manage_memory(char *offsets_str, char *keys_str) {
    long *offsets = parse_hex(offsets_str);
    int *keys = parse_keys(keys_str);
    size_t record_count = offsets[0];
    Record **records = malloc(record_count * sizeof(Record));

    for (size_t i = 0; i < record_count; ++i) {
        records[i] = (Record){
            .key = i + 'A',
            .value = rand_int(1, 100)
        };
    }

    size_t current_index = offsets[1];
    Record *current_record;

    for (size_t i = 2; i < record_count; ++i) {
        if (i == current_index) {
            current_record = &records[current_index];
            printf("Current record: key=%c, value=%d\n", current_record->key, current_record->value);

            // Log memory usage at this stage
            size_t mem_used = 0;
            for (size_t j = 0; j < i+1; ++j) {
                mem_used += sizeof(long) * offsets[j] + sizeof(*keys) * keys[j];
                if (j <= current_index) mem_used += sizeof(Record);
            }
            printf("Memory usage: %zu bytes\n", mem_used);

            resize_records(&records, i+1);
            current_record = &records[current_index];
        }

        if (i < offsets[i]) continue;

        // Allocate memory for a new record
        current_record = resize_records(records, i+1);
        current_record += current_index;

        current_record->key = keys[current_index];
        current_record->value = rand_int(1, 100);

        printf("New record: key=%c, value=%d\n", current_record->key, current_record->value);
        current_index = offsets[i+1];
    }

    // Free allocated memory after execution
    free(offsets);
    free(keys);
    free(records);
}
```

