#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    long offset;
    int key;
} Record;

Record* create_records(int num_offsets, int num_keys) {
    if (num_offsets <= 0 || num_keys <= 0) return NULL;

    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) return NULL;

    int *keys = (int *)calloc(num_keys, sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize keys
    for (int i = 0; i < num_keys; ++i)
        keys[i] = i + 1;

    long total_offset = 0;
    long max_offset = 10 * pow(10, 6);

    // Initialize offsets and check sum
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % (1000000 + 1);
        total_offset += offsets[i];
        if (total_offset > 10 * pow(10, 9)) {
            free(keys);
            free(offsets);
            return NULL;
        }
    }

    Record *records = (Record *)malloc(num_offsets * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    // Shuffle records and assign keys & offsets
    int record_index = 0;
    for (int i = 0; i < num_offsets; ++i) {
        int j = rand() % (i + 1);
        Record temp = records[j];
        records[j] = records[i];
        records[i] = temp;

        records[i].key = keys[record_index++];
        records[i].offset = offsets[i];
    }

    // Check key uniqueness and remove duplicates
    int *used_keys = (int *)calloc(num_keys, sizeof(int));
    for (int i = 0; i < num_offsets; ++i) {
        if (!used_keys[records[i].key - 1]) {
            used_keys[records[i].key - 1] = 1;
        } else {
            // Reassign key and offset to avoid conflicts
            int j = records[i].key;
            do {
                j = rand() % (num_keys + 1);
            } while (j <= record_index || used_keys[j - 1]);

            records[i].key = j;
            offsets[record_index++] = records[i].offset;
        }
    }

    free(used_keys);

    return records;
}
```

This function dynamically allocates memory for the requested arrays and structures, initializes them according to the given requirements, shuffles the `records` array randomly, and verifies key uniqueness. It also handles edge cases such as zero inputs or sums that exceed the specified limits. The performance is optimized by minimizing unnecessary overhead and operations during shuffling and key verification processes.']

