void* generate_key(void *arg) {
    static int unique_keys[5000];
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int used_keys = 0;

    while (true) {
        pthread_mutex_lock(&mutex);
        if (used_keys < 5000) {
            unique_keys[used_keys++] = *((int *)arg);
        }
        pthread_mutex_unlock(&mutex);

        if (used_keys >= 5000) {
            return NULL;
        }
    }
}

long* initialize_offsets() {
    long *offsets = malloc(10000 * sizeof(long));

    for (int i = 0; i < 10000; ++i) {
        offsets[i] = rand() % 1000000 + 1;
    }

    return offsets;
}

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T *data, long offset, int key) {
    data->crc_indication_rel8.crcflag = (offset + key) % 1000000;
}

