        void *arg = &keys[i];
        pthread_create(&thread_ids[i], NULL, generate_key, arg);
    }

    for (i = 0; i < 5000; ++i) {
        void* tmp_res = pthread_join(thread_ids[i], NULL);
        if (tmp_res != NULL) {
            keys[i] = *((int *)tmp_res);
        }
    }

    for (i = 0; i < 10000; ++i) {
        data_pairs[i].offset = offsets[i];
        data_pairs[i].key = keys[i % 5000];
