void log_memory() {
    struct mallinfo mi = mallinfo();
    double usage_percentage = (100.0 * (mi.uordblok / (double)mi.usmall + mi.forwbl / (double)mi.smax - mi.keepcost) / (double)mi.total_size);
    printf("Current memory usage: %.2f%%\n", usage_percentage);
}

void *generate_record(void *arg) {
    record *record = (record *) arg;

    // Set random values for the integer and double fields
    record->key = rand() % 100;
    record->data = (double)rand() / RAND_MAX * 100.0;

    // Allocate memory for the char pointer and set it to a random string from the predefined list
    int len = rand() % 5 + 4; // Length of the string, minimum 4 characters
    record->str = (char *) malloc(len);
    strncpy(record->str, words[rand() % NUM_WORDS], len);
    record->str[len] = '\0';

    log_memory();

    return NULL;
}

void allocate_arrays() {
    int num_offsets = 100; // Change this value to adjust the size of the offset array
    int *offsets = (int *) malloc(num_offsets * sizeof(int));
    int *keys = (int *) mallctl("VM", MLCGET, MACH_PORT_NULL, (mach_msg_type_t *)&num_keys, NULL, 0, NULL);
    double *data_points = (double *) malloc(num_offsets * sizeof(double));

    // Check for buffer overflows
    if ((sizeof(offsets) + sizeof(keys) + sizeof(data_points)) > MAX_SIZE || num_keys > num_offsets) {
        printf("Error: Buffer overflow or array size too large\n");
        exit(1);
    }

    // Allocate memory for the record structures and initialize them with random values
    int num_records = 50; // Change this value to adjust the number of records
    record *records = (record *) malloc(num_records * sizeof(record));
    pthread_t threads[num_records];

    for (int i = 0; i < num_records; ++i) {
        pthread_create(&threads[i], NULL, generate_record, &records[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(offsets);
    free(keys);
    free(data_points);
}

void maintain_memory() {
    static double previous_usage = 0.0;
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);

    if (previous_usage - (double)usage.ru_maxrss / (1024 * 1024) < THRESHOLD) {
        // Free some records to manage memory effectively
        int num_records = (previous_usage - THRESHOLD + 0.01) / ((double)usage.ru_maxrss / (1024 * 1024));
        for (int i = 0; i < num_records; ++i) {
            free(records[i].str);
            free(&records[i]);
        }
    }

    previous_usage = usage.ru_maxrss / (1024 * 1024);
}

int main() {
    pthread_mutex_init(&mutex, NULL);
    allocate_arrays();
    maintain_memory();

    // Perform any additional tasks here as needed

    return 0;
}
```

