void* deserialize(const unsigned char* buffer, size_t bufferSize) {
    if (!buffer || !bufferSize) {
        perror("Invalid input");
        return NULL;
    }

    const size_t offsetCount = atoi(getenv("OFFSET_COUNT"));
    const size_t keyCount = atoi(getenv("KEY_COUNT"));
    const size_t recordCount = atoi(getenv("RECORD_COUNT"));

    long *offsets = (long*)calloc(offsetCount, sizeof(long));
    int *keys = (int*)calloc(keyCount, sizeof(int));
    Record *records = (Record*)calloc(recordCount, sizeof(Record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    size_t pos = 0;

    for (size_t i = 0; i < offsetCount; ++i) {
        memcpy(&offsets[i], buffer + pos, sizeof(long));
        pos += sizeof(long);
    }

    for (size_t i = 0; i < keyCount; ++i) {
        memcpy(&keys[i], buffer + pos, sizeof(int));
        pos += sizeof(int);
    }

    for (size_t i = 0; i < recordCount; ++i) {
        Record *recordPtr = &records[keys[i]];
        int value;

        memcpy(&value, buffer + offsets[i], sizeof(int));
        recordPtr->value = be32toh(value);

        pos += sizeof(int);
    }

    void* objectTypeId = *(void**)buffer++; // Assume type id is at the beginning of the byte array

    if (objectTypeId == NULL) {
        fprintf(stderr, "No type id found\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Implement a method to identify and load the correct class from the objectTypeId here...

    free(offsets);
    free(keys);
    free(records);
    return NULL;
}
