#include <stdbool.h>
#include <sys/mman.h> // For POSIX shared memory

struct record {
    long offset;
    int key;
};

typedef struct hash_table {
    int size;
    void *data;
    pthread_mutex_t lock;
} HashTable;

// Initialize a rolling checksum for validating offsets sum
long checksum = 0;

HashTable create_hash_table(int capacity) {
    HashTable table = {capacity, NULL, PTHREAD_MUTEX_INITIALIZER};
    if (posix_memalign((void**)&table.data, getpagesize(), sizeof(void*) * capacity)) {
        perror("Error allocating memory for hash table");
        exit(1);
    }
    return table;
}

bool insert_key(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    void** slots = table->data;
    int hash = key % table->size;
    for (int i = hash; ; i = (i + 1) % table->size) {
        if (!slots[i]) {
            slots[i] = &key;
            pthread_mutex_unlock(&table->lock);
            return true;
        } else if (slots[i] == &key) {
            pthread_mutex_unlock(&table->lock);
            return false;
        }
    }
}

long* allocate_offsets(int num_offsets) {
    long* offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        perror("Error allocating memory for offsets");
        exit(1);
    }
    srand(time(NULL));
    for (int i = 0; i < num_offsets && checksum + rand() % 1000000 < 10000000000L; ++i) {
        offsets[i] = rand() % 1000000;
        checksum += offsets[i];
    }
    if (checksum > 10000000000L) {
        fprintf(stderr, "Error: Sum of offsets exceeds limit\n");
        exit(1);
    }
    return offsets;
}

int* allocate_keys(int num_keys) {
    int* keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        perror("Error allocating memory for keys");
        exit(1);
    }
    for (int i = 0; i < num_keys; ++i) {
        keys[i] = i + 1;
    }
    return keys;
}

struct record* allocate_records(int num_records, long *offsets, int *keys) {
    struct record* records = malloc(num_records * sizeof(struct record));
    if (!records) {
        perror("Error allocating memory for records");
        exit(1);
    }
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = offsets[rand() % num_offsets];
        records[i].key = keys[i];
    }
    return records;
}

void shuffle(struct record* records, int num_records) {
    for (int i = 0; i < num_records - 1; ++i) {
        int j = rand() % (num_records - i) + i;
        struct record tmp = records[j];
        records[j] = records[i];
        records[i] = tmp;
    }
}

void* initialize(void *arg) {
    int num_offsets = *(int*)arg;
    long* offsets = allocate_offsets(num_offsets);
    HashTable hash_table = create_hash_table(num_offsets);

    for (int i = 0; i < num_offsets; ++i) {
        int key = i + 1;
        if (!insert_key(&hash_table, key)) {
            fprintf(stderr, "Error: Key conflict during offsets initialization\n");
            exit(1);
        }
    }

    int* keys = allocate_keys(num_offsets);

    struct record* records = allocate_records(num_offsets, offsets, keys);

    shuffle(records, num_offsets);

    free(offsets);
    free(keys);

    pthread_exit((void*)&hash_table);
}

struct data {
    int num_offsets;
    struct record* records;
};

void* process_records(void *arg) {
    struct data* data = (struct data*)arg;
    HashTable hash_table = *(HashTable*)pthread_self();
    int num_offsets = data->num_offsets;

    for (int i = 0; i < num_offsets; ++i) {
        struct record* current = &data->records[i];
        int key = current->key;
        if (!find(hash_table, key)) {
            fprintf(stderr, "Error: Key conflict during records processing\n");
            exit(1);
        }
    }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("Usage: %s <num_offsets>\n", argv[0]);
        return 1;
    }

    int num_offsets = atoi(argv[1]);
    if (num_offsets <= 0) {
        printf("Error: num_offsets must be greater than zero\n");
        return 1;
    }

    pthread_t threads[num_offsets];
    struct data data[num_offsets];

    for (int i = 0; i < num_offsets; ++i) {
        data[i].num_offsets = num_offsets;
        data[i].records = NULL;
        pthread_create(&threads[i], NULL, initialize, &num_offsets);
    }

    for (int i = 0; i < num_offsets; ++i) {
        pthread_join(threads[i], (void**)&data[i].records);
    }

    for (int i = 0; i < num_offsets; ++i) {
        pthread_t thread;
        pthread_create(&thread, NULL, process_records, &data[i]);
        pthread_detach(thread);
    }

    return 0;
}
