void cache_init(struct Cache* cache, size_t max_size, size_t limit, const char* logfile) {
    cache->capacity = (max_size + sizeof(Connection) - 1) / sizeof(Connection);
    cache->limit = limit;
    cache->count = 0;
    cache->connections = malloc(cache->capacity * sizeof(Connection));
    if (!cache->connections) {
        fprintf(stderr, "Failed to allocate memory for connections\n");
        exit(EXIT_FAILURE);
    }
    connection_init(&cache->connections[0], 0); // Initialize the first connection as a placeholder
    cache->expire_interval.tv_sec = 60; // Expire every minute by default
    cache->fd = open(logfile, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
