    log_memory(cache); // Log memory usage details after each successful allocation
    pthread_mutex_lock(&cache->mutex);
    if (cache->count < cache->capacity) {
        memcpy(&cache->connections[cache->count], &conn, sizeof(Connection));
        connection_init(&cache->connections[cache->count], cache->count); // Update the ID field with the current count
        ++cache->count;
