void cache_remove_lru(struct Cache* cache) {
    if (cache->count == 0) return; // If there are no connections, do not remove any
    pthread_mutex_lock(&cache->mutex);
    size_t i = 0;
    time_t max_age = LONG_MIN;
    Connection* oldest_conn = NULL;
    for (size_t j = 0; j < cache->count; ++j) {
        if (cache->connections[j].last_activity > max_age) {
            i = j;
            max_age = cache->connections[j].last_activity;
            oldest_conn = &cache->connections[i];
        }
    }
    if (!oldest_conn) return; // If no connection is older than the max age, do not remove any
    memcpy(&cache->connections[i], &cache->connections[--cache->count], sizeof(Connection));
    pthread_mutex_unlock(&cache->mutex);
}

void cache_expire(struct Cache* cache) {
    time_t now = time(NULL);
    for (size_t i = 0; i < cache->count; ++i) {
        if (now - cache->connections[i].last_activity > cache->expire_interval.tv_sec) {
            cache_remove_lru(cache);
        }
    }
}

void cache_check_memory(struct Cache* cache) {
    if ((size_t)(rss() - getrusage().ru_maxrss) < MEMORY_THRESHOLD) return; // If there's enough free memory, do not close any connections
    cache_remove_lru(cache);
}
```

