long rolling_sum(long *arr, int start, int end) {
    long sum = 0;
    for (int i = start; i < end; ++i) {
        sum += arr[i];
    }
    return sum;
}

bool check_rolling_sum(long *arr, int num_elements, int max_sum) {
    if (rolling_sum(arr, 0, num_elements) > max_sum) {
        return false;
    }
    for (int i = 1; i < num_elements - 1; ++i) {
        long current_sum = rolling_sum(arr, i, num_elements);
        if (current_sum > max_sum) {
            return false;
        }
    }
    return true;
}

struct HashTable* create_hash_table(int capacity) {
    struct HashTable *ht = malloc(sizeof(struct HashTable));
    ht->capacity = capacity;
    ht->size = 0;
    ht->keys = calloc(capacity, sizeof(int));
    ht->data = mmap(NULL, capacity * sizeof(void*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    ht->lock = PTHREAD_MUTEX_INITIALIZER;
    return ht;
}

int hash(int key, int capacity) {
    return key % capacity;
}

void* hash_table_put(struct HashTable *ht, void *data, size_t data_size, int key) {
    pthread_mutex_lock(&ht->lock);
    int index = hash(key, ht->capacity);
    while (ht->keys[index] != 0 && ht->keys[index] == key) {
        index = (index + 1) % ht->capacity;
    }
    if (index == ht->size) {
        ht->size++;
    }
    ht->keys[index] = key;
    memcpy(ht->data + index * data_size, data, data_size);
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

