#define MAX_RECORDS 10000
#define THRESHOLD 0.75
#define WORD_COUNT 10
#define MEM_CHECK_INTERVAL 1000 // in allocations

typedef struct Record {
    int i;
    double d;
    char* str;
} Record;

Record* records = NULL;
size_t num_records = 0;
size_t max_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned long total_memory = 0;
unsigned long used_memory = 0;
unsigned long free_memory = sysconf(_SC_PHYS_PAGES) * getpagesize(); // initial free memory

void* word_list[WORD_COUNT] = {
    "apple", "banana", "cherry", "date", "elderberry",
    "fig", "grape", "kiwi", "lemon", "mango"
};

// Generate random number within specified range
int rand_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    record->i = rand_range(INT_MIN, INT_MAX);
    record->d = ((double)rand_range(0, INT_MAX)) / RAND_MAX;
    size_t word_idx = rand() % WORD_COUNT;
    record->str = strdup(word_list[word_idx]);

    used_memory += sizeof(Record);
    return record;
}

void log_memory_stats() {
    used_memory += total_memory - free_memory;
    double memory_percentage = (double)used_memory / total_memory * 100.0;
    printf("Current memory usage: %.2f%%\n", memory_percentage);
}

void reclaim_memory() {
    if (num_records > 0 && free_memory < free_memory * THRESHOLD) {
        int records_to_free = num_records / MEM_CHECK_INTERVAL;
        for (int i = 0; i < records_to_free; ++i) {
            free(records[num_records - 1]);
            --num_records;
        }
    }
}

void add_record(Record* record) {
    pthread_mutex_lock(&mutex);
    if (num_records + 1 > max_records) {
        Record* new_array = realloc(records, sizeof(Record) * (max_records * 2));
        if (!new_array) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        records = new_array;
        max_records *= 2;
    }

    records[num_records++] = record;

    if (++used_memory > total_memory * THRESHOLD) {
        log_memory_stats();
        reclaim_memory();
    }

    pthread_mutex_unlock(&mutex);
}

void* thread_function(void* arg) {
    for (int i = 0; i < 1000; ++i) {
        Record* record = create_record();
        add_record(record);
    }
    return NULL;
}

int main() {
    pthread_t threads[4];

    total_memory = sysconf(_SC_PHYS_PAGES) * getpagesize();

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, NULL)) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 4; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Thread joining failed");
            exit(EXIT_FAILURE);
        }
    }

    free(records);
    return 0;
}
