```cpp
#include <iostream>
#include <list>
#include <mutex>
#include <unordered_map>
#include <memory>
#include <string>
#include <cmath>
#include <atomic>

constexpr double LOW_MEMORY_THRESHOLD = 0.75;
constexpr double GARBAGE_COLLECTION_THRESHOLD = 0.25;

std::mutex mtx;

class LRUCache {
public:
    LRUCache(size_t capacity) : _capacity(capacity), _usedMemory(0), _numItems(0) {}

    void add(int key, double value, std::string&& str) {
        if (_numItems + 1 > _capacity) {
            evictLeastRecentlyUsed();
        }

        auto it = _data.emplace(key, std::make_unique<Record>(std::move(str), value));
        _usedMemory += it->second->getSize();
        _numItems++;
        updateLRU(it);
    }

    Record* get(int key) {
        auto it = _data.find(key);
        if (it == _data.end()) return nullptr;

        updateLRU(it);
        return it->second.get();
    }

private:
    struct Record {
        std::string str;
        double value;
        size_t size;

        explicit Record(std::string&& s, double v) : str(s), value(v), size(sizeof(double) + s.size() + 1) {}

        size_t getSize() const { return size; }
    };

    std::unordered_map<int, std::unique_ptr<Record>> _data;
    std::list<std::unique_ptr<Record>> _lruList;

    void updateLRU(const auto& it) {
        std::scoped_lock lock(mtx);
        _lruList.erase(_lruList.begin());
        _lruList.push_back(std::move(it->second));
    }

    void evictLeastRecentlyUsed() {
        if (_lruList.empty()) return;

        auto it = _lruList.begin();
        _usedMemory -= (*it)->getSize();
        _numItems--;
        _data.erase((*it)->key);
        _lruList.pop_front();
    }

    size_t _capacity;
    std::atomic<size_t> _usedMemory;
    size_t _numItems;
};

void logMemoryUsage() {
    auto totalMem = std::max((uintmax_t)std::numeric_limits<decltype(_usedMemory)>::max(), getpagesize() * ::sysconf(_SC_PAGE_SIZE));
    auto usedMem = _usedMemory.load();
    double memPercentage = (double)usedMem / totalMem;
    std::cout << "Current memory usage: " << memPercentage * 100 << "%" << std::endl;
}
