// Custom allocator
typedef struct _mem_block {
    size_t size;
    struct _mem_block* next;
} mem_block;

mem_block* head = NULL;

void* custom_malloc(size_t size) {
    if (size == 0) return NULL;

    mem_block *current, *new_block;
    current = head;
    new_block = (mem_block*) malloc(sizeof(mem_block) + size);

    if (!new_block) return NULL;
    new_block->size = size;
    new_block->next = NULL;

    if (!head) {
        head = new_block;
        return (char*) new_block + sizeof(mem_block);
    }

    while (current && current->next) current = current->next;
    current->next = new_block;

    return (char*) new_block + sizeof(mem_block);
}

void custom_free(void* ptr) {
    if (!ptr || !head) return;

    mem_block *current, *temp;
    char *memory_ptr = (char*) ptr - sizeof(mem_block);
    mem_block *memory_block = (mem_block*) memory_ptr;

    for(current = head; current != NULL; current = current->next) {
        if (current == memory_block) {
            if (current == head) head = current->next;
            temp = current->next;
            free(current);
            break;
        }
    }
}

// Rolling checksum validation function for offsets array
long rolling_checksum(const long* arr, size_t len) {
    long sum = 0;
    if (len == 0) return 0;

    for (size_t i = 0; i < len; ++i) {
        sum += arr[i];
        if (sum > 10000000000LL) return false;
    }
    return sum;
}

// Hash table for key lookup in keys array
#define TABLE_SIZE 32767
typedef struct {
    int key;
    size_t index;
    struct _hash_node* next;
} hash_node;

struct _hash_node {
    hash_node* next;
};

hash_node table[TABLE_SIZE];
pthread_mutex_t table_lock = PTHREAD_MUTEX_INITIALIZER;

int get_key(int key) {
    pthread_mutex_lock(&table_lock);

    int index = hash(key);
    struct _hash_node* current = &table[index];

    for (; current != NULL; current = current->next) {
        if (current->key == key) {
            pthread_mutex_unlock(&table_lock);
            return current->index;
        }
    }

    // Create a new node and add it to the hash table
    int new_index = TABLE_SIZE - 1;
    for (int i = TABLE_SIZE - 1; i > 0; --i) {
        if (!table[i].key) {
            new_index = i;
            break;
        }
    }
    table[new_index].key = key;
    table[new_index].index = new_index;
    table[new_index].next = &table[index];

    pthread_mutex_unlock(&table_lock);
    return new_index;
}

// Custom parallel shuffle algorithm
void parallel_shuffle(void* data, size_t size, size_t chunk) {
    char* buffer = (char*) malloc(size);
    if (!buffer) return;

    pthread_t threads[chunk];
    for (size_t i = 0; i < chunk; ++i) {
        pthread_create(&threads[i], NULL, shuffle_worker, (void*) data + (i * size / chunk) * size);
    }

    for (size_t i = 0; i < chunk; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(buffer);
}

void* shuffle_worker(void* arg) {
    size_t start = *(size_t*) arg;
    size_t end = (start + sizeof(record)*chunk / sizeof(size_t)) % (sizeof(record)*size / sizeof(size_t));

    qsort((void*) ((char*)arg + start * sizeof(size_t)), end - start, sizeof(size_t), rand);

    return NULL;
}
