import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Supplier;
import java.util.logging.Logger;

public class EvenSumCache {
    private static final int CACHE_SIZE = 5000;
    private static final long TTL = TimeUnit.HOURS.toMillis(1);
    private static final AtomicLong sequenceNumber = new AtomicLong();
    private static final Logger LOGGER = Logger.getLogger("sum_cache_errors");
    private static Supplier<String> customSerializer;
    private final ConcurrentHashMap<Object, Object> cache;
    private final ScheduledExecutorService executor;
    private final ConcurrentLinkedQueue<CacheEvent> events;
    private final int[] buffer;
    private long totalMemoryAllocated = 0;

    static {
        customSerializer = () -> String.valueOf((int) sequenceNumber.getAndIncrement());
    }

    public EvenSumCache() {
        cache = new ConcurrentHashMap<>(CACHE_SIZE);
        events = new ConcurrentLinkedQueue<>();
        executor = Executors.newScheduledThreadPool(1);
        buffer = new int[2500 * 3];
        initializeBuffer();

        // Schedule cache full and eviction notifications
        executor.scheduleAtFixedRate(() -> {
            if (cache.size() >= CACHE_SIZE) {
                events.add(CacheEvent.CACHE_FULL);
            }
            for (Map.Entry<Object, Object> entry : cache.entrySet()) {
                if (System.currentTimeMillis() - entry.getValue() > TTL) {
                    events.add(CacheEvent.EVICTION + ":" + customSerializer.get());
                    cache.remove(entry.getKey());
                }
            }
        }, 0, TTL, TimeUnit.MILLISECONDS);

        // Setup logging retry logic and error file
        Runnable logError = new Runnable() {
            private int retries = 5;

            @Override
            public void run() {
                try {
                    LOGGER.severe(String.valueOf(this));
                } catch (Exception e) {
                    if (--retries > 0) {
                        executor.schedule(this, 1, TimeUnit.SECONDS);
                    }
                }
            }
        };
        LOGGER.addHandler(new java.util.logging.FileHandler("sum_cache_errors.log", true));
        LOGGER.setUseParentHandlers(false);
        executor.submit(logError);
    }

    public int[] evenSum(Collection<Integer> integers) {
        if (Objects.isNull(integers)) {
            return new int[0];
        }

        long sum = 0;
        for (int number : integers) {
            if (number % 2 == 0) {
                Object key = cache.keySet().stream().filter(k -> ((Number) k).intValue() == number).findFirst().orElse(null);
                if (Objects.isNull(key)) {
                    key = sequenceNumber.getAndIncrement();
                    cache.putIfAbsent(key, System.currentTimeMillis());
                }
                sum += buffer[(int) key * 2 + 1];
            }
        }
        return toIntArray(sum);
    }

    private void initializeBuffer() {
        for (int i = 0; i < buffer.length; ++i) {
            int offset = i / 3;
            int key = i % 3;
            if ((key == 0 || key == 2) && (offset < 2500)) {
                buffer[i] = new Random().nextInt(1_000_000);
            } else if (key == 1 && offset < 2500) {
                int k = i % 2500;
                buffer[i] = cache.containsKey(k) ? cache.get(k) : System.currentTimeMillis();
            }
        }
    }

    private int[] toIntArray(long sum) {
        totalMemoryAllocated += Long.BYTES + (sum * Integer.BYTES);
        int[] result = new int[(int) (totalMemoryAllocated / Integer.BYTES)];
        System.arraycopy(buffer, 0, result, 0, result.length);
        return result;
    }

    public void addCacheEventListener(Runnable listener) {
        events.forEach(listener);
        executor.submit(events::poll);
    }

    public static class CacheEvent {
        private final String name;

        public CacheEvent(String name) {
            this.name = name;
        }

        @Override
        public String toString() {
            return "CacheEvent{" + name + '}';
        }
    }
}
```
