// Define custom memory pool
typedef struct MemoryPool {
    void *pool;
    size_t size;
    size_t allocated;
} MemoryPool;

MemoryPool create_memory_pool(size_t size) {
    MemoryPool pool = {0};
    pool.size = size;
    pool.allocated = 0;
    if ((pool.pool = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)) == MAP_FAILED) {
        fprintf(stderr, "Memory mapping failed\n");
        exit(1);
    }
    return pool;
}

// Allocate an object from the memory pool and return a pointer to it
void *pool_alloc(MemoryPool *pool) {
    if (pool->allocated + sizeof(Record) > pool->size) {
        // Resize the memory pool when needed
        pool->size *= 2;
        if ((pool->pool = realloc(pool->pool, pool->size)) == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
    void *obj = (void *)((char *)pool->pool + pool->allocated);
    pool->allocated += sizeof(Record);
    return obj;
}

// Define Record structure and associated functions
typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

// Initialize a random Record with the given configuration
