    if (value == 0) value = rand() % CONFIG_VALUE_RANGE + CONFIG_VALUE_MIN;
    if (!key) key = offset % CONFIG_KEY_MODULUS + CONFIG_KEY_BASE;
    if (!offset) offset = pthread_self();
    record.offset = offset;
    record.key = key;
    record.value = value;
    return record;
}

// Initialize the records storage system with a given number of records
