        records[i] = pool_alloc(pool);
        Record *record = records[i];
        record->offset = pthread_self();
        record->key = CONFIG_KEY_BASE + (CONFIG_KEY_MODULUS / num_records) * i;
        record->value = rand() % CONFIG_VALUE_RANGE + CONFIG_VALUE_MIN;
    }
}

