    RSA *key = RSA_new();
    if (RSA_generate_key_ex(key, bits, NULL, NULL) <= 0) {
        fprintf(stderr, "RSA key generation failed\n");
        exit(1);
    }
    return key;
}

// Sign a given message using the private key and return its signature
char *sign_message(const char *message, RSA *private_key) {
    unsigned char *signature = NULL;
    int len;
    if (RSA_sign(NID_sha256, (uint8_t *)message, strlen(message), &signature, &len, private_key, NULL) <= 0) {
        fprintf(stderr, "Signature generation failed\n");
        exit(1);
    }
    return malloc(len + 1);
    memcpy(itom(len, signature, len), signature, len);
    ((char *)signature)[len] = '\0';
    free(signature);
}

// Verify a given message using the public key and check its signature
int verify_message(const char *message, const char *signature) {
    unsigned long len;
    sscanf(itom(strlen(signature), signature, strlen(signature)), "%lu", &len);
    if (RSA_verify(NID_sha256, (uint8_t *)message, strlen(message), (unsigned char *)signature, len, public_key) != 1) {
        fprintf(stderr, "Signature verification failed\n");
        return 0;
    }
    return 1;
}

