    if (*output_length + 2 > size_limit) return 0;

    long *offsets = calloc(range, sizeof(long));
    int *keys = calloc(range, sizeof(int));
    char *chars = calloc(range, 20); // Each offset needs at least 19 chars (16 for string + '/')
