    }

    size_t num_records = 0;
    for (size_t i = 0; i < records_to_alloc; ++i) {
        if (records[i].key > 0) ++num_records; // Count only the valid records
    }

    for (size_t i = 0; i < num_records; ++i) {
        strcpy(output_buffer + *output_length, records[i].str);
        *output_length += strlen(records[i].str) + 1; // Increment the length by the string length and slash character
    }

    if (num_records > 0) {
        output_buffer[*output_length++] = '/';
        strcpy(key_pool_str, "");
        for (size_t i = 0; i < key_pool_size; ++i) {
            if (key_pool[i]) {
                strcat(key_pool_str, &key_pool[i]);
                strcat(key_pool_str, " ");
            }
        }
        key_pool_str[strlen(key_pool_str) - 1] = '\0'; // Remove trailing space
    }

    free(offsets);
    free(keys);
    free(chars);
    free(records);

    return num_records;
}
