    if (size_limit <= 0 || range < 1 || length == NULL || keys == NULL || size_t(range + 1) > keys_size)
        return 0;

    srand(time(NULL));

    record *records = malloc((range + 1) * sizeof(record));
    if (!records) {
        printf("Failed to allocate memory for records.\n");
        return 0;
