    int unique_values[range + 1] = {};
    size_t num_generated = 0;

    // Initialize records and mark keys as used.
    for (int i = 0; i < range + 1; ++i) {
        records[i].key = keys[i];
        used_keys[records[i].key] = true;
    }

    // Generate unique values and update unique_values and records.
    for (size_t i = 0; num_generated < range && num_generated + 1 < size_limit; ++i) {
        int value = rand() % range;

        if (!unique_values[value]) {
            unique_values[value] = true;
            records[num_generated].value = value;
            ++num_generated;
        }
    }

    size_t buffer_size = num_generated + 2; // For the string and null-terminator.

    if (buffer_size > *length) {
        printf("The generated sequence exceeds the specified size limit.\n");
        free(records);
        free(used_keys);
        return 0;
    }

    // Build the string and write it to the provided buffer.
    snprintf(buffer, buffer_size, "");
    for (size_t i = 0; i < num_generated; ++i) {
        snprintf(&buffer[i * 2 + 1], 4, "%d ", records[i].value);
    }

    // Write the final null-terminator.
    buffer[num_generated * 2 + 1] = '\0';

    *length = num_generated * 3 + 1;

    free(records);
    free(used_keys);

    return 1;
}
