#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
} Record;

#define RECORD_SIZE sizeof(Record)
#define THRESHOLD 0.75 // Memory usage threshold in percentage

int compare_keys(const void *a, const void *b) {
    return (*(const int *)a - *(const int *)b);
}

void init_record_collection(Record ***records, size_t *num_records, size_t *memory_usage, size_t max_records) {
    *records = malloc(max_records * sizeof(Record*));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        *memory_usage = 0;
        *num_records = 0;
        return;
    }

    qsort(*records, 0, max_records * sizeof(Record), compare_keys);
    *num_records = 0;
    *memory_usage = 0;
}

void add_record(Record **records, size_t *num_records, size_t *memory_usage, int key, long offset) {
    if (*num_records == 0) {
        (*records)[*num_records] = malloc(RECORD_SIZE);
        if ((*records)[*num_records] == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            return;
        }
        (*records)[*num_records]->key = key;
        (*records)[*num_records]->offset = offset;
        (*num_records)++;
        *memory_usage += RECORD_SIZE;
    } else {
        size_t i = 0, j = *num_records - 1;
        while (i <= j) {
            size_t m = (i + j) / 2;
            if (key < (*records)[m]->key) {
                j = m - 1;
            } else if (key > (*records)[m]->key) {
                i = m + 1;
            } else {
                // Key already exists, do nothing
                break;
            }
        }

        Record *new_record = malloc(RECORD_SIZE);
        if (new_record == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            return;
        }

        new_record->key = key;
        new_record->offset = offset;

        size_t shift = i;
        while (shift < *num_records) {
            (*records)[shift] = (*records)[shift + 1];
            *memory_usage -= RECORD_SIZE;
            shift++;
        }
        (*records)[shift] = new_record;
        (*num_records)++;
        *memory_usage += RECORD_SIZE;
    }
}

void remove_record(Record **records, size_t *num_records, size_t *memory_usage, int key) {
    size_t i = 0;
    while (i < *num_records && (*records)[i]->key != key) {
        i++;
    }

    if (i >= *num_records) {
        fprintf(stderr, "Record with key %d not found.\n", key);
        return;
    }

    size_t j = *num_records - 1;
    while (i < j) {
        size_t m = (i + j) / 2;
        if ((*records)[m]->key < key) {
            i = m + 1;
        } else {
            j = m;
        }
    }

    // Move records from the right to fill the gap
    size_t shift = i + 1;
    while (shift < *num_records) {
        (*records)[shift - 1] = (*records)[shift];
        *memory_usage -= RECORD_SIZE;
        shift++;
    }

    free((*records)[i]);
    (*num_records)--;
    *memory_usage -= RECORD_SIZE;
}

void compact_storage(Record **records, size_t num_records, size_t memory_usage, size_t max_records, size_t *compacted_size) {
    *compacted_size = 0;

    size_t new_array_size = (num_records + 1) / 2;
    if (new_array_size <= num_records) {
        new_array_size *= 2;
    }

    Record *new_records = malloc(new_array_size * sizeof(Record*));
    if (new_records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    qsort(records, num_records, RECORD_SIZE, compare_keys);

    size_t i = 0, j = 0;
    while (i < num_records) {
        while (j < new_array_size && (*records)[i]->key <= (*records)[j]->key) {
            new_records[j] = (*records)[i];
            i++;
            j++;
        }

        if (j >= new_array_size) {
            break;
        }

        if ((*records)[i]->key <= (*records)[j]->key) {
            j++;
        } else {
            j = 0;
        }
    }

    free(*records);
    *records = new_records;

    *compacted_size = (double)*memory_usage / num_records > THRESHOLD ? new_array_size : *compacted_size;
}
```

This code provides a dynamic collection of records, each containing an integer key and long offset. The function `init_record_collection()` initializes the storage, while `add_record()` and `remove_record()` manage adding and removing records, respectively. The `compare_keys()` function is used for sorting the keys in ascending order.

The code periodically compacts the storage to reclaim unused memory and reduce fragmentation using the `compact_storage()` function. The memory usage is monitored, and an alert is triggered when it exceeds a predefined threshold.

The solution is optimized for both memory usage and speed, focusing on minimizing latency and resource consumption in high-throughput environments. It is designed to scale without significant rewrites as the size of records or the total number of records changes over time.']

