#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CHUNK_SIZE 1000000 // Maximum chunk size for memory allocation
#define TOTAL_MEMORY_LIMIT 5000000 // Total maximum memory limit

typedef struct {
    int value;
} record;

void custom_malloc(size_t* ptr, size_t size) {
    void* mem = malloc(size);
    if (!mem) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    *ptr = mem;
}

void custom_free(void* ptr) {
    free(ptr);
}

size_t get_memory_usage() {
    size_t usage = 0;
    char** memory_blocks = (char**)malloc(sizeof(char*) * 3);
    for (int i = 0; i < 3; ++i) {
        void* block = memory_blocks[i];
        if (block) {
            usage += sizeof(void*) + (size_t)(free(block) - block);
        }
    }
    free(memory_blocks);
    return usage;
}

void log_memory_usage(const char* message) {
    printf("%s: %zu bytes\n", message, get_memory_usage());
}

void initialize_arrays(size_t* long_offsets, size_t* keys, record** records, size_t* total_allocated, size_t chunk_size, size_t max_chunks) {
    *total_allocated = 0;
    size_t current_chunk = 0;
    while (*total_allocated < (chunk_size * max_chunks)) {
        custom_malloc((&long_offsets[*total_allocated]), sizeof(long));
        custom_malloc((&keys[*total_allocated]), sizeof(int));
        size_t record_size = sizeof(record);
        custom_malloc((records + *total_allocated), chunk_size * record_size);
        for (size_t i = *total_allocated; i < *total_allocated + chunk_size; ++i) {
            records[i]->value = rand() % 100 + 1;
        }
        log_memory_usage("Current chunk");
        *total_allocated += chunk_size;
        current_chunk++;
        if (current_chunk == max_chunks) break;
        if (*total_allocated >= TOTAL_MEMORY_LIMIT) {
            fprintf(stderr, "Error: Total memory limit exceeded\n");
            exit(EXIT_FAILURE);
        }
    }
    log_memory_usage("Total memory usage");
}
