} log_entry;

struct custom_allocator {
    void *memory_pool;
    size_t chunk_size;
    size_t allocation_limit;
    size_t total_allocated;
    pthread_mutex_t lock;
};

void* custom_alloc(struct custom_allocator *alloc, size_t size) {
    void *ptr = NULL;
    if (size > alloc->allocation_limit || !alloc->memory_pool) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    pthread_mutex_lock(&alloc->lock);
    if ((ptr = ((char*)alloc->memory_pool + alloc->total_allocated)) + size > ((char*)alloc->memory_pool + alloc->allocation_limit)) {
        fprintf(stderr, "Out of memory\n");
        pthread_mutex_unlock(&alloc->lock);
        return NULL;
    }

    ptr = ((char*)alloc->memory_pool + alloc->total_allocated);
    alloc->total_allocated += size;
    pthread_mutex_unlock(&alloc->lock);

    return ptr;
}

void custom_dealloc(struct custom_allocator *alloc, void *ptr) {
    if (!alloc || !ptr || !alloc->memory_pool) {
        fprintf(stderr, "Invalid deallocation\n");
        return;
    }

    pthread_mutex_lock(&alloc->lock);
    alloc->total_allocated -= (char*)ptr - ((char*)alloc->memory_pool);
    pthread_mutex_unlock(&alloc->lock);
}

