void *aligned_alloc(size_t alignment, size_t size) {
    char *ptr = malloc(size + (alignment - 1));
    if (!ptr) return NULL;
    size_t offset = (size_t)(ptr) % alignment;
    if (offset != 0) ptr += alignment - offset;
    return ptr;
}

void init_data_structures(long* offsets, int* keys, struct record* records, float* weights, time_t* timestamps, metadata_node_t** metadata, int max_keys, char* json_file, char* bin_file) {
