#define MAX_STATUS_LENGTH 50

typedef struct {
    long timestamp;
    double temperature;
    char status_message[MAX_STATUS_LENGTH];
} log_entry;

void compress(char *msg) {
    int i, j = 0;
    for (i = 0; msg[i] != '\0'; ++i) {
        if (i % 3 == 0 && msg[i] != ' ') {
            msg[j++] = '%';
            msg[j++] = '2';
            msg[j++] = 'x' + (msg[i] >> 4);
            msg[j++] = 'x' + (msg[i] & 0xf);
        } else {
            msg[j++] = msg[i];
        }
    }
    msg[j] = '\0';
}

log_entry* initialize_data(size_t *timestamps, double *temps, log_entry **entries, char **statuses) {
    *timestamps = malloc(sizeof(long) * 4);
    *temps = malloc(sizeof(double) * 4);
    *entries = malloc(sizeof(log_entry) * 4);
    *statuses = calloc(MAX_STATUS_LENGTH, sizeof(char));

    for (size_t i = 0; i < 4; ++i) {
        (*timestamps)[i] = time(NULL);
        compress((*statuses) + i * MAX_STATUS_LENGTH, MAX_STATUS_LENGTH);
        (*entries + i)->timestamp = (*timestamps)[i];
        (*entries + i)->temperature = (rand() % 100) + 25; // temperature within range [25, 125]
        if ((*entries + i)->temperature < 25 || (*entries + i)->temperature > 125) {
            fprintf(stderr, "Invalid temperature value: %f\n", (*entries + i)->temperature);
            exit(EXIT_FAILURE);
        }
        strncpy((*statuses) + i * MAX_STATUS_LENGTH, (*entries + i)->status_message, sizeof((*entries + i)->status_message));
        if (strlen((*statuses) + i * MAX_STATUS_LENGTH) > MAX_STATUS_LENGTH) {
            fprintf(stderr, "Status message exceeded the maximum length.\n");
            exit(EXIT_FAILURE);
        }
    }

    return *entries;
}

void free_data(size_t n, double *temps, log_entry *entries, char *statuses) {
    free(temps);
    free(entries);
    free(statuses);
}
