typedef struct {
    int sensor_id;
    double temperature;
    char status_message[256];
} sensor_data;

int is_valid_sensor_id(const int id, int* used_ids, size_t num_used_ids) {
    for (size_t i = 0; i < num_used_ids; ++i) {
        if (id == used_ids[i]) return false;
    }
    return true;
}

bool is_valid_temp(double temp) {
    // Implement your own temperature validation logic here
    return temp >= -273.15 && temp <= 1000.0;
}

void encode_status_message(char* message, size_t len) {
    // Implement a lossless compression algorithm for the status messages here
    // (e.g., run-length encoding, Huffman coding, etc.)
    z_stream strm;
    char outbuf[len];
    int outbuflen = len;
    int ret;

    memset(&strm, 0, sizeof(z_stream));
    strm.next_in = message;
    strm.avail_in = len;
    strm.next_out = outbuf;
    strm.avail_out = outbuflen;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    inflateInit(&strm);
    ret = inflate(&strm, Z_SYNC_FLUSH);
    inflateEnd(&strm);

    if (ret != Z_STREAM_END) {
        fprintf(stderr, "Compression error\n");
        exit(EXIT_FAILURE);
    }

    message = outbuf;
    len = strm.total_out;
}

sensor_data* allocate_and_initialize_sensors(size_t num_sensors, int sensor_id_limit, size_t total_memory_limit) {
    size_t id_array_size = num_sensors;
    size_t status_message_encoded_len_sum = 0;
    size_t temperature_array_size = num_sensors * sizeof(double);

    if (total_memory_limit < id_array_size + temperature_array_size) {
        fprintf(stderr, "Not enough memory\n");
        return NULL;
    }

    int* ids = malloc(id_array_size * sizeof(int));
    double* temps = malloc(temperature_array_size);
    char* status_messages = malloc(status_message_encoded_len_sum);

    size_t num_used_ids = 0;

    for (size_t i = 0; i < num_sensors; ++i) {
        int id = -1;
        double temp = NAN;
        char status_message[256];

        while (true) {
            if (!num_used_ids || !is_valid_sensor_id(id, ids, num_used_ids)) {
                id = i + 1;
                break;
            }
            ++id;
        }

        ids[num_used_ids] = id;
        num_used_ids++;

        scanf("%lf", &temp);

        if (!is_valid_temp(temp)) {
            fprintf(stderr, "Invalid temperature\n");
            free(ids);
            free(temps);
            free(status_messages);
            return NULL;
        }

        temps[i] = temp;
        scanf("%s", status_message);
        encode_status_message(status_message, sizeof(status_message));

        if (status_message + len > status_messages + status_message_encoded_len_sum) {
            status_messages = realloc(status_messages, status_message_encoded_len_sum + len);
            status_message_encoded_len_sum += len;
        }
        memcpy(status_messages + status_message_encoded_len_sum - len, status_message, len);
    }

    sensor_data* sensors = malloc(num_sensors * sizeof(sensor_data));

    for (size_t i = 0; i < num_sensors; ++i) {
        sensors[i].sensor_id = ids[i];
        sensors[i].temperature = temps[i];
        memcpy(sensors[i].status_message, status_messages + i * len, len);
    }

    free(ids);
    free(temps);
    free(status_messages);

    return sensors;
}
