#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <zlib.h>

typedef struct file_metadata {
    char *file_name;
    unsigned long long file_size;
    time_t access_time;
} file_metadata;

int validate(const file_metadata **files, int capacity, int size, unsigned long long threshold) {
    if (capacity < size) return 0;

    for (int i = 1; i < size; ++i) {
        for (int j = 0; j < i; ++j) {
            if (!strcmp((*files)[i].file_name, (*files)[j].file_name)) return 0;
        }

        if ((*files)[i].file_size > threshold) return 0;
    }

    return 1;
}

unsigned long long encode_access_time(const time_t access_time) {
    uLongF file, compressed_file;
    char *buffer = malloc((MAX_WBITS + 8) * 2);
    ByteF out[MAX_WBITS];

    if (!buffer || !out) exit(1);

    file = (uLongF)(access_time & ((1UL << MAX_WBITS) - 1));
    compressed_file = compressBound(file + 1);

    compress((ByteF *)&buffer, (uLong *)0, &file, 1, (z_stream *)NULL, Z_DEFAULT_COMPRESSION);

    unsigned long long result = file + compressed_file;
    free(buffer);
    return result;
}

void decode_access_time(const unsigned long long data, time_t *time) {
    uLongF file, compressed_file;
    ByteF buffer[MAX_WBITS];
    uLong len = (uLong)((data - file) & ((1UL << MAX_WBITS) - 1));
    int total = decompress((ByteF)&buffer, len, NULL, 0, (z_stream *)NULL, Z_DEFAULT_COMPRESSION);

    if (total != len + sizeof(file)) exit(1);

    file = *(uLongF *)&buffer;
    *time = file & ((1UL << MAX_WBITS) - 1);
    *time += (file >> MAX_WBITS) * CLOCKS_PER_SEC;
}

file_metadata* create_list(int *size, unsigned long long threshold, unsigned long long memory_limit) {
    const int initial_capacity = 8;
    file_metadata **files = malloc(initial_capacity * sizeof(file_metadata *));
    if (!files) exit(1);

    for (int i = 0; i < initial_capacity; ++i) {
        files[i] = malloc(sizeof(file_metadata));
        if (!files[i]) {
            free(files);
            exit(1);
        }
        memset(files[i], 0, sizeof(file_metadata));
    }

    int capacity = initial_capacity;
    int used = 0;

    file_metadata *new_files;
    while (used < *size) {
        if (!validate(files, capacity, used + 1, threshold)) {
            capacity *= 2;
            new_files = realloc(files, capacity * sizeof(file_metadata *));
            if (!new_files) exit(1);
            files = new_files;
        } else {
            files[used] = malloc(sizeof(file_metadata));
            if (!files[used]) {
                free(files);
                exit(1);
            }
            memset(files[used], 0, sizeof(file_metadata));
            used++;
        }

        char input_file_name[256];
        unsigned long long input_file_size;
        time_t input_access_time;

        printf("Enter file name: ");
        scanf("%s", input_file_name);
        if (strlen(input_file_name) >= 256) exit(1);

        printf("Enter file size: ");
        scanf("%llu", &input_file_size);
        if (input_file_size > threshold || input_file_size + files[used - 1]->file_size > memory_limit) exit(1);

        printf("Enter access time: ");
        time(&input_access_time);
        files[used - 1]->access_time = encode_access_time(input_access_time);

        strcpy(files[used - 1]->file_name, input_file_name);
        files[used - 1]->file_size = input_file_size;

        used++;
    }

    return files;
}

