struct memory_pool {
    void *pool[1000000];
    size_t used, capacity, allocations;
    pthread_mutex_t lock;
};

status_t init_memory_pool(struct memory_pool *mp, size_t capacity) {
    memset(mp, 0, sizeof(*mp));
    mp->capacity = capacity;
    pthread_mutex_init(&mp->lock, NULL);
    return SUCCESS;
}

void* get_from_memory_pool(struct memory_pool *mp) {
    pthread_mutex_lock(&mp->lock);
    void *ptr;
    if (mp->allocations < mp->capacity) {
        ptr = mp->pool[mp->allocations++];
    } else {
        ptr = realloc(mp->pool, sizeof(*mp->pool) * (2*mp->capacity));
        if (!ptr) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        memmove(mp->pool + mp->capacity, mp->pool, sizeof(*mp->pool)*mp->allocations);
        ptr = mp->pool + mp->capacity++;
    }
    mp->pool[mp->allocations-1] = ptr;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void free_to_memory_pool(struct memory_pool *mp, void *ptr) {
    pthread_mutex_lock(&mp->lock);
    if (ptr && mp->allocations > 0) {
        memcpy(mp->pool++, ptr, sizeof(*ptr));
        mp->allocations--;
    }
    pthread_mutex_unlock(&mp->lock);
}

