void compress(char *data, size_t *orig_len, size_t *comp_len) {
    char *buffer = NULL;
    size_t result;
    gzWriter gzw = gzopen((char *)data, "wb9");
    if (!gzw) return;
    gzwrite(gzw, data, *orig_len);
    gzclose(gzw);

    buffer = malloc(*orig_len + 10); // for extra bytes in case of compression
    result = gzdecompress((Bytef*)data, *orig_len, (Bytef*)buffer, *orig_len + 10);
    if (result == Z_STREAM_ERROR) {
        free(buffer);
        return;
    }
    *comp_len = result;
    buffer[*comp_len] = '\0';
}

