LogEntry* create_log_entry(time_t timestamp, const char* message) {
    LogEntry* entry = malloc(sizeof(LogEntry));
    if (!entry) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    entry->timestamp = timestamp;
    entry->message = strdup(message);
    if (!entry->message) {
        free(entry);
        perror("strdup");
        exit(EXIT_FAILURE);
    }
    entry->prev = NULL;
    entry->next = NULL;
    return entry;
}

LogEntry* add_log_entry(LogEntry** head, LogEntry* new_entry) {
    if (!new_entry || !head) {
        return *head;
    }

    // Append the new log entry to the end of the list.
    if (*head) {
        (*head)->next = new_entry;
        new_entry->prev = *head;
        *head = new_entry;
    } else {
        *head = new_entry;
    }
    return *head;
}

LogEntry* remove_log_entry(LogEntry** head, LogEntry* entry) {
    if (!entry || !head || !(*head)) {
        return NULL;
    }

    // Remove the given log entry from the list.
    if (entry == *head) {
        *head = entry->next;
        if (*head) {
            (*head)->prev = NULL;
        }
        entry->next = NULL;
        entry->prev = NULL;
    } else if (entry->prev) {
        entry->prev->next = entry->next;
        if (entry->next) {
            entry->next->prev = entry->prev;
        }
        entry->next = NULL;
        entry->prev = NULL;
    }
    return entry;
}

LogEntry* find_log_entry(LogEntry** head, time_t timestamp) {
    LogEntry* current = *head;
    while (current) {
        if (current->timestamp == timestamp) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void traverse_log_entries(LogEntry** head, void(*visit)(const LogEntry*)) {
    if (!head || !(*head)) {
        return;
    }

    // Traverse the log entries in both directions.
    LogEntry *current = *head;
    while (current) {
        visit(current);
        current = current->next;
        if (current == *head) {
            break;
        }
    }

    current = *head;
    while (current->next) {
        current = current->next;
        visit(current);
    }
}

