typedef struct Record {
    int id;
    int value;
} Record;

size_t gen_records(size_t max, size_t range, char *buf, size_t *len, Record ***records, bool priority_memory) {
    if (strlen(buf) >= *len) {
        // Free all previously allocated memory
        for (int i = 0; i < *max; ++i) {
            free((*records)[i]);
        }
        free(*records);

        fprintf(stderr, "String buffer exceeded size limit.\n");
        return 0;
    }

    if (!priority_memory) {
        // Allocate and initialize record structures
        *records = malloc(max * sizeof((*records)[0]));
        for (size_t i = 0; i < max; ++i) {
            (*records)[i] = malloc(sizeof(Record));
            memset((*records)[i], 0, sizeof(Record));
            (*records)[i]->id = i;
            (*records)[i]->value = rand() % range;
        }
    } else {
        // Reuse existing memory blocks where possible
        size_t used_memory = 0;
        for (size_t i = 0; i < max && used_memory < max; ++i) {
            if (!(*records)[i]) {
                (*records)[i] = malloc(sizeof(Record));
                memset((*records)[i], 0, sizeof(Record));
                (*records)[i]->id = i;
                (*records)[i]->value = rand() % range;
                used_memory++;
            }
        }
    }

    // Generate and append the string to the buffer
    char *buf_ptr = buf;
    for (size_t i = 0; i < max; ++i) {
        snprintf(buf_ptr, *len - (buf_ptr - buf), "%d: %d\n", (*records)[i]->id, (*records)[i]->value);
        buf_ptr += strlen(buf_ptr);
    }
    *len = buf_ptr - buf;

    return 1;
}
