struct MemoryPool {
    void *allocations[10000]; // configurable max number of allocations
    size_t count;
    size_t next_index;
};

void *memory_pool_alloc(struct MemoryPool *pool, size_t size) {
    if (pool->next_index < pool->count)
        return pool->allocations[pool->next_index++];

    void *new_allocation = malloc(size);
    if (!new_allocation) {
        // Handle failed allocation and provide retry mechanism here
    }
    pool->allocations[pool->next_index++] = new_allocation;
    return new_allocation;
}

void *aligned_malloc(size_t size, size_t alignment) {
    void *ptr = malloc((size + alignment - 1) & ~(alignment - 1));
    if (!ptr) return NULL;
    return (char *) ptr + (size_t)((char *) ptr % alignment);
}

void initialize_data_structures(void **timestamps, void **measurements, void **statuses, void **datapoints, void **summaries, size_t num_elements) {
