#include <string.h>
#include <time.h>
#include <sys/mman.h>
#include <pthread.h>

typedef struct Transaction {
    float amount;
    char* description;
};

// Custom allocator function
void* custom_malloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Custom free function
void custom_free(void* ptr, size_t size) {
    munmap(ptr, size);
}

// Function to dynamically allocate memory for the given arrays and structures
void dynamic_allocation(size_t chunk_size, size_t total_limit) {
    void** doubles = custom_malloc(chunk_size * sizeof(double));
    void** strings = custom_malloc(chunk_size * sizeof(char*));
    void** transactions = custom_malloc(chunk_size * sizeof(struct Transaction));

    size_t total_allocated = 0;
    size_t num_chunks = 0;

    for (size_t i = 0; total_allocated < total_limit; i++) {
        num_chunks++;
        total_allocated += chunk_size * sizeof(double) * sizeof(char*) * sizeof(struct Transaction);
        printf("Allocation chunk %zu of size %zu bytes\n", num_chunks, total_allocated);

        // Initialize doubles, strings and transactions within the allocated chunks
        for (size_t j = 0; j < chunk_size; j++) {
            double* d = doubles[j] = (double*)(doubles + i * chunk_size + j);
            char** s = strings[j] = (char*)(strings + i * chunk_size + j);
            struct Transaction* t = transactions[j] = (struct Transaction*)(transactions + i * chunk_size + j);

            // Initialize doubles, strings and transactions with random data
            *d = ((double)rand() / RAND_MAX) * 100.0;
            *s = malloc((rand() % 50 + 10) * sizeof(char));
            for (size_t k = 0; k < (*s - 10); k++) {
                (*s)[k] = (char)(rand() % 26 + 'a');
            }
            (*s)[*s - 1] = '\0';
            t->amount = ((float)rand() / RAND_MAX) * 100.0;
            t->description = malloc(sizeof(char) * (strlen(*s) + 2)); // Plus space for the terminator and random suffix
            strcpy(t->description, *s);
            sprintf(t->description + strlen(*s), "%u", rand());
        }
    }

    printf("Total memory usage: %zu bytes\n", total_allocated);
}

// Main function to demonstrate the dynamic allocation function
int main() {
    srand(time(NULL));
    size_t chunk_size = 10; // Number of elements per chunk
    size_t total_limit = 1000 * 1024 * 1024; // Total limit for memory allocation (1GB)
    dynamic_allocation(chunk_size, total_limit);

    return 0;
}
