        record->value = rand() % 101;
        record->offset = (*offsets + i);
        record->key = (*keys + i);
    }

    // Sort records array based on the random value in descending order
    qsort(*records, array_size, sizeof(Record), (int (*)(const void *, const void *))compare_records);
}

int compare_records(const void *a, const void *b) {
    return ((Record *) a)->value > ((Record *) b)->value ? 1 : -1;
}

