void increase_reference(metadata **metadata) {
    if (*metadata != NULL)
        (*metadata)->ref_count++;
}

void decrease_reference(metadata **metadata) {
    if ((*metadata != NULL) && ((*metadata)->ref_count > 0))
        (*metadata)->ref_count--;
    if ((*metadata != NULL) && ((*metadata)->ref_count == 0)) {
        free((*metadata)->record);
        free(*metadata);
