        exit(EXIT_FAILURE);
    }

    srand(123456789); // Use provided seed
    for (int i = 0; i < size; ++i) {
        int key = 1 + rand() % 50;
        bool duplicate = false;
        for (int j = 0; j < i; ++j) {
            if (keys[j] == key) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            keys[i] = key;
        } else {
            --i;
        }
    }
    return keys;
}

