    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % 101;
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    qsort(records, size, sizeof(record), (int (*)(const void *, const void *))compare_records);

    return records;
}

metadata *init_metadata(int size, record *records) {
    metadata *metadata = malloc(size * sizeof(metadata));
    if (metadata == NULL) {
        fprintf(stderr, "Failed to allocate memory for metadata.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        metadata[i].ref_count = 1;
        metadata[i].record = &records[i];
    }

    return metadata;
}

int compare_records(const void *a, const void *b) {
    record *ra = (record *)a;
    record *rb = (record *)b;
    int sum_ac = ra->value + (*ra->key);
    int sum_bc = rb->value + (*rb->key);
    if (ra->value != rb->value) {
        return (rb->value - ra->value) > 0 ? -1 : 1;
    } else {
        return sum_ac - sum_bc;
    }
}
