void increase_ref_count(metadata **metadata, size_t index) {
    pthread_mutex_lock(&metadata_mutex);
    if (metadata && index < size(*metadata)) {
        (*metadata)[index].ref_count++;
    }
    pthread_mutex_unlock(&metadata_mutex);
}

void decrease_ref_count(metadata **metadata, size_t index) {
    pthread_mutex_lock(&metadata_mutex);
    if (metadata && index < size(*metadata)) {
        if ((*metadata)[index].ref_count > 0) {
            (*metadata)[index].ref_count--;
            if ((*metadata)[index].ref_count == 0) {
                free((*metadata)[index].record);
                *metadata = realloc(*metadata, sizeof(record) * (size(*metadata) - 1));
            }
        }
    }
    pthread_mutex_unlock(&metadata_mutex);
}

void add_dependency(dependency *dependencies, size_t index, metadata **metadata) {
    pthread_mutex_lock(&dependency_mutex);
    if (index < dependencies->count && dependencies->dependencies[index]) {
        metadata_ref(dependencies->dependencies[index]);
    }

    dependencies->dependencies[index] = *metadata;
    increase_ref_count(&(dependencies->dependencies), index);

    pthread_mutex_unlock(&dependency_mutex);
}

void remove_dependency(dependency *dependencies, size_t index) {
    pthread_mutex_lock(&dependency_mutex);
    if (index < dependencies->count && dependencies->dependencies[index]) {
        decrease_ref_count(&(dependencies->dependencies[index]), 0);
        dependencies->dependencies[index] = NULL;
    }

    pthread_mutex_unlock(&dependency_mutex);
}

