// Adjustable random range function
void set_random_range(int* min, int* max) {
    if (*min > *max || *min < -1000 || *max > 1000) {
        printf("Error: Invalid range. Min value must be >= -1000 and Max value must be <= 1000.\n");
        exit(1);
    }
}

// Allocate memory for offset array, initialize with random values, and perform error checking
long* allocate_offsets(size_t size) {
    long *offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets.\n");
        exit(1);
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        set_random_range(&(-1000), &1000);
        offsets[i] = rand() % (*max - *min + 1) + *min;
    }
    return offsets;
}

// Allocate memory for key array, initialize with unique keys, and perform error checking
int* allocate_keys(size_t size) {
    int *keys = malloc(sizeof(int) * size);
    if (!keys) {
        printf("Error: Failed to allocate memory for keys.\n");
        exit(1);
    }

    for (size_t i = 0; i < size; ++i) {
        int key = rand() % 50 + 1;
        // Check for duplicates and adjust key if necessary
        for (size_t j = 0; j < i; ++j) {
            if (keys[j] == key) {
                set_random_range(&(key - 1), &(key + 1));
                key = rand() % (*max - *min + 1) + *min;
                break;
            }
        }
        keys[i] = key;
    }
    return keys;
}

// Allocate memory for record array, sort, and perform error checking
record* allocate_records(size_t size, long* offsets, int* keys) {
    record *records = malloc(sizeof(record) * size);
    if (!records) {
        printf("Error: Failed to allocate memory for records.\n");
        exit(1);
    }

    // Initialize records with random values and references to offsets and keys
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % 101;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].timestamp = time(NULL);
    }

    // Sort records based on descending random values and sum of metadata reference count and key
    qsort(records, size, sizeof(record), sort_records);

    return records;
}

// Allocate memory for metadata array, manage reference counting, and perform error checking
metadata* allocate_metadata(size_t size, record* records) {
    metadata *metadata = malloc(sizeof(metadata) * size);
    if (!metadata) {
        printf("Error: Failed to allocate memory for metadata.\n");
        exit(1);
    }

    // Initialize metadata with reference count and pointers to records
    for (size_t i = 0; i < size; ++i) {
        metadata[i].ref_count = 1;
        metadata[i].record = &records[i];
    }

    return metadata;
}

// Sort function for qsort comparator, handles large datasets efficiently
int sort_records(const void* a, const void* b) {
    record *ra = (record*)a;
    record *rb = (record*)b;
    int compare = ra->value > rb->value ? 1 : -1;
    if (compare == 0) {
        compare = ra->offset + ra->key > rb->offset + rb->key ? 1 : -1;
    }
    return compare;
}
