#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <unistd.h> // for usleep

typedef struct {
    int key;
    char *data;
} Record;

typedef struct {
    Record *records;
    bool *flags;
} Metadata;

long *offsets;
int *keys;
int num_records = 0;
Metadata *metadata;

void readCSV(const char *filename, void **data) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(1);
    }

    size_t capacity = 0;
    size_t count = 0;
    char **lines = NULL;
    char line[4096];

    while (fgets(line, sizeof(line), file)) {
        if (capacity < ++count) {
            capacity *= 2;
            lines = realloc(lines, count * sizeof(char*));
        }
        lines[count - 1] = strdup(line);
    }
    fclose(file);

    for (size_t i = 0; i < count; ++i) {
        (*data)[i] = malloc(strlen(lines[i]) + 1);
        strcpy((*data)[i], lines[i]);
    }

    free(lines);
}

void parseKeysAndMetadata(const char *filename, Metadata **metadata_ptr) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(1);
    }

    size_t capacity = 0;
    size_t count = 0;
    Metadata **metadata = malloc(sizeof(Metadata));
    metadata[0] = calloc(1, sizeof(Record) + sizeof(bool));

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        if (capacity < ++count) {
            capacity *= 2;
            metadata = realloc(metadata, count * sizeof(Metadata));
        }
        metadata[count - 1] = calloc(1, sizeof(Record) + sizeof(bool));

        sscanf(line, "%d%*c", &((metadata[count-1]->records[0].key)));
        metadata[count - 1]->flags[0] = true;
    }
    fclose(file);

    *metadata_ptr = realloc(*metadata_ptr, count * sizeof(Metadata));
    memcpy(*metadata_ptr, metadata, count * sizeof(Metadata));
}

void initDataStructures(int num_keys) {
    keys = malloc(num_keys * sizeof(int));
    offsets = calloc(num_keys + 1, sizeof(long));
    metadata = malloc(num_keys * sizeof(Metadata));

    for (size_t i = 0; i < num_keys; ++i) {
        metadata[i] = calloc(1, sizeof(Record) + sizeof(bool));
    }
}

void populateDataStructures() {
    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        size_t key_index = offsets[keys[i]] - 1;
        metadata[key_index]->flags[metadata[key_index]->records[0].key] = true;
        metadata[key_index]->records[0].key = keys[i];
        metadata[key_index]->records[0].data = malloc(256 * sizeof(char));
        snprintf(metadata[key_index]->records[0].data, 256, "Record %d", i);
        offsets[keys[i] + 1] = offsets[keys[i]] + sizeof(Record) + sizeof(bool);
    }

    for (size_t i = 0; i < num_records; ++i) {
        metadata[key_index]->records[i].int_field = rand() % 100 + 1;
    }
}

void resizeDataStructures(int new_num_keys) {
    Record *new_records = realloc(metadata, new_num_keys * sizeof(Metadata));
    if (!new_records) {
        perror("Error resizing data structures");
        exit(1);
    }
    metadata = new_records;

    for (size_t i = num_keys; i < new_num_keys; ++i) {
        metadata[i] = calloc(1, sizeof(Record) + sizeof(bool));
    }
}

int main() {
    const char *key_filename = "keys.csv";
    const char *metadata_filename = "metadata.csv";
    int num_keys;
    scanf("%d", &num_keys);

    initDataStructures(num_keys);

    readCSV(key_filename, (void *)&keys);
    parseKeysAndMetadata(metadata_filename, (Metadata **)&metadata);

    num_records = keys[num_keys - 1];
    resizeDataStructures(num_keys + num_records);

    populateDataStructures();

    // Use the data structures as needed...

    return 0;
}
