long* read_offsets(const char *filename, size_t *num_offsets) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    long *offsets = malloc((file_size / sizeof(long)) + 1);
    if (!offsets) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        ++count;
    }
    rewind(file);

    for (size_t i = 0; i < count; ++i) {
        if (fscanf(file, "%ld\n", &offsets[i]) != 1) {
            perror("fscanf");
            exit(EXIT_FAILURE);
        }
    }

    *num_offsets = count;
    fclose(file);
    return offsets;
}

int* read_keys(const char *filename, size_t num_keys) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t count = 0;
    char line[256];
    while (count < num_keys && fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%d", &keys[count]) != 1) {
            perror("sscanf");
            exit(EXIT_FAILURE);
        }
        ++count;
    }

    if (count < num_keys) {
        free(keys);
        perror("fgets");
        exit(EXIT_FAILURE);
    }

    fclose(file);
    return keys;
}

