    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_t threads[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        int rc = pthread_create(&threads[i], NULL, [](void *arg) {
            Record *record = static_cast<Record*>(arg);
            record->value = rand() % (max_value - min_value + 1) + min_value;
            return 0;
        }, records + i);

        if (rc) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }
}

