    if (!records) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        records[i].value = 0;
    }

    set_random_values(records, num_offsets, 1, 100);

    free(keys);
    free(offsets);
    free(records);

    return EXIT_SUCCESS;
}
