typedef struct {
    int score;
    long *offset;
    int *key;
} record;

void allocate_and_init(size_t *dataSize, size_t *indexSize) {
    srand(12345); // Set seed for consistent results

    // Allocate memory for offset array and initialize with random values
    long *offsets = malloc(*dataSize * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate offset memory");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < *dataSize; ++i) {
        offsets[i] = rand() % 2001 - 1000; // Ensure values are between -1000 and 1000
    }

    // Allocate memory for key array and ensure unique keys
    int *keys = malloc(*indexSize * sizeof(int));
    if (!keys) {
        perror("Failed to allocate key memory");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < *indexSize; ++i) {
        int key = rand() % 49 + 1; // Ensure values are between 1 and 50, inclusive
        bool duplicate = false;
        for (size_t j = 0; j < i; ++j) {
            if (keys[j] == key) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            keys[i] = key;
        } else {
            --i; // Decrement i and try again with a new key
        }
    }

    // Allocate memory for record array and sort based on relevance score
    record *records = malloc(*dataSize * sizeof(record));
    if (!records) {
        perror("Failed to allocate record memory");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < *dataSize; ++i) {
        records[i].score = rand() % 101; // Ensure values are between 0 and 100, inclusive
        records[i].offset = &offsets[i];
