record* init_index(size_t *offsets, size_t *keys, record **records) {
    srand(12345); // Seed for consistent results

    *offsets = calloc(MAX_RECORDS, sizeof(long));
    if (!*offsets) {
        fprintf(stderr, "Failed to allocate offset array\n");
        return NULL;
    }

    for (size_t i = 0; i < MAX_RECORDS; ++i)
        (*offsets)[i] = rand() % 2001 - 1000; // Initialize offsets with random values

    *keys = malloc((MAX_RECORDS + KEY_RANGE) * sizeof(int));
    if (!*keys) {
        fprintf(stderr, "Failed to allocate key array\n");
        free(*offsets);
        return NULL;
    }

    for (size_t i = 0, k = 1; i < MAX_RECORDS + KEY_RANGE; ++i)
        (*keys)[i] = (k++ <= KEY_RANGE) ? rand() % KEY_RANGE + 1 : (*(--keys)); // Ensure unique keys

    *records = calloc(MAX_RECORDS, sizeof(record));
    if (!*records) {
        fprintf(stderr, "Failed to allocate record array\n");
        free(*offsets);
        free(*keys);
        return NULL;
    }

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        (*records)[i].score = rand() % 101; // Initialize scores with random values between 0 and 100, inclusive
        (*records)[i].offset = (*offsets)[i];
        (*records)[i].key    = (*keys)[i];
    }

    qsort(*records, MAX_RECORDS, sizeof(record), (int (*)(const void*, const void*))compare_scores); // Sort records by relevance score in descending order

    return *records;
}

bool compare_scores(const void *a, const void *b) {
    return ((const record *)a)->score > ((const record *)b)->score;
}
