int generate_unique(int min, int max, size_t count, bool *numbers[]) {
    int *used = calloc(max - min + 1, sizeof(int));
    for (int i = 0; i < count; ++i) {
        int number = min + rand() % (max - min + 1);
        while (used[number - min]) {
            number = min + rand() % (max - min + 1);
        }
        used[number - min] = true;
        numbers[i] = &used[number - min];
    }
    free(used);
    return count;
}

