    for (size_t i = 1; i < size; ++i) {
        if (array[i].score > array[i - 1].score ||
            (array[i].score == array[i - 1].score && array[i].key < array[i - 1].key)) {
            return 0;
        }
    }
    return 1;
}

int compare_records(const void* a, const void* b) {
    record* recordA = (record*)a;
    record* recordB = (record*)b;
    int scoreDiff = recordB->score - recordA->score;
    if (scoreDiff == 0) {
        return recordA->key > recordB->key ? 1 : -1;
    }
    return scoreDiff > 0 ? 1 : -1;
}

void* fetch_keys(int min, int max, int* keys, size_t num_keys) {
    int unique_keys[num_keys];
    for (size_t i = 0; i < num_keys; ++i) {
        int key;
        do {
            key = rand() % (max - min + 1) + min;
        } while (binary_search(unique_keys, unique_keys + i, key));
        unique_keys[i] = key;
    }
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = unique_keys[i];
    }
    return NULL;
}

int binary_search(const int* array, const int* arrayEnd, int key) {
    int left = 0;
    int right = (arrayEnd - array);
    while (left <= right) {
        int mid = (left + right) / 2;
        if (key < array[mid]) {
            right = mid - 1;
        } else if (key > array[mid]) {
            left = mid + 1;
        } else {
            return 1;
        }
    }
    return 0;
}

void check_memory(void* ptr) {
    if (!ptr) {
        fprintf(stderr, "Error allocating memory\n");
        exit(EXIT_FAILURE);
    }
}

