#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct Record {
    int score;
    long *offset;
    int *key;
} Record;

typedef struct Metadata {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    Record *records;
    long *offsets;
    int *keys;
} Metadata;

Metadata *create_metadata(size_t initial_capacity) {
    Metadata *meta = malloc(sizeof(Metadata));
    if (!meta) return NULL;

    meta->capacity = initial_capacity;
    meta->count = 0;
    pthread_mutex_init(&meta->lock, NULL);
    meta->records = calloc(initial_capacity, sizeof(Record));
    if (!meta->records) {
        free(meta);
        return NULL;
    }

    meta->offsets = malloc(initial_capacity * sizeof(long));
    if (!meta->offsets) {
        free(meta->records);
        free(meta);
        return NULL;
    }

    meta->keys = malloc(initial_capacity * sizeof(int));
    if (!meta->keys) {
        free(meta->offsets);
        free(meta->records);
        free(meta);
        return NULL;
    }

    return meta;
}

void destroy_metadata(Metadata **meta) {
    pthread_mutex_destroy(&(*meta)->lock);
    free((*meta)->records);
    free((*meta)->offsets);
    free((*meta)->keys);
    free(*meta);
    *meta = NULL;
}

void adjust_range(Metadata *meta, int min, int max) {
    for (size_t i = 0; i < meta->capacity; ++i) {
        if (meta->offsets[i] < min || meta->offsets[i] > max) {
            meta->offsets[i] = rand() % (max - min + 1) + min;
        }
    }
}

int find_unique_key(Metadata *meta, int key) {
    for (size_t i = 0; i < meta->count; ++i) {
        if (meta->keys[i] == key) return -1;
    }
    return 1;
}

Record *allocate_record(Metadata *meta, int score) {
    Record *record = &meta->records[meta->count];

    record->score = score;
    record->offset = &meta->offsets[meta->count];
    record->key = &meta->keys[meta->count];

    do {
        *record->offset = rand() % 2001 - 1000;
    } while (find_duplicate_offset(*record, meta));

    do {
        *record->key = find_unique_key(meta, *record->key);
    } while (*record->key < 0);

    ++meta->count;
    return record;
}

bool find_duplicate_offset(Record r, Metadata *meta) {
    for (size_t i = 0; i < meta->count; ++i) {
        if (i != meta->count - 1 && r.offset == &meta->offsets[i + 1]) return true;
    }

    for (size_t i = 0; i < meta->count; ++i) {
        if (r.offset == &meta->offsets[i] && r.key != &meta->keys[i]) return true;
    }

    return false;
}
