void log_memory(size_t size) {
    if (peak_memory < size) {
        peak_memory = size;
        fprintf(log_file, "Peak memory consumption: %lld bytes\n", peak_memory);
    }
}

// Generate random string of length between min and max inclusive
char *generate_random_string(int min, int max) {
    char chars[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t len = rand() % (max - min + 1) + min;
    char *str = malloc(len + 1);
    memset(str, '\0', len + 1);
    for (int i = 0; i < len; ++i) {
        str[i] = chars[rand() % (sizeof(chars) - 1)];
    }
    return str;
}

// Check if a pointer is valid, i.e., not NULL and points to allocated memory
int is_valid_ptr(void *ptr) {
    return ptr && ptr != calloc(1, sizeof(char)) && ptr != realloc(NULL, 1);
}

void validate_pointers() {
    printf("Validating pointers:\n");
    if (is_valid_ptr(scores) && is_valid_ptr(names) && is_valid_ptr(items) && is_valid_ptr(details) && is_valid_ptr(reports)) {
        printf("All pointers are valid.\n");
    } else {
        printf("One or more pointers are not valid.\n");
    }
}

void* generate_data(void *arg) {
    pthread_mutex_lock(&mutex);

    float *scores = malloc((MAX_ELEMENTS + 1) * sizeof(float));
    log_memory(sizeof(scores));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        scores[i] = rand() % 101;
    }

    char **names = malloc((MAX_ELEMENTS + 1) * sizeof(char*));
    log_memory(sizeof(names));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        names[i] = generate_random_string(1, 50);
        log_memory(strlen(names[i]) + 1);
    }

    item *items = malloc((MAX_ELEMENTS + 1) * sizeof(item));
    log_memory(sizeof(items));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        items[i].score = &scores[i];
        items[i].name = names[i];
    }

    detail *details = malloc((MAX_ELEMENTS + 1) * sizeof(detail));
    log_memory(sizeof(details));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        details[i].detail_id = rand() % 1001;
        details[i].name = names[rand() % MAX_ELEMENTS];
        details[i].score = &scores[rand() % MAX_ELEMENTS];
    }

    report *reports = malloc((MAX_ELEMENTS + 1) * sizeof(report));
    log_memory(sizeof(reports));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        reports[i].report_weight = rand() % 2 + 0.5;
        reports[i].name = names[rand() % MAX_ELEMENTS];
        reports[i].score = &scores[rand() % MAX_ELEMENTS];
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

void sort(float *arr, size_t n, int order) {
    if (order == -1) {
        qsort(arr, n, sizeof(float), (int (*)(const void *, const void *))comparator_desc);
    } else {
        qsort(arr, n, sizeof(float), (int (*)(const void *, const void *))comparator_asc);
    }
}

int comparator_desc(const void *a, const void *b) {
    return *(const float *)a > *(const float *)b ? -1 : *(const float *)a < *(const float *)b ? 1 : 0;
}

int comparator_asc(const void *a, const void *b) {
    return *(const float *)a < *(const float *)b ? -1 : *(const float *)a > *(const float *)b ? 1 : 0;
}

void main() {
    pthread_t threads[MAX_ELEMENTS];
    log_file = fopen("log.txt", "w+");

    srand(time(NULL));

    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_create(&threads[i], NULL, &generate_data, NULL);
    }

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_join(threads[i], NULL);
    }

    validate_pointers();

    float scores[MAX_ELEMENTS];
    char **names = malloc((MAX_ELEMENTS + 1) * sizeof(char*));
    item items[MAX_ELEMENTS];
    detail details[MAX_ELEMENTS];
    report reports[MAX_ELEMENTS];

    int index = 0;
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        scores[index] = *(items[i].score);
        names[index] = items[i].name;
        details[index].detail_id = details[i].detail_id;
        details[index].name = details[i].name;
        details[index].score = details[i].score;
        reports[index].report_weight = reports[i].report_weight;
        reports[index].name = reports[i].name;
        reports[index].score = reports[i].score;

        index++;
    }

    sort(scores, MAX_ELEMENTS, -1);
    sort(details, MAX_ELEMENTS, -1);
    sort(reports, MAX_ELEMENTS, -1);

    validate_pointers();

    fclose(log_file);
}
