typedef struct {
    const char *filename;
    int width, height;
    enum processing_status { LOADING, LOADED, FAILED, PROCESSING } processing_status;
} image;

struct metadata_cache {
    size_t capacity;
    size_t count;
    image **data;
};

struct MetadataFetcher {
    bool validate;
    void (*fetch)(const char *, struct image *);
};

struct Semaphore {
    sem_t semaphore;
    int max_concurrent;
};

void init_semaphore(struct Semaphore *sem, int max) {
    sem_init(&sem->semaphore, 0, max);
}

int acquire_semaphore(struct Semaphore *sem) {
    return sem_wait(&sem->semaphore);
}

void release_semaphore(struct Semaphore *sem) {
    sem_post(&sem->semaphore);
}

struct image **process_images(const char *dir, size_t max_concurrent, size_t cache_capacity, bool cache_enabled, const struct MetadataFetcher *fetcher) {
    pthread_t threads[max_concurrent];
    struct Semaphore sem;
    init_semaphore(&sem, max_concurrent);
    struct metadata_cache cache;
    if (cache_enabled) {
        cache.capacity = cache_capacity;
        cache.count = 0;
        cache.data = calloc(cache_capacity, sizeof(image*));
    }
    DIR *dirp = opendir(dir);
    if (!dirp) return NULL;
    struct dirent *dp;
    size_t image_count = 0;
    while ((dp = readdir(dirp))) {
        if (strcmp(dp->d_name, ".") == 0 || strcmp(dp->d_name, "..") == 0) continue;
        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/%s", dir, dp->d_name);
        struct stat st;
        if (stat(filepath, &st) != 0 || S_ISDIR(st.st_mode)) continue;
        image images[image_count];
        for (size_t i = 0; i < image_count; ++i) {
            images[i].filename = dp->d_name;
            images[i].width = -1;
            images[i].height = -1;
            images[i].processing_status = LOADING;
        }
        pthread_create(&threads[image_count], NULL, process_images_worker, &images[0]);
        image_count++;
    }
    closedir(dirp);

    for (size_t i = 0; i < image_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    image **result = malloc(image_count * sizeof(image*));
    for (size_t i = 0; i < image_count; ++i) {
        result[i] = &images[i];
    }

    if (cache_enabled) {
        // Implement caching mechanism here.
    }
    return result;
}

void *process_images_worker(void *arg) {
    image *image = arg;
    struct Semaphore *sem = NULL;
    struct MetadataFetcher fetcher = { .validate = fetcher ? fetcher->validate : true };
    if (fetcher.fetch) {
        fetcher.fetch(image->filename, image);
    } else {
        acquire_semaphore(&sem); // Acquire semaphore before calling metadata fetcher to ensure thread safety.
        fetcher.fetch(image->filename, image);
        release_semaphore(&sem);
    }

    // Implement file reading and dimension extraction here.

    image->processing_status = LOADED;
    return NULL;
}
