    const auto keyPowerOfTwo = std::ceil(std::log2(keySize));
    keySize = std::pow(2, keyPowerOfTwo);

    std::vector<long> offsets(offsetSize / 4);
    std::vector<int> keys(keySize);
    std::vector<Record> records;

    // Allocate memory for and initialize an array of record structures.
    records.reserve(recordCount);

