// Function to initialize arrays with valid size constraints and key sorting
void initArrays(std::size_t& lenOffset, std::size_t& lenKey, std::vector<long>& offset, std::vector<int>& key) {
    const int log2Min = 3; // Minimum power of 2 for key array size
    const int alignmentFactor = 4; // Alignment factor for offset array size

    lenOffset = (alignmentFactor * (lenOffset / alignmentFactor));
    lenKey = std::max(1ull << log2Min, lenKey);

    offset.resize(lenOffset);
    key.resize(lenKey);

    // Sort key array in ascending order
    std::sort(key.begin(), key.end());
}

// Function to allocate and initialize an array of record structures
void initRecords(std::size_t len, std::vector<record>& records) {
    records.resize(len);
}

// Custom deleter for memory management
struct Deleter {
    void operator()(record* ptr) noexcept { delete ptr; }
};

// Function to set the value of each record's int field to a random value within a specified range using async operations
void generateRecordsAsync(std::size_t numThreads, std::vector<record>& records, uintmax_t min, uintmax_t max) {
    auto numRecordsPerThread = numThreads > records.size() ? records.size() : numThreads;
    auto rangeSize = records.size() / numThreads;

    std::vector<std::unique_ptr<record[], Deleter>> threadsData(numThreads);

    for (int i = 0; i < numThreads; ++i) {
        auto startIndex = i * rangeSize;
        auto endIndex = (i == numThreads - 1) ? records.size() : startIndex + rangeSize;

        threadsData[i] = std::make_unique<record[]>(endIndex - startIndex);

        std::thread{ [this, startIndex, endIndex, min, max](auto data) {
            for (auto j = startIndex; j < endIndex; ++j) {
                data[j].val = randInt(min, max);
            }
        }, threadsData[i].get()}.detach();
    }
}

// Main function integrating the above elements and handling error cases
void mainFunction(std::size_t lenOffset, std::size_t lenKey, std::vector<long>& offset, std::vector<int>& key, std::vector<record>& records) {
    assert(lenKey > 0 && (lenKey & (lenKey - 1)) == 0); // Validate power of 2 for key array size
    assert(lenOffset % 4 == 0); // Validate offset array alignment

    initArrays(lenOffset, lenKey, offset, key);
    initRecords(lenKey, records);

    generateRecordsAsync(std::thread::hardware_concurrency(), records, 0, UINTMAX_MAX);
}
