#include <memory>
#include <boost/serialization/access.hpp>
#include <boost/archive/text_oarchive.hpp>
#include <boost/archive/text_iarchive.hpp>
#include <boost/asio/io_service.hpp>
#include <boost/asio/strand.hpp>

namespace my_cache {

struct record {
    int value;
    long offset;
    static_assert(std::alignment_of<record>::value == sizeof(long), "Record alignment error");
};

struct cache_entry {
    std::string key;
    std::unique_ptr<uint8_t[]> data;
    uint64_t ttl;
    time_point last_accessed;
};

class custom_allocator {
public:
    custom_allocator(size_t bytes, size_t alignment) : block_(::operator new(bytes + alignment - 1), std::align_val_t(alignment)) {}

    void* allocate(size_t n, size_t alignment) {
        auto p = static_cast<char*>(block_) + sizeof(custom_allocator) + (static_cast<std::ptrdiff_t>(block_) % alignment);
        auto result = ::operator new(n * alignment, std::align_val_t(alignment), p);
        return result;
    }

    void deallocate(void* p, size_t n) {
        ::operator delete(p);
    }

private:
    char* block_;
};

class cache {
public:
    explicit cache(size_t cache_size) : cache_size_(cache_size), io_service_(), strand_(io_service_), data_(custom_allocator(10 * 1024 * 1024, sizeof(record))) {
        key_map_.reserve(cache_size);
    }

    void set_value(const std::string& key, int value) {
        auto it = key_map_.find(key);
        if (it != key_map_.end()) {
            auto record = it->second;
            record.value = value;
            update_record(record);
            return;
        }

        if (cache_size_ == key_map_.size()) {
            evict_least_recently_used();
        }

        auto new_record = data_.emplace(key.size() + sizeof(cache_entry), custom_allocator(sizeof(record)));
        new (new (data_.get())) record {value, -1};
        key_map_[key] = reinterpret_cast<record*>(new (data_.get()) *new_record);
    }

    int get_value(const std::string& key) const {
        auto it = key_map_.find(key);
        if (it != key_map_.end()) {
            const auto* record = it->second;
            return record->value;
        }
        return -1;
    }

    void randomize() {
        std::random_device rd;
        std::uniform_int_distribution<> dist(0, 100);

        for (auto& [key, record] : key_map_) {
            record->value = dist(rd);
            update_record(*record);
        }
    }

private:
    void update_record(record& record) {
        const auto index = static_cast<size_t>(record.offset / sizeof(record));
        if (index < keys_.size() && keys_[index] == record.key) {
            return;
        }

        if (!keys_.empty()) {
            keys_.back() = record.key;
            offsets_[keys_.size() - 1] = record.offset;
        } else {
            data_.resize(data_.size() * 2);
        }

        keys_.push_front(record.key);
        offsets_.insert(offsets_.end(), record.offset);
    }

    void evict_least_recently_used() {
        auto it = std::max_element(accessors_.rbegin(), accessors_.rend(), [](const auto& lhs, const auto& rhs) { return lhs->second > rhs->second; });
        if (it != accessors_.rend()) {
            const auto [key, entry] = *it;
            key_map_.erase(key);
            data_.deallocate(entry.data().get(), sizeof(cache_entry) + entry.data()->size());
            accessors_.erase(*it);
        }
    }

    boost::asio::io_service& get_io_service() { return io_service_; }

    struct accessor {
        const std::string key;
        const cache_entry data;
        time_point last_accessed;

        friend class boost::serialization::access;

        template<class Archive> void serialize(Archive& ar, const unsigned int version) {
            ar & key & data & last_accessed;
        }
    };

    size_t cache_size_;
    std::vector<std::string> keys_;
    std::vector<long> offsets_;
    std::map<std::string, record*> key_map_;
    std::vector<accessor> accessors_;
    std::unique_ptr<record[], custom_allocator> data_;
    boost::asio::io_service io_service_;
    boost::asio::strand<boost::asio::io_service::executor_type> strand_;
};

class cache_listener {
public:
    virtual void on_cache_full() = 0;
    virtual void on_eviction(const std::string& key) = 0;
};

} // namespace my_cache
