    Record* records;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    time_t expiration_timestamp; // Timestamp for sliding window mechanism
} DataSet;

DataSet* createDataSet() {
    DataSet* set = malloc(sizeof(DataSet));
    if (!set) return NULL;
    set->records = calloc(1, sizeof(Record));
    if (!set->records) goto fail;
    set->size = 0;
    set->capacity = 1;
    set->mutex = PTHREAD_MUTEX_INITIALIZER;
    set->expiration_timestamp = time(NULL) - EXPIRATION_DURATION;
    return set;
fail:
