class MemoryManager {
public:
    MemoryManager(size_t maxSize, int expiryDuration)
        : _maxSize(maxSize), _expiryDuration(expiryDuration), _data(), _mutex() {}

    Record* createRecord() {
        std::uniform_int_distribution<> keyDist(1, 50);
        int key = keyDist(rng);
        bool uniqueKey = true;

        while (uniqueKey) {
            uniqueKey = std::find(_data.begin(), _data.end(), Record{key, 0, 0, ""}) == _data.end();
            if (!uniqueKey)
                key = keyDist(rng);
        }

        // Asynchronous request to external data source
        std::promise<int> keyProm;
        auto keyFuture = keyProm.get_future();
        std::thread worker([&key, &keyProm]() {
            // Implement your asynchronous request logic here
            keyProm.set_value(key);
        });
        worker.detach();

        Record newRecord{key, 0, -1, ""};
        newRecord.strBuf = generateString();

        _data.push_back(newRecord);
        while (_data.size() > _maxSize && _expiryDuration) {
            auto it = _data.begin();
            std::advance(it, expiryDuration);
            Record& recordToExpire = *it;

            if (recordToExpire.key <= 0 || recordToExpire.relevanceScore < 0) {
                _data.erase(it);
                continue;
            }

            _mutex.lock();
            _data.erase(it);
            _mutex.unlock();
        }

        return &_data.back();
    }

    void updateRecord(Record* record, int relevanceScore) {
        record->relevanceScore = relevanceScore;
    }

private:
    std::vector<Record> _data;
    std::mutex _mutex;
    std::mt19937 rng{std::random_device{}()};
    size_t _maxSize;
    int _expiryDuration;

    std::string generateString() {
        static constexpr char alphabet[] = "abcdefghijklmnopqrstuvwxyz0123456789";
        std::uniform_int_distribution<> distribution(0, sizeof(alphabet) - 1);
        std::string result(16, ' ');
        for (auto& c : result) {
            c = alphabet[distribution(rng)];
        }
        return result;
    }
};

