int unique_key(int keys[], int len, int k) {
    for (int i = 0; i < len; ++i)
        if (keys[i] == k) return false;
    return true;
}

void shuffle(int *arr, size_t n) {
    for (size_t i = n - 1; i > 1; --i) {
        size_t j = rand() % i;
        if (j) swap(&arr[j], &arr[i]);
    }
}

record* init_data(size_t capacity, unsigned int seed) {
    srand(seed);

    long *offsets = malloc(capacity * sizeof(long));
    if (!offsets) die("Memory allocation failed for offsets array");
    memset(offsets, -1, capacity * sizeof(long));

    int *keys = malloc(50 * sizeof(int));
    if (!keys) die("Memory allocation failed for keys array");

    record *data = malloc(capacity * sizeof(record));
    if (!data) die("Memory allocation failed for data array");

    size_t key_count = 0;
    for (size_t i = 0; i < capacity; ++i) {
        long offset = offsets[i];
        int key = -1;
        while (!unique_key(keys, key_count, key)) {
            key = rand() % 50 + 1;
        }
        keys[key_count++] = key;
        offsets[i] = (long)i;

        data[i].score = rand() % 101;
        data[i].offset = &offsets[i];
        data[i].key = &keys[key_count - 1];
    }

    shuffle(data, capacity);
    qsort(data, capacity, sizeof(record), (int (*)(const void*, const void*))compare_scores);

    return data;
}

bool compare_scores(const void *a, const void *b) {
    record *r1 = a, *r2 = b;
    return r1->score > r2->score;
}
