void memory_pool(size_t size, void **pool, size_t *used, size_t *free) {
    *pool = malloc(size);
    if (*pool == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    *used = 0;
    *free = size;
}

void *get_from_pool(void **pool, size_t *used, size_t *free) {
    if (*free == 0) return NULL;
    void *ptr = (*pool) + *used;
    ++(*used);
    --(*free);
    return ptr;
}

void free_to_pool(void **pool, size_t *used, size_t *free, void *ptr) {
    (*used)--;
    (*free)++;
    memset(ptr, 0, sizeof(record));
    ptr = NULL;
}

