    }

    // Initialize records with random scores and offsets/keys based on provided seed
    for (int i = 0; i < maxRecords; ++i) {
        records[i].score = rand() % 101;
        records[i].offset = offsets[rand() % totalChunks + 1];
        records[i].key = keys[rand() % keyCount];
    }

    // Sort the records array based on relevance score in descending order
    qsort(records, maxRecords, sizeof(record), (int (*)(const void *, const void *))(compare_relevance));

    // Memory pool for compression
    char *compressionPool;
    size_t compressionPoolSize = 1024 * 1024; // 1MB
    compressionPool = mmap(NULL, compressionPoolSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (compressionPool == MAP_FAILED) {
        fprintf(stderr, "Error initializing memory pool for compression.\n");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[totalChunks];
