        threadData[i].totalChunks = totalChunks;
        threadData[i].streamDelay = streamDelay;
        threadData[i].useCompression = useCompression;
        threadData[i].outputStream = outputStream;
        threadData[i].maxDataValue = maxDataValue;
        threadData[i].maxRecords = maxRecords;
        threadData[i].offsets = offsets;
        threadData[i].keys = keys;
        threadData[i].records = records;
        pthread_create(&threads[i], NULL, processChunk, &threadData[i]);

        // Wait for some time as specified by streamDelay
        usleep(*streamDelay * 1000);
    }

    // Join all the threads and handle any errors
    for (int i = 0; i < totalChunks; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(offsets);
    free(keys);
    free(records);
    munmap(compressionPool, compressionPoolSize);
}

int compare_relevance(const void *a, const void *b) {
    return ((record *) a)->score > ((record *) b)->score ? 1 : -1;
}

void *processChunk(void *data) {
    // Cast data to the threadData type and extract the parameters
    threadData_t *threadData = (threadData_t *) data;

    // Allocate memory for the current chunk's records array
    record *chunkRecords = malloc(threadData->chunkSize * sizeof(record));

    // Initialize a subset of the overall records array as the current chunk's records
    int offset = 0;
    for (int i = 0; i < threadData->chunkSize; ++i) {
        chunkRecords[i] = threadData->records[offset++];
    }

    // Compress and stream the processed data if useCompression is true, otherwise stream as-is
    if (threadData->useCompression) {
        gzFile gzFile = gzopen(*(threadData->outputStream), "wb");
        gzwrite(gzFile, chunkRecords, threadData->chunkSize * sizeof(record));
        gzclose(gzFile);
    } else {
        fwrite(chunkRecords, sizeof(record), threadData->chunkSize, *(threadData->outputStream));
    }

    free(chunkRecords);
}

// Define the threadData_t struct to hold all necessary data for processing a chunk
struct threadData_t {
    int seed;
    int chunkSize;
    int totalChunks;
    int *streamDelay;
    bool useCompression;
    char **outputStream;
    int maxDataValue;
    int maxRecords;
    long *offsets;
    int *keys;
    record *records;
};
