    return (rand_r(&seeded++) % MAX_KEY);
}

// Function to initialize index with a given data size and seed for random number generator
void init_index(size_t data_size, unsigned long seed) {
    static unsigned long myseed = seed;
    srand(myseed++);

    start = clock();

    // Allocate memory for arrays of index offsets and keys
    long *offsets = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    int *keys = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

