    // Initialize index with data size and ensure unique keys
    for (size_t i = 0; i < data_size; ++i) {
        int key = generate_key();
        bool found = false;
        for (size_t j = 0; j < i; ++j) {
            if (keys[j] == key) {
                found = true;
                break;
            }
        }
        if (!found) {
            keys[total_records] = key;
            offsets[total_records] = -1; // Indicate empty record
            total_records++;
        }
    }

    pthread_mutex_unlock(&mutex);

    qsort(keys, total_records, sizeof(int), (int(*)(const void *, const void *))comparator);

    end = clock();
    printf("Initialization time: %.2fs\n", (end - start) / CLOCKS_PER_SEC);
}

// Comparison function for qsort()
int comparator(const void *a, const void *b) {
    return *(const int *)b - *(const int *)a;
}
