    CustomAllocator* resource = malloc(sizeof(CustomAllocator));
    if (!resource) {
        perror("Resource Manager initialization failed");
        return NULL;
    }

    resource->memory = calloc(1, sizeof(CustomAllocator));
    if (!resource->memory) {
        perror("Resource Manager memory allocation failed");
        free(resource);
        return NULL;
    }

