        for (size_t i = 0; i < size; ++i) {
            arr[i] = (double)rand() / RAND_MAX * 100.0;
        }

        return arr;
    }

    // Define image metadata structure and caching mechanism
    struct Metadata {
        char path[256];
        time_t last_modified;
        bool cached;
    };

    struct Cache {
        size_t capacity;
        struct Metadata *cache;
        pthread_mutex_t lock;
        int num_hits, num_misses;
    };

    // Initialize cache with a given capacity
    struct Cache* initialize_cache(size_t capacity) {
        struct Cache* cache = malloc(sizeof(struct Cache));
        if (!cache) {
            perror("Cache memory allocation failed");
            return NULL;
        }

        cache->capacity = capacity;
        cache->cache = calloc(cache->capacity, sizeof(struct Metadata));
        if (!cache->cache) {
            perror("Cache memory allocation failed");
            free(cache);
            return NULL;
        }

        pthread_mutex_init(&cache->lock, NULL);
        cache->num_hits = 0;
        cache->num_misses = 0;

        return cache;
    }

    // Function to fetch image metadata with optional validation and caching
    struct MetadataFetcher* fetch_metadata(struct Cache *cache, char *path, bool validate) {
        pthread_mutex_lock(&cache->lock);

        for (size_t i = 0; i < cache->capacity; ++i) {
            if (!strcmp(cache->cache[i].path, path)) {
                if (validate && cache->cache[i].last_modified < time(NULL)) {
                    // Invalid cached metadata, so fetch from file system
                    pthread_mutex_unlock(&cache->lock);
                    return NULL;
                } else {
                    // Cache hit, return metadata without further fetching
                    pthread_mutex_unlock(&cache->lock);
                    cache->num_hits++;
                    return &cache->cache[i];
                }
            }
        }

        pthread_mutex_unlock(&cache->lock);
        // Cache miss, fetch from file system and optionally cache the result
        struct stat st;
        if (stat(path, &st) != 0) {
            perror("Failed to stat image file");
            return NULL;
        }

        struct Metadata metadata = { path, st.st_mtime, false };
        if (!cache || cache->capacity == 0) {
            // No cache or cache is disabled, so do not cache the result
            return &metadata;
        } else {
            // Cache hit rate below capacity, so evict an existing entry to cache this one
            int index = (hash(path) % cache->capacity);
            while (cache->cache[index].cached && index != 0) {
                index--;
            }

            memmove(&cache->cache[(index + 1) % cache->capacity], &cache->cache[index], sizeof(struct Metadata));
            memcpy(&cache->cache[index], &metadata, sizeof(struct Metadata));
            cache->num_misses++;

            return &cache->cache[index];
        }
    }

    // Helper function for calculating the hash of a string
    unsigned int hash(const char *str) {
        unsigned long hash = 5381;
        int c;

        while ((c = *str++))
            hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

        return hash % cache->capacity;
    }

    struct Cache* cache = initialize_cache(10); // Initialize cache with a capacity of 10

