            pthread_mutex_unlock(lock);
            return NULL;
        }
        allocated->used_size += num_doubles * sizeof(double);

        void *string = create_string(string_len);
        if (!string) {
            perror("Failed to allocate string");
            free(double_arr);
            pthread_mutex_unlock(lock);
            return NULL;
