        resource->allocated_size += chunk_size;
        resource->used_size += num_doubles * sizeof(double) + num_transactions * sizeof(Transaction*);

        printf("Resource Manager: Allocated chunk of size %zu bytes\n", allocated->allocated_size);

        pthread_mutex_unlock(lock);
        return allocated;
    }

    return resource;
}
