struct data_index {
    record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void init_data_index(struct data_index* index, size_t capacity) {
    index->capacity = capacity;
    index->size = 0;
    index->records = malloc(sizeof(record) * capacity);
    if (!index->records) {
        fprintf(stderr, "Failed to allocate memory for records array.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&index->mutex, NULL);
}

void destroy_data_index(struct data_index* index) {
    free(index->records);
    pthread_mutex_destroy(&index->mutex);
}

record* new_record() {
    record* new_record = malloc(sizeof(record));
    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for new record.\n");
        exit(EXIT_FAILURE);
    }

    return new_record;
}

void generate_data(struct data_index* index) {
    static long srand_seed = 123456789;
    for (size_t i = 0; i < index->capacity && index->size < index->capacity * 0.9; ++i) {
        record* r = new_record();
        r->relevance = rand_r(&srand_seed) % 101;
        r->offset = (long)(rand_r(&srand_seed) * 2000L - 1000);
        r->key = rand_r(&srand_seed) % 50 + 1;
        pthread_mutex_lock(&index->mutex);
        index->records[index->size++] = *r;
        pthread_mutex_unlock(&index->mutex);
    }
}

void sort_data(struct data_index* index) {
    qsort(index->records, index->size, sizeof(record), compare);
}

int compare(const void* a, const void* b) {
    double score_a = ((double) ((record*)a)->relevance + 0.5 * ((record*)a)->key);
    double score_b = ((double) ((record*)b)->relevance + 0.5 * ((record*)b)->key);
    if (score_a > score_b) {
        return -1;
    } else if (score_a < score_b) {
        return 1;
    }
    return 0;
}

