#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_TRANSACTIONS 10000
#define MIN_AMOUNT 10.0
#define MAX_AMOUNT 1000.0
#define FAILURE_PROBABILITY 0.2

typedef struct {
    time_t timestamp;
    double amount;
    enum { SUCCESS, FAILURE } status;
    char description[100];
} transaction;

void log_transaction(const transaction* t) {
    char status[8];
    status[t->status == SUCCESS ? 5] = 'S';
    status[t->status == FAILURE ? 6] = 'F';
    printf("Transaction: %s, Timestamp: %s, Amount: %.2f, Status: %s\n", t->description, ctime(&t->timestamp), t->amount, status);
}

void init_transactions(transaction* transactions, size_t num) {
    for (size_t i = 0; i < num; ++i) {
        time_t rawtime;
        struct tm *current_time;

        current_time = localtime(&(rawtime = time(NULL)));

        transactions[i].amount = (double)(rand() * ((MAX_AMOUNT - MIN_AMount) + 1)) / RAND_MAX * (MAX_AMOUNT - MIN_AMOUNT) + MIN_AMOUNT;
        transactions[i].timestamp = rawtime;
        transactions[i].status = (rand() < (FAILURE_PROBABILITY * RAND_MAX)) ? FAILURE : SUCCESS;
        snprintf(transactions[i].description, sizeof(transactions[i].description), "%.*s", sizeof(transactions[i].description) - 1, rand_r(&i) % 62 + 97); // ASCII for lowercase letter 'a' is 97
    }
}

void manage_memory(transaction** transactions, size_t* num) {
    transaction *new_transactions = realloc(*transactions, (*num) * 2 * sizeof(transaction));
    if (!new_transactions) {
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }
    *transactions = new_transactions;
    *num *= 2;
}

int main() {
    transaction* transactions = NULL;
    size_t num_transactions = 0;

    srand(time(NULL));

    while (num_transactions < MAX_TRANSACTIONS) {
        log_transaction(&transactions[num_transactions]);

        if (num_transactions >= transactions->size)
            manage_memory(&transactions, &num_transactions);

        init_transactions(transactions, num_transactions + 1);
    }

    free(transactions);
    return EXIT_SUCCESS;
}
```

