#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

typedef enum { FULFILLED, CANCELLED } OrderStatus;

struct Order {
    unsigned long orderID;
    int quantity;
    double price;
    OrderStatus status;
    char productDescription[256];
};

#define ORDER_MAX 10000
pthread_mutex_t orders_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned long totalOrders = 0, failedOrders = 0;
struct Order *orders = NULL;

void logOperation(const char *operation) {
    printf("[%s] Operation: %s\n", __func__, operation);
}

void initOrder(struct Order *order, unsigned long *nextID) {
    order->orderID = (*nextID)++;
    order->quantity = rand() % (MAX_QUANTITY - MIN_QUANTITY + 1) + MIN_QUANTITY;
    order->price = (double)(rand() % (MAX_PRICE - MIN_PRICE + 1) + MIN_PRICE);
    order->status = (rand() % 10 > 5) ? FULFILLED : CANCELLED;
    for (int i = 0; i < 256; ++i) {
        order->productDescription[i] = 'a' + rand() % 26 + (rand() % 2) * 10 + '0';
    }
}

void* createOrder(void *arg) {
    pthread_mutex_lock(&orders_mutex);
    if ((!orders) || (totalOrders >= ORDER_MAX)) {
        logOperation("Failed to allocate memory for orders.");
        pthread_mutex_unlock(&orders_mutex);
        return NULL;
    }

    struct Order *order = orders + totalOrders++;
    initOrder(order, &totalOrders);

    if (order->quantity > AVAILABLE_STOCK) {
        failedOrders++;
        logOperation("Failed to fulfill order due to stock unavailability.");
    } else {
        logOperation("Successfully fulfilled order.");
    }

    pthread_mutex_unlock(&orders_mutex);
    return order;
}

void freeOrder(struct Order *order) {
    pthread_mutex_lock(&orders_mutex);
    memset(order, 0, sizeof(*order));
    pthread_mutex_unlock(&orders_mutex);
}

void manageOrders(unsigned int threadCount, unsigned int minStock, unsigned int maxStock) {
    AVAILABLE_STOCK = minStock;
    orders = calloc(ORDER_MAX, sizeof(*orders));
    if (!orders) {
        logOperation("Failed to allocate memory for orders.");
        return;
    }

    pthread_t threads[threadCount];
    struct Order *order;
    for (int i = 0; i < threadCount; ++i) {
        if (pthread_create(&threads[i], NULL, createOrder, NULL)) {
            logOperation("Failed to create a thread.");
        }
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], (void **)&order);
        if (!order) continue;
        freeOrder(order);
    }

    free(orders);
}
```

This code defines an Order struct, initializes a mutex for concurrent access to the orders array, and provides functions to manage memory for the order array, populate it with order data, and track failed and fulfilled orders. The `manageOrders()` function handles error cases, initializes the orders array, creates threads to generate orders, joins those threads, and frees the allocated memory when done. It also sets the available stock and optimizes for concurrent access by multiple threads using pthreads.']

