char* sanitize_path(const char *path, size_t max_size) {
    size_t path_len = strlen(path);

    if (path_len > max_size - 1 || path_len == 0) {
        free(path); // Free the input path since it's not valid or too large
        return NULL;
    }

    char *sanitized_path = malloc(max_size + 1);
    if (!sanitized_path) {
        free(path); // Free the input path and return NULL for memory allocation failure
        return NULL;
    }

    memcpy(sanitized_path, path, path_len + 1); // Copy the sanitized path
    sanitized_path[path_len] = '\0'; // Append a null byte at the end

    for (size_t i = 0; i <= path_len; ++i) {
        if (!isalnum(sanitized_path[i]) && sanitized_path[i] != '.' && sanitized_path[i] != '_' && sanitized_path[i] != '/') {
            free(sanitized_path); // Free the allocated memory and return NULL for invalid characters
            return NULL;
        }
    }

    return sanitized_path; // Return the pointer to the sanitized path
}
```
