char* processString(const char *inputStr, size_t sizeLimit, char *resultBuffer) {
    if (!inputStr || !resultBuffer)
        return NULL;

    size_t inputLen = strlen(inputStr);
    if (inputLen > sizeLimit)
        return resultBuffer; // return as is if input exceeds limit

    size_t minSize = (inputLen + 1 > sizeLimit ? sizeLimit : inputLen + 1);
    char* tmpBuf = realloc(resultBuffer, minSize);

    if (!tmpBuf) {
        free(resultBuffer); // free old buffer if realloc fails
        return NULL;
    }

    resultBuffer = tmpBuf; // update pointer to new buffer
    strcpy(resultBuffer, inputStr); // copy input string
    resultBuffer[inputLen] = '/'; // append slash if needed

    return resultBuffer;
}
