class MemoryPool {
public:
    unique_ptr<void[]> allocate(size_t size) {
        auto index = next_block_;
        if (index >= blocks_.size()) {
            blocks_.resize(index + NUM_BLOCKS, nullptr);
        }

        auto block = blocks_[index];
        if (!block) {
            block.reset(new void[size]);
        }

        next_block_ = (index + 1) % NUM_BLOCKS;
        return move(block);
    }

    void deallocate(unique_ptr<void[]> block) {
        if (!block) {
            return;
        }

        size_t index = (next_block_ - 1 + NUM_BLOCKS) % NUM_BLOCKS;
        blocks_[index].reset(move(block));
    }

private:
    static constexpr int NUM_BLOCKS = 10;
    vector<unique_ptr<void[]>> blocks_;
    size_t next_block_ = 0;
};

class Logger {
public:
