        std::lock_guard<std::mutex> lock(mutex_);
        auto timestamp = std::chrono::system_clock::now().time_since_epoch().count();
        auto duration = duration_cast<microseconds>(steady_clock::now() - last_log_time_).count();
        last_log_time_ = steady_clock::now();

        string log_message = "[" + to_string(timestamp) + "] " + message + ", Duration: " + to_string(duration) + " µs\n";
