// Define the number of records initially (e.g., numRecords) and the maximum records limit.
// Assume a growth factor (e.g., GROWTH_FACTOR = 2).
#define GROWTH_FACTOR 2

struct record {
    int value;
};

void ensure_capacity(struct record **arr, size_t *capacity, size_t new_size) {
    if (*new_size > *capacity) {
        size_t old_capacity = *capacity;
        *capacity *= GROWTH_FACTOR;
        struct record *new_array = realloc(*arr, *capacity * sizeof(struct record));
        if (!new_array) {
            fprintf(stderr, "Failed to allocate memory for records\n");
            exit(1);
        }
        *arr = new_array;
    }
}

struct record* allocate_records(size_t numRecords, size_t maxMemoryLimit) {
    struct record *records = malloc(numRecords * sizeof(struct record));
    if (!records || (sizeof(records) > maxMemoryLimit)) {
        fprintf(stderr, "Failed to allocate memory for records or exceeded maximum memory limit\n");
        exit(1);
    }
    return records;
}
