        printf("Error: Exceeded maximum memory limit.\n");
        return 0;
    }
    return 1;
}

void initialize_arrays(size_t numFloats, size_t maxStringLength, size_t numStrings, size_t numElements, double* floats, char* strings[], struct element elements[], size_t numProcessors) {
