    }
    for (size_t i = 0; i < numStrings; ++i) {
        strings[i] = malloc(maxStringLength * sizeof(char));
        memset(strings[i], 0, maxStringLength);
    }
    for (size_t i = 0; i < numElements; ++i) {
        elements[i].value = 0.0f;
        elements[i].index = 0;
    }
}

processor* initialize_processors(size_t numProcessors, size_t numFloatsPerProcessor, size_t maxStringLength, size_t numStringsPerProcessor, size_t numElementsPerProcessor) {
    processor* processors = malloc(numProcessors * sizeof(processor));
    if (!processors) {
        printf("Error: Failed to allocate memory for processors.\n");
        return NULL;
    }

    size_t totalMemoryRequired = numProcessors * (sizeof(double) * numFloatsPerProcessor + sizeof(char*) * numStringsPerProcessor + sizeof(struct element*) + numElementsPerProcessor * sizeof(element));

    if (!check_memory(MAX_MEMORY, totalMemoryRequired)) {
        free(processors);
        return NULL;
    }

    for (size_t i = 0; i < numProcessors; ++i) {
        processors[i].floatPtr = malloc(numFloatsPerProcessor * sizeof(double));
        processors[i].stringPtr = malloc(numStringsPerProcessor * maxStringLength * sizeof(char));
        processors[i].elementPtr = malloc(numElementsPerProcessor * sizeof(struct element));

        if (!processors[i].floatPtr || !processors[i].stringPtr || !processors[i].elementPtr) {
            printf("Error: Failed to allocate memory for processor %zu.\n", i);
            free_processor(&processors[0], i);
            return NULL;
        }
    }

    return processors;
}

void populate_processors(processor* processors, size_t numProcessors, size_t numFloatsPerProcessor, double minFloat, double maxFloat, int minInt, int maxInt) {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < numProcessors; ++i) {
        for (size_t j = 0; j < numFloatsPerProcessor; ++j) {
            processors[i].floatPtr[j] = (double)(rand() * (maxFloat - minFloat)) + minFloat;
        }
        for (size_t j = 0; j < numElementsPerProcessor; ++j) {
            processors[i].elementPtr[j].value = (double)(rand() * (maxFloat - minFloat)) + minFloat;
            processors[i].elementPtr[j].index = rand() % (maxInt - minInt + 1) + minInt;
        }
    }
}

void sanity_check(processor* processors, size_t numProcessors, double minFloat, double maxFloat, int minInt, int maxInt) {
    for (size_t i = 0; i < numProcessors; ++i) {
        for (size_t j = 0; j < numFloatsPerProcessor; ++j) {
            if (processors[i].floatPtr[j] < minFloat || processors[i].floatPtr[j] > maxFloat) {
                printf("Warning: Float value out of bounds in processor %zu at index %zu. Adjusting value to %f.\n", i, j, (processors[i].floatPtr[j] < minFloat ? minFloat : maxFloat));
                processors[i].floatPtr[j] = (processors[i].floatPtr[j] < minFloat ? minFloat : maxFloat);
            }
        }
        for (size_t j = 0; j < numElementsPerProcessor; ++j) {
            if (processors[i].elementPtr[j].value < minFloat || processors[i].elementPtr[j].value > maxFloat || processors[i].elementPtr[j].index < minInt || processors[i].elementPtr[j].index > maxInt) {
                printf("Warning: Value out of bounds in processor %zu at index %zu. Adjusting value to the nearest boundary.\n", i, j);
                if (processors[i].elementPtr[j].value < minFloat) {
                    processors[i].elementPtr[j].value = minFloat;
                } else if (processors[i].elementPtr[j].value > maxFloat) {
                    processors[i].elementPtr[j].value = maxFloat;
                }
                if (processors[i].elementPtr[j].index < minInt) {
                    processors[i].elementPtr[j].index = minInt;
                } else if (processors[i].elementPtr[j].index > maxInt) {
                    processors[i].elementPtr[j].index = maxInt;
                }
            }
        }
    }
}

void free_processor(processor* processor, size_t index) {
    if (processor->floatPtr) {
        free(processor->floatPtr);
    }
    if (processor->stringPtr) {
        free(processor->stringPtr);
    }
    if (processor->elementPtr) {
        free(processor->elementPtr);
    }
}

void free_processors(processor* processors, size_t numProcessors) {
