        orders[i].orderID = (*current_index)++;
        orders[i].quantity = rand_range(1, 100);
        orders[i].price = (double)(rand_range(1, 100)) / 100.0; // Random price between 0.01 and 9.99
        if (rand() % 10 == 0) {
            orders[i].status = CANCELLED;
        } else {
            orders[i].status = FULFILLED;
        }
        for (size_t j = 0; j < 256; ++j) {
            orders[i].productDescription[j] = 'a' + rand() % 26 + (rand() % 2) * 26; // Random alphanumeric characters
        }
    }
    return orders;
}

// Function to serialize and deserialize the order array to disk
void serialize_orders(const char* filename, const order* orders, size_t order_count) {
    gzFile file = gzopen(filename, "wb");
    if (!file) {
        perror("gzopen failed");
        return;
    }
    gzwrite(file, &order_count, sizeof(size_t));
    for (size_t i = 0; i < order_count; ++i) {
        gzwrite(file, &orders[i].orderID, sizeof(unsigned long));
        gzwrite(file, &orders[i].quantity, sizeof(int));
        gzwrite(file, &orders[i].price, sizeof(double));
        size_t status_size = sizeof(order_status);
        gzwrite(file, &orders[i].status, status_size);
        gzwrite(file, orders[i].productDescription, 256);
    }
    gzclose(file);
}

// Function to handle dynamic order processing (add new orders at runtime without reallocating the entire array)
void add_order(order* orders, size_t current_index, size_t* total_orders, order* new_order) {
    if ((*total_orders + 1) >= sizeof(order) / sizeof(order[0])) {
        // Resize the array dynamically when needed
