#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    struct key {
        int key_int;
        char key_char[32];
    } key;
} Record;

struct set {
    Record* records;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
};

int initialize_set(struct set* set, size_t size) {
    if (size <= 0) return -1; // Invalid input: size must be a positive integer

    set->records = calloc(size, sizeof(Record));
    if (!set->records) return -2; // Memory allocation failure

    set->capacity = size;
    set->size = 0;
    pthread_mutex_init(&set->mutex, NULL);

    return 0;
}

struct key generate_key() {
    struct key k;
    k.key_int = rand() % 1001;
    memset(k.key_char, rand() % 256, sizeof(k.key_char));
    return k;
}

Record* get_next_record(struct set* set) {
    Record* r;
    if (set->size < set->capacity) {
        r = &set->records[set->size];
        set->size++;
    } else {
        r = realloc(set->records, set->capacity * 2 * sizeof(Record));
        if (!r) return NULL; // Memory allocation failure
        memmove(&r[set->size], set->records, set->capacity * sizeof(Record));
        set->capacity *= 2;
        r = &r[set->size - 1];
    }

    pthread_mutex_lock(&set->mutex);
    r->offset = (long)r - (long)set->records;
    r->key = generate_key();
    pthread_mutex_unlock(&set->mutex);

    return r;
}

void free_set(struct set* set) {
    free(set->records);
    pthread_mutex_destroy(&set->mutex);
}

int main() {
    struct set s;
    if (initialize_set(&s, 10)) return -1; // Error check initialization

    Record* r;
    while ((r = get_next_record(&s))) {
        printf("Record: offset=%ld key.int=%d\n", r->offset, r->key.key_int);
        for (size_t i = 0; i < strlen(r->key.key_char); ++i)
            printf("%c", r->key.key_char[i]);
    }

    free_set(&s);

    return 0;
}
```

