    for (int i = 0; i < capacity; ++i) {
        offsets[i] = rand() % 2001 - 1000;
    }

    // Hash-based mechanism to maintain uniqueness and minimize collisions
    int hashFunction(int key) { return key % (capacity + 1); }

    // Populate keys with unique values between 1 and 50, inclusive
    for (int i = 0; i < capacity; ++i) {
        int key = 1 + rand() % 50;
        int hashIndex = hashFunction(key);

        while (keys[hashIndex] || keys[hashIndex + 1] == key) {
            key = 1 + rand() % 50;
            hashIndex = hashFunction(key);
