#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char *description;
    time_t start_time;
    time_t end_time;
    priority_t priority;
} task;

typedef struct {
    task *task_ptr;
    time_t start;
    time_t duration;
    int progress;
} status;

void manage_memory(task **tasks, size_t tasks_count, status **statuses) {
    if (!tasks || !*tasks || !tasks_count || !statuses) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    *statuses = malloc(tasks_count * sizeof(status));
    if (!*statuses) {
        perror("Memory allocation error");
        return;
    }

    for (size_t i = 0; i < tasks_count; ++i) {
        if (!(*tasks)[i].start_time || !(*tasks)[i].end_time) {
            fprintf(stderr, "Invalid timestamp\n");
            return;
        }
    }

    for (size_t i = 0; i < tasks_count; ++i) {
        (*statuses + i)->task_ptr = &(*tasks)[i];
        if ((*tasks + i)->end_time <= (*tasks + i)->start_time) {
            fprintf(stderr, "Task with index %zu has invalid time stamps\n", i);
            return;
        }
    }

    for (size_t i = 0; i < tasks_count; ++i) {
        (*statuses + i)->start = (*tasks + i)->start_time;
        (*statuses + i)->duration = (*tasks + i)->end_time - (*tasks + i)->start_time;
        if ((*statuses + i)->duration <= 0) {
            fprintf(stderr, "Task with index %zu has zero or negative duration\n", i);
            return;
        }
    }

    // Update progress percentage dynamically without reallocating the entire memory block.
    for (size_t i = 0; i < tasks_count; ++i) {
        struct timespec now, diff;
        clock_gettime(CLOCK_REALTIME, &now);
        if ((*tasks + i)->end_time <= now.tv_sec) continue; // Task is already completed

        time_t current = now.tv_sec;
        diff.tv_sec = current - (*statuses + i)->start + (*statuses + i)->duration;
        diff.tv_nsec = (now.tv_nsec - (*statuses + i)->duration % 1000000000) % 1000000000;
        double progress = (diff.tv_sec + diff.tv_nsec / 1e9) / (*tasks + i)->duration * 100;
        (*statuses + i)->progress = (int)(progress + 0.5); // Round to nearest integer
    }
}
