typedef enum { INT, FLOAT, STRING, BOOLEAN } DataType;

struct ConfigSetting {
    char name[64];
    union {
        int32_t i;
        float f;
        char *s;
        bool b;
    } value;
    struct ConfigSetting *next;
};

static sem_t mutex;
static size_t num_settings = 0;
static struct ConfigSetting *head = NULL;
static const char *ERROR_MSG[] = { "Invalid number of settings", "Name exceeded max length", "Insufficient memory allocation", "Unknown data type" };

int init_config(size_t num) {
    if (num <= 0 || sem_init(&mutex, 0, 1) < 0) return -1;
    num_settings = num;
    head = malloc(sizeof(struct ConfigSetting) * num);
    if (!head) return -2;
    for (size_t i = 0; i < num; ++i) {
        head[i].name[0] = '\0';
        head[i].value.i = 0;
        head[i].value.f = 0.0;
        head[i].value.s = NULL;
        head[i].value.b = false;
        head[i].next = (i + 1 < num) ? &head[i + 1] : NULL;
    }
    return 0;
}

int add_setting(const char *name, DataType dt, ...) {
    va_list args;
    struct ConfigSetting *current = head;
    sem_wait(&mutex);
    for (size_t i = 0; i < num_settings; ++i, current++) {
        if (!strncmp(name, current->name, sizeof(current->name))) {
            sem_post(&mutex);
            return -3;
        }
        if (!current->next) break;
        current = current->next;
    }
    if (current->next) current = current->next;
    strncpy(current->name, name, sizeof(current->name));
    sem_post(&mutex);
    sem_wait(&mutex);
    va_start(args, dt);
    switch (dt) {
        case INT:
            current->value.i = va_arg(args, int);
            break;
        case FLOAT:
            current->value.f = va_arg(args, double);
            break;
        case STRING:
            current->value.s = va_arg(args, char*);
            break;
        case BOOLEAN:
            current->value.b = va_arg(args, int);
            break;
    }
    sem_post(&mutex);
    return 0;
}

void* get_setting(const char *name) {
    struct ConfigSetting *current = head;
    sem_wait(&mutex);
    for (size_t i = 0; i < num_settings; ++i, current++) {
        if (!strncmp(name, current->name, sizeof(current->name))) {
            sem_post(&mutex);
            return current;
        }
        if (!current->next) break;
        current = current->next;
    }
    sem_post(&mutex);
    return NULL;
}

void reset_config() {
    struct ConfigSetting *current, *temp;
    sem_wait(&mutex);
    for (size_t i = 0; i < num_settings; ++i) {
        current = &head[i];
        temp = malloc(sizeof(struct ConfigSetting));
        if (!temp) break;
        memmove(temp, current, sizeof(*current));
        free(current);
        current = temp;
    }
    num_settings = 0;
    sem_post(&mutex);
}
```

