#include "config_system.h"
#include <assert.h>
#include <pthread_np.h>

typedef struct setting {
    char name[65];
    void* value;
    size_t size;
    pthread_mutex_t lock;
} setting_t;

struct config_system {
    size_t num_settings;
    setting_t** settings;
    pthread_mutex_t system_lock;
};

static void* alloc_aligned(size_t n, size_t alignment) {
    size_t aligned = (n + alignment - 1) & ~(alignment - 1);
    void* ptr = malloc(aligned);
    if (!ptr) config_system_error(ERROR_LEVEL_CRITICAL, "Out of memory");
    return ptr;
}

static void free_aligned(void* p, size_t alignment) {
    assert(p != NULL);
    free(p);
}

static void* config_system_init(size_t num_settings) {
    if (num_settings == 0) return NULL;

    struct config_system* system = alloc_aligned(sizeof(struct config_system), 64);
    system->num_settings = num_settings;
    system->settings = calloc(num_settings, sizeof(setting_t*));
    if (!system->settings) {
        free_aligned(system, 64);
        return NULL;
    }

    pthread_mutex_init(&system->system_lock, NULL);
    return system;
}

static void config_system_free(void* system) {
    if (!system) return;

    for (size_t i = 0; i < ((struct config_system*)system)->num_settings; ++i) {
        setting_t** s = ((struct config_system*)system)->settings + i;
        free((*s)->value);
        free(*s);
    }

    free((\[struct config_system\]*system)->settings);
    pthread_mutex_destroy(&((struct config_system*)system)->system_lock);
    free_aligned(system, 64);
}

static void config_system_reset(void* system) {
    assert(system != NULL);

    for (size_t i = 0; i < ((struct config_system*)system)->num_settings; ++i) {
        setting_t** s = ((struct config_system*)system)->settings + i;
        (*s)->value = NULL;
        memset((*s)->name, '\0', sizeof((*s)->name));
    }
}

void config_system_set(void* system, const char* name, value_type_t type, const void* value, size_t size) {
    assert(system != NULL);
    assert(value != NULL);

    pthread_mutex_lock(&((struct config_system*)system)->system_lock);

    setting_t** slot = ((struct config_system*)system)->settings;
    for (size_t i = 0; i < ((struct config_system*)system)->num_settings; ++i, ++slot) {
        if (strcmp((*slot)->name, name) == 0) {
            (*slot)->value = malloc(size);
            memcpy((*slot)->value, value, size);
            (*slot)->size = size;
            pthread_mutex_unlock(&((struct config_system*)system)->system_lock);
            return;
        }
    }

    slot = ((struct config_system*)system)->settings + ((struct config_system*)system)->num_settings;
    ((struct config_system*)system)->num_settings += 1;

    setting_t* new_setting = alloc_aligned(sizeof(setting_t), 64);
    strcpy(new_setting->name, name);
    new_setting->value = malloc(size);
    memcpy(new_setting->value, value, size);
    new_setting->size = size;
    pthread_mutex_init(&new_setting->lock, NULL);

    *slot = &new_setting;
    pthread_mutex_unlock(&((struct config_system*)system)->system_lock);
}

bool config_system_get(const void* system, const char* name, value_type_t* type, void** value, size_t* size) {
    assert(system != NULL);
    assert(name != NULL);
    assert(value != NULL);
    assert(size != NULL);

    pthread_mutex_lock(&((struct config_system*)system)->system_lock);

    setting_t** slot = ((struct config_system*)system)->settings;
    for (size_t i = 0; i < ((struct config_system*)system)->num_settings; ++i, ++slot) {
        if (strcmp((*slot)->name, name) == 0) {
            *value = (*slot)->value;
            *type = (*slot)->size == sizeof(int) ? INT :
                   (*slot)->size == sizeof(float) ? FLOAT :
                   (*slot)->size == sizeof(char *) ? STRING : BOOLEAN;
            *size = (*slot)->size;
            pthread_mutex_unlock(&((struct config_system*)system)->system_lock);
            return true;
        }
    }

    pthread_mutex_unlock(&((struct config_system*)system)->system_lock);
    return false;
}

static void* alloc_keys(size_t num) {
    assert(num > 0);
    void* ptr = malloc(num * sizeof(int));
    if (!ptr) config_system_error(ERROR_LEVEL_CRITICAL, "Out of memory");
    memset(ptr, 0, num * sizeof(int));
    return ptr;
}

static void free_keys(void* keys) {
