        fprintf(stderr, "Error compiling regular expression.\n");
        return -1;
    }

    if (regcomp(&whitespace_regex, whitespace, REG_EXTENDED | REG_NEWLINE)) {
        fprintf(stderr, "Error compiling regular expression.\n");
        regfree(&sku_regex);
        return -1;
    }

    while (1) {
        if (!regexec(&sku_regex, text, 0, &match, REG_NOTEOL)) {
            if (match.rm_eo) {
                break;
            }

            if (skus_count == sizeof(skus) / sizeof(int)) {
                int *new_skus = realloc(skus, skus_count + 500 * sizeof(int));
                if (!new_skus) {
                    fprintf(stderr, "Error allocating memory for product SKUs.\n");
                    regfree(&sku_regex);
                    regfree(&whitespace_regex);
                    return -1;
                }
                skus = new_skus;
            }

            if (regexec(&whitespace_regex, text + match.rm_so, match.rm_eo - match.rm_so, &match, REG_NOTEOL)) {
                skus[skus_count++] = (int)(text + match.rm_so - text) / sizeof(char);
            } else {
                skus[skus_count++] = (int)(text + match.rm_eo - text) / sizeof(char);
            }
        } else if (regexec(&whitespace_regex, text, 0, &match, REG_NOTEOL)) {
            if (regexec(&sku_regex, text + match.rm_so, match.rm_eo - match.rm_so, &match, REG_NOTEOL)) {
                skus[skus_count++] = (int)(text + match.rm_so - text) / sizeof(char);
            }
        } else if (!match.rm_eo && !*text++) {
            break;
        }
    }

    regfree(&sku_regex);
    regfree(&whitespace_regex);

    int product_counts[500];
    memset(product_counts, 0, sizeof(product_counts));

    for (int i = 0; i < skus_count; ++i) {
        if (product_counts[skus[i]]++ > 1) {
            n_skus++;
        }
    }

    return n_skus;
}
