```cpp
#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <ctime>
#include <regex>
#include <pthread.h>
#include <mutex>

// Define regular expressions for product SKUs extraction
std::regex sku_reg("\\w+");

struct device_status {
    int status;
    std::string description;
    double timestamp;
};

class DataManager {
private:
    int* serial_numbers;
    int* battery_levels;
    int* temperatures;
    struct device_status* device_states;
    std::vector<std::string> skus;
    int n;
    mutex mtx;

public:
    DataManager(int _n) {
        if (_n <= 0) throw "Invalid input size";
        n = _n;
        allocate_memory();
        generate_data();
    }

    void allocate_memory() {
        serial_numbers = new int[n];
        battery_levels = new int[n];
        temperatures = new int[n];
        device_states = new struct device_status[n];
        // Initialize memory to zeros
        memset(serial_numbers, 0, n * sizeof(int));
        memset(battery_levels, 0, n * sizeof(int));
        memset(temperatures, 0, n * sizeof(int));
        memset(device_states, 0, n * sizeof(struct device_status));
    }

    void generate_data() {
        // Generate unique serial numbers and temperature readings within a range
        for (int i = 0; i < n; ++i) {
            serial_numbers[i] = i + 1;
            temperatures[i] = rand() % 100 + 20;
        }

        // Set battery levels based on temperature readings
        for (int i = 0; i < n; ++i) {
            double battery_level = static_cast<double>(temperatures[i]) / 50.0;
            battery_levels[i] = battery_level * 100;
        }

        // Generate unique device descriptions
        for (int i = 0; i < n; ++i) {
            std::string description;
            for (size_t j = 0; j < 20; ++j) {
                description += static_cast<char>(rand() % ('z' - 'a') + 'a');
            }
            device_states[i].description = description;
        }
    }

    void extract_skus(const std::string& text, std::map<std::string, int>& sku_count) {
        std::smatch match;
        for (size_t pos = 0; std::regex_search(text, match, sku_reg); ++pos) {
            sku_count[match.str()]++;
        }
    }

    // Thread-safe function to add SKUs from multiple threads
    void process_skus_threaded(const std::string& text, int thread_id) {
        std::map<std::string, int> sku_count;
        extract_skus(text, sku_count);
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& pair : sku_count) {
            skus.push_back(pair.first);
            // Add frequency of each SKU in the text to the vector
            if (find(skus.begin(), skus.end(), pair.first) != skus.end()) {
                auto it = std::find(skus.begin(), skus.end(), pair.first);
                it->second += pair.second;
            } else {
                skus.push_back(pair.first);
            }
        }
    }

    void reset() {
        // Reinitialize data structures without deallocating memory
        allocate_memory();
        generate_data();
    }
};
```

