#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    off_t offset;
    int key;
    char name[33];
} file_metadata;

struct metadata_manager {
    file_metadata* records;
    size_t capacity, size;
    pthread_mutex_t lock;
    clock_t expiration_window;
};

void generate_random(char *str, int len) {
    for (int i = 0; i < len; ++i) str[i] = (rand() % 26) + 'a';
    str[len] = '\0';
}

int is_valid_size(size_t size) {
    return size > 0 && size <= INT_MAX / sizeof(file_metadata);
}

void cleanup_records(struct metadata_manager* mm) {
    for (size_t i = 0; i < mm->capacity; ++i) {
        if ((clock() - mm->expiration_window > mm->records[i].offset)) {
            free(mm->records + i);
            --mm->capacity;
            memmove(mm->records + i, mm->records + i + 1, (mm->size - i - 1) * sizeof(file_metadata));
        }
    }
}

struct metadata_manager* init_metadata_manager(size_t size) {
    if (!is_valid_size(size)) return NULL;

    struct metadata_manager* mm = malloc(sizeof(struct metadata_manager));
    if (!mm) {
        perror("Memory allocation failure");
        return NULL;
    }

    mm->capacity = size;
    mm->size = 0;
    mm->expiration_window = clock() + (60 * CLOCKS_PER_SEC); // 1 minute expiration window
    pthread_mutex_init(&mm->lock, NULL);

    mm->records = calloc(sizeof(file_metadata), size);
    if (!mm->records) {
        perror("Memory allocation failure");
        free(mm);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        mm->records[i].offset = clock();
        generate_random(mm->records[i].name, sizeof(mm->records[i].name));
        srand((unsigned int)&mm->records[i]); // Seed random number generator for each record
        mm->records[i].key = rand() % 1001;
    }

    return mm;
}

void insert(struct metadata_manager* mm, const off_t offset, const char *name) {
    pthread_mutex_lock(&mm->lock);

    if (mm->size >= mm->capacity) cleanup_records(mm);

    file_metadata *record = mm->records + mm->size;
    record->offset = offset;
    generate_random(record->name, sizeof(record->name));
    strncpy(record->name, name, sizeof(record->name) - 1); // Copy and ensure null termination
    record->key = rand() % 1001;

    mm->size++;
    pthread_mutex_unlock(&mm->lock);
}

// Implement delete function and database interaction functions here
