    bool validated;
} Metric;

void processAndStoreMetrics(int seed, int chunkSize, int totalChunks, int *samplingRate, bool *useAggregation, Metric **dataStream, int maxValue, int maxSamples) {
    if (!seed || !chunkSize || !totalChunks || !samplingRate || !useAggregation || !dataStream || !maxValue || !maxSamples) {
        fprintf(stderr, "Invalid input parameters!\n");
        return;
    }

    *samplingRate = (*samplingRate < chunkSize) ? chunkSize : *samplingRate;
    int windowSize = (*useAggregation) ? min(*samplingRate, maxSamples) : 1;
    double threshold = (*useAggregation) ? windowSize * maxValue / 2.0 : 0.0;

    // Initialize memory pool for Metric structures
    Metric *metricPool = malloc(MAX_MEMORY_RETRIES * maxSamples * sizeof(Metric));

    // Dynamically allocate and initialize memory structures for timestamp and metric arrays
    size_t timestampsSize = totalChunks * chunkSize * *samplingRate;
    Timestamp *timestamps = malloc(timestampsSize * sizeof(Timestamp));
    if (!timestamps) {
        perror("Failed to allocate memory for timestamp array.\n");
        return;
    }

    size_t metricsSize = totalChunks * chunkSize * maxSamples;
    Metric *metrics = malloc(metricsSize * sizeof(Metric));
    if (!metrics) {
        free(timestamps);
        perror("Failed to allocate memory for metric array.\n");
        return;
    }

    // Initialize random number generator and generate timestamps
    srand(seed);
    for (size_t i = 0; i < timestampsSize; ++i) {
        time_t currentTime = time(NULL);
        double randomOffset = (double)(rand() % (RAND_MAX / chunkSize * 2 + 1));
        timestamps[i].timestamp = currentTime + (time_t)(randomOffset * chunkSize);
    }

    // Process and store metrics
    for (int i = 0; i < totalChunks; ++i) {
        size_t startIndex = i * chunkSize * *samplingRate;
        size_t endIndex = min((i + 1) * chunkSize * *samplingRate, timestampsSize);

        for (size_t j = startIndex; j < endIndex; ++j) {
            Metric *metric = &metrics[i * chunkSize + (j - startIndex) / *samplingRate];
            metric->timestamp = &timestamps[j];
            metric->value = (double)(rand() % maxValue);
            metric->validated = false;
        }

        if (*useAggregation) {
            aggregateMetrics(metrics, chunkSize, windowSize, threshold, metricsPool);
        }
    }
}
