typedef struct {
    int relevanceScore;
    LONG* offset;
    INT key;
} Record;

void configureAndIndexUserRecords(int seed, int chunkSize, int totalChunks, int* streamDelay, BOOLEAN useCompression, char** outputStream, int maxDataValue, int maxRecords) {
    srand(seed);

    LONG* offsets = (LONG*)malloc(totalChunks * maxRecords * sizeof(LONG));
    INT* keys = (INT*)calloc(maxRecords, sizeof(INT));
    Record* records = (Record*)calloc(maxRecords, sizeof(Record));

    for (int i = 0; i < maxRecords; ++i) {
        records[i].relevanceScore = rand() % 101;
        records[i].offset = offsets + rand() % totalChunks * maxRecords + i;
        records[i].key = keys[i] = i + 1;
    }

    qsort(records, maxRecords, sizeof(Record), (int (*)(const void*, const void*))compareRelevanceScore);

    HANDLE hStream = CreateFile(*outputStream, GENERIC_WRITE, FILE_SHARE_WRITE | FILE_FLAG_SEQUENTIAL_SCAN, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);

    for (int i = 0; i < totalChunks; ++i) {
        int chunkStart = i * chunkSize;
        int chunkEnd = min(chunkStart + chunkSize, maxRecords);
        for (int j = chunkStart; j < chunkEnd; ++j) {
            Record* record = records + j;
            if (!useCompression || GetFreeDiskSpaceEx(".", NULL, NULL, NULL) > (DWORD)(i + 1) * 1024 * 1024) { // Check if there's enough free disk space before compressing
                fseek(hStream, (long long)*record->offset * sizeof(Record), SEEK_SET);
                fwrite(record, sizeof(Record), 1, hStream);
            } else {
                // Handle compression here and stream the compressed data
            }
        }
        Sleep(*streamDelay); // Delay between processing each chunk
    }

    CloseHandle(hStream);

    free(offsets);
    free(keys);
    free(records);
}

int compareRelevanceScore(const void* a, const void* b) {
    return (*(Record*)a).relevanceScore < *(*(Record*)b).relevanceScore ? -1 : ((*(Record*)a).relevanceScore == *(*(Record*)b).relevanceScore ? 0 : 1);
}
```

