void initLogging();
log4cxx::LoggerPtr getLogger(const char* name);
void logOperationDetails(log4cxx::LoggerPtr logger, const char* operation, size_t total_entries, size_t processed_entries);

void filterAndSortData(float* float_values, double* timestamps, DataPoint** data_points, size_t num_entries, size_t page_size, float threshold, int sort_ascending, int filter) {
    // dynamically allocate memory for arrays
    float_values = (float*)realloc(float_values, num_entries * sizeof(float));
    if (!float_values) {
        printf("Error: Failed to allocate memory for float values.\n");
        return;
    }

    timestamps = (double*)realloc(timestamps, num_entries * sizeof(double));
    if (!timestamps) {
        printf("Error: Failed to allocate memory for timestamp values.\n");
        free(float_values);
        return;
    }

    DataPoint* temp_data_points = (DataPoint*)malloc(num_entries * sizeof(DataPoint));
    if (!temp_data_points) {
        printf("Error: Failed to allocate memory for data points.\n");
        free(float_values);
        free(timestamps);
        return;
    }

    DataPoint* data_points = temp_data_points;

    // copy data from input arrays into temporary array
    for (size_t i = 0; i < num_entries; ++i) {
        data_points[i].value = float_values[i];
        data_points[i].status = *(data_points[i].status + 1); // assuming status is at the end of the struct
    }

    // sort and filter data based on user-specified criteria
    qsort(data_points, num_entries, sizeof(DataPoint), (int (*)(const void*, const void*))compare);

    size_t processed_entries = 0;
    for (size_t i = 0; i < num_entries && processed_entries < page_size; ++i) {
        if (sort_ascending) {
            if (data_points[i].value <= threshold || filter == 0 || data_points[i].status != 'F') { // assuming 'F' is the filter status
                processed_entries++;
                // return pointer to current entry for further processing
                DataPoint* result = &data_points[i];
                data_points += processed_entries;
                return result;
            }
        } else {
            if (data_points[i].value > threshold || filter == 0 || data_points[i].status != 'F') { // assuming 'F' is the filter status
                processed_entries++;
                // return pointer to current entry for further processing
                DataPoint* result = &data_points[i];
                data_points += processed_entries;
                return result;
            }
        }
    }

    free(temp_data_points);
    float_values = NULL;
    timestamps = NULL;

    return NULL; // no more entries to process
}

int compare(const void* a, const void* b) {
    DataPoint* pa = (DataPoint*)a;
    DataPoint* pb = (DataPoint*)b;

    if (*((const float*)pa - (const float*)pb) < FLT_EPSILON)
        return 0;
    else if (*((const float*)pa - (const float*)pb) < 0)
        return -1;
    else
        return 1;
}

void initLogging() {
    log4cxx::Initialization::initialize();
}

log4cxx::LoggerPtr getLogger(const char* name) {
    return log4cxx::Logger::getLogger(name);
}

void logOperationDetails(log4cxx::LoggerPtr logger, const char* operation, size_t total_entries, size_t processed_entries) {
    std::stringstream ss;
    ss << "Operation: [" << operation << "] Total Entries: [" << total_entries << "], Processed Entries: [" << processed_entries << "]";
    logger->info(ss.str());
}
