typedef struct Record {
    int value;
    const int *key;
    const long *offset;
} Record;

static pthread_mutex_t alloc_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_records = 0;
static Record *records = NULL;
static long *offsets = NULL;
static int *keys = NULL;

int init_arrays(size_t num_records) {
    pthread_mutex_lock(&alloc_mutex);

    if (num_records == 0 || records != NULL) {
        pthread_mutex_unlock(&alloc_mutex);
        return -1; // Error: invalid arguments or memory already allocated
    }

    size_t total_size = sizeof(Record) * num_records + sizeof(long) * num_records + sizeof(int) * num_records;

    void *combined_memory = malloc(total_size);
    if (combined_memory == NULL) {
        pthread_mutex_unlock(&alloc_mutex);
        return -2; // Error: memory allocation failure
    }

    records = (Record *) combined_memory;
    offsets = (long *) ((char *) records + sizeof(Record) * num_records);
    keys = (int *) ((char *) offsets + sizeof(long) * num_records);

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100; // Adjust the range as needed
        records[i].key = keys + i;
        records[i].offset = offsets + i;
    }

    pthread_mutex_unlock(&alloc_mutex);

    return 0; // Success
}
