    [MarshalAs(UnmanagedType.LPStr)]
    public string Pointer;
}

public struct LogEntry
{
    public int Id;
    [MarshalAs(UnmanagedType.LPStr)]
    public string Data;
}

[StructLayout(LayoutKind.Sequential, Pack = 8)]
public struct MemoryStructure
{
    public double[] Probabilities;
    public Event[] Events;
    public LogEntry[] LogEntries;
}

public void AddWebsiteAndSortMemoryStructures(string directoryPath, string siteName)
{
    // Check for web.config and validate the presence of the site in it
    if (!File.Exists($"{directoryPath}/web.config"))
        throw new FileNotFoundException("web.config", $"{directoryPath}/web.config");

    var config = XDocument.Load(directoryPath + "/web.config");
    if (!config.Root.Element("sites").Elements("site")
                          .Any(e => e.Attribute("name").Value == siteName))
        throw new ArgumentException($"Site '{siteName}' not found in web.config", nameof(siteName));

    // Implement retry mechanism with exponential backoff for adding the website using Process class
    var process = new Process
    {
        StartInfo = new ProcessStartInfo
        {
            FileName = $"{directoryPath}/webadmin.exe",
            Arguments = $"addsite {siteName}",
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true,
            WorkingDirectory = directoryPath
        },
        EnableRaisingEvents = true
    };

    var maxRetries = 10;
    var delay = TimeSpan.FromMilliseconds(200);
    for (var i = 0; i < maxRetries; i++)
    {
        try
        {
            process.Start();
            process.WaitForExit();
            if (process.ExitCode == 0)
                break;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Failed to add site '{siteName}'. Error: {ex.Message}. Retrying in {delay.TotalMilliseconds}ms");
            Thread.Sleep(delay);
        }

        if (i == maxRetries - 1)
            throw new Exception($"Failed to add site '{siteName}' after {maxRetries} retries.");
    }

    // Allocate and initialize memory structures
    var memoryStructure = new MemoryStructure();

    // Generate unique random probabilities
    Random rand = new Random();
    var probabilitySet = new HashSet<double>();
    while (probabilitySet.Count < 100)
        probabilitySet.Add(rand.NextDouble());
    memoryStructure.Probabilities = probabilitySet.ToArray();

    // Allocate event and log entry arrays
    var eventCount = 100;
    memoryStructure.Events = new Event[eventCount];
    memoryStructure.LogEntries = new LogEntry[eventCount];

    // Initialize pointers, validate them, and sort events based on timestamps
    Parallel.For(0, eventCount, i =>
    {
        memoryStructure.Events[i].Timestamp = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        memoryStructure.Events[i].Pointer = $"{Guid.NewGuid()}.txt";
    });

    Array.Sort(memoryStructure.Events, (a, b) => a.Timestamp.CompareTo(b.Timestamp));

    // Initialize log entries, validate pointers, and sort log entries by IDs
    Parallel.For(0, eventCount, i =>
    {
        memoryStructure.LogEntries[i].Id = i;
        memoryStructure.LogEntries[i].Data = $"{Guid.NewGuid()}.txt";
    });

    Array.Sort(memoryStructure.LogEntries, (a, b) => a.Id.CompareTo(b.Id));

    // Performance optimizations and memory usage logging
    // ...

    // Free allocated memory before returning
    GC.Collect();
}
