using System;
using System.Diagnostics;
using System.IO;
using System.Linq;

public int StartWebsite(string directoryPath, string siteName, bool useHttps)
{
    string webConfigPath = Path.Combine(directoryPath, "web.config");
    if (!File.Exists(webConfigPath)) return -1;

    string logFilePath = Path.Combine(directoryPath, $"{siteName}.log");
    TextWriterTraceListener traceListener = new TextWriterTraceListener(logFilePath);
    Trace.Listeners.Add(traceListener);
    Trace.AutoFlush = true;

    try
    {
        var processStartInfo = new ProcessStartInfo
        {
            FileName = "IISExpress.exe",
            Arguments = $"/site {siteName} /config {webConfigPath} {(useHttps ? "/wwwroot https" : string.Empty)}",
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true,
            WorkingDirectory = directoryPath,
        };

        Process process;
        if (IntPtr.Size == 4)
        {
            process = new Process { StartInfo = processStartInfo, StartInfo.FileName += ".x86" };
        }
        else
        {
            process = new Process { StartInfo = processStartInfo };
        }

        process.Start();
        int pid = process.Id;
        traceListener.Flush();
        return pid;
    }
    catch (Exception ex)
    {
        Trace.TraceError(ex.Message);
        return -1;
    }
}
