#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double value;
    char* string;
    size_t ref_count;
} data_point;

// Custom memory pool for data_points
typedef void* (*custom_allocator)(size_t);
typedef void* (*custom_deallocator)(void*);

struct mem_pool {
    void* start;
    size_t capacity;
    size_t allocated;
    custom_allocator alloc;
    custom_deallocator dealloc;
};

// Function to initialize a memory pool for data_points
void init_mem_pool(struct mem_pool* pool, size_t capacity) {
    pool->start = pool->alloc(capacity * sizeof(data_point));
    if (!pool->start) {
        perror("Failed to allocate memory pool");
        exit(1);
    }
    pool->capacity = capacity;
    pool->allocated = 0;
    pool->dealloc = free;
}

// Function to get a data_point from the memory pool
data_point* pool_get(struct mem_pool* pool) {
    if (pool->allocated == pool->capacity) {
        perror("Memory pool is full");
        exit(1);
    }
    data_point* dp = pool->start + pool->allocated++;
    dp->string = calloc(MAX_STR_LEN, sizeof(char));
    if (!dp->string) {
        perror("Failed to allocate memory for string");
        exit(1);
    }
    return dp;
}

// Function to return a data_point to the memory pool
void pool_put(struct mem_pool* pool, data_point* dp) {
    dp->ref_count = 0;
    dp->string[0] = '\0';
    memset(dp->string + 1, 0, MAX_STR_LEN - 1);
}

// Function to dynamically allocate and initialize arrays
void init_arrays(size_t num_doubles, size_t num_chars, size_t num_data_points, struct mem_pool* pool) {
    double* doubles = pool->alloc(num_doubles * sizeof(double));
    char* chars = pool->alloc(num_chars);
    data_point* data_points = pool_get(pool);

    if (!doubles || !chars || !data_points) {
        perror("Failed to allocate memory for arrays");
        exit(1);
    }

    srand(time(NULL)); // Seed random number generator once per program execution

    for (size_t i = 0; i < num_doubles; ++i) {
        doubles[i] = (double)(rand() / RAND_MAX * MAX_DOUBLE);
    }

    for (size_t i = 0; i < num_data_points; ++i) {
        data_points[i].value = (double)(rand() / RAND_MAX * MAX_DOUBLE);
        strncpy(data_points[i].string, "INITIAL STRING", MAX_STR_LEN - 1);
        data_points[i].ref_count = 0;
    }

    for (size_t i = num_doubles; i < num_chars; ++i) {
        chars[i] = 'A' + (rand() % 26);
    }
}
```

