    private static void RetryPolicy(Func<Task> action)
    {
        const int MaxRetries = 5;
        const int BackoffSeconds = 2;

        async Task ExecuteAction()
        {
            for (int attempt = 1; attempt <= MaxRetries; attempt++)
            {
                try
                {
                    await action();
                    return;
                }
                catch (Exception ex) when (attempt < MaxRetries)
                {
                    Console.WriteLine($"Retry {attempt}: Failed, trying again in {BackoffSeconds ^ attempt} seconds...");
                    await Task.Delay(TimeSpan.FromSeconds(BackoffSeconds ^ attempt));
                }
            }

            throw new AggregateException($"Max retries reached.");
        }

        ExecuteAction().GetAwaiter().OnCompleted(() => Console.WriteLine("All retries exhausted."));
    }
