using Microsoft.Extensions.Logging;

namespace WebApplicationStarter
{
    public class WebAppStarter
    {
        private readonly ILogger<WebAppStarter> _logger;
        private readonly IWebHostBuilder _webHostBuilder;

        public WebAppStarter(ILogger<WebAppStarter> logger, IWebHostBuilder webHostBuilder)
        {
            _logger = logger;
            _webHostBuilder = webHostBuilder;
        }

        public async Task<IWebHost>? StartWebApplicationAsync(string directoryPath, string siteName)
        {
            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath)) return null;

            try
            {
                var configuration = new ConfigurationBuilder()
                    .SetBasePath(directoryPath)
                    .AddJsonFile("websettings.json") // Customize this for your specific needs
                    .Build();

                var serviceProvider = new ServiceCollection()
                    .ConfigureServices((hostContext, services) =>
                        _webHostBuilder.ConfigureAppConfiguration((context, builder) =>
                            builder.SetBasePath(directoryPath))
                            .ConfigureLogging((hostingContext, loggingBuilder) =>
                                loggingBuilder.AddConsole())
                            .ConfigureServices(services))
                    .BuildServiceProvider();

                var host = _webHostBuilder.UseConfiguration(configuration)
                    .UseServiceProvider(serviceProvider)
                    .UseStartup<Startup>() // Customize this for your specific needs
                    .SetDataRoot(directoryPath)
                    .SetContentRoot(directoryPath)
                    .UseUrls($"http://{siteName}:5000") // Customize port and URL as required
                    .Build();

                var startTask = host.StartAsync();

                // Exponential backoff retry mechanism with a maximum number of retries
                const int MaxRetries = 10;
                int retries = 0;
                Action<CancellationTokenSource> stopTask = cts => host.StopAsync(cts.Token);

                do
                {
                    try
                    {
                        await startTask;
                        return host;
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError($"Failed to start web application '{siteName}'. {ex.Message}. Retrying...");
                        retries++;
                        if (retries >= MaxRetries) throw new AggregateException("Maximum retries reached.");
                    }

                    // Wait for a random amount of time based on the current retry count
                    await Task.Delay(TimeSpan.FromMilliseconds(Math.Pow(2, retries)));
                    stopTask = c => host.StopAsync(c.Token);
                } while (true);
            }
            catch (Exception ex)
            {
                _logger.LogError($"An error occurred while starting the web application: {ex}");
            }

            return null;
        }
    }
}
