    public MetadataFetcher Process(string directoryPath, string siteName, TimeSpan timeout, Config config)
    {
        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist.");

        var webConfig = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfig))
            return new MetadataFetcher { SiteConfiguration = new SiteConfiguration { Name = siteName } };

        try
        {
            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };

            var webAppProcesses = new ConcurrentDictionary<string, Process>();
            var sensorData = new ConcurrentQueue<SensorData>();

            // Start the web application and load image metadata concurrently
            LoadImageMetadata(directoryPath, _images);
            StartWebApplications(webConfig, siteName, timeout, options, webAppProcesses);

            ProcessSensorData(sensorData, _images);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing data: {ex}");
        }

        return new MetadataFetcher { SiteConfiguration = new SiteConfiguration { Name = siteName, ImageMetadata = _images.ToList() } };
    }

    private void StartWebApplications(string webConfig, string siteName, TimeSpan timeout, ParallelOptions options, ConcurrentDictionary<string, Process> webAppProcesses)
    {
        var startArgs = new[] { $"/{webConfig}", "/site", $"--name={siteName}" };
        Func<ProcessStartInfo, Process> startWebApp = pi => new Process { StartInfo = pi };

        Parallel.ForEach(Directory.GetFiles(directoryPath, "WebApplication*.exe", SearchOption.AllDirectories), options, args =>
        {
            var processCount = Interlocked.Increment(ref webAppProcesses.Count);

            if (processCount > GlobalMaxThreads) return;

            ProcessStartInfo pi = new ProcessStartInfo(args, startArgs)
            {
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true,
                WorkingDirectory = Path.GetDirectoryName(args),
                Timeout = (int)timeout.TotalMilliseconds,
                ErrorDialog = false
            };

            try
            {
                webAppProcesses[siteName] = startWebApp(pi);
                webAppProcesses[siteName].Start();
            }
            catch (Exception ex)
            {
                if (ex is OutOfMemoryException || ex is TimeoutException || ex is WebException || ex is TaskCanceledException)
                {
                    Console.WriteLine($"Error starting web application for site '{siteName}': {ex}");
                }
                else
                {
                    throw;
                }
            }
        });
    }

    private void LoadImageMetadata(string directoryPath, ConcurrentBag<Image> images)
    {
        Parallel.ForEach(Directory.GetFiles(directoryPath, "*.jpg", SearchOption.AllDirectories), new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount }, args =>
        {
            try
            {
                using (var fileStream = File.OpenRead(args))
                {
                    _imageSemaphore.Wait();

                    var image = new Image { Filename = Path.GetFileName(args), Width = GetWidth(fileStream), Height = GetHeight(fileStream) };
                    images.Add(image);

                    _imageSemaphore.Release();
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading image '{Path.GetFileName(args)}': {ex}");
            }
        });
    }

    private void ProcessSensorData(ConcurrentQueue<SensorData> sensorData, ConcurrentBag<Image> images)
    {
        var dataChunkSize = (int)(sensorData.Count / 10);
        for (int i = 0; i < sensorData.Count; i += dataChunkSize)
        {
            var chunk = new SensorData[dataChunkSize];
            sensorData.CopyTo(chunk, i);
            ProcessDataChunk(chunk, images);
        }
    }

    private void ProcessDataChunk(SensorData[] sensorDataChunk, ConcurrentBag<Image> images)
    {
        Parallel.ForEach(sensorDataChunk, new ParallelOptions { MaxDegreeOfParallelism = Math.Min(sensorDataChunk.Length, MaxThreadsPerInstance) }, data =>
        {
            ProcessSingleDataItem(data, images);
        });
    }

    private void ProcessSingleDataItem(SensorData data, ConcurrentBag<Image> images)
    {
        // Implement processing logic for each data item here
    }
}

