                var userProfileJson = JsonDocument.Parse(profileData);
                var userProfile = userProfileJson.RootElement.GetProperty("userProfile");

                if (!_authService.ValidateCredentials(username, email, password)) return null;

                // Validate and store the user profile in local database
                await StoreUserProfileInLocalDb(userProfile);

