            private async Task StoreUserProfileInCloudStorage(JsonElement userProfile, HttpClient httpClient)
            {
                const int maxRetries = 5;
                const TimeSpan delayBetweenRetries = TimeSpan.FromSeconds(2);

                for (int i = 0; i < maxRetries; i++)
                {
                    try
                    {
                        var request = new HttpRequestMessage
                        {
                            Method = HttpMethod.Post,
                            RequestUri = new Uri("https://your-cloud-storage-api-url"),
                            Content = JsonContent.Create(userProfile)
