                        }
                    }
                    catch (HttpRequestException ex) when (i < maxRetries - 1)
                    {
                        Console.WriteLine($"Error storing user profile in cloud storage: {ex.Message}. Retrying in {delayBetweenRetries.TotalSeconds} seconds.");
                        await Task.Delay(delayBetweenRetries);
