        public async Task<UserProfile> CreateUserProfileAsync(string username, string email, string password)
        {
            if (!File.Exists(_profileDirectory + $"\\{username}\\profile.json"))
                return null;

            var dbConnection = new SqlConnection(_connectionString);
            var s3Client = CreateS3Client();

            try
            {
                await RetryAsync(CreateAndSaveUserProfile, (_, _) => SaveToCloudStorage(dbConnection, s3Client, username), username, password);

