                throw;
            }
            finally
            {
                dbConnection.Dispose();
                s3Client?.Dispose();
            }
        }

        private IAmazonS3 CreateS3Client()
        {
            return new AmazonS3Client(new BasicAWSCredentials(_awsAccessKey, _awsSecretKey), RegionEndpoint.USWest2);
        }

        private async Task<T> RetryAsync<T>(Func<Task<T>> action, Func<UserProfile, Task<T>> fallbackAction, string username, T defaultValue = default)
        {
            int retryCount = 0;
            TimeSpan elapsedTime = TimeSpan.Zero;

            while (retryCount < _maxRetries)
            {
                try
                {
                    return await action();
                }
                catch (Exception ex) when (ex is not TaskCancelledException && elapsedTime + _retryInterval < DateTime.Now)
                {
                    retryCount++;
                    _logger.LogInformation("Retrying operation for user {Username} after failure. Retry count: {RetryCount}", username, retryCount);
                    elapsedTime += _retryInterval;
                    await Task.Delay(_retryInterval * Math.Pow(2, retryCount));
                }
            }

            return defaultValue;
        }

