    public async Task<int?> StartSiteAsync(string directoryPath, string siteName, Action<string> callback)
    {
        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError("Invalid directory path provided.");
            return null;
        }

        var webConfigFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFilePath))
        {
            if (!AskForConfirmation($"No web.config file found in directory '{directoryPath}'. Do you want to generate a default configuration?"))
