                Arguments = $"run --project {webConfigFilePath} &",
                WorkingDirectory = directoryPath,
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true,
            }
        };

        var startedProcess = process.Start();
        if (startedProcess == null || !startedProcess.HasExited)
        {
