#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_NODES 1024

typedef struct Node {
    int value;
    struct Node* next;
} node;

node* initList(size_t size) {
    if (size > MAX_NODES) {
        printf("Error: List size exceeds the maximum allowed nodes.\n");
        return NULL;
    }

    node* list = malloc(sizeof(node) * size);
    for (size_t i = 0; i < size - 1; ++i) {
        list[i].next = &list[i + 1];
        list[i].value = 0;
    }
    list[size - 1].next = NULL;

    return list;
}

void insertNode(node* list, size_t position, int value) {
    if (position >= MAX_NODES || position <= 0) {
        printf("Error: Invalid node position.\n");
        return;
    }

    node* newNode = malloc(sizeof(node));
    if (!newNode) {
        freeMem(list, position);
        return;
    }

    newNode->value = value;
    newNode->next = list + position;

    for (size_t i = position + 1; i < MAX_NODES && list[i].next != NULL; ++i) {
        node* temp = list[i].next;
        list[i].next = newNode;
        newNode = temp;
    }
}

void freeMem(node* list, size_t position) {
    for (size_t i = 0; i <= position && list != NULL; ++i) {
        node* temp = list;
        list = list->next;
        free(temp);
    }
}

int sumNodes(node* list, size_t size) {
    int total = 0;
    for (size_t i = 0; i < size; ++i) {
        total += list[i].value;
    }
    return total;
}
