```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 1000

typedef struct Node {
    int value;
    struct Node* next;
} Node;

Node* createLinkedList(int size) {
    if (size <= 0 || size > MAX_NODES) return NULL;

    Node *list = malloc(sizeof(Node) * size);
    if (!list) return NULL;

    memset(list, 0, sizeof(Node) * size);

    for (int i = 1; i < size; ++i) {
        list[i - 1].next = &list[i];
    }
    list[size - 1].next = NULL;

    return list;
}

void insertNode(Node* list, int pos, int value) {
    if (!list || pos < 0 || pos >= MAX_NODES) return;

    Node *current = list;
    for (int i = 0; i < pos && current != NULL; ++i) {
        current = current->next;
    }

    if (current == NULL) return; // invalid position

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        freeMem(list);
        return;
    }

    newNode->value = value;
    newNode->next = current->next;
    current->next = newNode;
}

int sumListValues(Node* list, int size) {
    if (!list || size <= 0 || size > MAX_NODES) return 0;

    Node *current = list;
    int sum = 0;

    for (int i = 0; i < size && current != NULL; ++i, current = current->next) {
        sum += current->value;
    }

    return sum;
}

void freeMem(Node* list) {
    while (list != NULL) {
        Node *temp = list;
        list = list->next;
        free(temp);
    }
}
