#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    char *data;
    struct Node *next;
} Node;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

Node* create_node_list(int num_records, int min_value, int max_value, size_t max_string_length) {
    Node *head = NULL;
    Node **tail = &head;

    if (num_records <= 0 || max_string_length <= 0) {
        log_error("Invalid input parameters");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for offsets, keys, and records arrays
    long *offsets = (long*) malloc(num_records * sizeof(long));
    if (!offsets) {
        log_error("Failed to allocate memory for offsets");
        goto cleanup;
    }

    int *keys = (int *) malloc(num_records * sizeof(int));
    if (!keys) {
        log_error("Failed to allocate memory for keys");
        free(offsets);
        goto cleanup;
    }

    Node **records = (Node**) calloc(num_records, sizeof(Node*));
    if (!records) {
        log_error("Failed to allocate memory for records");
        free(keys);
        free(offsets);
        goto cleanup;
    }

    // Initialize offset values and keys
    int i = 0;
    long current_offset = 0;
    for (; i < num_records; ++i) {
        pthread_mutex_lock(&mutex);
        if (current_offset >= num_records) {
            log_error("Overflow condition detected");
            break;
        }
        offsets[i] = current_offset++;
        keys[i] = min_value + rand() % (max_value - min_value + 1);
        pthread_mutex_unlock(&mutex);
    }

    // Populate the records array and link nodes sequentially
    if (i > 0) {
        Node *current = (Node*) malloc(sizeof(Node));
        if (!current) {
            log_error("Failed to allocate memory for current node");
            goto cleanup;
        }
        current->key = keys[0];
        current->data = calloc(max_string_length + 1, sizeof(char));
        if (!current->data) {
            log_error("Failed to allocate memory for data in current node");
            free(current);
            goto cleanup;
        }
        strcpy(current->data, "");
        current->next = NULL;
        *tail = current;
        tail = &current->next;
    }

    for (i = 1; i < num_records; ++i) {
        Node *current = (Node*) malloc(sizeof(Node));
        if (!current) {
            log_error("Failed to allocate memory for current node");
            goto cleanup;
        }
        current->key = keys[i];
        current->data = calloc(max_string_length + 1, sizeof(char));
        if (!current->data) {
            log_error("Failed to allocate memory for data in current node");
            free(current);
            goto cleanup;
        }
        strcpy(current->data, "");
        current->next = NULL;
        *tail = current;
        tail = &current->next;
    }

    // Set the last node's next pointer to NULL and clean up resources if needed
    (*tail)->next = NULL;

    // Summing all node values without traversing the entire list more than once
    int sum = 0;
    Node *current_node = head;
    while (current_node != NULL) {
        sum += current_node->key;
        current_node = current_node->next;
    }

cleanup:
    for (i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->data);
            free(records[i]);
        }
    }
    free(keys);
    free(offsets);
    free(records);

    return head;
}
