using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using StackExchange.Redis;

namespace WebApplicationStarter
{
    public class WebApplicationStarter
    {
        private readonly IWebHostBuilder _webHostBuilder;
        private readonly ILogger<WebApplicationStarter> _logger;
        private readonly ConnectionMultiplexer _redisConnection;
        private const string ConfigCacheKeyPrefix = "webconfig:{0}";

        public WebApplicationStarter(IWebHostBuilder webHostBuilder, ILogger<WebApplicationStarter> logger, ConnectionMultiplexer redisConnection)
        {
            _webHostBuilder = webHostBuilder;
            _logger = logger;
            _redisConnection = redisConnection;
        }

        public async Task<string> StartWebApplicationAsync(string directoryPath, string siteName)
        {
            var configCacheKey = GetConfigCacheKey(directoryPath);
            var webConfigExistsInCache = await _redisConnection.GetDatabase().StringExistsAsync(configCacheKey);

            if (!webConfigExistsInCache)
            {
                if (await File.ExistsAsync($"{directoryPath}\\web.config"))
                {
                    await _redisConnection.GetDatabase().StringSetAsync(configCacheKey, "true");
                }
                else
                {
                    return null;
                }
            }

            var webHost = _webHostBuilder
                .UseContentRoot(directoryPath)
                .UseIISIntegration()
                .UseStartup<Startup>()
                .SetApplicationName(siteName);

            try
            {
                using (var host = await webHost.Build().StartAsync())
                {
                    _logger.LogInformation("Web application started: {SiteName}", siteName);
                    return host.Addresses.FirstOrDefault()?.ToString();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to start web application: {SiteName}", siteName);
                await RetryStartWebApplicationAsync(directoryPath, siteName);
            }
        }

        private string GetConfigCacheKey(string directoryPath) => $"webconfig:{Directory.GetHashCode(directoryPath)}";

        private async Task RetryStartWebApplicationAsync(string directoryPath, string siteName, int maxRetries = 10, TimeSpan retryIntervalBase = TimeSpan.FromSeconds(2))
        {
            for (int i = 0; i < maxRetries; i++)
            {
                try
                {
                    await StartWebApplicationAsync(directoryPath, siteName);
                    return;
                }
                catch (Exception ex) when (i < maxRetries - 1)
                {
                    _logger.LogError(ex, "Attempting to start web application (Retry #{0}): {SiteName}", i + 1, siteName);
                    await Task.Delay((long)(retryIntervalBase.TotalMilliseconds * Math.Pow(2, i)));
                }
            }
        }
    }
}
