    public UserRecordsManager(int seed, int chunkSize, int totalChunks, ref int streamDelay, bool useCompression, out Stream outputStream, int maxDataValue, int maxRecords)
    {
        _seed = seed;
        _chunkSize = chunkSize;
        _totalChunks = totalChunks;
        _offsets = new int[_totalChunks];
        _keys = Enumerable.Range(1, 50).ToArray();
        _records = new Record[_maxRecords];
        _useCompression = useCompression;
        outputStream = outputStream;
        _maxDataValue = maxDataValue;
        _maxRecords = maxRecords;
