public async Task<UserProfile> InitializeUserProfile(string username, string email, string password)
{
    // Validate input parameters
    if (string.IsNullOrWhiteSpace(username)) throw new ArgumentException("Username is required");
    if (string.IsNullOrWhiteSpace(email)) throw new ArgumentException("Email is required");
    if (string.IsNullOrWhiteSpace(password) || password.Length < 8) throw new ArgumentException("Password must be at least 8 characters long");

    // Check for existence of profile.json file and return null if not found
