    var dbProfiles = JsonConvert.DeserializeObject<List<UserProfile>>(File.ReadAllText(Path.Combine(localDirectory, "profile.json")));

    // Hash the provided password for security
    using (var sha256 = SHA256.Create())
    {
        byte[] hashedPassword = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
        string passwordHash = BitConverter.ToString(hashedPassword).Replace("-", "");

        // Perform exponential backoff retry mechanism for concurrent modifications
        int retryCount = 0;
        const int maxRetries = 5;
        while (true)
        {
            retryCount++;
            if (retryCount > maxRetries) return null; // Give up after max retries

            try
            {
                // Check if the profile already exists in local database or remote cloud service
                UserProfile existingProfile = dbProfiles.FirstOrDefault(p => p.Username == username || p.Email == email);
                if (existingProfile != null) return null; // Return null if profile already exists

                // Create new UserProfile object with hashed password
                var newProfile = new UserProfile { Username = username, Email = email, PasswordHash = passwordHash };

                // Save the new profile to local database and cloud storage service (sample implementation)
                dbProfiles.Add(newProfile);
                File.WriteAllText(Path.Combine(localDirectory, "profile.json"), JsonConvert.SerializeObject(dbProfiles));

                using (var httpClient = new HttpClient())
                {
                    var cloudStorageRequest = new CloudStorageRequest
                    {
                        Username = username,
                        Email = email,
                        PasswordHash = passwordHash
                    };

                    string cloudStorageUrl = "<cloud_storage_service_url>";
                    HttpResponseMessage response = await httpClient.PostAsJsonAsync(cloudStorageUrl, cloudStorageRequest);
                    if (!response.IsSuccessStatusCode) return null; // Return null on failure to save profile to cloud service
                }

                return newProfile;
            }
            catch (Exception ex) when (ex is IOException || ex is TaskCanceledException)
            {
                // Handle race conditions, network latency, and connectivity issues gracefully with exponential backoff retry mechanism
                await Task.Delay(Math.Pow(2, retryCount - 1) * 100); // Increase delay exponentially based on retries
            }
        }
    }
}

