typedef struct node {
    double value;
    char* str;
    struct node* next;
    int flag;
} Node;

struct DataStructure {
    Node** doubles;
    char** strings;
    Node*** nodes;
    int* flags;
    size_t capacity, currentSize;
};

void ds_init(struct DataStructure* ds, size_t maxNodes) {
    ds->capacity = maxNodes;
    ds->currentSize = 0;
    ds->doubles = malloc(maxNodes * sizeof(Node*));
    ds->strings = malloc(maxNodes * sizeof(char*));
    ds->nodes = malloc(maxNodes * sizeof(Node**));
    ds->flags = malloc(maxNodes * sizeof(int));
}

void ds_deinit(struct DataStructure* ds) {
    for (size_t i = 0; i < ds->currentSize; ++i) {
        free(ds->doubles[i]);
        free(ds->strings[i]);
        free(ds->nodes[i]);
    }
    free(ds->doubles);
    free(ds->strings);
    free(ds->nodes);
    free(ds->flags);
}

void ds_insert(struct DataStructure* ds, double value, const char* str, int flag, Node** last) {
    if (ds->currentSize == ds->capacity) {
        // Handle memory overflow by retrying allocation or adjusting data structure design
        return;
    }

    Node* node = malloc(sizeof(Node));
    if (!node) {
        // Log error and handle failure
        return;
    }

    node->value = value;
    node->str = strdup(str);
    if (!node->str) {
        // Free allocated memory and handle failure
        free(node);
        return;
    }

    node->next = NULL;
    node->flag = flag;

    if (ds->currentSize == 0) {
        ds->doubles[0] = &node->value;
        ds->strings[0] = node->str;
        ds->nodes[0] = &node;
        ds->flags[0] = node->flag;
    } else {
        last[0]->next = &node->value;
        last[1][ds->currentSize] = &node;
        last[2][ds->currentSize] = node;
        last[3][ds->currentSize] = &node->flag;
    }

    ++ds->currentSize;
}

double ds_average(const struct DataStructure* ds) {
    double sum = 0.0;
    size_t count = 0;
    for (size_t i = 0; i < ds->currentSize; ++i)
        sum += ds->doubles[i];
    return sum / ds->currentSize;
}
