            try
            {
                AcquireLock().Wait();

                var moduleData = JsonConvert.DeserializeObject<WebServiceModuleData>(File.ReadAllText(_serviceJsonFilePath));

                // Validate compatibility, perform integration and return the instance of the Web Service Module

                ReleaseLock();

                return new WebServiceModuleResult(moduleInstance);
            }
            catch (Exception ex)
            {
                _loggingService.LogError($"Failed to initialize Web Service Module: {ex.Message}");
                ReleaseLock();
                throw;
            }
        }

        private async Task AcquireLock()
        {
            while (true)
            {
                var lockValue = await _redisDb.SetNXAsync(_redisLockKeyFormat, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());

                if (lockValue)
                    return; // Successfully acquired the lock

                await Task.Delay(TimeSpan.FromSeconds(5)); // Backoff strategy
            }
        }

        private void ReleaseLock()
        {
            _redisDb.KeyDelete(_redisLockKeyFormat);
        }
    }
