typedef struct Node {
    int value;
    struct Node *next;
} Node;

typedef struct List {
    unsigned int size;
    Node *head;
    unsigned int max_nodes;
    bool is_full;
} List;

List* create_list(unsigned int max_nodes) {
    List *list = malloc(sizeof(List));
    list->size = 0;
    list->max_nodes = max_nodes;
    list->head = NULL;
    list->is_full = false;
    return list;
}

Node* create_node(int value) {
    Node *node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }

    node->value = value;
    node->next = NULL;
    return node;
}

void insert_at(List *list, unsigned int position, Node *node) {
    if (position >= list->max_nodes || position < 0) {
        fprintf(stderr, "Invalid position to insert!\n");
        exit(EXIT_FAILURE);
    }

    if (position == 0) {
        node->next = list->head;
        list->head = node;
        ++list->size;
    } else {
        Node *current = list->head;
        for (unsigned int i = 0; i < position - 1; ++i) {
            if (!current) {
