public class ProcessWaitInfo : IDisposable
{
    private readonly Process _process;
    private int _pid;
    private bool _success;

    public ProcessWaitInfo(Process process, out int pid)
    {
        _process = process;
        _pid = 0;
        _success = false;
        Start();
        if (_process.HasExited)
        {
            _pid = _process.ExitCode;
            _success = true;
            _process.Dispose();
            return;
        }

        pid = 0;
    }

    public void Start()
    {
        // Use PInvoke to get the Process ID
        var kern32 = LoadLibrary("kernel32");
        var NtQueryInformationProcessEx = GetProcAddress(kern32, "NtQueryInformationProcess");
        IntPtr processHandle = OpenProcess(_process.Id, FOREGROUND_QUERY_LIMITED_INFO, _process.Handle);
        ProcessBasicInformation processInfo;
        Marshal.StructureToPtr(new ProcessBasicInformation(), out var infoPtr);
        uint result = (_delegate)NtQueryInformationProcessEx(processHandle, 0, infoPtr, (uint)Marshal.SizeOf<ProcessBasicInformation>(), out _);
        if (result == 0) throw new Exception("Failed to get process information.");
        Marshal.PtrToStructure(infoPtr, out processInfo);
        _pid = processInfo.UniqueProcessId;
        CloseHandle(processHandle);
    }

    private static IntPtr LoadLibrary(string dllName) => LoadLibraryExW(GetModuleHandleW(null), dllName, LOAD_LIBRARY_AS_DATAFILE | LOADER_AS_DATAFILE32 | LOADER_AS_DATAFILE64);

    [DllImport("kernel32.dll")]
    private static extern IntPtr LoadLibraryExW(IntPtr hFile, string lpFileName, uint dwFlags);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode)]
    private static extern IntPtr GetModuleHandleW(string lpModuleName);

    [DllImport("kernel32.dll")]
    private static extern IntPtr OpenProcess(int dwDesiredAccess, bool bInheritHandle, int dwProcessId);

    [DllImport("kernel32.dll")]
    private static extern IntPtr GetProcAddress(IntPtr hModule, string lpProcName);

    [DllImport("kernel32.dll")]
    private static extern bool CloseHandle(IntPtr hObject);

    [StructLayout(LayoutKind.Sequential)]
    private struct ProcessBasicInformation
    {
        public int UniqueProcessId; // PID of the process
    }

    private delegate uint NtQueryInformationProcessEx(IntPtr ProcessHandle, uint ProcessInformationClass, ref System.Runtime.InteropServices.SafeHandle RefProcessInformation, uint BufferLength, out uint ReturnLength);
}
