void processAndCacheFileChunks(const std::string& filePath, int chunkSize, int totalChunks, const std::shared_ptr<AsyncQueue>& workQueue, std::mutex& lock, std::condition_variable& cv, std::atomic<int>& completedChunks, std::ofstream* outputFileStream, bool useCompression) {
    this->filePath = filePath;
    this->chunkSize = chunkSize;
    this->totalChunks = totalChunks;
    this->workQueue = workQueue;
    this->lock = lock;
    this->cv = cv;
    this->completedChunks = completedChunks;
    this->outputFileStream = outputFileStream;
    this->useCompression = useCompression;

    chunks.resize(totalChunks);
    chunkKeys.reserve(totalChunks);

    for (size_t i = 0; i < totalChunks; ++i) {
        chunkKeys.push_back("chunk" + std::to_string(i));
    }

    boost::asio::io_service ioService;
    std::vector<boost::asio::streambuf> buffers(totalChunks);
    std::vector<boost::asio::async_read_streambuf> asyncReadStreamBufs(totalChunks);

    for (size_t i = 0; i < totalChunks; ++i) {
        asyncReadStreamBufs[i].reset(new boost::asio::streambuf());
        buffers[i].set_buffer(asyncReadStreamBufs[i].data(), chunkSize);
        workQueue->enqueue([&](auto e) {
            e.get_executor().post([&]() {
                boost::asio::ip::tcp::iostream stream;
                stream.expires_after(std::chrono::seconds(60)); // Set timeout for I/O operations

                try {
                    if (stream.open(filePath, std::ios::binary)) {
                        stream.async_read_some(boost::asio::buffer(buffers[i].data(), chunkSize), [&](boost::system::error_code ec, size_t) {
                            if (!ec) {
                                // Validate the read operation
                                if (buffers[i].data() == std::string(chunkSize, '\0').c_str()) {
                                    // Handle error cases gracefully
                                    std::cout << "Invalid chunk data" << std::endl;
                                    return;
                                }
                                lock.lock();
                                chunks[i].assign(buffers[i].data(), buffers[i].size());
                                lock.unlock();
                                completedChunks++;
                                cv.notify_one();
                            } else {
                                // Handle transient failures and retry logic
                                if (ec == boost::asio::error::operation_aborted) {
                                    return;
                                }
                                std::cout << "I/O error: " << ec.message() << std::endl;
                            }
                        });
                    } else {
                        // Handle file opening errors gracefully
                        std::cout << "Could not open the file" << std::endl;
                    }
                });
            });
        });
    }

    ioService.run();
}

void processChunk(const size_t& chunkIndex) {
    if (useCompression) {
        boost::beast::zlib::gzipstream compressedStream;
        compressedStream.put(chunks[chunkIndex].begin(), chunks[chunkIndex].end());
        *outputFileStream << compressedStream.get().data();
    } else {
        *outputFileStream << chunks[chunkIndex].begin(), chunks[chunkIndex].end();
    }
}
