void streamAndTransformData(const std::string& dataFilePath, int recordSize, int totalRecords, std::shared_ptr<AsyncQueue> workQueue, std::mutex& lock, std::condition_variable& cv, std::atomic<int>& processedRecords, std::ofstream* outputFileStream, const std::vector<std::function<void(const std::string&)>>& transformFunctions) {
    std::ifstream inputFileStream(dataFilePath, std::ios::in);
    if (!inputFileStream.is_open()) {
        std::cerr << "Error: Could not open file." << std::endl;
        return;
    }

    processedRecords.resize((totalRecords / recordSize) + (totalRecords % recordSize > 0 ? 1 : 0), std::vector<std::string>(recordSize));

    int currentRecord = 0;
    std::string line;
    while (std::getline(inputFileStream, line)) {
        if (line.size() != recordSize) {
            std::cerr << "Error: Record size mismatch." << std::endl;
            continue;
        }

        try {
            for (const auto& transformFunction : transformFunctions) {
                transformFunction(line);
            }

            *outputFileStream << line;
            ++processedRecordsCount;

            int checksum = std::accumulate(line.begin(), line.end(), 0, [](int sum, char c) { return sum + c; });
            processedRecords[currentRecord][recordSize] = checksum % 1000;
        } catch (const std::exception& e) {
            std::cerr << "Error: Transformation failed with exception: " << e.what() << std::endl;
        }

        ++currentRecord;
        workQueue->enqueue([this, line]() mutable {
            lock.lock();
            while (processedRecordsCount >= processedRecords.size()) {
                cv.wait(lock);
            }
            processedRecords[currentRecord - 1] = std::move(line);
            ++processedRecordsCount;
            lock.unlock();
        });
    }

    inputFileStream.close();
}
