std::vector<int> generateCoordinateIndices(int seed, int chunkSize, int totalChunks) {
    std::mt19937 generator(seed);
    std::uniform_int_distribution<> dist(-1000, 1000);
    std::vector<cv::Point> coordinates(chunkSize);
    for (size_t i = 0; i < coordinates.size(); ++i) {
        coordinates[i] = cv::Point(dist(generator), dist(generator));
    }

    std::mt19937 indexGenerator(seed + 1);
    std::uniform_int_distribution<> indexDist(1, 50);
    std::vector<int> indices;
    std::unordered_set<int> usedIndices;
    for (size_t i = 0; i < chunkSize; ++i) {
        int index;
        do {
            index = indexDist(indexGenerator);
        } while (usedIndices.find(index) != usedIndices.end());
        indices.push_back(index);
        usedIndices.insert(index);
    }
    return indices;
}

std::vector<imageRecord> processAndTransformImageStreams(int seed, int chunkSize, int totalChunks, int* streamDelay, bool useCompression, cv::Mat** images, int maxDataValue, int maxRecords) {
    std::vector<cv::Mat> imageChunks;
    std::vector<std::vector<imageRecord>> recordsPerChunk;
    std::mutex chunksMutex;
    std::condition_variable chunksCV;
    std::deque<std::function<void()>> tasks;
    std::vector<int> coordinateIndices = generateCoordinateIndices(seed, chunkSize, totalChunks);

    for (size_t i = 0; i < totalChunks; ++i) {
        int startIndex = i * chunkSize;
        int endIndex = (i + 1) * chunkSize;
        std::vector<imageRecord> recordsForChunk(endIndex - startIndex);
        recordsPerChunk.push_back(recordsForChunk);
    }

    for (size_t i = 0; i < images[0]->rows; ++i) {
        int chunkNum = i / chunkSize;
        cv::Mat imgChunk = images[0]->rowRange(i, i + chunkSize);
        imageChunks.push_back(imgChunk);
        tasks.push_back([=]() { processImageChunk(imgChunk, useCompression, recordsPerChunk[chunkNum], maxDataValue, maxRecords); });
    }

    std::thread workerThread([&]() {
        while (!tasks.empty()) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(chunksMutex);
                chunksCV.wait(lock, [&](){ return !tasks.empty(); });
                task = tasks.front();
                tasks.pop_front();
            }
            task();
            {
                std::unique_lock<std::mutex> lock(chunksMutex);
                chunksCV.notify_one();
            }
        }
    });

    for (size_t i = 0; i < imageChunks.size(); ++i) {
        recordsPerChunk[i / chunkSize][coordinateIndices[i] - 1].qualityScore = rand() % 101;
        recordsPerChunk[i / chunkSize][coordinateIndices[i] - 1].point = &imageChunks[i](rand() % imageChunks[i].rows, rand() % imageChunks[i].cols);
        recordsPerChunk[i / chunkSize][coordinateIndices[i] - 1].index = &coordinateIndices[i];
    }

    std::sort(recordsPerChunk.begin(), recordsPerChunk.end(), [](const auto& a, const auto& b) { return a.back().qualityScore > b.back().qualityScore; });

    workerThread.join();

    std::vector<imageRecord> finalRecords;
    for (const auto& chunk : recordsPerChunk) {
        finalRecords.insert(finalRecords.end(), chunk.begin(), chunk.end());
    }

    return finalRecords;
}
