public async Task AddWebsiteAsync(string directoryPath, string siteName)
{
    if (!Directory.Exists(directoryPath))
        throw new DirectoryNotFoundException($"The provided directory '{directoryPath}' does not exist.");

    var necessaryFiles = new[] { "web.config", "global.asax.cs", "global.asax.designer.cs" };

    foreach (var file in necessaryFiles)
        if (!File.Exists(Path.Combine(directoryPath, file)))
            throw new FileNotFoundException($"The provided directory '{directoryPath}' does not contain the required file '{file}'.");

    var webConfig = Path.Combine(directoryPath, "web.config");

    if (!File.Exists(webConfig) || !UserHasAdminPrivileges())
    {
        if (File.Exists(webConfig))
            return; // Site already has a custom configuration

        if (!UserHasAdminPrivileges())
            throw new UnauthorizedAccessException("The user does not have administrative privileges.");

        GenerateDefaultWebConfig(webConfig);
    }

    var startInfo = new ProcessStartInfo($"{Path.Combine(directoryPath, "wc.exe")}", $"/server:{siteName}")
                       { WorkingDirectory = directoryPath };

    var process = new Process
    {
        StartInfo = startInfo,
        StartInfo.UseShellExecute = false,
        StartInfo.RedirectStandardOutput = true,
        EnableRaisingEvents = true
    };

    var timeoutTokenSource = new CancellationTokenSource();
    var cancellationToken = timeoutTokenSource.Token;

    Task.Run(async () => await TimeoutTask(timeout: TimeSpan.FromMinutes(5), cancellationToken)).ContinueWith((t) =>
    {
        if (t.IsFaulted) return;

        if (!process.HasExited)
            timeoutTokenSource.Cancel();
    });

    try
    {
        process.Start();

        while (!process.HasExited && !cancellationToken.IsCancelled)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);
            if (process.HasExited) break;

            Log($"Checking site '{siteName}' status...");
            // You can add a call to check the status of the site here
        }
    }
    catch (Exception ex)
    {
        Log($"Error starting site '{siteName}': {ex.Message}", LogLevel.Error);

        for (int i = 0; i < 5; i++)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(i + 1), cancellationToken);
                StartSite(directoryPath, siteName);
                break;
            }
            catch (Exception ex2)
            {
                Log($"Retry #{i + 1}: Error starting site '{siteName}': {ex2.Message}", LogLevel.Error);
            }
        }
    }

    // You can add a call to validate domain ownership and SSL certificate here

    CleanUp(directoryPath, siteName);
    Log($"Site '{siteName}' added successfully.");
}

private bool UserHasAdminPrivileges()
{
    var key = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion");

    if (key == null) return false;

    var isAdmin = key.GetValue("ProductName") switch
    {
        "Professional" or "Server" or "Ultimate" => true,
        _ => false
    };

    return RuntimeInformation.IsOSPlatform(OSPlatform.Windows) && isAdmin;
}

private void GenerateDefaultWebConfig(string webConfigFile)
{
    using var writer = new StreamWriter(webConfigFile);

    writer.WriteLine("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
    writer.WriteLine("<configuration>");
    writer.WriteLine("  <system.web>");
    // You can add the necessary configuration settings here
    writer.WriteLine("  </system.web>");
    writer.WriteLine("</configuration>");
}

private void StartSite(string directoryPath, string siteName)
{
    var startInfo = new ProcessStartInfo($"{Path.Combine(directoryPath, "wc.exe")}", $"/server:{siteName}")
                       { WorkingDirectory = directoryPath };

    var process = new Process
    {
        StartInfo = startInfo,
        StartInfo.UseShellExecute = false,
        StartInfo.RedirectStandardOutput = true,
        EnableRaisingEvents = true
    };

    process.Start();
}

private void CleanUp(string directoryPath, string siteName)
{
    // You can add code to clean up temporary files or processes here
}

private void Log(string message, [CallerMemberName] string method = null, LogLevel level = LogLevel.Info)
{
    Console.WriteLine($"{DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff")}: [{method}] {message}");
}

private enum LogLevel
{
    Info,
