    public int Key { get; set; }
}

public struct UserRecordManager
{
    public int[] Offsets;
    public int[] Keys;
    public record[] Records;
}

public class EnhancedManageAndIndexUserRecords
{
    private const int MinKey = 1;
    private const int MaxKey = 50;
    private const int MaxRelevanceScore = 100;
    private const int RandomSeed = seed;
    private const int MaxDataValue = maxDataValue;
    private const int MaxRecords = maxRecords;

    private UserManager<IdentityUser> _userManager;
    private ILogger _logger;

    public EnhancedManageAndIndexUserRecords(UserManager<IdentityUser> userManager, ILogger logger)
    {
        _userManager = userManager;
        _logger = logger;
    }

    public async Task EnhancedManageAndIndexUserRecordsAsync(int seed, int chunkSize, int totalChunks, ref int streamDelay, bool useCompression, Stream outputStream, int maxDataValue, int maxRecords, ref UserRecordManager[] recordBuffers, IPerformanceLogger performanceLogger)
    {
        var random = new Random(seed);

        var offsets = new long[totalChunks * chunkSize];
        var keys = Enumerable.Range(1, totalChunks * chunkSize).ToArray();
        var records = new record[totalChunks * chunkSize];

        ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };

        Parallel.ForEach(Enumerable.Range(0, totalChunks), options, i =>
        {
            var startIndex = i * chunkSize;
            var endIndex = (i + 1) * chunkSize;

            for (int j = startIndex; j < endIndex; j++)
            {
                records[j].RelevanceScore = random.Next(MaxRelevanceScore);
                records[j].Offset = random.Next(long.MinValue, long.MaxValue) % MaxDataValue;
                records[j].Key = GetUniqueKey(keys);
            }
        });

        Array.Sort(records, (a, b) => b.RelevanceScore.CompareTo(a.RelevanceScore));

        int index = 0;
        for (int i = 0; i < records.Length; i++)
        {
            recordBuffers[index] = new UserRecordManager() { Offsets = offsets, Keys = keys, Records = new record[chunkSize] };

            for (int j = 0; j < chunkSize && index < totalChunks * chunkSize; j++, i++)
            {
                var record = records[i];
                recordBuffers[index].Records[j] = record;
                offsets[index++] = record.Offset;
                keys[record.Key - 1] = Int32.MinValue; // Mark key as used
            }
        }

        var compressedStream = useCompression ? outputStream : new DeflateStream(outputStream, CompressionLevel.Optimal);

        int chunkIndex = 0;
        int processedRecords = 0;

        while (processedRecords < totalChunks * chunkSize)
        {
            var currentChunkSize = Math.Min(chunkSize, totalChunks * chunkSize - processedRecords);

            for (int i = 0; i < recordBuffers.Length && processedRecords + currentChunkSize <= totalChunks * chunkSize; i++)
            {
                if (recordBuffers[i].Records.Length > 0)
                {
                    var recordsToProcess = Math.Min(currentChunkSize, recordBuffers[i].Records.Length);
                    Array.Copy(recordBuffers[i].Records, 0, _userManager.Users.AddAsync(new IdentityUser { UserName = $"User_{processedRecords}" }, null).Result.ToList().ToArray(), recordsToProcess);

                    performanceLogger.LogPerformance("Created user", processedRecords + recordsToProcess);

                    Array.Copy(recordBuffers[i].Offsets, 0, offsets, processedRecords, recordsToProcess);
                    Array.Copy(recordBuffers[i].Keys, 0, keys, processedRecords, recordsToProcess);

                    processedRecords += recordsToProcess;
                }
            }

            if (useCompression)
            {
                using (var memoryStream = new MemoryStream())
                {
                    await using var writer = new BinaryWriter(memoryStream);

                    // Write data to the compressed stream
                    // ...

                    await compressedStream.WriteAsync(memoryStream.ToArray());
                    await compressedStream.FlushAsync();
                }
            }
            else
            {
                await compressedStream.WriteAsync(_userManager.Users.Select(u => u).ToArray().AsMemory(unsafe => new Span<IdentityUser>(unsafe)));
            }

            if (streamDelay > 0)
                await Task.Delay(TimeSpan.FromMilliseconds(streamDelay));
        }
    }

    private int GetUniqueKey(int[] array)
    {
        for (int i = MinKey; i <= MaxKey; i++)
        {
            if (!array.Contains(i))
                return i;
        }

        throw new Exception("All keys are already used.");
    }
}
