void batchProcessAndAggregateData(const std::string& dataFilePath, int batchSize, int totalBatches, std::shared_ptr<AsyncQueue> workQueue, std::mutex& lock, std::condition_variable& cv, std::atomic<int> processedBatches, std::ofstream* outputFileStream, std::vector<std::function<void(const std::string&, int)>> aggregateFunctions) {
