        // Store the results in recordsPerBatch[batchIndex]
    }

    std::vector<int> metadata(totalBatches);

    for (size_t batchIdx = 0; batchIdx < recordsPerBatch.size(); ++batchIdx) {
        if (!recordsPerBatch[batchIdx].empty()) {
            parseAndValidateRecord(recordsPerBatch[batchIdx][0], metadata[batchIdx]);
            workQueue->enqueue([this, batchIdx, recordsPerBatch, metadata, outputFileStream, aggregateFunctions]() mutable {
