                applyAggregationFunctions(recordsPerBatch[batchIdx], aggregateFunctions);

                // Write the aggregated result to the output file stream
                (*outputFileStream) << recordsPerBatch[batchIdx][0] << ',' << metadata[batchIdx] << '\n';

                ++processedBatches;
                lock.lock();
                cv.notify_one();
                lock.unlock();
            });
        }
    }

    // Wait for all batches to be processed
    std::unique_lock<std::mutex> uniqueLock(lock);
    cv.wait(uniqueLock, [this]() { return processedBatches.load() == totalBatches; });
}
