public class WebAppStarter
{
    private readonly ILogger<WebAppStarter> _logger;
    private readonly IWebHostBuilder _webHostBuilder;

    public WebAppStarter(ILogger<WebAppStarter> logger, IWebHostBuilder webHostBuilder)
    {
        _logger = logger;
        _webHostBuilder = webHostBuilder;
    }

    public async Task<StartupResult> StartAsync(string directoryPath, string siteName)
    {
        DirectoryInfo dirInfo = new DirectoryInfo(directoryPath);
        if (!dirInfo.Exists || !dirInfo.GetFiles("web.config").Any())
        {
            _logger.LogInformation($"No web.config found in directory: {directoryPath}");
            return StartupResult.Failed("Invalid directory or missing web.config");
        }

        if (!IsPermitted(dirInfo))
        {
            _logger.LogError($"Insufficient permissions to start website in directory: {directoryPath}");
            return StartupResult.Failed("Insufficient permissions to start website");
        }

        var existingSites = await GetExistingSites();
        if (existingSites.Any(s => s.Port == GetPort(dirInfo) && s.HostName == GetHostName(dirInfo)))
        {
            _logger.LogError($"Conflicting site found: Port={GetPort(dirInfo)}, HostName={GetHostName(dirInfo)}");
            return StartupResult.Failed("Conflicting site found");
        }

        try
        {
            await EnsurePackagesInstalledAsync(dirInfo);
            using (var webHost = _webHostBuilder.SetContentRoot(directoryPath).UseIISIntegration().UseStartup<Startup>().Build())
            {
                var startupTask = webHost.RunAsynchronously();
                var taskCompletedEvent = new ManualResetEventSlim(false);
                var cts = new CancellationTokenSource();
                var timeoutToken = Task.Delay(-1, cts.Token).ContinueWith(_ => { cts.Cancel(); });

                StartupResult startupStatus;
                var started = await Task.WhenAny(startupTask, timeoutToken);
                if (started == startupTask)
                {
                    taskCompletedEvent.Wait(cancellationToken: cts.Token);
                    startupStatus = startupTask.Result;
                }
                else
                {
                    _logger.LogError($"Website failed to start within the specified time limit in directory: {directoryPath}");
                    startupStatus = StartupResult.Failed("Timeout while starting website");
                }

                if (startupStatus.Success)
                {
                    _logger.LogInformation($"Website started successfully on port: {GetPort(dirInfo)}, hostname: {GetHostName(dirInfo)}");
                    return startupStatus;
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"An error occurred while starting website in directory: {directoryPath}");
            return StartupResult.Failed("An error occurred while starting website");
        }

        // Retry up to three times
        for (int i = 1; i <= 3; i++)
        {
            if (await StartAsync(directoryPath, siteName).ConfigureAwait(false).Result.Success) return StartupResult.Successful("Website started after retries");
        }

        _logger.LogError($"Failed to start website in directory: {directoryPath} after three attempts");
        return StartupResult.Failed("Failed to start website after three attempts");
    }

    private static int GetPort(DirectoryInfo dirInfo) => int.Parse(new FileInfo(Path.Combine(dirInfo.FullName, "launchSettings.json")).Name.Split('_')[1]);
    private static string GetHostName(DirectoryInfo dirInfo) => $"http://localhost:{GetPort(dirInfo)}";

    private bool IsPermitted(DirectoryInfo dirInfo)
    {
        try
        {
            // Add your permissions check here, such as checking the user has read/write access to the specified directory.
            return true;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"An error occurred while checking permissions for directory: {dirInfo.FullName}");
            return false;
        }
    }

