void handleDynamicMemoryAndAsynchronousProcessing(const std::string& filePath, int chunkSize, int totalChunks, std::shared_ptr<AsyncQueue> workQueue, std::mutex& lock, std::condition_variable& cv, std::atomic_int completedChunks, std::ofstream* outputFileStream, const std::vector<std::function<void(const std::string&, int)>>& aggregateFunctions, bool useCompression, bool singleThreaded) {
    // Initialize memory for processing chunks or records
    std::vector<std::vector<char>> processedChunks;
    processedChunks.reserve(totalChunks);

    // Read data from file in chunks
    auto readData = [&](const std::filesystem::path& path) {
        std::ifstream inputStream(path, std::ios::binary);
        if (!inputStream) throw std::runtime_error("Error opening the file");
        std::vector<char> chunk(chunkSize);
        size_t bytesRead;
        while (inputStream.read(reinterpret_cast<char*>(chunk.data()), chunkSize)) {
            processedChunks.emplace_back(std::move(chunk));
            workQueue->push([&](auto) mutexScope {
                // Process each chunk asynchronously
                for (size_t i = 0; i < processedChunks.size(); ++i) {
                    if (singleThreaded) {
                        processSingleThreaded(processedChunks[i], aggregateFunctions, useCompression, lock, cv, completedChunks);
                    } else {
                        processMultiThreaded(processedChunks[i], i, aggregateFunctions, useCompression, lock, cv, completedChunks);
                    }
                }
            });
        }
        if (!inputStream.eof()) throw std::runtime_error("Error reading the file");
    };

    try {
        std::filesystem::path dataFilePath(filePath);
        dataFilePath += ".data";
        readData(dataFilePath);
    } catch (const std::exception& e) {
        // Handle errors gracefully
        std::cerr << "Error: " << e.what() << '\n';
    }

    // Write processed chunks to output stream, handle compression, and memory management
    if (outputFileStream) {
        auto writeData = [&](const std::vector<char>& data, const bool compress) {
            std::ostringstream os;
            size_t bytesWritten = 0;
            for (size_t i = 0; i < data.size(); ) {
                size_t bytesToWrite = std::min(data.size() - i, static_cast<size_t>(outputFileStream->precision() * outputFileStream->width()));
                os.write(reinterpret_cast<const char*>(data.data() + i), bytesToWrite);
                i += bytesToWrite;
                if (compress) {
                    gzwrite(reinterpret_cast<gzFile>(*outputFileStream), data.data() + i, static_cast<unsigned int>(data.size() - i));
                    i += gzflush(*outputFileStream);
                } else {
                    bytesWritten += *outputFileStream << std::noskipws >> os.str().c_str();
                }
            }
        };

        for (auto& chunk : processedChunks) {
            if (useCompression) {
                gzwrite(*outputFileStream, chunk.data(), static_cast<unsigned int>(chunk.size()));
            } else {
                writeData(chunk, false);
            }
        }
    }
}
