public async Task ManageAndIndexUserRecords(int seed, int chunkSize, int totalChunks, out int[] offsets, out IList<int> keys, out Record[] records, UserManager<IdentityUser> userManager)
{
    Random random = new Random(seed);
    offsets = Enumerable.Range(0, maxRecords).Select(_ => random.Next(-1000, 1000)).ToArray();
    keys = Enumerable.Repeat(0, totalChunks * chunkSize).Select((_, i) => i + 1).Distinct().ToList();
    records = new Record[maxRecords];

    ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
    Parallel.For(0, totalChunks, options, (int chunkIndex) =>
    {
        List<Record> chunkRecords = new List<Record>();

        for (int i = keys[chunkIndex] - 1; i < keys[chunkIndex + 1] && i < maxRecords; ++i)
        {
            int score = random.Next(0, 101);
            records[i].Score = score;
            records[i].Offset = offsets[i];
            records[i].Key = keys[chunkIndex];
            chunkRecords.Add(records[i]);
        }

        Sort(chunkRecords);
    });

    int currentKey = 1;
    for (int i = 0; i < maxRecords; ++i)
