typedef struct {
    int relevance;
    long *offset;
    int *key;
} Record;

void processUserRecords(int seed, int chunkSize, int totalChunks, int *streamDelay, bool useCompression, char **outputStream, int maxDataValue, int maxRecords) {
    // Initialize arrays and memory structures
    long *offsets = malloc((maxRecords + 1) * sizeof(long));
    int *keys = malloc((maxRecords + 1) * sizeof(int));
    Record *records = malloc(maxRecords * sizeof(Record));

    // Ensure uniqueness and proper initialization of offsets, keys, and records
    for (int i = 0; i < maxRecords; ++i) {
        offsets[i] = rand() % (2001);
        keys[i] = rand() % 51 + 1;

        bool uniqueKey = true;
        for (int j = 0; j < i; ++j) {
            if (keys[i] == keys[j]) {
                uniqueKey = false;
                break;
            }
        }

        if (!uniqueKey) {
            --i;
            break;
        }

        records[i].relevance = rand() % 101;
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    // Sort the array based on relevance score in descending order
    qsort(records, maxRecords, sizeof(Record), (int (*)(const void *, const void *))compareRecords);

    // Concurrent processing and validation
    pthread_t threads[totalChunks];
    sem_t sem;
    sem_init(&sem, 0, chunkSize);

    int chunkIndex = 0;
    for (int i = 0; i < totalChunks; ++i) {
        int result = pthread_create(&threads[i], NULL, processChunk, &seed, &chunkSize, &sem, records + chunkIndex, maxDataValue);
        if (result != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
        chunkIndex += chunkSize;
    }

    for (int i = 0; i < totalChunks; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Compression and streaming logic
    int compressBufferSize = chunkSize * sizeof(Record);
    char *compressedData = malloc(compressBufferSize);
    uLongf totalOut = 0;
    int fd = -1;

    if (useCompression) {
        gzFile outFile = gzopen(*outputStream, "wb");
        if (!outFile) {
            perror("gzopen");
            exit(EXIT_FAILURE);
        }

        fd = fileno(outFile);

        for (int i = 0; i < chunkSize * totalChunks; ++i) {
            z_stream strm;
            memset(&strm, 0, sizeof(z_stream));
            strm.zalloc = Z_NULL;
            strm.zfree = Z_NULL;
            strm.opaque = Z_NULL;
            strm.avail_in = compressBufferSize - totalOut;
            strm.next_in = compressedData + totalOut;
            strm.avail_out = compressBufferSize;
            strm.next_out = compressedData;

            int ret = deflateInit(&strm, Z_DEFAULT_COMPRESSION);
            if (ret != Z_OK) {
                perror("deflateInit");
                exit(EXIT_FAILURE);
            }

            memcpy(compressedData + totalOut, records[i].offset, sizeof(long));
            memcpy(compressedData + totalOut + sizeof(long), &records[i].key, sizeof(int));

            strm.next_in += sizeof(Record);
            strm.avail_in -= sizeof(Record);
            totalOut += sizeof(Record);

            ret = deflate(&strm, Z_NO_FLUSH);
            if (ret != Z_OK) {
                perror("deflate");
                exit(EXIT_FAILURE);
            }

            size_t written = write(fd, compressedData, totalOut);
            if (written != totalOut) {
                perror("write");
                exit(EXIT_FAILURE);
            }

            deflateEnd(&strm);
        }

        gzclose(outFile);
    } else {
        fd = open(*outputStream, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (fd < 0) {
            perror("open");
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < chunkSize * totalChunks; ++i) {
            int written = write(fd, records[i].offset, sizeof(long));
            if (written != sizeof(long)) {
                perror("write");
                exit(EXIT_FAILURE);
            }

            written = write(fd, &records[i].key, sizeof(int));
            if (written != sizeof(int)) {
                perror("write");
                exit(EXIT_FAILURE);
            }
        }

        close(fd);
    }

    // External API integration for identity verification
    // Implement retry policies with exponential backoff and session timeouts
    // ...

    // Memory cleanup
    free(offsets);
    free(keys);
    free(records);
    free(compressedData);
}
