void init_arrays(size_t *offsets, size_t offset_count, int *keys, size_t key_count, record **records, size_t record_count, int min, int max, int seed) {
    if (seed > 0) {
        srand(seed);
    } else {
        // Use current time as seed for random number generation in case no explicit seed is provided
        srand((unsigned int)time(NULL));
    }

    *offsets = (long*)malloc(offset_count * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Error allocating memory for offsets array.\n");
        exit(EXIT_FAILURE);
    }

    *keys = (int*)malloc(key_count * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Error allocating memory for keys array.\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = malloc(record_count * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Error allocating memory for records array.\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    // Initialize offsets with consecutive integers, starting from 0.
    for (size_t i = 0; i < offset_count; ++i) {
        (*offsets)[i] = i;
    }

    // Shuffle the offsets array to distribute the keys randomly.
    for (size_t i = offset_count - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        long temp = (*offsets)[i];
        (*offsets)[i] = (*offsets)[j];
        (*offsets)[j] = temp;
    }

    // Initialize keys with the corresponding random values within the specified range.
    for (size_t i = 0; i < offset_count; ++i) {
        (*keys)[(*offsets)[i]] = rand() % (max - min + 1) + min;
    }

    // Initialize records with random values within the specified range.
    for (size_t i = 0; i < record_count; ++i) {
        (*records)[i].value = rand() % (max - min + 1) + min;
    }
}
