#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Custom allocator, optimized for large datasets
typedef struct custom_mem_allocator {
    void *memory_start;
    size_t memory_size;
    size_t allocated_memory;
    pthread_mutex_t lock;
} custom_mem_allocator_t;

void* custom_mem_allocate(custom_mem_allocator_t* allocator, size_t size) {
    if (allocator->allocated_memory + size > allocator->memory_size) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    pthread_mutex_lock(&allocator->lock);
    void* result = allocator->memory_start;
    allocator->memory_start += size;
    allocator->allocated_memory += size;
    pthread_mutex_unlock(&allocator->lock);

    return result;
}

void custom_mem_deallocate(custom_mem_allocator_t* allocator, void* ptr) {
    if (ptr < allocator->memory_start || ptr >= allocator->memory_end) {
        fprintf(stderr, "Invalid pointer\n");
        return;
    }

    pthread_mutex_lock(&allocator->lock);
    allocator->allocated_memory -= size;
    allocator->memory_start = ptr;
    pthread_mutex_unlock(&allocator->lock);
}
