Record* create_records(size_t n, int min, int max, time_t* seed) {
    if (n <= 0) return NULL;

    size_t record_size = sizeof(int) + sizeof(char) * 64;
    Record* records = malloc(n * record_size);
    if (!records) return NULL;

    int* keys = calloc(n + 1, sizeof(int));
    if (!keys) {
        free(records);
        return NULL;
    }

    // Initialize keys array with sequential values starting from 0.
    for (size_t i = 0; i < n; ++i)
        keys[i] = i;

    // Set keys[n] to a sentinel value to keep it separate from user-defined keys.
    keys[n] = -1;

    srand(*seed);

    // Initialize records array with random int values and unique strings.
    for (size_t i = 0; i < n; ++i) {
        Record* record = &records[i];
        record->key = min + rand() % (max - min + 1);
        char prefix[] = "REC_";
        size_t len = strlen(prefix);
        size_t str_len = len + i + 1; // Add index and 1 for null terminator.
        record->str = malloc(str_len);
        if (!record->str) {
            free(keys);
            free(records);
            return NULL;
        }

        memcpy(record->str, prefix, len);
        record->str[len] = '*'; // Replace with index to minimize memory overhead.
        record->str[len + i] = '\0';
    }

    return records;
}
