// Custom Memory Pool for efficient memory usage
class MemoryPool {
public:
    MemoryPool() = default;
    ~MemoryPool() { free(_pool); }

    void* allocate(size_t size) {
        if (_current == _end) {
            _current = std::malloc(_blockSize * _alignment);
            if (!_current) return nullptr;

            _pool.push_back(_current);
            _end = _current + _blockSize * _alignment;
            _current += _alignment;
        }
        void* result = _current;
        _current += size + _alignment;
        return result;
    }

private:
    std::vector<void*> _pool;
    static constexpr size_t _blockSize = 1024 * 64; // 64KB block size
    static constexpr size_t _alignment = 16;        // Align memory on 16-byte boundaries
    void* _pool = nullptr;
    void* _current = nullptr;
    void* _end = nullptr;
};

