#include <string.h>

#define TABLE_SIZE 1024 // Adjust as needed for better trade-off between space complexity and access speed

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct HashTable {
    Record** data;
    int capacity;
    pthread_mutex_t mutex;
} HashTable;

HashTable* create_hash_table() {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->capacity = TABLE_SIZE;
    table->data = calloc(TABLE_SIZE, sizeof(Record*));
    if (!table->data) {
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

int hash_function(const int key, const int capacity) {
    return key % capacity;
}

Record* create_record(int key, long offset) {
    Record* record = malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->offset = offset;
    return record;
}

void insert(HashTable* table, int key, long offset) {
    pthread_mutex_lock(&table->mutex);
    int hash_index = hash_function(key, table->capacity);
    Record* new_record = create_record(key, offset);
    if (!new_record) {
        pthread_mutex_unlock(&table->mutex);
        return;
    }
    if (table->data[hash_index] == NULL) {
        table->data[hash_index] = new_record;
    } else {
        Record* current = table->data[hash_index];
        Record* prev = NULL;
        while (current != NULL && current->key < key) {
            prev = current;
            current = current->next;
        }
        if (current == NULL || current->key > key) {
            if (prev == NULL) {
                new_record->next = table->data[hash_index];
                table->data[hash_index] = new_record;
            } else {
                prev->next = new_record;
                new_record->next = current;
            }
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

Record* find(const HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    int hash_index = hash_function(key, table->capacity);
    Record* current = table->data[hash_index];
    while (current != NULL && current->key < key) {
        current = current->next;
    }
    if (current != NULL && current->key == key) {
        pthread_mutex_unlock(&table->mutex);
        return current;
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

void iterate(const HashTable* table, void (*func)(Record*)) {
    pthread_mutex_lock(&table->mutex);
    for (int i = 0; i < table->capacity; ++i) {
        Record* current = table->data[i];
        while (current != NULL) {
            Record* temp = current;
            current = current->next;
            func(temp);
            free(temp);
        }
    }
    pthread_mutex_unlock(&table->mutex);
}
```

