    HashTable* hash = malloc(sizeof(HashTable));
    hash->capacity = capacity;
    hash->size = 0;
    hash->table = calloc(capacity, sizeof(Image*));
    hash->lock = PTHREAD_MUTEX_INITIALIZER;
    return hash;
}

int hash_function(const char* id, int capacity) {
    unsigned long hash = 5381;
    int len = strlen(id);
    for (int i = 0; i < len; ++i)
        hash = ((hash << 5) + hash) + id[i];
    return hash % capacity;
}

