    pthread_mutex_lock(&hash->lock);
    if (hash->table[index] != NULL) {
        insert_image(hash, id, data_buffer, metadata); // Recursively handle collisions using open addressing or chaining
    } else {
        hash->table[index] = create_image(id, data_buffer, metadata);
        ++hash->size;
    }
    pthread_mutex_unlock(&hash->lock);
}

