    int index = hash_function(id, hash->capacity);
    pthread_mutex_lock(&hash->lock);
    Image* img = hash->table[index];
    if (img != NULL) {
        Image* result = img;
        img = img->next; // Handle chaining or open addressing for collision resolution
        pthread_mutex_unlock(&hash->lock);
        return result;
    } else {
        pthread_mutex_unlock(&hash->lock);
        return NULL;
    }
}

void update_image(HashTable* hash, const char* id, void* new_data_buffer) {
    Image* img = get_image(hash, id);
    if (img != NULL) {
        pthread_mutex_lock(&img->lock);
        if (new_data_buffer != img->data_buffer) {
            free(img->data_buffer);
            img->data_buffer = new_data_buffer;
        }
        pthread_mutex_unlock(&img->lock);
