typedef struct Record {
    int key;
    char* str;
} Record;

Record* manage_memory(int n, int min, int max, unsigned long seed) {
    pthread_mutex_t keys_lock = PTHREAD_MUTEX_INITIALIZER;
    Record* records = malloc(n * sizeof(Record));
    int* keys = calloc(n + 1, sizeof(int));
    if (!records || !keys) {
        free(records);
        free(keys);
        return NULL;
    }

    // Custom memory pool for strings
    void* arena = mmap(NULL, 1024 * 1024, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (arena == MAP_FAILED) {
        free(records);
        free(keys);
        return NULL;
    }

    pthread_mutex_t string_lock = PTHREAD_MUTEX_INITIALIZER;
    char* string_pool = arena + 0;
    size_t string_index = 0;

    // Initialize keys and records
    for (int i = 0; i < n; ++i) {
        pthread_mutex_lock(&keys_lock);
        while (keys[i] != 0)
            pthread_mutex_unlock(&keys_lock);
        keys[i] = i;
        pthread_mutex_unlock(&keys_lock);

        records[i].key = rand() % (max - min + 1) + min;
        records[i].str = string_pool + string_index;
        string_index += sprintf(string_pool + string_index, "%d_%u", i, pthread_self());
    }

    // Cleanup on error or early termination
    void (*cleanup)(void*) = [](void* ptr) {
        munmap(arena, 1024 * 1024);
        free(keys);
        free(records);
        free(ptr);
    };

    return [records, keys, cleanup];
}
```

