// Custom memory pool structure
typedef struct MemoryPool_ {
    void* free_list;
    size_t aligned_size;
    pthread_mutex_t lock;
} MemoryPool;

// Helper functions for MemoryPool
void* mempool_alloc(MemoryPool* pool, size_t size);
void mempool_free(MemoryPool* pool, void* ptr);
void mempool_init(MemoryPool* pool, size_t aligned_size);

// Complex object structure
typedef struct Object_ {
    int id;
    char* name;
    struct MetadataNode_* metadata;
} Object;

// Metadata node structure
typedef struct MetadataNode_ {
    void* value;
    struct MetadataNode_* next;
} MetadataNode;

// Helper functions for objects and metadata nodes
void init_objects(Object*, int, MemoryPool*, int, bool);
char* str_alloc(size_t len, bool on_stack);
MetadataNode* node_alloc();
void node_free(MetadataNode*);

// Multi-reader single-writer lock mechanism
pthread_rwlock_t rwlock;

MemoryPool memory_pool;
Object* objects;
int* ids;
size_t num_objects;
bool include_metadata;

void manage_memory(int n, int min, int max, bool includeMetadata) {
    // Initialize memory pool and locks
    mempool_init(&memory_pool, sizeof(void*) * alignof(void*));
    pthread_rwlock_init(&rwlock, PTHREAD_RWLOCK_DEFAULT);

    // Allocate memory for ids and objects arrays
    ids = (int*)mempool_alloc(&memory_pool, sizeof(int) * n);
    objects = (Object*)mempool_alloc(&memory_pool, sizeof(Object) * n);

    // Initialize parameters
    num_objects = n;
    include_metadata = includeMetadata;

    // Initialize objects with random IDs and names, and metadata nodes if required
    init_objects(objects, n, &memory_pool, min, max, includeMetadata);
}

void init_objects(Object* obj, int n, MemoryPool* pool, int min, int max, bool includeMetadata) {
    for (int i = 0; i < n; ++i) {
        // Initialize ID and name
        obj[i].id = ids[i];
        obj[i].name = str_alloc(64, false);
        snprintf(obj[i].name, 64, "[%d]", i);

        if (includeMetadata) {
            // Allocate and initialize metadata nodes if required
            obj[i].metadata = node_alloc();
        }
    }
}

void* mempool_alloc(MemoryPool* pool, size_t size) {
    void* ptr;
    pthread_mutex_lock(&pool->lock);
    if (pool->free_list) {
        ptr = pool->free_list;
        pool->free_list = *(void**)(pool->free_list);
    } else {
        ptr = malloc(size + pool->aligned_size - size % alignof(void*));
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void mempool_free(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    *(void**)ptr = pool->free_list;
    pool->free_list = ptr;
    pthread_mutex_unlock(&pool->lock);
}

void mempool_init(MemoryPool* pool, size_t aligned_size) {
    pool->aligned_size = aligned_size;
    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}
```

