#include <unistd.h>

// Node structure definition
typedef struct node {
    int id;
    float health_metrics[NUM_METRICS];
    int last_maintenance_status;
} Node;

// Global variables
Node* nodes;
size_t num_nodes = 0;
size_t capacity = 0;
pthread_mutex_t mutex;

void add_node(int id, const float* metrics, int status) {
    if (num_nodes == capacity) {
        resize();
    }
    Node* node = &nodes[num_nodes];
    node->id = id;
    memcpy(node->health_metrics, metrics, sizeof(float) * NUM_METRICS);
    node->last_maintenance_status = status;
    num_nodes++;
}

void resize() {
    capacity *= 2;
    Node* new_nodes = realloc(nodes, capacity * sizeof(Node));
    if (!new_nodes) {
        fprintf(stderr, "Failed to allocate memory for node array\n");
        exit(EXIT_FAILURE);
    }
    nodes = new_nodes;
}

void* find_node_by_id(int id) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_nodes; ++i) {
        if (nodes[i].id == id) {
            pthread_mutex_unlock(&mutex);
            return &nodes[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}
