    char line[1024];
    size_t idx = 0;
    while (fgets(line, sizeof(line), fp)) {
        MatchResult* result = &books[idx++];
        if (regcomp(&old_testament_regex, line, REG_EXTENDED | REG_ICASE) != 0) {
            fprintf(stderr, "Error compiling regex\n");
            exit(1);
        }
        result->count = 0;
    }
    fclose(fp);

    // Match books in the provided text string
    char* text = getenv("TEXT_STRING");
    char* words[128];
    int num_words = 0;
    char word[128];
    regmatch_t match;
    regexec(&old_testament_regex, text, 0, &match, 0);

    while (regexec(&old_testament_regex, text, REG_OFFSET + 1, &match, 0)) {
        word[match.rm_eo - match.rm_so] = '\0';
        words[num_words++] = strdup(text + match.rm_so);
        text += match.rm_eo;
    }

    for (int i = 0; i < num_words; ++i) {
        MatchResult* result = &books[idx++];
        strcpy(result->keyword, words[i]);
        ++result->count;
    }
}

