    typedef struct {
        time_t timestamp;
        struct Metric *metrics; // dynamic array of metrics, size determined at runtime based on chunkSize and maxSamples
    } Timestamp;

    void processAndStoreMetrics(int seed, int chunkSize, int totalChunks, int *samplingRate, bool *useAggregation, double **dataStream, int maxValue, int maxSamples, int *windowSize) {
        srand(seed);

        // Allocate memory for timestamp and metric arrays
        Timestamp *timestamps = malloc(totalChunks * chunkSize * sizeof(Timestamp));
        Metric *metrics = malloc(maxSamples * totalChunks * chunkSize * sizeof(Metric));

        if (!timestamps || !metrics) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(1);
        }

        // Initialize timestamp and metric arrays with random timestamps and metrics
        for (int i = 0; i < totalChunks * chunkSize; ++i) {
            timestamps[i].timestamp = rand() % MAX_TIMESTAMP_RANGE + MIN_TIMESTAMP_RANGE;
            metrics[i].value = ((double)rand() / RAND_MAX) * maxValue;
            metrics[i].timestamp = &timestamps[i];
            metrics[i].validated = false;
        }

        // Process each chunk, applying aggregation if useAggregation is true
        for (int i = 0; i < totalChunks; ++i) {
            int startIndex = i * chunkSize;
            int endIndex = (i == totalChunks - 1) ? totalChunks * chunkSize : (i + 1) * chunkSize;

            if (*useAggregation) {
                // Aggregate data points within each chunk using moving average over windowSize
                for (int j = startIndex; j < endIndex; ++j) {
                    int windowStart = (j + windowSize - 1) % totalChunks * chunkSize;
                    double sum = 0.0;
                    int count = 0;

                    for (int k = windowStart; k < endIndex && k < windowStart + windowSize; ++k) {
                        if (!metrics[k].validated) continue;
                        sum += metrics[k].value;
                        ++count;
                    }

                    if (count > 0) {
                        Metric *aggregatedMetric = &metrics[j];
                        aggregatedMetric->value = sum / count;
                        if (aggregatedMetric->value > THRESHOLD) {
                            // Store the aggregated value if it exceeds the threshold
                            *dataStream = realloc(*dataStream, sizeof(double) * (*dataStream_size + 1));
                            (*dataStream)[*dataStream_size] = aggregatedMetric->value;
                            ++*dataStream_size;
                        }
                    }
                }
            }

            // Validate data points within each chunk, handle transient failures and partial successes
            for (int j = startIndex; j < endIndex; ++j) {
                Metric *metric = &metrics[j];

                if (!validateMetric(metric)) {
                    // Retry logic to handle transient failures or use an alternative data source
                    continue;
                }

                metric->validated = true;
            }
        }

        free(metrics);
        free(timestamps);
    }
