public class WebsiteManager
{
    private readonly string _rootDirectory;
    private SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
    private readonly ILogger _logger;

    public WebsiteManager(string rootDirectory, ILogger logger)
    {
        _rootDirectory = rootDirectory;
        _logger = logger;
    }

    public async Task<Process> AddAndStartWebsiteAsync(string siteName)
    {
        var websiteDirectory = Path.Combine(_rootDirectory, siteName);

        if (!Directory.Exists(websiteDirectory)) return null;

        if (!File.Exists(Path.Combine(websiteDirectory, "web.config"))) return null;

        await _semaphore.WaitAsync();
        try
        {
            var process = StartWebsite(siteName);

            if (process.Start())
            {
                _logger.LogAddingSiteSuccess(siteName, DateTime.UtcNow);
                return process;
            }

            _logger.LogAddingSiteFailure(siteName, DateTime.UtcNow, process.ExitCode);
            return null;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private Process StartWebsite(string siteName)
    {
        var websiteProcess = new Process
        {
            StartInfo = new ProcessStartInfo
            {
                FileName = "path_to_your_website_executable",
                Arguments = $"{siteName}",
                WorkingDirectory = Path.Combine(_rootDirectory, siteName),
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true
            },
        };

        // Add error handling to check for potential external dependencies or configuration changes that might affect the website's ability to start successfully.
        // Log detailed information about each attempt to add a site, including timestamps and any errors encountered.

        return websiteProcess;
    }
}
