    std::vector<int> indices;
    std::vector<imageRecord> records;
    std::mutex coordMutex, idxMutex;

    // Generate coordinates and indices
    for (size_t i = 0; i < totalChunks * chunkSize; ++i) {
        std::unique_lock<std::mutex> coordLock(coordMutex);
        int x = static_cast<int>(coordDist(seedGen));
        int y = static_cast<int>(coordDist(seedGen));
        cv::Point point{x, y};
        coordinates.push_back(point);

        std::unique_lock<std::mutex> idxLock(idxMutex);
        int idx = idxDist(seedGen);
        indices.push_back(idx);
    }

    // Ensure unique indices and sort records by quality score
    std::sort(records.begin(), records.end(), [](const imageRecord& a, const imageRecord& b) { return a.qualityScore > b.qualityScore; });

    for (size_t i = 0; i < totalChunks; ++i) {
        int startIdx = i * chunkSize;
        int endIdx = std::min((i + 1) * chunkSize, totalChunks * chunkSize);

        // Process and transform the image chunk
