                }, idx, inputImages[i], maxDataValue, streamDelay);
            } else {
                compressedTask = std::async(std::launch::none, []() {});
            }

            tasks.push_back(compressedTask);
        }

        // Wait for all tasks to complete and handle exceptions if needed
        for (auto& task : tasks) {
            try {
                task.wait();
            } catch (const std::exception& e) {
                // Handle exception here, such as retrying or logging the error
            }
        }

        // Add processed image records to outputRecords
        size_t j = 0;
        for (size_t i = startIdx; i < endIdx; ++i) {
            if (!tasks[j].valid()) throw std::runtime_error("Task not valid");

            imageRecord* record = new imageRecord{};
