import os
import sys
import json
from cryptography.fernet import Fernet
from time import sleep
import tempfile
import logging
from shutil import copyfile, move

def validate_dict(config_dict):
    for key in config_dict:
        if not key.isalpha() or key.islower():
            raise ValueError("Invalid placeholder name. Must be lowercase alphabetic.")
        if isinstance(config_dict[key], str) and len(config_dict[key]) > 255:
            raise ValueError("Placeholder value exceeds the maximum length of 255 characters.")

def get_encryption_key():
    encryption_key = os.getenv("ENCRYPTION_KEY")
    if not encryption_key:
        logging.error("Encryption key is not set. Exiting...")
        sys.exit(1)
    return Fernet(encryption_key)

def log_operation(message):
    with open("/path/to/audit_log.txt", "a") as log_file:
        log_file.write(f"{message}\n")

def replace_placeholders(config_file, config_dict):
    with open(config_file) as file:
        data = file.readlines()

    new_data = []
    for line in data:
        for key, value in config_dict.items():
            if f"${key}" in line:
                new_data.append(line.replace(f"${key}", value))
                break
        else:
            new_data.append(line)

    return new_data

def encrypt_password(password):
    encryption_key = get_encryption_key()
    f = Fernet(encryption_key)
    encrypted_password = f.encrypt(password.encode()).decode()
    return encrypted_password

def check_file_permissions(filepath):
    if not os.access(filepath, os.W_OK):
        logging.error(f"Insufficient permissions for '{filepath}'. Exiting...")
        sys.exit(1)

def main():
    config_file = "/etc/sysconfig/kickstart"
    audit_log = "/path/to/audit_log.txt"

    try:
        with open("/path/to/config_dict.json") as json_file:
            config_dict = json.load(json_file)
            validate_dict(config_dict)
    except Exception as e:
        logging.error(f"Error in loading or validating configuration dictionary: {str(e)}")
        sys.exit(1)

    password = config_dict["system_password"]
    encrypted_password = encrypt_password(password)
    new_data = replace_placeholders(config_file, config_dict)
    new_data.append(f"KICKSTART_PASSWORD=${encrypted_password}")

    with tempfile.TemporaryFile() as temp:
        for line in new_data:
            temp.write(line.encode())
        temp.seek(0)

        check_file_permissions(config_file)

        attempts = 3
        while True:
            try:
                copyfile(temp, config_file)
                log_operation(f"Successfully updated {config_file}")
                break
            except Exception as e:
                attempts -= 1
                if not attempts:
                    logging.error(f"Failed to update {config_file}. Error: {str(e)}")
                    sys.exit(1)
                log_operation(f"Attempting to update {config_file} (attempt {attempts})...")
                sleep(5)

if __name__ == "__main__":
    main()
