using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace YourApplicationNameSpace
{
    public class WebServiceManager
    {
        private readonly ILogger<WebServiceManager> _logger;
        private readonly IDistributedCache _distributedCache;
        private readonly IConfiguration _configuration;
        private readonly TimeSpan _retryDelay;
        private readonly int _maxRetries;

        public WebServiceManager(
            ILogger<WebServiceManager> logger,
            IDistributedCache distributedCache,
            IConfiguration configuration)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _distributedCache = distributedCache ?? throw new ArgumentNullException(nameof(distributedCache));
            _configuration = configuration;

            _retryDelay = TimeSpan.FromSeconds(_configuration["RetryIntervalSeconds"]);
            _maxRetries = int.Parse(_configuration["MaxRetries"]);
        }

        public async Task<WebServiceModule> InitializeModuleAsync()
        {
            var moduleTypeName = _configuration["ModuleType"];
            var assemblyName = _configuration["AssemblyName"];
            var serviceJsonKey = "service.json";

            if (!IsFrameworkCompatible()) return null;
            if (! await TryAcquireLock(serviceJsonKey)) return null;

            try
            {
                var assembly = LoadAssembly(assemblyName);
                if (assembly == null) return null;

                var moduleType = assembly.GetTypes().FirstOrDefault(t => t.Name == moduleTypeName);
                if (moduleType == null) return null;

                var serviceJsonContent = await LoadServiceJsonAsync(serviceJsonKey);
                if (string.IsNullOrEmpty(serviceJsonContent)) return null;

                var moduleInstance = (WebServiceModule)Activator.CreateInstance(moduleType);
                moduleInstance.Initialize(JsonConvert.DeserializeObject<ServiceConfiguration>(serviceJsonContent));

                ReleaseLock(serviceJsonKey);
                _logger.LogInformation("Successfully initialized web service module.");
                return moduleInstance;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to initialize web service module.");
                ReleaseLock(serviceJsonKey);
            }

            return RetryInitializationAsync();
        }

        private Assembly LoadAssembly(string assemblyName)
        {
            var assemblies = AppDomain.CurrentDomain.GetAssemblies();
            return assemblies.FirstOrDefault(a => a.GetName().Name == assemblyName);
        }

        private async Task<string> LoadServiceJsonAsync(string key)
        {
            var content = await _distributedCache.GetStringAsync(key);
            if (content != null) return content;

            var serviceJsonFilePath = _configuration[$"{key}.Path"];
            if (!File.Exists(serviceJsonFilePath)) return string.Empty;

            using (var reader = new StreamReader(serviceJsonFilePath))
            {
                return await reader.ReadToEndAsync();
            }
        }

        private bool IsFrameworkCompatible()
        {
            // Implement a logic to check if the current application framework version is compatible with the module's requirements.
            // Return false if incompatible, otherwise true.
        }

        private async Task<bool> TryAcquireLock(string key)
        {
            using (var transactionScope = new TransactionScope(TransactionScopeOption.RequiresNew))
            {
                var lockId = Guid.NewGuid().ToString();
                _distributedCache.SetStringAsync(key, lockId, TimeSpan.MaxValue);

                if (_distributedCache.GetStringAsync(lockId) == lockId)
                {
                    transactionScope.Complete();
                    return true;
                }

                await Task.Delay(_retryDelay);
                return TryAcquireLock(key);
            }
        }

        private void ReleaseLock(string key) => _distributedCache.Remove(key);

        private async Task<WebServiceModule> RetryInitializationAsync()
        {
            var retries = 0;
            while (retries < _maxRetries)
            {
                try
                {
                    return await InitializeModuleAsync();
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to initialize web service module. Retry {RetryNumber}", retries + 1);
                    await Task.Delay(_retryDelay * Math.Pow(2, retries));
                    retries++;
                }
            }

            _logger.LogError("Maximum retries reached. Giving up on initializing web service module.");
            return null;
        }
    }
}
