}

private void ManageMemoryStructures(bool sortInAscending)
{
    const int maxElements = 100000;
    Record[] records = new Record[maxElements];
    AuxRecord[] auxRecords = new AuxRecord[maxElements];
    long[] offsets = new long[maxElements];
    int[] keys = new int[maxElements];

    // Initialize offsets, keys, and pointers in records and auxRecords with random values
