    for (int i = 0; i < maxElements; i++)
    {
        records[i].Value = random.Next(0, 101);
        offsets[i] = random.Next(-1000, 1001);
        keys[i] = random.Next(1, 51) + 50 * (i / 100); // Ensure unique keys within each group of 100 elements

        records[i].Offset = offsets[i];
        records[i].Key = keys[i];

        auxRecords[i].Value = random.Next(51, 101);
        auxRecords[i].OffsetPointer = offsets[i].ToString();
        auxRecords[i].KeyPointer = keys[i].ToString();
    }

