        if (!long.TryParse(records[i].OffsetPointer, out long offset) || !int.TryParse(records[i].KeyPointer, out int key))
            throw new InvalidDataException("Invalid pointer values in records");

        if (offsets[offset] != i || keys[key] != i)
            throw new InvalidDataException("Dangling pointers in records");
    }

    for (int i = 0; i < maxElements; i++)
    {
        if (!long.TryParse(auxRecords[i].OffsetPointer, out long auxOffset) || !int.TryParse(auxRecords[i].KeyPointer, out int auxKey))
            throw new InvalidDataException("Invalid pointer values in auxRecords");

        if (offsets[auxOffset] != i || keys[auxKey] != i)
            throw new InvalidDataException("Dangling pointers in auxRecords");
