std::vector<cv::Point> generateCoordinates(int maxDataValue) {
    std::vector<cv::Point> coordinates(totalChunks);
    std::default_random_engine generator(seed);
    std::uniform_int_distribution<int> distribution(-1000, 1000);

    for (size_t i = 0; i < coordinates.size(); ++i) {
        coordinates[i] = cv::Point(distribution(generator), distribution(generator));
    }
    return coordinates;
}

std::vector<int> generateIndices(int maxDataValue) {
    std::vector<int> indices(totalChunks);
    std::default_random_engine generator(seed);
    std::uniform_int_distribution<int> distribution(1, 50);

    std::map<int, bool> usedIndices;
    for (size_t i = 0; i < indices.size(); ++i) {
        int index;
        do {
            index = distribution(generator);
        } while (usedIndices[index]);
        usedIndices[index] = true;
        indices[i] = index;
    }
    return indices;
}

void processAndTransformImageStreams(int seed, int chunkSize, int totalChunks, int *streamDelay,
                                      bool useCompression, cv::Mat **imageData, int maxDataValue,
                                      int maxRecords, imageRecord **imageRecords) {
    std::vector<cv::Point> coordinates = generateCoordinates(maxDataValue);
    std::vector<int> indices = generateIndices(totalChunks);
    std::vector<imageRecord> records;

    for (size_t i = 0; i < totalChunks; ++i) {
        imageRecord record;
        record.qualityScore = rand() % 101;
        record.coordinate = &coordinates[i];
        record.index = &indices[i];
        records.push_back(record);
    }

    std::sort(records.begin(), records.end(), [](const imageRecord &l, const imageRecord &r) {
        return l.qualityScore > r.qualityScore;
    });

    std::atomic<int> currentChunkIndex{0};
    std::mutex chunkSync;

    auto compressImage = [&](cv::Mat &image, bool useCompression) {
        if (useCompression && image.total() > 1e9) {
            cv::Mat compressedImage;
            // Compressing code here
            if (!compressedImage.empty()) {
                return compressedImage;
            } else {
                std::cout << "Failed to compress image, reallocating memory" << std::endl;
                cv::Mat tempImage(image);
                // Reallocate memory here
            }
        }
        return image;
    };

    auto processChunk = [&](int chunkIndex) {
        imageRecord &record = records[chunkIndex];
        cv::Mat *imageDataPtr = imageData[*record.index];
        imageDataPtr->copyTo(imageDataPtr); // Stream the data as-is if not using compression

        if (useCompression) {
            *imageDataPtr = compressImage(*imageDataPtr, useCompression);
        }

        std::this_thread::sleep_for(std::chrono::milliseconds(*streamDelay[chunkIndex]));
    };

    auto processChunks = [&]() {
        std::deque<int> chunkQueue;
        for (size_t i = 0; i < totalChunks; ++i) {
            chunkQueue.push_back(i);
        }

        while (!chunkQueue.empty()) {
            std::unique_lock<std::mutex> lock(chunkSync);
            int currentChunkIndex;
            if (currentChunkIndex < totalChunks && !chunkQueue.empty()) {
                currentChunkIndex = chunkQueue.front();
                chunkQueue.pop_front();
            } else {
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
                lock.lock();
            }

            if (currentChunkIndex < totalChunks) {
                processChunk(currentChunkIndex);
            }
        }
    };

    std::thread processingThread(processChunks);

    try {
        processingThread.join();
    } catch (const std::exception &e) {
        std::cerr << "An error occurred during image processing: " << e.what() << std::endl;
    }

    *imageData = nullptr;
    *imageRecords = records.data();
}
