} lte_ue_context;

typedef struct lte_ue_context_array {
    lte_ue_context *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    uint64_t max_ue_id;
} lte_ue_context_array;

lte_ue_context_array* create_lte_ue_context_array(size_t initial_capacity) {
    lte_ue_context_array *array = malloc(sizeof(lte_ue_context_array));
    if (!array) return NULL;

    array->array = malloc(initial_capacity * sizeof(lte_ue_context));
    if (!array->array) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->max_ue_id = 0;

    return array;
}

bool add_lte_ue_context(lte_ue_context_array *array, uint64_t ue_id) {
    pthread_mutex_lock(&array->mutex);

    if (array->count >= array->capacity) {
        lte_ue_context *new_array = realloc(array->array, (array->capacity + 1) * sizeof(lte_ue_context));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return false;
        }
        array->array = new_array;
        array->capacity++;
    }

    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].ue_id == ue_id) {
            pthread_mutex_unlock(&array->mutex);
            return false; // UE ID already exists in the array
        }
    }

    lte_ue_context *context = &array->array[array->count];
    context->ue_id = ue_id;
    context->num_rrc_states = 0;
    context->last_activity = time(NULL);
    array->max_ue_id = (array->max_ue_id > ue_id) ? array->max_ue_id : ue_id;
    ++array->count;

    pthread_mutex_unlock(&array->mutex);
    return true;
}

lte_ue_context* get_lte_ue_context(lte_ue_context_array *array, uint64_t ue_id) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].ue_id == ue_id) {
            lte_ue_context *context = &array->array[i];
            pthread_mutex_unlock(&array->mutex);
            return context;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return NULL; // UE ID not found in the array
}

void update_lte_ue_context(lte_ue_context *context, time_t current_time) {
    context->last_activity = current_time;
}

void destroy_lte_ue_context_array(lte_ue_context_array *array) {
    if (!array) return;

    free(array->array);
    free(array);
}
```

