namespace b = boost::asio;

class TCPConnection final {
public:
    explicit TCPConnection(uint32_t id) : _id(id), _lastSent(std::chrono::steady_clock::now()) {}

    uint32_t getId() const { return _id; }
    std::vector<b::io_service::work>& getWorkItems() { return _workItems; }
    void setState(const b::ip::tcp::connection_state state) { _states.push(_stateMutex, state); }
    b::ip::tcp::connection_state getState() const { return _states.pop(); }
    auto getLastSentTime() const { return _lastSent; }
    void setLastSentTime(const std::chrono::steady_clock::time_point& time) { _lastSent = time; }

private:
    uint32_t _id;
    std::vector<b::io_service::work> _workItems;
    b::ip::tcp::connection_state _state;
    std::chrono::steady_clock::time_point _lastSent;
    std::queue<b::ip::tcp::connection_state> _states;
    mutex _stateMutex;
    static atomic<uint32_t> _maxId;

    friend class TCPConnectionManager;
};

std::atomic<uint32_t> TCPConnection::_maxId = 0;

class TCPConnectionManager final {
public:
    void add(TCPConnection& connection) {
        std::unique_lock<mutex> lock(_connectionsMutex);
        connections.push_back(std::move(connection));
        _maxId.store(std::max(_maxId.load(), connection.getId()), std::memory_order_relaxed);
    }

    const TCPConnection* getById(uint32_t id) {
        std::unique_lock<mutex> lock(_connectionsMutex);
        for (const auto& connection : connections) {
            if (connection.getId() == id) {
                lock.unlock();
                return &connection;
            }
        }
        return nullptr;
    }

private:
    std::vector<TCPConnection> connections;
    mutex _connectionsMutex;
};
```
