using namespace System;
using namespace System::IO::Compression;
using namespace System::Runtime::Serialization::Formatters::Binary;

struct Record
{
    int relevanceScore;
    LONG* offset;
    int* key;
};

void manageAndIndexUserRecords(int seed, int chunkSize, int totalChunks, int* streamDelay, bool* useCompression, byte** outputStream, int maxDataValue, int maxRecords)
{
    srand(seed);

    LONG* indexOffsets = (LONG*)malloc((maxRecords + chunkSize - 1) / chunkSize * totalChunks * sizeof(LONG));
    for (int i = 0; i < (maxRecords + chunkSize - 1) / chunkSize * totalChunks; ++i)
        indexOffsets[i] = rand() % 2001 - 1000;

    int* keys = (int*)malloc(maxRecords * sizeof(int));
    int keyCount = 0;
    int hashMap[51] = { 0 };
    for (int i = 0; i < maxRecords; ++i)
    {
        int keyValue = rand() % 50 + 1;
        while (hashMap[keyValue])
            keyValue = rand() % 50 + 1;
        keys[i] = keyValue;
        hashMap[keyValue] = 1;
    }

    Record* records = (Record*)calloc(maxRecords, sizeof(Record));
    for (int i = 0; i < maxRecords; ++i)
    {
        records[i].relevanceScore = rand() % 101;
        records[i].offset = &indexOffsets[(i / chunkSize) * totalChunks + (i % chunkSize)];
        records[i].key = &keys[i];
    }

    qsort(records, maxRecords, sizeof(Record), [](const void* a, const void* b) { return ((const Record*)a)->relevanceScore > ((const Record*)b)->relevanceScore; });

    BinaryFormatter formatter = gcnew BinaryFormatter();
    GCHandle gchOutputStream = GCHandle::Alloc(outputStream, GCHandleType::Pinned);
    MemoryStream memoryStream = gcnew MemoryStream();
    for (int chunkIndex = 0; chunkIndex < totalChunks; ++chunkIndex)
    {
        int startIndex = chunkIndex * chunkSize;
        int endIndex = min(maxRecords, (chunkIndex + 1) * chunkSize);
        if (useCompression)
        {
            DeflateStream deflateStream = gcnew DeflateStream(gchOutputStream.AddrOfPinnedObject(), CompressionMode::Compress, false);
            formatter->Serialize(deflateStream, records + startIndex, recordsCount);
            deflateStream->Close();
        }
        else
        {
            formatter->Serialize(memoryStream, records + startIndex, (endIndex - startIndex));
            int bytesWritten = memoryStream->ToArray().CopyTo((int*)gchOutputStream.AddrOfPinnedObject());
            memoryStream->SetLength(0);
        }
        Sleep(*streamDelay);
    }
    gchOutputStream.Free();
}
