using System;
using System.Data;
using System.Data.SqlClient;
using Newtonsoft.Json;
using System.IO;
using System.Collections.Generic;
using System.Linq;

public class DatabaseConnection
{
    private string _connectionString;
    public event Action<string, TimeSpan> OnLogMessage;

    public DatabaseConnection(string connectionString)
    {
        _connectionString = connectionString;
    }

    public dynamic configureDatabaseConnectionAndExecuteQuery(string directoryPath, string databaseName, string queryType, dynamic queryData)
    {
        if (!File.Exists($"{directoryPath}/config.json")) return null;

        var config = JsonConvert.DeserializeObject<Dictionary<string, object>>(File.ReadAllText($"{directoryPath}/config.json"));

        var connectionSettings = config["connectionStrings"]?.Where(x => x.Value["name"].Equals(databaseName)).Select(x => x.Value).FirstOrDefault();

        if (connectionSettings == null) return null;

        var connection = new SqlConnection(_connectionString);

        connectAndVerifyDatabase(connection, databaseName);

        using (var command = new SqlCommand())
        {
            command.Connection = connection;
            command.CommandType = queryType switch
            {
                "SELECT" => CommandType.Text,
                "INSERT" => CommandType.Text,
                _ => throw new ArgumentException($"Invalid query type: '{queryType}'")
            };
            command.Parameters.AddWithValue("@data", queryData);

            connection.Open();

            switch (queryType)
            {
                case "SELECT":
                    var resultSet = command.ExecuteReader();
                    var rowsAffected = resultSet.Count;
                    var filteredRows = filterRows(resultSet, queryData);
                    OnLogMessage?.Invoke($"Executed SELECT query with {rowsAffected} total rows and {filteredRows.Count()} filtered rows.", TimeSpan.Zero);
                    return new { RowsAffected = rowsAffected, FilteredRows = filteredRows };
                case "INSERT":
                    var affectedRows = command.ExecuteNonQuery();
                    OnLogMessage?.Invoke($"Executed INSERT query with {affectedRows} row(s) affected.", TimeSpan.Zero);
                    return new { RowsAffected = affectedRows };
            }
        }
    }

    private void connectAndVerifyDatabase(SqlConnection connection, string databaseName)
    {
        try
        {
            var builder = new SqlConnectionStringBuilder(_connectionString);
            builder.InitialCatalog = databaseName;

            if (!connection.State.Equals(ConnectionState.Open))
                connection.Open();

            if (connection.InfoMessage != null)
                OnLogMessage?.Invoke($"Database '{databaseName}' connected: {connection.InfoMessage}", TimeSpan.Zero);
        }
        catch (Exception ex)
        {
            if (!connection.State.Equals(ConnectionState.Open))
                connection.Open();

            if (ex is SqlException sqlEx && !sqlEx.Number.HasValue)
                OnLogMessage?.Invoke($"Failed to connect to database '{databaseName}': {ex.Message}", TimeSpan.FromMilliseconds(ex.InnerException?.StackTrace?.Split('\n').Last().Length > 0 ? ex.InnerException.StackTrace.Split('\n')[^1].Length : 0));
            else
                OnLogMessage?.Invoke($"Failed to connect to database '{databaseName}': {ex.Message}", TimeSpan.FromMilliseconds(ex.StackTrace?.Split('\n').Last().Length > 0 ? ex.StackTrace.Split('\n')[^1].Length : 0));
        }
    }

    private IEnumerable<IDataRecord> filterRows(IDataReader reader, dynamic filterData)
    {
        var columnToFilter = reader.GetName(filterData.ColumnIndex);

        return reader.Cast<IDataRecord>()
            .Where(row => row[columnToFilter].ToString().ToInt32() > filterData.Threshold);
    }
