    for (int i = 0; i < size; ++i) {
        while (indicesBackup[dPtr[i].index] != 0) {
            dPtr[i].index = rand() % 50 + 1;
        }
        indicesBackup[dPtr[i].index] = 1;
        ++indexCount;
    }

    free(indicesBackup);
