            gzclose(outStream);
        }
    } else {
        // Stream data as-is without compression
    }
}

int compareBrightness(const void *a, const void *b) {
    return (*(image **)b)->brightnessAdjustmentFactor - (*(image **)a)->brightnessAdjustmentFactor;
}
