        public DatabasePoolManager(string connectionString, string poolName, int maxConnectionLimit)
        {
            if (string.IsNullOrWhiteSpace(connectionString))
                throw new ArgumentException("Invalid connection string", nameof(connectionString));
            _connectionString = connectionString;
            _poolName = poolName;
            InitializePool();
        }

        private void InitializePool()
        {
            if (!File.Exists("connection-pool.xml"))
                Console.WriteLine($"Configuration file not found at '{Directory.GetCurrentDirectory()}/connection-pool.xml'");

            var directoryPermissions = File.GetAccessControl(Directory.GetCurrentDirectory()).GetEffectiveRights();
            if (!(directoryPermissions & FileSystemRights.ReadData))
                throw new UnauthorizedAccessException("Insufficient permissions to manage connection pool.");

            var xmlConfig = XDocument.Load("connection-pool.xml");
            var hostPort = GetHostPortFromPoolName(_poolName);
            if (xmlConfig.Elements().Any(e => e.Attribute("name").Value == _poolName && e.Attribute("hostport").Value == hostPort))
                throw new ArgumentException($"A pool with the name '{_poolName}' is already in use on host and port {hostPort}.");

            var driverAssemblyName = GetDriverAssemblyName();
            if (!_installedDrivers.Contains(driverAssemblyName))
                InstallDriver(driverAssemblyName);

            lock (LockObject)
            {
                if (_pools.ContainsKey(_poolName))
                    return;

                try
                {
                    var connectionFactory = CreateConnectionFactory();
                    _pools[_poolName] = new DatabasePool(connectionFactory, _poolName, _connectionString, _maxConnectionLimit: maxConnectionLimit);
                }
                catch (Exception ex)
                {
                    HandleInitializationError(_poolName, ex);
                }
            }
        }

