            throw new NotImplementedException();
        }

        private void HandleInitializationError(string poolName, Exception ex)
        {
            LogError($"Failed to initialize connection pool '{poolName}', retrying up to {MaxRetryAttempts} times.", ex);

            for (int i = 0; i < MaxRetryAttempts; i++)
            {
                try
                {
                    InitializePool();
                    return;
                }
                catch (Exception ex2)
                {
                    Thread.Sleep(5000); // Sleep for 5 seconds before retrying.
                    LogError($"Initialization attempt #{i + 1} failed for pool '{poolName}', retrying...", ex2);
                }
            }

            LogError($"Pool '{poolName}' failed to initialize after {MaxRetryAttempts} attempts, giving up.", ex);
        }

        private void LogError(string message, Exception ex)
        {
            Console.WriteLine(message);
            if (ex != null)
                Console.WriteLine($"Exception details: {ex.Message}\n{ex.StackTrace}");
        }

        public bool TryGetConnection(out DbConnection connection)
        {
            lock (_pools[_poolName])
            {
                return _pools[_poolName].TryTakeConnection(out connection);
            }
        }

        public void ReturnConnection(DbConnection connection)
        {
            lock (_pools[_poolName])
            {
                _pools[_poolName].ReturnConnection(connection);
            }
        }
    }
