    private readonly ILogger<WebsiteManager> _logger;
    private readonly IConfiguration _configuration;

    public WebsiteManager(ILogger<WebsiteManager> logger, IConfiguration configuration)
    {
        _logger = logger;
        _configuration = configuration;
    }

    public async Task<Process> AddSiteAsync(string directoryPath, string siteName, object configurationObj)
    {
        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
            return null;

        var configuration = ValidateConfiguration(configurationObj);
        if (configuration == null)
            return null;

        lock (_lockObject) // Synchronize access to the directory to handle race conditions
        {
            var siteProcesses = GetSiteProcesses(directoryPath, siteName);

            if (siteProcesses.Any())
            {
                var existingProcess = siteProcesses.First();

                // Check if the process is alive and can be resumed
                if (!existingProcess.HasExited && !existingProcess.Resuscitate())
                    return existingProcess;
            }
        }

        var startInfo = CreateStartInfo(configuration);
        var process = Process.Start(startInfo);

        // Log detailed information about each attempt to add a site
        _logger.LogInformation($"Attempting to start site '{siteName}' in directory '{directoryPath}' at {DateTime.Now}.");

        if (process == null)
            return null;

        process.Exited += (sender, args) =>
        {
            int exitCode = args.ExitCode;
            _logger.LogInformation($"Site '{siteName}' exited with code: {exitCode}.");
        };

        return process;
    }

    private static ProcessStartInfo CreateStartInfo(object configurationObj)
    {
        // Create the ProcessStartInfo object using the configuration data
    }

    private static IEnumerable<Process> GetSiteProcesses(string directoryPath, string siteName)
    {
        return Process.GetProcessesByName(siteName).Where(process => process.MainModule.FileName.StartsWith($"{directoryPath}/"));
    }

    private object ValidateConfiguration(object configurationObj)
    {
        // Implement validation logic to ensure the configuration object is valid and contains necessary properties
    }
}
