int hash(const char *str, size_t len) {
    unsigned long hash = 5381;
    for (size_t i = 0; i < len; ++i)
        hash = ((hash << 5) + hash) + str[i]; /* hash * 33 + c */
    return hash % INT_MAX;
}

void init(size_t n) {
    if (n <= 0)
        return;

    max_records = n;

    records_allocated = malloc(n * sizeof(Record));
    if (!records_allocated) {
        log_event("Memory allocation failed");
        return;
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < n; ++i) {
        records_allocated[i].key = hash(strdup(""), i % INT_MAX);
        memset(records_allocated[i].str, '\0', sizeof(records_allocated[i].str));
        records_allocated[i].offset = 0;
    }
    pthread_mutex_unlock(&mutex);
}

