        return -2; // Allocation failure
    }

    // Create a thread for periodically checking activity
    std::thread activityThread([this, resources]() {
        std::chrono::steady_clock::time_point lastCheckTime = std::chrono::steady_clock::now();
        while (true) {
            periodicallyCheckActivity(resources, lastCheckTime);
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    });
    activityThread.detach(); // Run the thread independently

    return 0; // Successful initialization
