bool initializeAndSort(int maxElements, bool ascendingOrder = true, bool logDetails = true) {
    // Check if config.json exists in the specified directory
    boost::filesystem::path configFilePath("config.json");
    if (!boost::filesystem::exists(configFilePath)) return false;

    // Allocate memory for timestamp array and initialize with random values
    std::vector<double> timestamps(maxElements);
    std::mt19937 generator(std::chrono::system_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<> distribution(0, 1000);
    for (auto& timestamp : timestamps) {
        timestamp = distribution(generator);
    }

    // Allocate memory for entry array and initialize with unique strings
    std::vector<std::string> entries(maxElements);
    std::mt19937 gen(std::chrono::system_clock::now().time_since_epoch().count());
    std::uniform_int_distribution<> dist(10, 100);
    std::stringstream ss;
    for (size_t i = 0; i < maxElements; ++i) {
        ss.clear();
        ss << "Log entry #" << i + 1 << ": " << std::setw(dist(gen)) << std::left << std::string(10, 'X');
        entries[i] = ss.str();
    }

    // Allocate memory for record and aux_record arrays
    std::vector<Record> records(maxElements);
    std::vector<AuxRecord> auxRecords(maxElements);

    // Initialize pointers in record and aux_record structures
    for (size_t i = 0; i < maxElements; ++i) {
        records[i].p_timestamp = &timestamps[i];
        records[i].p_entry = &entries[i];

        auxRecords[i].p_timestamp = &timestamps[i];
        auxRecords[i].p_entry = &entries[i];
    }

    // Sort primary and auxiliary record arrays based on timestamp in ascending order
    std::sort(records.begin(), records.end(), [&](const Record& a, const Record& b) {
        return ascendingOrder ? a.p_timestamp < b.p_timestamp : a.p_timestamp > b.p_timestamp;
    });

    // Sort secondary auxiliary array based on length of log message in descending order
    std::sort(auxRecords.begin(), auxRecords.end(), [&](const AuxRecord& a, const AuxRecord& b) {
        return a.p_entry->length() > b.p_entry->length();
    });

    // Validate pointer integrity before and after sorting
    for (size_t i = 0; i < maxElements; ++i) {
        if (!records[i].p_timestamp || !records[i].p_entry || !auxRecords[i].p_timestamp || !auxRecords[i].p_entry) return false;
    }

    if (logDetails) logMemoryUsage(maxElements);
    return true;
}

void appendLogEntry(const std::string& logFilePath, const std::string& entryContent) {
    std::ofstream file(logFilePath, std::ios_base::app);
    if (!file) return; // Handle failure to open the file

    file << entryContent << std::endl;
}

