    if (!initializeAndSort(maxElements)) return -1;

    Json::Value config; // Load configuration from config.json file and use it as needed

    std::string logFilePath = config["log_file"].asString();
    std::string logEntryContent = "Initialization complete.";
    appendLogEntry(logFilePath, logEntryContent);

    return 0;
}
