    for (int i = 0; i <= num_records; ++i) offsets[i] = i;
    return offsets;
}

Record* allocate_records(int num_records) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    for (int i = 0; i < num_records; ++i) records[i].value = rand() % RAND_MAX;
    return records;
