void manage_list(int num_records, int range, int use_offsets, int *offsets, Record **records) {
    if (use_offsets && !offsets) {
        printf("Error: offset array is null.\n");
        return;
    }

    if (!use_offsets) {
        offsets = allocate_offsets(num_records);
        if (!offsets) {
            printf("Error: memory allocation for offsets failed.\n");
            return;
        }
    }

    *records = allocate_records(num_records);
    if (!*records) {
        printf("Error: memory allocation for records failed.\n");
        free(offsets);
        return;
    }
}

void cleanup(int *offsets, Record *records) {
    if (offsets) free(offsets);
    if (records) free(records);
}
