typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int data;
} Record;

struct Offset {
    int offset;
    struct Offset *next;
};

void handleDynamicRecordsAndSignalProcessing(int recordCount, int range, int useOffsetArray, int fileCount, int chunkSize, int totalChunks, int *streamDelay, int useCompression, char **outputStream, int enableLogging, int fileIdentifierRange) {
    pthread_mutex_t filesLock = PTHREAD_MUTEX_INITIALIZER;
    int maxOpenFiles = 10; // Adjust as needed to limit the number of open files
    int openFilesCount = 0;

    Record* records = malloc(recordCount * sizeof(Record));

    if (!records) {
        perror("Memory allocation failed");
        return;
    }

    // Initialize records with random values and flags
    for (int i = 0; i < recordCount; ++i) {
        records[i].RX_UE_INFORMATION_TAG = rand();
        records[i].RNTI = rand();
        records[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        records[i].data = rand() % range;
    }

    if (useOffsetArray) {
        struct Offset* offsets = malloc(recordCount * sizeof(struct Offset));

        if (!offsets) {
            perror("Memory allocation failed");
            free(records);
            return;
        }

        for (int i = 0; i < recordCount; ++i) {
            offsets[i].offset = i;
            offsets[i].next = &offsets[(i + 1) % recordCount];
        }

        int* currentOffset = offsets;
        for (int i = 0; i < recordCount; ++i) {
            records[currentOffset->offset].CRC_INDICATION_REL8_TAG.RXFLAG = rand() % 100 + 50; // Flag value range is [50, 150]
            currentOffset = currentOffset->next;
        }
    } else {
        for (int i = 0; i < recordCount; ++i) {
            records[i].CRC_INDICATION_REL8_TAG.RXFLAG = rand() % 100 + 50; // Flag value range is [50, 150]
        }
    }

    pthread_t threadPool[recordCount];

    for (int i = 0; i < recordCount; ++i) {
        int rc = pthread_create(&threadPool[i], NULL, processRecord, &records[i]);
        if (rc) {
            perror("Could not create thread");
            exit(-1);
        }
    }

    // Wait for all threads to finish execution
    for (int i = 0; i < recordCount; ++i) {
        pthread_join(threadPool[i], NULL);
    }

    free(records);
}

void* processRecord(void* data) {
    Record* record = (Record*)data;
    gid_t fileGroupID;

    // Generate a unique group ID for each file to ensure parallel processing doesn't conflict with file permissions
    if ((fileGroupID = getgid()) == -1) {
        perror("Unable to generate a unique group ID");
        return NULL;
    }

    int fileDescriptor, chunkIndex = 0;
    char* outputFilePath;
    struct stat fileStat;

    // Allocate memory for the output file path
    asprintf(&outputFilePath, "/path/to/output/%d_%d.bin", getpid(), (int)(record->CRC_INDICATION_REL8_TAG.RXFLAG));

    while (openFilesCount >= maxOpenFiles) {
        // Wait for a file to be closed before opening a new one
        pthread_mutex_lock(&filesLock);
        while (openFilesCount > 0 && openFilesCount >= maxOpenFiles) {
            pthread_cond_wait(&filesCondition, &filesLock);
        }
        pthread_mutex_unlock(&filesLock);
    }

    // Open the output file for writing
    if ((fileDescriptor = open(outputFilePath, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) == -1) {
        perror("Unable to open output file");
        free(outputFilePath);
        return NULL;
    }

    // Increment the number of open files and store the file descriptor for later cleanup
    openFilesCount++;

    if (useCompression) {
        gzFile gzFilePtr = gzdopen(fileDescriptor, "wb");
        if (!gzFilePtr) {
            perror("Unable to compress output file");
            close(fileDescriptor);
            free(outputFilePath);
            return NULL;
        }
    }

    for (int i = chunkSize * chunkIndex; i < min((int)record->data, recordCount + chunkSize * chunkIndex); ++i) {
        if (useCompression) {
            gzwrite(gzFilePtr, &records[i], sizeof(Record));
        } else {
            write(fileDescriptor, &records[i], sizeof(Record));
        }
    }

    chunkIndex++;

    // Flush and close the file
    if (useCompression) {
        gzclose(gzFilePtr);
    }
    close(fileDescriptor);

    // Signal that a file has been closed to allow opening a new one
    pthread_mutex_lock(&filesLock);
    openFilesCount--;
    pthread_cond_signal(&filesCondition);
    pthread_mutex_unlock(&filesLock);

    free(outputFilePath);

    return NULL;
}
