} Graph;

void error_handler(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

Graph* create_graph(int num_nodes, int min_weight, int max_weight, bool use_preallocated) {
    Graph *g = malloc(sizeof(Graph));
    if (!g) error_handler("Memory allocation failure");

    g->num_nodes = num_nodes;
    g->min_weight = min_weight;
    g->max_weight = max_weight;

    // Allocate memory for adjacency matrix
    g->adjacency_matrix = malloc(num_nodes * sizeof(int*));
    if (!g->adjacency_matrix) error_handler("Memory allocation failure");
    for (int i = 0; i < num_nodes; ++i) {
        g->adjacency_matrix[i] = malloc(num_nodes * sizeof(int));
        if (!g->adjacency_matrix[i]) error_handler("Memory allocation failure");
    }

    // If using pre-allocated matrix, copy it into the new graph
    if (use_preallocated) {
        for (int i = 0; i < num_nodes; ++i) {
            for (int j = 0; j < num_nodes; ++j) {
                g->adjacency_matrix[i][j] = *(*(int **)((&g->adjacency_matrix[0]) + i) + j);
            }
        }
    } else { // Initialize adjacency matrix with zeros for sparse graphs
        for (int i = 0; i < num_nodes; ++i) {
            for (int j = 0; j < num_nodes; ++j) {
                g->adjacency_matrix[i][j] = 0;
            }
        }
    }

    return g;
