#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct MemoryPool {
    Record *data;
    size_t capacity;
    size_t used;
} MemoryPool;

void memory_pool_init(MemoryPool *pool, size_t size) {
    pool->capacity = size;
    pool->used = 0;
    pool->data = malloc(sizeof(Record) * pool->capacity);
}

Record *memory_pool_get(MemoryPool *pool) {
    if (pool->used < pool->capacity) {
        return &pool->data[pool->used++];
    }
    return NULL;
}

void memory_pool_put(MemoryPool *pool, Record *record) {
    record->value = 0;
    pool->data[--pool->used] = *record;
}

void *load_records(void *args) {
    int range = *(int *) args;
    MemoryPool *pool = *(MemoryPool **)(args + sizeof(int));

    for (int i = 0; i < pool->capacity; ++i) {
        Record *record = memory_pool_get(pool);
        if (!record) {
            usleep(1000); // Simulate delay or failure
            continue;
        }
        record->value = rand() % range;
    }

    return NULL;
}

void manage_records(size_t num_records, int range, int use_offsets, Record **records) {
    MemoryPool pool;

    if (use_offsets) {
        *records = malloc(sizeof(Record) * num_records);
        // Pre-initialized offset array provided, set the first element to 0 and update the rest accordingly.
        (*records)[0].value = 0;
    } else {
        MemoryPool *pool = &pool;
        memory_pool_init(pool, num_records);
        *records = malloc(sizeof(Record) * pool->used);
        size_t offset = 0;
        Record **record_ptr = *records;
        for (size_t i = 0; i < pool->used; ++i, ++offset, ++record_ptr) {
            *record_ptr = &pool->data[i];
        }
    }

    pthread_t threads[num_records];
    int args[2 * num_records];

    for (size_t i = 0; i < num_records; ++i) {
        args[2 * i] = range;
        args[2 * i + 1] = &pool;
    }

    for (size_t i = 0; i < num_records; pthread_create(&threads[i], NULL, load_records, &args[2 * i])) {
        usleep(10); // Yield CPU to other threads
    }

    for (size_t i = 0; i < num_records; pthread_join(threads[i], NULL)) {}

    if (!use_offsets) {
        free(pool->data);
        free(pool);
    }
}
```

