#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <time.h>

typedef struct {
    unsigned int width;
    unsigned int height;
    unsigned int color_range;
    bool pre_init_palette;
    bool async_load;
    void* palette;
    sem_t* palette_sem;
    pthread_t load_thread;
    bool* loaded;
    void (*callback)(bool success);
} GridConfig;

typedef struct Cell {
    unsigned int x, y;
    unsigned int color;
} Cell;

void* grid_palette(void *arg) {
    GridConfig *config = arg;
    if (!config->pre_init_palette) {
        config->palette = mmap(NULL, config->color_range * sizeof(unsigned int), PROT_WRITE | PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (config->palette == MAP_FAILED) {
            fprintf(stderr, "Failed to allocate palette memory\n");
            return EXIT_FAILURE;
        }
    }

    for (unsigned int i = 0; i < config->color_range; ++i) {
        ((unsigned int*)config->palette)[i] = rand() % config->color_range;
    }

    sem_post(config->palette_sem);

    pthread_exit(EXIT_SUCCESS);
