Slab* create_slab(size_t num_connections, bool use_preallocated) {
    if (use_preallocated) {
        // Assuming pre-initialized status array is provided
        Slab* slab = malloc(sizeof(Slab));
        slab->capacity = num_connections;
        slab->used = 0;
        return slab;
    } else {
        Connection* connections = calloc(num_connections, sizeof(Connection));
        if (!connections) {
            perror("Memory allocation failure");
            exit(EXIT_FAILURE);
        }
        Slab* slab = malloc(sizeof(Slab));
        slab->capacity = num_connections;
        slab->used = 0;
        slab->connections = connections;
        return slab;
    }
}

void free_slab(Slab* slab) {
    if (slab->connections) {
        free(slab->connections);
        free(slab);
    }
}

Connection* get_connection(Slab* slab, size_t index) {
    if (index >= slab->capacity || index < 0) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
