    if (slab->used <= index) {
        // Expand the slab if necessary
        Slab* expanded_slab = create_slab(slab->capacity * 2, false);
        for (size_t i = 0; i < slab->used; ++i) {
            expanded_slab->connections[i] = slab->connections[i];
        }
        free_slab(slab);
        slab = expanded_slab;
    }
    return &(slab->connections[index]);
}

