time_t get_current_timestamp() {
    time_t rawtime;
    struct tm* timeinfo;
    char timeString[20];
    time (&rawtime);
    timeinfo = localtime (&rawtime);

    strftime(timeString, sizeof(timeString), "%Y-%m-%d %H:%M:%S", timeinfo);

