```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Session {
    pthread_mutex_t lock;
    time_t expiration_timestamp;
} Session;

typedef struct SessionManager {
    size_t capacity;
    size_t count;
    size_t head, tail;
    Session *sessions;
    pthread_mutex_t sessions_lock;
    time_t timeout;
    bool use_timestamps;
    time_t *timestamps;
} SessionManager;

void session_init(Session *session) {
    session->expiration_timestamp = time(NULL) + timeout;
}

void session_manager_init(SessionManager *session_mgr, size_t capacity, time_t timeout, bool use_timestamps) {
    session_mgr->capacity = capacity;
    session_mgr->count = 0;
    session_mgr->head = session_mgr->tail = 0;
    session_mgr->timeout = timeout;
    session_mgr->use_timestamps = use_timestamps;
    if (use_timestamps) {
        session_mgr->timestamps = calloc(capacity, sizeof(time_t));
    }
    session_mgr->sessions = malloc(sizeof(Session) * capacity);
    for (size_t i = 0; i < capacity; ++i) {
        pthread_mutex_init(&session_mgr->sessions[i].lock, NULL);
        session_init(&session_mgr->sessions[i]);
    }
    pthread_mutex_init(&session_mgr->sessions_lock, NULL);
}

void session_manager_cleanup(SessionManager *session_mgr) {
    for (size_t i = 0; i < session_mgr->capacity; ++i) {
        pthread_mutex_destroy(&session_mgr->sessions[i].lock);
    }
    free(session_mgr->sessions);
    if (session_mgr->use_timestamps) {
        free(session_mgr->timestamps);
    }
}

bool session_manager_is_full(const SessionManager *session_mgr) {
    return ((tail + 1) % capacity == head);
}

bool session_manager_add(SessionManager *session_mgr, const Session *session) {
    if (session_manager_is_full(session_mgr)) {
        return false;
    }

    pthread_mutex_lock(&session_mgr->sessions_lock);
    if (session_manager_is_full(session_mgr)) {
        pthread_mutex_unlock(&session_mgr->sessions_lock);
        return false;
    }

    if (!use_timestamps) {
        session->expiration_timestamp = time(NULL) + timeout;
        timestamps[tail] = session->expiration_timestamp;
    } else {
        session->expiration_timestamp = timestamps[tail];
    }

    tail = (tail + 1) % capacity;
    ++count;
    pthread_mutex_unlock(&session_mgr->sessions_lock);
    return true;
}

void session_manager_prune(SessionManager *session_mgr) {
    time_t now = time(NULL);
    pthread_mutex_lock(&session_mgr->sessions_lock);

    size_t new_head = head;
    for (size_t i = head; i != tail; new_head = (i + 1) % capacity) {
        if (now >= sessions[i].expiration_timestamp) {
            session_init(&sessions[i]);
            --count;
        } else {
            break;
        }
        i = (i + 1) % capacity;
    }

    head = new_head;
    pthread_mutex_unlock(&session_mgr->sessions_lock);
}

bool session_manager_remove(SessionManager *session_mgr, size_t index) {
    if (index >= capacity || count == 0) {
        return false;
    }

    pthread_mutex_lock(&session_mgr->sessions_lock);
    if (index >= capacity || count == 0) {
        pthread_mutex_unlock(&session_mgr->sessions_lock);
        return false;
    }

    session_init(&session_mgr->sessions[index]);
    --count;
    memmove(sessions + index, sessions + (index + 1), sizeof(Session) * (capacity - index));
    pthread_mutex_unlock(&session_mgr->sessions_lock);
    return true;
}

void session_manager_reset(SessionManager *session_mgr, size_t index, time_t new_timeout) {
    if (index >= capacity || count == 0) {
        return;
    }

    pthread_mutex_lock(&session_mgr->sessions_lock);
    if (index >= capacity || count == 0) {
        pthread_mutex_unlock(&session_mgr->sessions_lock);
        return;
    }

    session_mgr->sessions[index].expiration_timestamp = time(NULL) + new_timeout;
    if (use_timestamps) {
        timestamps[index] = sessions[index].expiration_timestamp;
    }
    pthread_mutex_unlock(&session_mgr->sessions_lock);
}
