    while (current != NULL) {
        next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
}

int add_node_threadsafe(Node** head, const char* text) {
    Node *node = create_node(text);
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // lock the list
    pthread_mutex_lock(&mutex);

    Node *last = *head;

    if (!*head) {
        *head = node;
    } else {
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = node;
    }

    pthread_mutex_unlock(&mutex);

    // clean up
    pthread_mutex_destroy(&mutex);

    return 0;
}

