Node* create_node(const char *text) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->str = strdup(text);
    if (!new_node->str) {
        free(new_node);
        return NULL;
    }

    new_node->data = rand() % MAX_INT;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    return new_node;
}

Node* create_linked_list(size_t size, const char *text) {
    Node *head = NULL, *current = NULL, *new_node;
    unsigned long hash = 0;

    if (size == 0) return head;

    for (size_t i = 0; i < size; ++i) {
        new_node = create_node(text + hash);
        if (!new_node) goto cleanup;

        hash = (hash * HASH_PRIME) % strlen(text);

        pthread_mutex_lock(&current->lock);
        current->next = new_node;
        pthread_mutex_unlock(&current->lock);
        current = new_node;
    }

    return head;

cleanup:
    while (head) {
        Node *temp = head;
        head = head->next;
        free(temp->str);
        free(temp);
    }

    return NULL;
}

void destroy_linked_list(Node **head) {
    Node *current = *head;
    Node *next;

    while (current != NULL) {
        next = current->next;
        free(current->str);
        free(current);
        current = next;
    }

    *head = NULL;
}

// Concurrent access methods
Node* get_next_node(Node *node) {
    pthread_mutex_lock(&node->lock);
    Node *temp = node->next;
    pthread_mutex_unlock(&node->lock);
    return temp;
}

void set_next_node(Node *node, Node *new_next) {
    pthread_mutex_lock(&node->lock);
    node->next = new_next;
    pthread_mutex_unlock(&node->lock);
}
```

