#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct ConnectionState {
    int id;
    int status; // 0 for disconnected, 1 for connected, etc.
    long long latency;
    long long bandwidth_usage;
    time_t last_update_timestamp;
    pthread_mutex_t mutex;
} ConnectionState;

typedef struct MemoryPool {
    ConnectionState* connections;
    size_t capacity;
    size_t size;
    sem_t free_semaphore;
} MemoryPool;

int create_memory_pool(MemoryPool* pool, size_t max_connections, size_t threshold) {
    if (!pool || !max_connections || threshold < max_connections) return -1; // Error: Invalid arguments

    pool->capacity = max_connections;
    pool->size = 0;
    pool->connections = malloc(sizeof(ConnectionState) * max_connections);
    if (!pool->connections) return -2; // Error: Memory allocation failed

    sem_init(&pool->free_semaphore, 0, max_connections);

    for (size_t i = 0; i < max_connections; ++i) {
        ConnectionState* state = &pool->connections[i];
        state->id = i;
        state->status = 0;
        state->latency = rand() % threshold + 1;
        state->bandwidth_usage = rand() % (threshold / 10) * 10;
        state->last_update_timestamp = time(NULL);
        pthread_mutex_init(&state->mutex, NULL);
    }

    return 0; // Success
}

ConnectionState* allocate_connection_state(MemoryPool* pool) {
    if (!pool || !pool->capacity) return NULL; // Error: Invalid pool or no capacity

    sem_wait(&pool->free_semaphore);
    ConnectionState* state = &pool->connections[pool->size];
    ++pool->size;

    return state;
}

void deallocate_connection_state(MemoryPool* pool, ConnectionState* state) {
    if (!pool || !pool->capacity || !state) return; // Error: Invalid arguments

    sem_post(&pool->free_semaphore);
    pool->size--;
}

void update_connection_state(ConnectionState* state, int status, long long latency, long long bandwidth_usage) {
    if (!state) return; // Error: Invalid argument

    pthread_mutex_lock(&state->mutex);
    time_t current_timestamp = time(NULL);
    state->status = status;
    state->latency = latency;
    state->bandwidth_usage = bandwidth_usage;
    state->last_update_timestamp = current_timestamp;
    pthread_mutex_unlock(&state->mutex);
}
```

