```cpp
#include <iostream>
#include <unordered_map>
#include <string>
#include <random>
#include <atomic>
#include <list>
#include <mutex>
#include <memory>

struct Node {
    std::string str;
    int value;
    std::unique_ptr<Node> next;
};

class LinkedList {
private:
    size_t capacity = 0;
    std::unordered_map<std::string, size_t> hashMap;
    std::mutex mtx;
    std::atomic<size_t> headIdx = 0;
    std::list<std::unique_ptr<Node>> nodes;
    static std::mt19937 rng; // Random number generator

public:
    LinkedList(size_t initialCapacity, const std::string& seed) {
        if (initialCapacity == 0) throw std::invalid_argument("Initial capacity must be greater than zero.");
        rng.seed(std::hash<std::string>{}(seed));
        resize(initialCapacity);
    }

    ~LinkedList() { clear(); }

    void resize(size_t newSize) {
        if (newSize <= capacity) return;

        while (nodes.size() + 1 > newSize) popBack();
        for (auto i = nodes.size(); i < newSize; ++i) pushBack();
    }

    void pushBack(const std::string& str) {
        auto node = std::make_unique<Node>();
        node->str = generateSubstring(str);
        node->value = generateRandomValue();
        std::unique_lock<std::mutex> lock(mtx);
        nodes.push_back(std::move(node));
    }

    const Node& front() const {
        std::unique_lock<std::mutex> lock(mtx);
        return *nodes[headIdx];
    }

    void popBack() {
        std::unique_lock<std::mutex> lock(mtx);
        nodes.pop_back();
        if (!nodes.empty()) headIdx = (headIdx + 1) % capacity;
    }

private:
    static std::string generateSubstring(const std::string& input) {
        size_t idx = hashMap[input]++;
        return input.substr(idx % input.size());
    }

    int generateRandomValue() {
        static std::uniform_int_distribution<> distr(0, INT_MAX);
        return distr(rng);
    }

    void clear() {
        while (!nodes.empty()) popBack();
    }
};

std::mt19937 LinkedList::rng; // Initialize the random number generator once for all instances
```

