4. `DynamicList_Remove(struct DynamicList* list, struct DynamicListElement* element)` - Removes an element from the dynamic list while managing memory usage and locking.

```c
void DynamicList_Remove(struct DynamicList* list, struct DynamicListElement* element) {
    pthread_mutex_lock(&list->lock);

    if (element == list->head) {
        list->head = element->next;
    }

    if (element->next == NULL) {
        list->tail = list->head;
    } else {
        struct DynamicListElement* previous = list->head;
        while (previous->next != element) {
            previous = previous->next;
        }
        previous->next = element->next;
    }

    --list->size;
    free(element);

    pthread_mutex_unlock(&list->lock);
}
