class Stream {
public:
    std::atomic<bool> active{true};
    std::atomic_int64_t start_timestamp;
    std::atomic_int64_t next_update_timestamp;

    Stream(std::atomic_int64_t interval, bool use_preallocated_timestamps) :
        start_timestamp(std::chrono::steady_clock::now().time_since_epoch().count() + interval),
        next_update_timestamp(start_timestamp + interval) {}

    void set_start_timestamp(std::atomic_int64_t timestamp) {
        start_timestamp = timestamp;
        next_update_timestamp = start_timestamp + next_update_interval();
    }

    std::atomic_int64_t next_update_interval() const {
        return next_update_timestamp - start_timestamp;
    }
};

class StreamManager {
private:
    std::vector<Stream*> streams_;
    std::deque<std::atomic_int64_t> timestamps_;
    size_t max_streams_;
    mutex streams_mutex_;

public:
    StreamManager(size_t num_streams, std::atomic_int64_t default_interval, bool use_preallocated_timestamps) :
        max_streams_(num_streams), timestamps_(default_interval ? num_streams : 0) {
        for (size_t i = 0; i < num_streams && i < max_streams_; ++i) {
            streams_.emplace_back(new Stream(default_interval, use_preallocated_timestamps));
        }
    }

    ~StreamManager() {
        for (auto* stream : streams_) {
            delete stream;
        }
    }

    void add_stream(const std::atomic_int64_t& interval, bool use_preallocated_timestamps) {
        if (streams_.size() >= max_streams_) return;

        streams_.emplace_back(new Stream(interval, use_preallocated_timestamps));
    }

    void update_stream(size_t index, const std::atomic_int64_t& data) {
        unique_lock<mutex> lock(streams_mutex_);
        if (index >= streams_.size() || !streams_[index]->active) return;

        streams_[index]->next_update_timestamp = chrono::steady_clock::now().time_since_epoch().count();
    }

    void reset_stream(size_t index, const std::atomic_int64_t& timestamp) {
        unique_lock<mutex> lock(streams_mutex_);
        if (index >= streams_.size()) return;

        streams_[index]->set_start_timestamp(timestamp);
    }

    void prune_incomplete_streams() {
        auto it = streams_.begin();
        while (it != streams_.end()) {
            if (!it->get()->active) {
                delete it++;
                streams_.erase(it);
            } else {
                ++it;
            }
        }
    }
};
