        timestamp_offsets[i] = rand() % 1001;
        identifiers[i] = rand() % 500 + 1;
    }

    // Sort events based on priority level in descending order
    qsort(events, maxRecords, sizeof(event), (int (*)(const void*, const void*))cmp_event);

    int *compressed_identifiers = NULL;
    gzFile outfile = useCompression ? gzopen(*outputStream, "wb") : fopen(*outputStream, "w");

    for (int i = 0; i < totalBatches; ++i) {
        int batchStart = i * batchSize;
        int batchEnd = min(batchStart + batchSize, maxRecords);

        // Process each event in the current batch and handle retry logic if needed
        for (int j = batchStart; j < batchEnd; ++j) {
            event *e = &events[j];

            // Simulate transient failure with a 10% probability
            if (rand() % 10 == 0) {
                fprintf(stderr, "Transient failure occurred while processing event %d.\n", j);
                continue;
            }

            // Stream data or compress and stream it based on useCompression flag
            if (useCompression) {
                if (!compressed_identifiers) {
                    compressed_identifiers = malloc(maxRecords * sizeof(int));
                    if (!compressed_identifiers) {
                        fprintf(stderr, "Failed to allocate memory for compressed_identifiers.\n");
                        break;
                    }
                }

                gzwrite(outfile, &e->identifier, sizeof(int));
                gzwrite(outfile, &e->timestamp_offset, sizeof(long));
            } else {
                fprintf(outfile, "%d %ld\n", e->identifier, e->timestamp_offset);
            }
        }

        // Release memory for compressed identifiers if compression was enabled
        if (useCompression && i == totalBatches - 1) {
            free(compressed_identifiers);
            compressed_identifiers = NULL;
        }
    }

    if (useCompression) gzclose(outfile);
    else fclose(outfile);

    free(timestamp_offsets);
    free(identifiers);
    free(events);
}

int cmp_event(const void *a, const void *b) {
    event *e1 = (event *)a;
    event *e2 = (event *)b;
    return e1->priority - e2->priority;
}
