    void DataStructure::loadData(const char* userFile, const char* sessionFile) {
        std::atomic_int numUsersLoaded{0};
        std::mutex usersMutex;
        std::atomic_int numSessionsLoaded{0};
        std::mutex sessionsMutex;

        struct stat fileStat;
        if (stat(userFile, &fileStat) != 0) {
            throw std::runtime_error("Error while accessing user file: " + std::string(userFile));
        }

        auto processUserJson = [&](const nlohmann::json& json) {
            User user;
            user.name = json["name"].get<std::string>();
            user.age = json["age"].get<int>();
            user.weight = json["weight"].get<float>();
            // Allocate memory for the string field based on a predefined length
            user.name.resize(10);
            random_fill(user.name.begin(), user.name.end(), 65 + rand() % 26);
            // Generate a random float value within a specified range
            user.weight = (float)rand() / RAND_MAX * 30.f + 50.f;
            // Lock the users list to add the new user node
            std::lock_guard<std::mutex> usersLock(usersMutex);
            ++numUsersLoaded;
            return user;
        };

        auto processSessionJson = [&](const nlohmann::json& json) {
            Session session;
            if (numUsersLoaded == 0) {
                throw std::runtime_error("Error: User list is empty");
            }

            // Find the user corresponding to the given user id
            auto currentUser = this->users.get();
            for (int i = 0; i < numUsersLoaded && currentUser != nullptr; ++i) {
                if (currentUser->age == json["userId"].get<int>()) {
                    session.user.reset(new User(*currentUser));
                    currentUser = currentUser->nextUser.get();
                } else {
                    currentUser = currentUser->nextUser.get();
                }
            }

            if (currentUser == nullptr) {
                throw std::runtime_error("Error: User not found with given user id");
            }

            session.sessionId = json["sessionId"].get<uint64_t>();
            session.timestamp = static_cast<time_t>(json["timestamp"].get<double>());
            session.nextSession.reset(nullptr);
            // Lock the sessions list to add the new session node
            std::lock_guard<std::mutex> sessionsLock(sessionsMutex);
            ++numSessionsLoaded;
            return session;
        };

        auto loadFile = [&](const char* filePath) {
            std::ifstream ifs(filePath, std::ios::binary);
            if (!ifs.is_open()) {
                throw std::runtime_error("Error while accessing " + std::string(filePath));
            }

            nlohmann::json json;
            try {
                ifs >> json;
            } catch (const std::exception& e) {
                ifs.close();
                throw std::runtime_error("Error parsing JSON from " + std::string(filePath) + ": " + e.what());
            }

            return json;
        };

        auto processFiles = [&]() {
            std::vector<std::future<nlohmann::json>> userFutures, sessionFutures;

            // Split the processing of user and session files across multiple threads to handle concurrency and potential I/O failures gracefully
            const int numThreads = std::thread::hardware_concurrency();
            for (int i = 0; i < numThreads; ++i) {
                userFutures.push_back(std::async(std::launch::async, [&](const char* filePath) { return loadFile(filePath); }, userFile + "_thread_" + std::to_string(i % numThreads)));
                sessionFutures.push_back(std::async(std::launch::async, [&](const char* filePath) { return loadFile(filePath); }, sessionFile + "_thread_" + std::to_string(i % numThreads)));
            }

            // Wait for all the threads to finish processing their files and collect the results
            for (auto& future : userFutures) {
                auto userJson = future.get();
                for (const auto& jsonUser : userJson.items()) {
                    *this->users.emplace_back(processUserJson(jsonUser));
                }
            }

            for (auto& future : sessionFutures) {
                auto sessionJson = future.get();
                for (const auto& jsonSession : sessionJson.items()) {
                    *this->sessions.emplace_back(processSessionJson(jsonSession));
                }
            }
        };

        this->users.reset(new std::vector<User>());
        this->sessions.reset(new std::vector<Session>());
        processFiles();
    }

    // Add other member functions and data members as needed
