#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jansson.h>
#include <pthread.h>
#include <semaphore.h>
#include <hash_map.h>

// Memory pool for linked lists and arrays
typedef struct {
    void *data;
    struct memory_pool *next;
} memory_block;

struct memory_pool {
    size_t size;
    unsigned int count;
    memory_block *head, *tail;
    pthread_mutex_t lock;
    semaphore_t free_count;
};

memory_pool* create_memory_pool(size_t size) {
    memory_pool *pool = malloc(sizeof(memory_pool));
    pool->size = size;
    pool->count = 0;
    pool->head = pool->tail = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    sem_init(&pool->free_count, 0, 0);
    return pool;
}

void* mem_alloc(memory_pool *pool) {
    memory_block *block;
    void *data;

    pthread_mutex_lock(&pool->lock);

    if (pool->free_count > 0) {
        block = pool->head;
        pool->head = block->next;
        if (pool->head == NULL) pool->tail = NULL;
        data = block->data;
        pool->free_count--;
    } else {
        block = malloc(sizeof(memory_block));
        if (!block) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        block->data = malloc(pool->size);
        if (!block->data) {
            free(block);
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
    }

    block->next = pool->tail;
    if (pool->tail) pool->tail->next = block;
    else pool->head = block;
    pool->tail = block;
    pool->count++;

    pthread_mutex_unlock(&pool->lock);
    return block->data;
}

void mem_free(memory_pool *pool, void *ptr) {
    memory_block *block = (memory_block*)((char*)ptr - sizeof(memory_block));

    pthread_mutex_lock(&pool->lock);
    block->next = pool->head;
    pool->head = block;
    pool->free_count++;
    pool->count--;
    pthread_mutex_unlock(&pool->lock);
}

// Implement the rest of the functions for handling JSON files, data structures (users, sessions, activities), hash tables, custom resizing strategies, error handling, logging, and integration with external services.
