```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class MicroserviceManager {
    private final ConcurrentHashMap<String, Microservice> microservices;
    private final AlertManager alertManager;

    public MicroserviceManager(AlertManager alertManager) {
        this.microservices = new ConcurrentHashMap<>();
        this.alertManager = alertManager;
    }

    public void addService(String serviceName) {
        Microservice microservice = new Microservice();
        if (!microservices.putIfAbsent(serviceName, microservice)) {
            throw new IllegalStateException("Service already exists: " + serviceName);
        }
    }

    public void updateServiceMetrics(String serviceName, double invocationLatency, double resourceUtilization, ServiceStatus status) {
        Microservice microservice = microservices.get(serviceName);
        if (microservice == null) {
            throw new IllegalStateException("Service not found: " + serviceName);
        }

        AtomicLong invocationLatencies = microservice.getInvocationLatencies();
        invocationLatencies.updateAndGet(l -> l + invocationLatency);

        AtomicLong resourceUtilizationCounter = microservice.getResourceUtilizationCounter();
        resourceUtilizationCounter.addAndGet((long) (resourceUtilization * 100));

        microservice.setStatus(status);

        checkAndNotifyAlerts(serviceName, invocationLatency, resourceUtilization);
    }

    public Microservice getServiceByName(String serviceName) {
        return microservices.getOrDefault(serviceName, null);
    }

    private void checkAndNotifyAlerts(String serviceName, double invocationLatency, double resourceUtilization) {
        alertManager.checkAlert(serviceName, invocationLatency, resourceUtilization);
    }
}
