class ConfigManager {
private:
    std::mutex mtx;
    std::unordered_map<std::string, std::pair<int, std::chrono::milliseconds>> config;
    std::vector<std::unique_ptr<void[]>> keys; // First element is key string, second is int value, third is timeout duration
    size_t capacity = 0;
    static constexpr double compression_threshold = 0.75; // Threshold for when to compress data

public:
    ConfigManager() {}

    void insert(const std::string& key, int value, std::chrono::milliseconds timeout) {
        if (capacity * compression_threshold < keys.size())
            reorganize();

        auto it = config.emplace(key, std::make_pair(value, timeout));
        keys.push_back({ new char[key.length() + 1], &it.first->second, &it.first->second }); // Allocate memory for key, value, and timeout pointers
        capacity++;
    }

    std::pair<int, std::chrono::milliseconds> get(const std::string& key) {
        auto it = config.find(key);
        if (it == config.end()) throw std::out_of_range("Key not found");
        return it->second;
    }

    void setRandomValue(int min, int max, const std::string& key) {
        auto it = config.find(key);
        if (it == config.end()) throw std::out_of_range("Key not found");
        (*it->second.first) = min + rand() % (max - min + 1); // Set value to random number within the specified range
    }

    void concurrentAccess() {
        std::thread t1([this](){ for(auto& k : keys){ setRandomValue(0, 100, *static_cast<std::string*>(k[0])); } });
        std::thread t2([this](){ for(auto& k : keys){ setRandomValue(500, 600, *static_cast<std::string*>(k[0])); } }; t2.join();
        t1.join();
