typedef struct {
    char mac[18]; // MAC address (e.g., "00:11:22:33:44:55")
    struct in_addr ip; // IP configuration
    int status; // Link state flag
    int num_records;
    int *records; // Array of 'int' values
    long *offsets; // Array for 'long' offset values
    int *keys; // Array for 'int' keys
    pthread_mutex_t lock; // Mutex for thread safety
} nicp_config;

typedef struct {
    nicp_config* config;
    void* arg;
} iterate_arg;

nicp_config* create_config(const char* mac, const struct in_addr ip) {
    nicp_config* config = malloc(sizeof(nicp_config));
    memcpy(config->mac, mac, 18);
    config->ip = ip;
    config->status = 0;
    config->num_records = 10; // Initial number of records
    config->records = malloc(config->num_records * sizeof(int));
    for (int i = 0; i < config->num_records; ++i) {
        config->records[i] = rand() % 100;
    }
    config->offsets = calloc(config->num_records, sizeof(long));
    config->keys = malloc(config->num_records * sizeof(int));
    for (int i = 0; i < config->num_records; ++i) {
        config->keys[i] = rand() % INT_MAX;
    }
    pthread_mutex_init(&config->lock, NULL);
    return config;
}

void add_config(nicp_config** list, const char* mac, const struct in_addr ip) {
    for (nicp_config* config : *list) {
        if (!strcmp(config->mac, mac)) {
            // Duplicate MAC address, handle appropriately
            return;
        }
    }
    nicp_config* new_config = create_config(mac, ip);
    *list = realloc(*list, sizeof(**list) * (*list + 1));
    (*list)[*list - 1] = new_config;
}

void update_config(nicp_config** list, size_t index, const struct in_addr new_ip) {
    if (index >= *list) {
        // Index out of bounds, handle appropriately
        return;
    }
    nicp_config* config = &(*list)[index];
    memcpy(&(config->ip), &new_ip, sizeof(struct in_addr));
}

void iterate_network(nicp_config** list, void(*callback)(nicp_config*, void*), void* arg) {
    for (size_t i = 0; i < *list; ++i) {
        pthread_mutex_lock(&((*list)[i]->lock));
        callback((*list)[i], arg);
        pthread_mutex_unlock(&((*list)[i]->lock));
    }
}

void log_event(const char* event, nicp_config* config) {
    // Implement logging system here
}

