```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>
#include <thread>
#include <mutex>
#include <vector>

// Document class with a transform method to be extended as needed
class Document {
public:
    virtual ~Document() = default;
    virtual void transform() = 0;
};

class TextDocument : public Document {
private:
    std::string data;
public:
    TextDocument(const std::string& str) : data(str) {}
    void transform() override {
        // Implement your document transformation logic here
    }
};

// Memory manager for documents
class DocManager {
private:
    std::unordered_map<std::string, std::unique_ptr<Document>> documents;
    mutable std::mutex mtx;
public:
    void insert(const std::string& name, std::unique_ptr<Document> doc) {
        std::lock_guard<std::mutex> lock(mtx);
        if (documents.find(name) != documents.end()) {
            // Overwrite existing document with the same name
            documents[name].reset(doc.release());
        } else {
            documents[name] = std::move(doc);
        }
    }

    std::unique_ptr<Document> get(const std::string& name) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = documents.find(name);
        if (it != documents.end()) {
            return it->second;
        }
        return nullptr;
    }
};

// Thread-safe function to transform a document
void safe_transform(DocManager& manager, const std::string& name) {
    auto doc = manager.get(name);
    if (doc != nullptr) {
        std::unique_lock<std::mutex> lock(manager.mtx);
        doc->transform();
    }
}

// Example usage in a multi-threaded program
int main() {
    DocManager manager;
    std::vector<std::string> names = {"document1", "document2", "document3"};

    // Insert documents into the document manager
    for (const auto& name : names) {
        std::unique_ptr<Document> doc(new TextDocument(name + ": content"));
        manager.insert(name, std::move(doc));
    }

    // Transform each document concurrently
    std::vector<std::thread> threads;
    for (const auto& name : names) {
        threads.emplace_back(safe_transform, std::ref(manager), name);
    }

    for (auto& t : threads) {
        t.join();
    }

    // Print transformed documents
    for (const auto& name : names) {
        auto doc = manager.get(name);
        if (doc != nullptr) {
            std::cout << "Transformed document: " << name << ": " << doc->data << '\n';
        }
    }
}
