typedef struct {
    char id;
    double value;
    char *error_message;
    int error_code;
} service_t;

// Function to parse JSON string and store keys, values, and timeouts
void parse_json(char *json_str, char **keys, int *defaults, long long *timeouts) {
    // Initialize variables for json-c library
    struct json_object *root = json_tokener_parse(json_str);
    if (IS_ERR(root)) {
        fprintf(stderr, "Error parsing JSON: %s\n", json_object_get_error(root));
        return;
    }

    // Iterate through JSON key-value pairs and store them in the respective lists
    struct json_object *iter = json_object_get_members(root);
    while (iter) {
        const char *key = json_object_get_name(iter);
        struct json_object *val = iter->u.member.value;
        int type = json_object_get_type(val);

        if (type == json_type_string) {
            // Store keys and default values
            keys[*keys] = strdup(key);
            ++(*keys);
            defaults[*defaults] = atoi(json_object_get_string(val));
            ++(*defaults);
        } else if (type == json_type_int) {
            // Store timeouts
            timeouts[*timeouts] = json_object_get_int(val);
            ++(*timeouts);
        }

        iter = json_object_get_next(iter);
    }
}

// Function to dynamically resize the service array
void resize_services(service_t **services, size_t *size, size_t new_size) {
    if (new_size > *size) {
        service_t *new_array = realloc(*services, sizeof(service_t) * new_size);
        if (!new_array) {
            fprintf(stderr, "Memory allocation error\n");
            return;
        }
        *services = new_array;
        *size = new_size;
    }
}

// ... (Implement other functions as per requirements 2-12)
