void generate_key(RSA **priv_key, RSA **pub_key) {
    const RSA_METHOD *meth = NULL;
    RSA *rsakey = NULL;

    meth = RSA_get_default_method();
    rsakey = RSA_new();
    if (!rsakey) {
        fprintf(stderr, "Could not allocate RSA key\n");
        exit(EXIT_FAILURE);
    }

    if (1 != RSA_generate_key_ex(rsakey, 2048, meth, NULL, NULL)) {
        fprintf(stderr, "Error in RSA key generation\n");
        exit(EXIT_FAILURE);
    }

    *priv_key = rsakey;

    BIO *bio = NULL;
    RSA *temp_key = NULL;

    bio = BIO_new(BIO_s_mem());
    if (!BIO_ctrl_set_fp(bio, BIO_FP_FILENO, stdout)) {
        fprintf(stderr, "Could not set BIO fp\n");
        exit(EXIT_FAILURE);
    }

    PEM_write_RSAPrivateKey(bio, rsakey, NULL, NULL, 0, NULL, NULL);
    BIO_flush(bio);
    BIO_reset(bio);
    if (BIO_ctrl_get_length(bio) <= 0) {
        fprintf(stderr, "Error in RSA key export\n");
        exit(EXIT_FAILURE);
    }

    void *priv_key_buf = malloc(BIO_ctrl_get_length(bio));
    if (!priv_key_buf) {
        fprintf(stderr, "Error allocating memory for private key buffer\n");
        exit(EXIT_FAILURE);
    }

    BIO_read(bio, priv_key_buf, BIO_ctrl_get_length(bio));
    if (BIO_pending(bio) > 0) {
        fprintf(stderr, "Error reading private key from BIO\n");
        exit(EXIT_FAILURE);
    }

    RSA_free(rsakey);
    rsakey = PEM_read_RSAPrivateKey(priv_key_buf, NULL, NULL, NULL);

    *priv_key = rsakey;

    bio = BIO_new(BIO_s_mem());
    if (!BIO_ctrl_set_fp(bio, BIO_FP_FILENO, stdout)) {
        fprintf(stderr, "Could not set BIO fp\n");
        exit(EXIT_FAILURE);
    }

    PEM_write_RSA_PUBKEY(bio, rsakey);
    BIO_flush(bio);
    BIO_reset(bio);
    if (BIO_ctrl_get_length(bio) <= 0) {
        fprintf(stderr, "Error in RSA key export\n");
        exit(EXIT_FAILURE);
    }

    void *pub_key_buf = malloc(BIO_ctrl_get_length(bio));
    if (!pub_key_buf) {
        fprintf(stderr, "Error allocating memory for public key buffer\n");
        exit(EXIT_FAILURE);
    }

    BIO_read(bio, pub_key_buf, BIO_ctrl_get_length(bio));
    if (BIO_pending(bio) > 0) {
        fprintf(stderr, "Error reading public key from BIO\n");
        exit(EXIT_FAILURE);
    }

    *pub_key = PEM_read_RSAPUBKEY(pub_key_buf);
}

void generate_records(record **records, size_t count, RSA *priv_key, int min_key, int max_key) {
    *records = malloc(count * sizeof(record));

    for (size_t i = 0; i < count; ++i) {
        record *rec = &((*records)[i]);

        rec->offset = i;
        rec->length = snprintf(rec->buffer, sizeof(rec->buffer), "Identifier-%lu", i);

        RSA_PrivateKey *pkey = RSA_PKCS1_PRIV_decode(NULL, priv_key, (const unsigned char *)rec->buffer + sizeof(int), rec->length - sizeof(int), RSA_NOOPT);
        if (!pkey) {
            fprintf(stderr, "Error decoding RSA private key\n");
            exit(EXIT_FAILURE);
        }

        rec->key = RSA_PKCS1_AUTO_PRIV_decode(&i, pkey, &rec->length, NULL);
        if (rec->key < min_key || rec->key > max_key) {
            fprintf(stderr, "Decoded key out of range\n");
            exit(EXIT_FAILURE);
        }

        RSA_free(pkey);
    }
}

int main() {
    RSA *priv_key = NULL;
    RSA *pub_key = NULL;
    generate_key(&priv_key, &pub_key);

    size_t record_count = 10;
    record *records = NULL;
    generate_records(&records, record_count, priv_key, 1000, 2000);

    // Sign and verify the records here...

    RSA_free(priv_key);
    RSA_free(pub_key);
    free(records);

    return 0;
}
