#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

struct Store {
    Record *data;
    size_t capacity;
    size_t count;
    FILE *file;
    pthread_mutex_t mutex;
};

Store *store_init(const char *filename, size_t initial_capacity) {
    Store *store = malloc(sizeof(Store));
    store->data = calloc(initial_capacity, sizeof(Record));
    store->capacity = initial_capacity;
    store->count = 0;
    store->file = fopen(filename, "w+");
    if (!store->file) {
        free(store);
        perror("Error opening file");
        return NULL;
    }
    pthread_mutex_init(&store->mutex, NULL);
    return store;
}

int store_write(Store *store, long offset, int key, int value) {
    if (store == NULL || store->count == store->capacity) {
        size_t new_capacity = store->capacity * 2;
        Record *new_data = realloc(store->data, new_capacity * sizeof(Record));
        if (!new_data) {
            perror("Error reallocating data array");
            return -1;
        }
        store->data = new_data;
        store->capacity = new_capacity;
    }

    pthread_mutex_lock(&store->mutex);
    Record *record = &store->data[store->count];
    record->offset = offset;
    record->key = key;
    record->value = rand() % 100; // Generate random value within range (0-99)
    store->count++;
    fseek(store->file, store->count * sizeof(Record), SEEK_SET);
    if (fwrite(record, sizeof(Record), 1, store->file) != 1) {
        perror("Error writing to file");
        pthread_mutex_unlock(&store->mutex);
        return -1;
    }
    pthread_mutex_unlock(&store->mutex);

    return 0;
}

int store_read(Store *store, long offset, Record *result) {
    if (store == NULL || store->count == 0)
        return -1;

    pthread_mutex_lock(&store->mutex);
    fseek(store->file, offset * sizeof(Record), SEEK_SET);
    if (fread(result, sizeof(Record), 1, store->file) != 1) {
        perror("Error reading from file");
        pthread_mutex_unlock(&store->mutex);
        return -1;
    }
    pthread_mutex_unlock(&store->mutex);

    return 0;
}

void store_destroy(Store *store) {
    if (store == NULL)
        return;

    fclose(store->file);
    free(store->data);
    pthread_mutex_destroy(&store->mutex);
    free(store);
}
```

