int generate_records(size_t offsets_size, size_t keys_size, size_t records_count, size_t range, size_t max_allocation, pthread_mutex_t *mutex) {
    void *offsets = fragmentation_aware_malloc(offsets_size * sizeof(long));
    if (!offsets) return -1;

    void *keys = fragmentation_aware_malloc(keys_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1;
    }

    void *records = NULL;
    size_t records_allocated = 0;
    while (records_count > records_allocated) {
        if ((max_allocation - (records_allocated + records_size)) < sizeof(record)) break;

        records = fragmentation_aware_realloc(records, records_allocated + records_size, sizeof(record));
        if (!records) {
            free(offsets);
            free(keys);
            return -1;
        }
        records_allocated += records_size;
    }

    pthread_mutex_lock(mutex);
    for (size_t i = 0; i < records_count; ++i) {
        records[i].value = rand() % range;
    }
    pthread_mutex_unlock(mutex);

    SHA256_CTX sha256;
    unsigned char hash[SHA256_DIGEST_LENGTH];

    void *identifiers = fragmentation_aware_malloc(records_count * sizeof(unsigned char[SHA256_DIGEST_LENGTH]));
    if (!identifiers) {
        free(offsets);
        free(keys);
        if (records != NULL) free(records);
        return -1;
    }

    for (size_t i = 0; i < records_count; ++i) {
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, keys, sizeof(int));
        SHA256_Update(&sha256, offsets + (i * sizeof(long)), sizeof(long));
        SHA256_Final(hash, &sha256);

        memcpy(identifiers + i * SHA256_DIGEST_LENGTH, hash, SHA256_DIGEST_LENGTH);
    }

    return 0;
}

