const size_t MAX_RECORDS = 100000; // Maximum number of records to handle
const size_t RECORD_SIZE = sizeof(Record);
const size_t LIMIT = 10 * (MAX_RECORDS + 2 * sizeof(long) + sizeof(int)); // Predefined memory limit

Record* initialize_arrays(size_t* offsets, int* keys, Record** records, size_t num_records, size_t record_size_limit) {
    size_t allocated_offsets = 0;
    size_t allocated_keys = 0;
    size_t allocated_records = 0;
    long* offsets_arr = NULL;
    int* keys_arr = NULL;
    Record* records_arr = NULL;

    offsets_arr = malloc(num_records * sizeof(long)); // Offset array
    if (!offsets_arr || allocated_offsets + num_records > MAX_RECORDS) {
        goto cleanup;
    }
    allocated_offsets += num_records;

    keys_arr = malloc(num_records * sizeof(int)); // Key array
    if (!keys_arr || allocated_keys + num_records > MAX_RECORDS) {
        goto cleanup;
    }
    allocated_keys += num_records;

    records_arr = calloc(num_records, record_size_limit); // Record array
    if (!records_arr || (allocated_records + num_records > MAX_RECORDS && (size_t)record_size_limit < num_records)) {
        goto cleanup;
    }
    allocated_records += num_records * record_size_limit;

    srand(time(NULL)); // Initialize random number generator

    for (size_t i = 0; i < num_records; ++i) {
        records_arr[i].value = rand() % INT_MAX;
    }

    *offsets = allocated_offsets;
    *keys = allocated_keys;
    *records = records_arr;

cleanup:
    if (offsets_arr && allocated_offsets > 0) free(offsets_arr);
    if (keys_arr && allocated_keys > 0) free(keys_arr);
    if (records_arr && (allocated_records > 0 || num_records > 0)) free(records_arr);

    return records;
}
