int init_data_structures(size_t n, size_t m, size_t k, int min_val, int max_val) {
    long *offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) return 1; // Memory allocation failure

    int *keys = (int*)malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        return 2; // Memory allocation failure
    }

    record *records = (record*)calloc(m, sizeof(record));
