    int used_indices[k];
    int i, j, random_index, filled = 0;

    // Initialize offsets and keys arrays
    for (i = 0; i < n; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Initialize records array with random values within specified range and zeros for the rest
    srand(time(NULL));
    for (i = 0; i < k && filled < k; ++i) {
        pthread_mutex_lock(&lock);
        random_index = rand() % n;
        if (used_indices[random_index] == 0) {
            used_indices[random_index] = 1;
            records[filled].value = min_val + (rand() % (max_val - min_val + 1));
            filled++;
        }
        pthread_mutex_unlock(&lock);
    }

    free(used_indices); // Free any temporary memory allocated for used indices

    // Layout optimization: Pack records with non-zero values closely together in memory for cache efficiency
    qsort(records, filled, sizeof(record), [](const void *a, const void *b) {
        return ((record*)a)->value - ((record*)b)->value;
    });

    // Cleanup upon function exit
    free(offsets);
    free(keys);
    free(records);

    return 0; // Function execution success
}
