    if (size == 0 || range == 0)
        return NULL;

    int *keys = (int *)malloc(sizeof(int) * size);
    if (!keys)
        return NULL;

    bool *used = calloc(range, sizeof(bool));
    if (!used) {
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        do {
            keys[i] = rand() % range;
        } while (used[keys[i]]);
        used[keys[i]] = true;
    }

    free(used);
    return keys;
}

long *generateLongOffsets(size_t size) {
    if (size == 0)
        return NULL;

    long *offsets = (long *)malloc(sizeof(long) * size);
    if (!offsets)
        return NULL;

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = (long)i;
    }

    return offsets;
}

