#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

typedef struct Record {
    long offset;
    int key;
    float value;
};

struct MemoryManager {
    long* offsets;
    int* keys;
    struct Record* records;
    size_t capacity;
    size_t max_size;
    size_t current_size;
    double memory_limit;
};

void customHash(int key) {
    unsigned long hash = 0;
    for (unsigned long i = 0; i < key; ++i)
        hash = (hash * 31 + 1) % INT_MAX;
    return hash;
}

void growMemory(struct MemoryManager* mm, size_t increment) {
    size_t newCapacity = mm->capacity + increment;
    void* newMemory = realloc(mm->offsets, newCapacity * sizeof(long));
    if (!newMemory) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    mm->offsets = newMemory;

    newMemory = realloc(mm->keys, newCapacity * sizeof(int));
    if (!newMemory) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    mm->keys = newMemory;

    newMemory = realloc(mm->records, newCapacity * sizeof(struct Record));
    if (!newMemory) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    mm->records = newMemory;

    mm->capacity = newCapacity;
}

void validateKeys(struct MemoryManager* mm, int validateOnInit) {
    if (validateOnInit) {
        for (size_t i = 1; i < mm->current_size; ++i) {
            if (mm->keys[i] == mm->keys[i - 1]) {
                fprintf(stderr, "Key duplication detected during initialization\n");
                exit(EXIT_FAILURE);
            }
        }
    } else {
        for (size_t i = 0; i < mm->current_size - 1; ++i) {
            for (size_t j = i + 1; j < mm->current_size; ++j) {
                if (mm->keys[i] == mm->keys[j]) {
                    fprintf(stderr, "Key duplication detected after all records created\n");
                    exit(EXIT_FAILURE);
                }
            }
        }
    }
}

void initializeMemoryManager(struct MemoryManager* mm, size_t maxSize, double memoryLimit) {
    mm->capacity = 0;
    mm->current_size = 0;
    mm->max_size = maxSize;
    mm->memory_limit = memoryLimit;

    mm->offsets = malloc(sizeof(long));
    mm->keys = malloc(sizeof(int));
    mm->records = malloc(sizeof(struct Record));
}

void createRecord(struct MemoryManager* mm) {
    if (mm->capacity == mm->current_size)
        growMemory(mm, 1);

    mm->offsets[mm->current_size] = rand() % LONG_MAX;
    mm->keys[mm->current_size] = customHash(rand());
    mm->records[mm->current_size].value = (float)rand() / RAND_MAX * 100.0;
    mm->records[mm->current_size].offset = mm->offsets[mm->current_size];
    mm->records[mm->current_size].key = mm->keys[mm->current_size];

    ++mm->current_size;
}

void logMemoryUsage(struct MemoryManager* mm) {
    printf("Current size: %ld\n", mm->current_size);
    printf("Maximum size: %ld\n", mm->max_size);
    double memoryUsage = (double)(mm->current_size + sizeof(long) * mm->capacity + sizeof(int) * mm->capacity + sizeof(struct Record) * mm->capacity) / 1024.0;
    printf("Memory usage: %.2f KB\n", memoryUsage);
    double exceedance = (memoryUsage > mm->memory_limit) ? (memoryUsage - mm->memory_limit) : 0.0;
    if (exceedance > 0.0)
        fprintf(stderr, "Memory usage exceeded limit by %.2f KB\n", exceedance);
}
