Manager* create_manager(size_t capacity, int min_key, int max_key) {
    Manager* manager = malloc(sizeof(Manager));
    manager->capacity = capacity;
    manager->size = 0;
    manager->records = calloc(capacity, sizeof(Record));
    manager->min_key = min_key;
    manager->max_key = max_key;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int get_unique_key(Manager* manager) {
    int key;
    pthread_mutex_lock(&manager->lock);
    do {
        key = rand() % (manager->max_key - manager->min_key + 1) + manager->min_key;
    } while (manager_contains_key(manager, key));
    pthread_mutex_unlock(&manager->lock);
    return key;
}

long get_random_value() {
