void* add_record(void* manager_ptr) {
    Manager* manager = (Manager*)manager_ptr;
    int key = get_unique_key(manager);
    long value = get_random_value();

    pthread_mutex_lock(&manager->lock);
    if (manager->size < manager->capacity) {
        manager->records[manager->size].key = key;
        manager->records[manager->size].value = value;
        manager->size++;
    }
    pthread_mutex_unlock(&manager->lock);
}

void free_manager(Manager* manager) {
    free(manager->records);
    free(manager);
}

int manager_contains_key(Manager* manager, int key) {
