class MemoryManager {
public:
    explicit MemoryManager(size_t max_memory) : max_memory_(max_memory), current_memory_(0) {}

    void* allocate(size_t size) {
        if (current_memory_ + size > max_memory_) {
            reduce_records();
        }
        auto memory = std::malloc(size);
        current_memory_ += size;
        return memory;
    }

    void deallocate(void* ptr, size_t size) {
        current_memory_ -= size;
        std::free(ptr);
    }

private:
    void reduce_records() {
        // Implement a strategy to reduce the number of records while maintaining performance
    }

    const size_t max_memory_;
    size_t current_memory_;
};

void initialize_data(MemoryManager& memory_manager, std::vector<long>& timestamps,
                     std::vector<double>& temperatures, std::vector<log_entry>& log_entries,
                     std::vector<long>& offsets, std::vector<int>& keys, std::vector<record>& records) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dist_key(0, std::numeric_limits<int>::max() / 2);
    std::uniform_long_distribution<> dist_timestamp(0, std::numeric_limits<long>::max());
    std::uniform_real_distribution<> dist_temp(-100.0, 100.0), dist_message(0.0, 255.0);

    auto max_status_length = std::numeric_limits<decltype(log_entry::status_message)>::max();

    for (auto& t : timestamps) {
        t = dist_timestamp(gen);
    }
    for (auto& temp : temperatures) {
        if (temp < -100.0 || temp > 100.0) {
            std::cerr << "Warning: invalid temperature value assigned." << std::endl;
            temp = 0.0;
        }
        temp = dist_temp(gen);
    }
    for (auto& le : log_entries) {
        le.timestamp = *std::max_element(timestamps.begin(), timestamps.end());
        le.temperature = *std::max_element(temperatures.begin(), temperatures.end());
        auto message_len = std::min((size_t)dist_message(gen), max_status_length);
        le.status_message.resize(message_len);
        std::generate_n(le.status_message.begin(), message_len, []() { return static_cast<char>(std::rand() % 256); });
    }
    for (auto& o : offsets) {
        o = dist_key(gen);
    }
    for (auto& k : keys) {
        k = dist_key(gen);
    }
    for (auto& r : records) {
        r.value = dist_key(gen);
    }
}

