// Union-Find data structure for disjoint pair checking
typedef struct {
    int *parent;
    int count;
} uf;

int find(uf *uf, int i) {
    if (i == uf->parent[i]) return i;
    return uf->parent[i] = find(uf, uf->parent[i]);
